@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Sora:wght@400;500;600;700&display=swap');

:root {
  --bg: #fbfbff;
  --ink: #17111f;
  --muted: #71687f;
  --dim: #948aa3;
  --line: #ebe7f5;
  --card: #fff;
  --purple: #7b42ff;
  --pink: #ff4ecd;
  --orange: #ff9f43;
  --blue: #2e8cff;
  --green: #20c997;
  --cyan: #10c7e8;
  --red: #ff5a66;
  --navy: #160c2b;
  --grad: linear-gradient(135deg, #7b42ff 0%, #ff4ecd 52%, #ff9f43 100%);
  --grad-blue: linear-gradient(135deg, #2e8cff, #7b42ff 56%, #ff4ecd);
  --shadow: 0 22px 60px rgba(35, 18, 80, .08);
  --shadow-lg: 0 34px 100px rgba(44, 22, 97, .15)
}

* {
  box-sizing: border-box
}

html {
  scroll-behavior: smooth
}

body {
  margin: 0;
  min-width: 320px;
  background: radial-gradient(circle at 8% 4%, rgba(123, 66, 255, .12), transparent 34rem), radial-gradient(circle at 94% 8%, rgba(255, 78, 205, .11), transparent 34rem), linear-gradient(180deg, #fff 0%, #fbfbff 38%, #f8f6ff 100%);
  color: var(--ink);
  font-family: Inter, "DM Sans", system-ui, sans-serif
}

a {
  color: inherit;
  text-decoration: none
}

button,
input,
select,
textarea {
  font: inherit
}

button {
  cursor: pointer
}

h1,
h2,
h3,
p {
  margin-top: 0
}

h1,
h2,
h3,
.brand b {
  font-family: Manrope, Inter, sans-serif
}

.flex {
  display: flex;
  align-items: center
}

.flex-between {
  justify-content: space-between
}

.flex-gap {
  gap: 12px
}

.full {
  width: 100%
}

.mt8 {
  margin-top: 8px
}

.mt16 {
  margin-top: 16px
}

.mt24 {
  margin-top: 24px
}

.mb12 {
  margin-bottom: 12px
}

.mb16 {
  margin-bottom: 16px
}

.mb24 {
  margin-bottom: 24px
}

.text-muted {
  color: var(--muted)
}

.text-xs {
  font-size: 12px
}

.fw700 {
  font-weight: 800
}

.btn {
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 18px;
  background: #fff;
  color: var(--ink);
  font-weight: 850;
  box-shadow: 0 10px 28px rgba(33, 17, 70, .06);
  transition: .2s
}

.btn svg {
  width: 16px;
  height: 16px
}

.btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 38px rgba(33, 17, 70, .1);
  border-color: rgba(123, 66, 255, .24);
  color: var(--purple)
}

.btn.primary,
.btn.btn-primary {
  background: var(--grad);
  border-color: transparent;
  color: #fff;
  box-shadow: 0 18px 42px rgba(123, 66, 255, .24), 0 8px 22px rgba(255, 78, 205, .16)
}

.btn.primary:hover {
  color: #fff;
  box-shadow: 0 22px 54px rgba(123, 66, 255, .32)
}

.btn.ghost {
  background: rgba(255, 255, 255, .75);
  color: var(--muted)
}

.btn.light {
  background: #fff;
  color: var(--purple);
  border-color: rgba(123, 66, 255, .18)
}

.btn.small,
.btn-sm {
  min-height: 38px;
  padding: 0 14px;
  font-size: 13px
}

.btn.dark {
  background: #07111f !important;
  border-color: #07111f !important;
  color: #fff !important
}

.eyebrow {
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  align-items: center;
  gap: 8px;
  border-radius: 999px;
  padding: 8px 13px;
  background: rgba(123, 66, 255, .07);
  border: 1px solid rgba(123, 66, 255, .16);
  color: var(--purple);
  text-transform: uppercase;
  letter-spacing: .12em;
  font-size: 11px;
  font-weight: 900
}

.badge {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 900
}

.badge-green {
  background: rgba(32, 201, 151, .12);
  color: #0b8b66
}

.badge-amber {
  background: rgba(255, 159, 67, .13);
  color: #b56800
}

.badge-gray {
  background: rgba(123, 66, 255, .09);
  color: var(--purple)
}

.badge-red {
  background: #fff1f4;
  color: #bc2231
}

.card,
.cardish {
  background: rgba(255, 255, 255, .92);
  border: 1px solid var(--line);
  border-radius: 26px;
  padding: 24px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(16px)
}

.grid4 {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px
}

.grid2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px
}

.brand-mark,
.cu-brand-mark {
  width: 42px;
  height: 42px;
  border-radius: 15px;
  background: var(--grad);
  display: grid;
  place-items: center;
  color: #fff;
  box-shadow: 0 16px 34px rgba(123, 66, 255, .25)
}

.brand span {
  display: flex;
  flex-direction: column
}

.brand b {
  font-size: 18px;
  letter-spacing: -.04em
}

.brand small {
  font-size: 10px;
  color: var(--dim);
  text-transform: uppercase;
  font-weight: 900;
  letter-spacing: .14em
}

.app-shell {
  min-height: 100vh
}

.sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: 272px;
  padding: 22px 16px;
  background: radial-gradient(circle at 20% 0%, rgba(255, 78, 205, .18), transparent 18rem), radial-gradient(circle at 100% 16%, rgba(123, 66, 255, .22), transparent 16rem), linear-gradient(180deg, #180d31, #0d071d);
  color: rgba(255, 255, 255, .82);
  border-right: 1px solid rgba(255, 255, 255, .08);
  box-shadow: 20px 0 60px rgba(30, 12, 72, .16);
  z-index: 20;
  display: flex;
  flex-direction: column
}

.sb-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 4px 8px 20px
}

.sb-logo {
  width: 42px;
  height: 42px;
  border-radius: 15px;
  background: var(--grad);
  display: grid;
  place-items: center;
  color: #fff
}

.sb-name {
  color: #fff;
  font-family: Manrope;
  font-weight: 900
}

.sb-sub {
  font-size: 11px;
  color: rgba(255, 255, 255, .55);
  font-weight: 800
}

.sb-close-btn {
  display: none;
  margin-left: auto;
  background: transparent;
  border: 0;
  color: #fff
}

.sb-scroll {
  overflow: auto
}

.sb-section {
  margin-top: 20px
}

.sb-label {
  font-size: 10px;
  color: rgba(255, 255, 255, .36);
  text-transform: uppercase;
  letter-spacing: .16em;
  font-weight: 900;
  margin: 0 12px 10px
}

.sb-item {
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 11px;
  border-radius: 15px;
  padding: 0 13px;
  color: rgba(255, 255, 255, .62);
  font-size: 14px;
  font-weight: 850;
  border: 1px solid transparent
}

.sb-item svg {
  color: rgba(255, 255, 255, .48)
}

.sb-item:hover {
  background: rgba(255, 255, 255, .08);
  color: #fff;
  transform: translateX(2px)
}

.sb-item.active {
  background: linear-gradient(135deg, rgba(123, 66, 255, .95), rgba(255, 78, 205, .82));
  color: #fff;
  border-color: rgba(255, 255, 255, .14);
  box-shadow: 0 14px 30px rgba(123, 66, 255, .24)
}

.sb-item em {
  margin-left: auto;
  font-style: normal;
  font-size: 10px;
  background: rgba(255, 255, 255, .16);
  padding: 4px 7px;
  border-radius: 999px
}

.sb-foot {
  margin-top: auto;
  border-top: 1px solid rgba(255, 255, 255, .08);
  padding: 18px 8px 0;
  display: flex;
  align-items: center;
  gap: 10px
}

.sb-avatar {
  width: 39px;
  height: 39px;
  border-radius: 50%;
  background: var(--grad);
  color: #fff;
  display: grid;
  place-items: center;
  font-weight: 900
}

.sb-foot b {
  color: #fff;
  font-size: 12px
}

.sb-foot small {
  display: block;
  color: rgba(255, 255, 255, .5);
  font-size: 10px
}

.btn-icon {
  border: 0;
  background: transparent;
  color: #aaa;
  margin-left: auto
}

.app-main {
  margin-left: 272px;
  min-height: 100vh;
  padding: 34px 42px
}

.topbar {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 28px
}

.topbar-spacer {
  flex: 1
}

.topbar-search {
  height: 44px;
  min-width: 320px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
  border-radius: 999px;
  background: #fff;
  border: 1px solid var(--line);
  box-shadow: 0 10px 24px rgba(35, 18, 80, .05)
}

.topbar-search svg {
  color: var(--purple)
}

.topbar-search input {
  border: 0;
  outline: 0;
  background: transparent;
  width: 100%;
  font-weight: 700
}

.notif-btn {
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 50%;
  position: relative
}

.notif-btn span {
  position: absolute;
  right: 10px;
  top: 9px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--red)
}

.mobile-menu {
  display: none
}

.page,
.dashboard-page,
.detail-page,
.territory-page,
.analytics-page,
.contacts-page,
.inbox-page,
.settings-page-v54,
.setup-page-v54,
.ai-page-v54 {
  max-width: 1320px;
  margin: auto
}

.page-heading,
.page-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  margin-bottom: 18px
}

.page-heading h1,
.page-top h1 {
  font-size: 34px;
  line-height: 1.08;
  letter-spacing: -.045em;
  font-weight: 900;
  margin: 8px 0
}

.page-heading p {
  color: var(--muted);
  font-weight: 650;
  line-height: 1.65
}

.metric-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 26px;
  padding: 22px;
  box-shadow: var(--shadow)
}

.metric-icon {
  width: 44px;
  height: 44px;
  border-radius: 15px;
  display: grid;
  place-items: center;
  color: #fff;
  background: var(--grad);
  margin-bottom: 20px
}

.metric-icon.green {
  background: linear-gradient(135deg, #20c997, #10c7e8)
}

.metric-icon.amber {
  background: linear-gradient(135deg, #ff9f43, #ff4ecd)
}

.metric-icon.blue {
  background: linear-gradient(135deg, #2e8cff, #7b42ff)
}

.metric-num {
  font-family: Manrope;
  font-size: 30px;
  font-weight: 900;
  letter-spacing: -.05em
}

.metric-num.sm {
  font-size: 22px
}

.metric-label {
  color: var(--muted);
  font-size: 13px;
  font-weight: 800
}

.metric-trend {
  margin-top: 10px;
  color: #0b8b66;
  font-size: 12px;
  font-weight: 900
}

.mini-chart {
  height: 110px;
  display: flex;
  align-items: flex-end;
  gap: 10px
}

.mini-bar {
  flex: 1;
  min-height: 10%;
  border-radius: 10px;
  background: #eee9f9
}

.mini-bar.accent {
  background: var(--grad)
}

.stats-row {
  gap: 28px
}

.campaign-row,
.channel-row,
.activity-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid #f0ecf8
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--orange)
}

.status-dot.active {
  background: var(--green)
}

.activity-row {
  align-items: flex-start
}

.activity-row b,
.activity-row small {
  display: block
}

.activity-row span {
  font-size: 12px;
  color: var(--dim)
}

.toolbar {
  min-height: 66px;
  background: rgba(255, 255, 255, .86);
  border: 1px solid var(--line);
  border-radius: 24px;
  padding: 12px 16px;
  margin: 28px 0 20px;
  box-shadow: var(--shadow);
  display: flex;
  justify-content: space-between;
  align-items: center
}

.search {
  position: relative
}

.search svg {
  position: absolute;
  left: 14px;
  top: 13px;
  width: 17px;
  color: var(--purple)
}

.search input {
  height: 42px;
  width: 300px;
  background: #f7f4ff;
  border: 1px solid rgba(123, 66, 255, .1);
  border-radius: 999px;
  padding: 0 14px 0 40px;
  outline: 0;
  font-weight: 750
}

.campaign-grid,
.skeleton-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px
}

.campaign-card {
  position: relative;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 30px;
  padding: 24px;
  box-shadow: var(--shadow);
  transition: .2s
}

.campaign-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 28px 70px rgba(35, 18, 80, .13)
}

.campaign-card-top {
  display: flex;
  justify-content: space-between
}

.status {
  display: inline-flex;
  align-items: center;
  min-height: 27px;
  padding: 0 11px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 950;
  letter-spacing: .1em;
  text-transform: uppercase
}

.status.active {
  background: rgba(32, 201, 151, .12);
  color: #0b8b66
}

.status.queued {
  background: rgba(255, 159, 67, .13);
  color: #b56800
}

.status.history {
  background: rgba(123, 66, 255, .1);
  color: var(--purple)
}

.icon-btn {
  border: 0;
  background: transparent;
  color: #b1a8bf
}

.icon-btn:hover {
  color: var(--red)
}

.icon-btn svg {
  width: 16px
}

.campaign-card h3 {
  font-size: 21px;
  line-height: 1.15;
  letter-spacing: -.045em;
  margin: 17px 0 8px
}

.campaign-card>p {
  color: var(--muted);
  font-size: 13px;
  font-weight: 750;
  display: flex;
  align-items: center;
  gap: 5px
}

.campaign-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: #faf8ff;
  border: 1px solid var(--line);
  border-radius: 20px;
  margin: 20px 0;
  overflow: hidden
}

.campaign-stats>span {
  display: grid;
  grid-template-columns: 28px 1fr;
  padding: 15px
}

.campaign-stats>span+span {
  border-left: 1px solid var(--line)
}

.campaign-stats svg {
  grid-row: 1/3;
  color: var(--purple)
}

.campaign-stats b {
  font-weight: 900
}

.campaign-stats small {
  font-size: 11px;
  color: var(--dim);
  font-weight: 800
}

.campaign-card>a {
  display: flex;
  justify-content: space-between;
  color: var(--purple);
  font-weight: 900
}

.card-progress>span {
  display: block;
  height: 8px;
  background: #eee9f9;
  border-radius: 999px;
  overflow: hidden
}

.card-progress i {
  display: block;
  height: 100%;
  background: var(--grad-blue)
}

.card-progress small {
  display: block;
  color: var(--dim);
  margin: 6px 0 15px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis
}

.empty {
  min-height: 360px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: #fff;
  border: 1px dashed rgba(123, 66, 255, .24);
  border-radius: 32px;
  color: var(--muted);
  box-shadow: var(--shadow);
  padding: 28px
}

.empty>span {
  width: 64px;
  height: 64px;
  border-radius: 22px;
  background: var(--grad);
  display: grid;
  place-items: center;
  color: #fff
}

.empty h3 {
  color: #180f27;
  font-size: 24px
}

.empty p {
  max-width: 420px;
  line-height: 1.65
}

.skeleton-list i,
.map-skeleton {
  height: 250px;
  border-radius: 30px;
  background: linear-gradient(90deg, #eee9f9, #fff, #eee9f9);
  background-size: 220%;
  animation: shimmer 1.2s infinite
}

@keyframes shimmer {
  to {
    background-position: -220%
  }
}

.builder-page {
  max-width: 980px;
  margin: auto
}

.step-count {
  font-family: Manrope;
  font-size: 36px;
  color: var(--purple);
  font-weight: 900
}

.step-count small {
  font-size: 14px;
  color: var(--dim)
}

.step-line {
  display: flex;
  gap: 10px;
  margin: 24px 0 34px
}

.step-line i {
  height: 6px;
  flex: 1;
  max-width: 128px;
  border-radius: 99px;
  background: #ebe7f5
}

.step-line i.active {
  background: var(--grad)
}

.builder-card {
  position: relative;
  background: radial-gradient(circle at 16% 0%, rgba(123, 66, 255, .08), transparent 18rem), radial-gradient(circle at 88% 8%, rgba(255, 78, 205, .08), transparent 20rem), #fff;
  border: 1px solid var(--line);
  border-radius: 28px;
  box-shadow: var(--shadow-lg);
  min-height: 520px;
  padding: 52px 60px 30px;
  overflow: hidden
}

.builder-step {
  text-align: center
}

.builder-step h2 {
  font-size: 34px;
  line-height: 1.1;
  letter-spacing: -.045em;
  font-weight: 900;
  margin: 12px 0 8px
}

.builder-step>p {
  color: var(--muted);
  font-size: 16px;
  line-height: 1.55;
  font-weight: 650
}

.step-fields {
  max-width: 720px;
  margin: 36px auto 0;
  text-align: left
}

.choice-grid {
  display: grid;
  gap: 14px
}

.choice-grid.two {
  grid-template-columns: 1fr 1fr
}

.choice {
  position: relative;
  min-height: 104px;
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 20px;
  padding: 20px;
  text-align: left;
  display: flex;
  align-items: center;
  gap: 15px;
  color: var(--ink);
  box-shadow: 0 14px 34px rgba(35, 18, 80, .06)
}

.choice.active {
  border: 2px solid rgba(123, 66, 255, .72);
  background: #f7f4ff;
  padding: 19px
}

.choice>span {
  width: 52px;
  height: 52px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  background: #f5f2ff;
  color: var(--purple)
}

.choice.active>span {
  background: var(--grad);
  color: #fff
}

.choice div {
  display: flex;
  flex-direction: column
}

.choice b {
  font-size: 16px;
  font-weight: 900
}

.choice small {
  color: var(--muted);
  font-weight: 650
}

.choice>i {
  position: absolute;
  right: 15px;
  top: 15px;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--grad);
  color: #fff
}

.choice>i svg {
  width: 14px
}

.field {
  display: block;
  margin-bottom: 19px
}

.field>span,
.range-label>span,
.launch-settings label>span {
  display: block;
  margin-bottom: 8px;
  color: #3f314f;
  font-size: 12px;
  font-weight: 900
}

.input-wrap {
  position: relative
}

.input-wrap svg {
  position: absolute;
  left: 15px;
  top: 17px;
  width: 18px;
  color: var(--purple)
}

.input-wrap svg+input {
  padding-left: 46px
}

.field input,
.field select,
.field textarea,
.launch-settings select {
  width: 100%;
  height: 52px;
  border: 1px solid var(--line);
  border-radius: 15px;
  padding: 0 15px;
  outline: 0;
  background: #fff;
  color: var(--ink);
  font-weight: 750
}

.field textarea {
  min-height: 130px;
  padding: 14px;
  resize: vertical
}

.field input:focus,
.field select:focus,
.field textarea:focus,
.launch-settings select:focus {
  border-color: rgba(123, 66, 255, .55);
  box-shadow: 0 0 0 5px rgba(123, 66, 255, .1)
}

.suggestions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap
}

.suggestions button {
  min-height: 38px;
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 999px;
  padding: 0 13px;
  font-size: 12px;
