/* ==========================================================
   External Lead Campaigns
   ========================================================== */

.external-campaign-page {
  width: min(1320px, 100%);
  margin: 0 auto;
  display: grid;
  gap: 22px;
  min-width: 0;
}

.external-campaign-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 22px;
  padding: 8px 0 10px;
}

.external-campaign-hero h1 {
  margin: 10px 0 10px;
  color: var(--ink);
  font-size: clamp(32px, 4vw, 48px);
  line-height: 1;
  letter-spacing: -.06em;
  font-weight: 950;
}

.external-campaign-hero p {
  max-width: 820px;
  margin: 0;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.65;
  font-weight: 750;
}

.external-stepper {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.external-step {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 14px;
  border-radius: 22px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .78);
  box-shadow: 0 14px 34px rgba(35, 18, 80, .045);
}

.external-step > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  color: var(--muted);
  background: #f5f2ff;
  font-weight: 950;
}

.external-step small,
.external-step b {
  display: block;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.external-step small {
  color: var(--dim);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: .09em;
}

.external-step b {
  margin-top: 4px;
  color: var(--ink);
  font-size: 13px;
  font-weight: 950;
}

.external-step.active {
  border-color: rgba(123, 66, 255, .34);
  background:
    radial-gradient(circle at 0 0, rgba(123, 66, 255, .11), transparent 12rem),
    #fff;
  box-shadow: 0 20px 52px rgba(35, 18, 80, .08);
}

.external-step.active > span,
.external-step.done > span {
  color: #fff;
  background: var(--grad);
  box-shadow: 0 14px 30px rgba(123, 66, 255, .22);
}

.external-card {
