  background: linear-gradient(90deg, #7627f4, #c72ceb 56%, #ff4b9f);
  box-shadow: 0 0 18px rgba(201, 44, 224, 0.45);
  transition: width 420ms cubic-bezier(0.2, 0.75, 0.25, 1);
}

.live-progress-meta {
  flex-wrap: wrap;
  gap: 10px 22px;
  margin-top: 12px;
  color: var(--muted, #756d82);
  font-size: 12px;
}

.live-progress-meta b {
  color: var(--text, #20172f);
}

.live-results-error {
  margin-top: 14px;
  padding: 11px 13px;
  border: 1px solid rgba(199, 57, 85, 0.18);
  border-radius: 12px;
  background: rgba(255, 235, 239, 0.72);
  color: #a92b43;
  font-size: 13px;
  font-weight: 700;
}

.live-results-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.live-result-stat {
  padding: 18px;
  border: 1px solid rgba(109, 76, 160, 0.12);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.84);
  box-shadow: 0 10px 35px rgba(59, 31, 101, 0.06);
}

.live-result-stat span,
.live-result-stat small {
  display: block;
  color: var(--muted, #756d82);
}

.live-result-stat span {
  margin-bottom: 8px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.live-result-stat strong {
  display: block;
  margin-bottom: 4px;
  color: var(--text, #21172e);
  font-size: 30px;
  letter-spacing: -0.04em;
}

.live-result-stat small {
  font-size: 11px;
}

.live-results-content {
  padding: 22px;
  border: 1px solid rgba(109, 76, 160, 0.12);
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.86);
  box-shadow: 0 18px 55px rgba(59, 31, 101, 0.07);
}

.live-results-toolbar {
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 18px;
}

.live-results-toolbar h2 {
  margin: 5px 0 0;
  font-size: 24px;
  letter-spacing: -0.035em;
}

.live-results-search {
  display: flex;
  align-items: center;
  gap: 10px;
  width: min(360px, 100%);
  min-height: 44px;
  padding: 0 14px;
  border: 1px solid rgba(103, 73, 151, 0.17);
  border-radius: 14px;
  background: #fff;
  color: #81768e;
  box-shadow: 0 8px 26px rgba(57, 32, 91, 0.05);
}

.live-results-search svg {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
}

.live-results-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text, #21172e);
  font: inherit;
}

.live-lead-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 14px;
}

.live-lead-card {
  display: flex;
  min-width: 0;
  min-height: 260px;
  flex-direction: column;
  padding: 18px;
  border: 1px solid rgba(102, 70, 151, 0.12);
  border-radius: 19px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(252, 249, 255, 0.95));
  box-shadow: 0 9px 30px rgba(62, 35, 103, 0.055);
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.live-lead-card:hover {
  transform: translateY(-3px);
  border-color: rgba(126, 59, 231, 0.25);
  box-shadow: 0 18px 44px rgba(79, 40, 136, 0.11);
}

.live-lead-card-head {
  justify-content: space-between;
}

.live-lead-avatar {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: linear-gradient(135deg, rgba(118, 39, 244, 0.13), rgba(242, 56, 165, 0.13));
  color: #7028da;
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.02em;
}

.live-lead-number {
  padding: 5px 8px;
  border-radius: 999px;
  background: rgba(105, 73, 151, 0.07);
  color: #7d7189;
  font-size: 10px;
  font-weight: 800;
}

.live-lead-card-title {
  margin: 15px 0 14px;
}

.live-lead-card-title h3 {
  overflow: hidden;
  margin: 0 0 7px;
  color: var(--text, #21172e);
  font-size: 16px;
  line-height: 1.35;
  text-overflow: ellipsis;
}

.live-lead-card-title > span {
  display: inline-flex;
  max-width: 100%;
  padding: 5px 8px;
  overflow: hidden;
  border-radius: 8px;
  background: rgba(112, 72, 177, 0.07);
  color: #725d89;
  font-size: 10px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.live-lead-details {
  display: grid;
  gap: 9px;
  margin-bottom: 16px;
}

.live-lead-details > div {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  color: #71677d;
  font-size: 12px;
  line-height: 1.45;
}

.live-lead-details svg,
.live-lead-detail-symbol {
  width: 15px;
  height: 15px;
  margin-top: 1px;
  color: #8b58d5;
}

.live-lead-details a {
  overflow: hidden;
  color: inherit;
  text-decoration: none;
  text-overflow: ellipsis;
}

.live-lead-details a:hover {
  color: #6e2bdf;
}

.live-lead-card-footer {
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 13px;
  border-top: 1px solid rgba(105, 72, 153, 0.09);
}

.live-lead-website {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 7px;
  color: #6331c5;
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
}

.live-lead-website svg {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
}

.live-lead-website span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.live-lead-website svg:last-child {
  width: 12px;
  height: 12px;
}

.live-lead-no-website {
  color: #988ea1;
  font-size: 11px;
}

.live-lead-quality {
  display: grid;
  place-items: center;
  width: 32px;
  height: 28px;
  flex: 0 0 auto;
  border-radius: 9px;
  background: rgba(22, 142, 102, 0.1);
  color: #107b58;
  font-size: 10px;
  font-weight: 900;
}

.live-lead-quality.weak {
  background: rgba(209, 133, 45, 0.1);
  color: #a7651c;
}

.live-lead-skeleton {
  pointer-events: none;
}

.live-lead-skeleton i,
.live-lead-skeleton b,
.live-lead-skeleton span {
  display: block;
  border-radius: 8px;
  background: linear-gradient(90deg, rgba(116, 82, 165, 0.07), rgba(116, 82, 165, 0.14), rgba(116, 82, 165, 0.07));
  background-size: 220% 100%;
  animation: live-shimmer 1.3s linear infinite;
}

.live-lead-skeleton i {
  width: 42px;
  height: 42px;
  margin-bottom: 18px;
}

.live-lead-skeleton b {
  width: 72%;
  height: 17px;
  margin-bottom: 16px;
}

.live-lead-skeleton span {
  width: 100%;
  height: 12px;
  margin-bottom: 12px;
}

.live-lead-skeleton span:last-child {
  width: 58%;
}

.live-results-loading-more {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 22px 0 2px;
  color: #746980;
  font-size: 12px;
  font-weight: 700;
}

.live-results-loading-more span {
  width: 14px;
  height: 14px;
  border: 2px solid rgba(112, 44, 222, 0.2);
  border-top-color: #702cde;
  border-radius: 50%;
  animation: live-spin 0.8s linear infinite;
}

.live-results-empty {
  display: grid;
  place-items: center;
  min-height: 290px;
  padding: 40px;
  border: 1px dashed rgba(108, 74, 157, 0.2);
  border-radius: 18px;
  color: #766b81;
  text-align: center;
}

.live-results-empty svg {
  width: 34px;
  height: 34px;
  margin-bottom: 12px;
  color: #8f60d8;
}

.live-results-empty h3 {
  margin: 0 0 5px;
  color: var(--text, #21172e);
}

.live-results-empty p {
  margin: 0;
  font-size: 13px;
}

.live-results-promise {
  margin-top: 18px;
}

@keyframes live-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes live-pulse {
  0%,
  100% {
    opacity: 0.4;
    transform: scale(0.85);
  }

  50% {
    opacity: 1;
    transform: scale(1.12);
  }
}

@keyframes live-shimmer {
  to {
    background-position: -220% 0;
  }
}

@media (max-width: 900px) {
  .live-results-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .live-progress-card {
    top: 8px;
  }
}

@media (max-width: 680px) {
  .live-results-page {
    padding-top: 0;
  }

  .live-results-topbar,
  .live-results-hero,
  .live-results-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .live-results-top-actions {
    width: 100%;
  }

  .live-results-top-actions .btn {
    flex: 1;
  }

  .live-status-pill {
    align-self: flex-start;
  }

  .live-progress-card {
    position: relative;
    top: 0;
  }

  .live-progress-main {
    grid-template-columns: 1fr;
    padding: 18px;
  }

  .live-progress-title-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .live-progress-title-row strong {
    font-size: 18px;
  }

  .live-results-stats {
    grid-template-columns: 1fr 1fr;
  }

  .live-results-content {
    padding: 16px;
  }

  .live-results-search {
    width: 100%;
  }

  .live-lead-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 420px) {
  .live-results-stats {
    grid-template-columns: 1fr;
  }
}

/* ==========================================================
   Lead audit experience
   ========================================================== */

body.audit-drawer-open {
  overflow: hidden;
}

.live-lead-card.audit-ready {
  cursor: pointer;
  outline: none;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.live-lead-card.audit-ready:hover,
.live-lead-card.audit-ready:focus-visible {
  border-color: rgba(22, 163, 74, 0.38);
  box-shadow:
    0 18px 42px rgba(15, 23, 42, 0.09),
    0 0 0 3px rgba(22, 163, 74, 0.07);
  transform: translateY(-2px);
}

.mini-audit-button {
  width: 100%;
  min-height: 42px;
  margin-top: 14px;
  padding: 10px 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid rgba(22, 163, 74, 0.2);
  border-radius: 12px;
  background:
    linear-gradient(135deg, rgba(240, 253, 244, 0.96), rgba(236, 253, 245, 0.8));
  color: #166534;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    transform 160ms ease;
}

.mini-audit-button:hover:not(:disabled) {
  border-color: rgba(22, 163, 74, 0.42);
  background: #dcfce7;
  transform: translateY(-1px);
}

.mini-audit-button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.mini-audit-button > span {
  width: 22px;
  height: 22px;
  display: inline-grid;
  place-items: center;
  border-radius: 7px;
  background: #16a34a;
  color: #fff;
  font-size: 12px;
  box-shadow: 0 5px 12px rgba(22, 163, 74, 0.22);
}

.mini-audit-button svg {
  width: 15px;
  height: 15px;
  margin-left: auto;
}

.audit-drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  justify-content: flex-end;
  background: rgba(15, 23, 42, 0.48);
  backdrop-filter: blur(6px);
  animation: auditBackdropIn 180ms ease both;
}

.lead-audit-drawer {
  width: min(920px, 96vw);
  height: 100%;
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  background: #f8fafc;
  border-left: 1px solid rgba(148, 163, 184, 0.25);
  box-shadow: -28px 0 80px rgba(15, 23, 42, 0.2);
  animation: auditDrawerIn 220ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.audit-drawer-header {
  min-height: 92px;
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  color: #fff;
  background:
    radial-gradient(circle at 88% 12%, rgba(34, 197, 94, 0.24), transparent 30%),
    linear-gradient(135deg, #0f172a 0%, #111827 72%, #052e16 130%);
}

.audit-drawer-header .eyebrow {
  color: #86efac;
  letter-spacing: 0.13em;
}

.audit-drawer-header h2 {
  margin: 5px 0 3px;
  color: #fff;
  font-size: clamp(20px, 2.2vw, 29px);
  line-height: 1.08;
}

.audit-drawer-header p {
  margin: 0;
  color: #cbd5e1;
  font-size: 13px;
}

.audit-close-button {
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.17);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  font-size: 26px;
  line-height: 1;
  cursor: pointer;
  transition: background 160ms ease, transform 160ms ease;
}

.audit-close-button:hover {
  background: rgba(255, 255, 255, 0.16);
  transform: rotate(3deg);
}

.audit-kind-tabs {
  min-height: 58px;
  padding: 9px 20px;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  border-bottom: 1px solid #e2e8f0;
  background: #fff;
}

.audit-kind-tabs button {
  min-height: 38px;
  padding: 8px 13px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 11px;
  background: transparent;
  color: #64748b;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
  cursor: pointer;
}

.audit-kind-tabs button:hover {
  color: #0f172a;
  background: #f8fafc;
}

.audit-kind-tabs button.active {
  border-color: rgba(22, 163, 74, 0.18);
  color: #166534;
  background: #f0fdf4;
  box-shadow: inset 0 0 0 1px rgba(22, 163, 74, 0.04);
}

.audit-kind-tabs button i {
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #16a34a;
  color: #fff;
  font-size: 10px;
  font-style: normal;
}

.audit-kind-tabs button i.pending {
  border: 2px solid #bbf7d0;
  border-top-color: #16a34a;
  background: transparent;
  animation: auditSpin 800ms linear infinite;
}

.audit-action-bar {
  min-height: 76px;
  padding: 13px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  border-bottom: 1px solid #e2e8f0;
  background: rgba(255, 255, 255, 0.94);
}

.audit-action-bar > div {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.audit-action-bar small {
  color: #64748b;
  font-size: 11px;
}

.audit-status {
  width: fit-content;
  padding: 4px 9px;
  border-radius: 999px;
  color: #92400e;
  background: #fffbeb;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.audit-status.complete {
  color: #166534;
  background: #dcfce7;
}

.audit-status.failed {
  color: #991b1b;
  background: #fee2e2;
}

.audit-download-button {
  flex: 0 0 auto;
  min-width: 132px;
}

.audit-inline-error {
  margin: 12px 22px 0;
  padding: 11px 13px;
  border: 1px solid #fecaca;
  border-radius: 12px;
  color: #991b1b;
  background: #fff1f2;
  font-size: 12px;
  font-weight: 700;
}

.audit-report-scroll {
  min-height: 0;
  overflow-y: auto;
  padding: 24px;
  scroll-behavior: smooth;
}

.mini-audit-sheet,
.expanded-audit-sheet {
  width: min(760px, 100%);
  margin: 0 auto;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 18px 48px rgba(15, 23, 42, 0.07);
}

.mini-audit-sheet {
  padding: clamp(22px, 4vw, 42px);
}

.mini-audit-confidential {
  margin: calc(clamp(22px, 4vw, 42px) * -1) calc(clamp(22px, 4vw, 42px) * -1) 0;
  padding: 9px 18px;
  border-radius: 20px 20px 0 0;
  color: #fff;
  background: #0f172a;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-align: center;
}

.mini-audit-brandline {
  margin: 0 calc(clamp(22px, 4vw, 42px) * -1);
  padding: 12px 18px;
  color: #166534;
  background: linear-gradient(90deg, #f0fdf4, #ecfdf5);
  border-bottom: 1px solid #dcfce7;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-align: center;
}

.mini-audit-title {
  padding: 28px 0 10px;
}

.mini-audit-title h1 {
  margin: 0;
  color: #0f172a;
  font-size: clamp(24px, 4vw, 36px);
  letter-spacing: -0.035em;
  line-height: 1.03;
}

.mini-audit-title p {
  margin: 7px 0 0;
  color: #64748b;
  font-size: 13px;
}

.audit-section-title {
  margin: 25px 0 14px;
  display: flex;
  align-items: center;
  gap: 12px;
  color: #166534;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.audit-section-title::after {
  content: "";
  height: 1px;
  flex: 1;
  background: linear-gradient(90deg, #bbf7d0, transparent);
}

.mini-audit-snapshot {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.mini-audit-snapshot > div {
  min-height: 64px;
  padding: 12px 13px;
  display: grid;
  align-content: start;
  gap: 5px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #f8fafc;
}

.mini-audit-snapshot > div:last-child {
  grid-column: 1 / -1;
}

.mini-audit-snapshot span {
  color: #64748b;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.mini-audit-snapshot b {
  color: #1e293b;
  font-size: 12px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.mini-audit-issues {
  display: grid;
  gap: 10px;
}

.mini-audit-issue {
  padding: 14px;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 11px;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  background: #fff;
}

.mini-audit-issue > span {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: #fff;
  background: linear-gradient(135deg, #16a34a, #15803d);
  box-shadow: 0 7px 16px rgba(22, 163, 74, 0.18);
  font-size: 11px;
  font-weight: 900;
}

.mini-audit-issue h3 {
  margin: 1px 0 7px;
  color: #0f172a;
  font-size: 12px;
  letter-spacing: 0.015em;
  text-transform: uppercase;
}

.mini-audit-issue p {
  margin: 0 0 6px;
  color: #475569;
  font-size: 11.5px;
  line-height: 1.52;
}

.mini-audit-issue p.pain {
  color: #166534;
}

.mini-audit-issue small {
  color: #94a3b8;
  font-size: 9px;
  overflow-wrap: anywhere;
}

.mini-audit-footer-copy,
.expanded-audit-disclaimer {
  margin: 25px 0 0;
  padding-top: 14px;
  border-top: 1px solid #e2e8f0;
  color: #64748b;
  font-size: 9px;
  line-height: 1.5;
}

.expanded-audit-sheet {
  padding: clamp(22px, 4vw, 38px);
}

.audit-report-heading {
  padding: 2px 0 22px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid #e2e8f0;
}

.audit-report-heading > div:first-child {
  min-width: 0;
}

.audit-report-heading > div > span {
  color: #16a34a;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.audit-report-heading h1 {
  margin: 7px 0 9px;
  color: #0f172a;
