  border: 1px solid #e2e8f0;
  border-radius: 14px;
}

.audit-finding-list > article > span,
.audit-roadmap > article > span {
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: #166534;
  background: #dcfce7;
  font-size: 10px;
  font-weight: 900;
}

.audit-finding-list h3,
.audit-roadmap h3 {
  margin: 0 0 5px;
  color: #0f172a;
  font-size: 13px;
}

.audit-finding-list p {
  margin: 0 0 5px;
  color: #64748b;
  font-size: 11px;
  line-height: 1.5;
}

.audit-finding-list b {
  color: #166534;
  font-size: 11px;
}

.audit-bullet-list {
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
  list-style: none;
}

.audit-bullet-list li {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  color: #475569;
  font-size: 12px;
  line-height: 1.5;
}

.audit-bullet-list li > span {
  color: #16a34a;
  font-weight: 900;
}

.audit-bullet-list.positive li {
  padding: 9px 11px;
