  color: #ffffff;
  background: var(--rf-chat-primary);
  border-color: var(--rf-chat-primary);
}

.rf-chat-action-button--primary:hover:not(:disabled) {
  color: #ffffff;
  background: var(--rf-chat-primary-dark);
}

.rf-chat-action-button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.rf-chat-alert {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 43px;
  padding: 8px 18px;
  color: #8f3441;
  font-size: 12px;
  background: #fff3f5;
  border-bottom: 1px solid #f4d6db;
}

.rf-chat-alert button {
  padding: 4px 8px;
  color: #8f3441;
  font-size: 11px;
  font-weight: 700;
  background: transparent;
  border: 0;
}

.rf-chat-content {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
}

.rf-message-area {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background:
    radial-gradient(
      circle at 70% 0%,
      rgba(101, 88, 245, 0.025),
      transparent 28%
    ),
    #ffffff;
}

.rf-message-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 24px 28px 16px;
  scrollbar-width: thin;
  scrollbar-color: #ccd2df transparent;
}

/* ------------------------------------------------------------------ */
/* Messages                                                           */
/* ------------------------------------------------------------------ */

.rf-message-row {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 10px;
  width: 100%;
  margin-bottom: 5px;
}

.rf-message-row--own {
  grid-template-columns: minmax(0, 1fr);
}

.rf-message-avatar-spacer {
  width: 36px;
}

.rf-message-block {
  min-width: 0;
  max-width: min(690px, 78%);
}

.rf-message-row--own .rf-message-block {
  justify-self: end;
}

.rf-message-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 19px;
  margin-bottom: 4px;
}

.rf-message-row--own .rf-message-meta {
  justify-content: flex-end;
}

.rf-message-meta strong {
  color: #40495b;
  font-size: 11px;
  font-weight: 750;
}

.rf-message-meta time {
  color: #9aa1b0;
  font-size: 9px;
  font-weight: 550;
}

.rf-message-bubble {
  display: inline-block;
  max-width: 100%;
  padding: 10px 13px;
  color: #30394b;
  background: #f0f2f6;
  border: 1px solid #ebedf2;
  border-radius: 5px 15px 15px 15px;
  box-shadow:
    0 4px 12px rgba(30, 37, 55, 0.025);
}

.rf-message-row--own .rf-message-bubble {
  color: #ffffff;
  background:
    linear-gradient(
      145deg,
      #6d60fa,
      #5b4ee3
    );
  border-color: transparent;
  border-radius: 15px 5px 15px 15px;
  box-shadow:
    0 8px 18px rgba(101, 88, 245, 0.18);
}

.rf-message-bubble p {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: 13px;
  line-height: 1.52;
  white-space: pre-wrap;
}

.rf-message-bubble.is-deleted {
  color: #8d95a6;
  background: #f8f9fb;
  border-style: dashed;
  box-shadow: none;
}

.rf-message-bubble em {
  font-size: 11px;
}

.rf-message-attachments {
  display: grid;
  gap: 6px;
  margin-top: 9px;
}

.rf-message-attachments a {
  display: block;
  max-width: 320px;
  padding: 8px 10px;
  overflow: hidden;
  color: inherit;
  font-size: 11px;
  font-weight: 700;
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 8px;
}

.rf-message-actions {
  display: flex;
  gap: 4px;
  min-height: 19px;
  margin-top: 2px;
  opacity: 0;
  transition: opacity 140ms ease;
}

.rf-message-row:hover .rf-message-actions {
  opacity: 1;
}

.rf-message-row--own .rf-message-actions {
  justify-content: flex-end;
}

.rf-message-actions button {
  padding: 2px 5px;
  color: #8c94a4;
  font-size: 9px;
  font-weight: 650;
  background: transparent;
  border: 0;
}

.rf-message-actions button:hover {
  color: var(--rf-chat-primary);
}

.rf-message-loading {
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.rf-message-loading span {
  width: 7px;
  height: 7px;
  background: var(--rf-chat-primary);
  border-radius: 999px;
  animation: rf-message-loading 1s infinite ease-in-out;
}

.rf-message-loading span:nth-child(2) {
  animation-delay: 120ms;
}

.rf-message-loading span:nth-child(3) {
  animation-delay: 240ms;
}

@keyframes rf-message-loading {
  0%,
  100% {
    opacity: 0.3;
    transform: translateY(0);
  }

  50% {
    opacity: 1;
    transform: translateY(-5px);
  }
}

.rf-chat-empty {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px;
  text-align: center;
}

.rf-chat-empty > div {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin-bottom: 14px;
  color: var(--rf-chat-primary);
  font-size: 16px;
  font-weight: 800;
  background: var(--rf-chat-primary-soft);
  border-radius: 18px;
}

.rf-chat-empty h3 {
  margin: 0;
  font-size: 17px;
}

.rf-chat-empty p {
  max-width: 330px;
  margin: 8px 0 0;
  color: var(--rf-chat-muted);
  font-size: 12px;
  line-height: 1.55;
}

/* ------------------------------------------------------------------ */
/* Typing indicator and composer                                      */
/* ------------------------------------------------------------------ */

.rf-typing-space,
.rf-typing-indicator {
  min-height: 27px;
}

.rf-typing-indicator {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 28px;
  color: #8d95a6;
  font-size: 10px;
}

.rf-typing-indicator span {
  margin-right: 4px;
}

.rf-typing-indicator i {
  width: 4px;
  height: 4px;
  background: #9da4b2;
  border-radius: 999px;
  animation: rf-typing 1s infinite ease-in-out;
}

.rf-typing-indicator i:nth-of-type(2) {
  animation-delay: 120ms;
}

.rf-typing-indicator i:nth-of-type(3) {
  animation-delay: 240ms;
}

@keyframes rf-typing {
  0%,
  100% {
    opacity: 0.35;
    transform: translateY(0);
  }

  50% {
    opacity: 1;
    transform: translateY(-2px);
  }
}

.rf-message-composer {
  position: relative;
  padding: 0 20px 18px;
  background: #ffffff;
}

.rf-composer-context {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 100%;
  padding: 8px 10px;
  color: #575f72;
  background: var(--rf-chat-primary-soft);
  border-left: 3px solid var(--rf-chat-primary);
  border-radius: 9px 9px 0 0;
}

.rf-composer-context > div {
  min-width: 0;
}

.rf-composer-context strong,
.rf-composer-context span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-composer-context strong {
  font-size: 10px;
}

.rf-composer-context span {
  max-width: 600px;
  margin-top: 2px;
  color: #7b8292;
  font-size: 9px;
}

.rf-composer-context button {
  padding: 2px 6px;
  color: #697184;
  font-size: 18px;
  background: transparent;
  border: 0;
}

.rf-message-composer__body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 10px;
  padding: 9px 9px 9px 14px;
  background: #f7f8fa;
  border: 1px solid var(--rf-chat-border);
  border-radius: 15px;
  box-shadow:
    0 5px 18px rgba(31, 38, 62, 0.04);
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease,
    background 150ms ease;
}

.rf-message-composer:focus-within
  .rf-message-composer__body {
  background: #ffffff;
  border-color: rgba(101, 88, 245, 0.55);
  box-shadow:
    0 0 0 3px rgba(101, 88, 245, 0.08),
    0 7px 20px rgba(31, 38, 62, 0.05);
}

.rf-composer-context
  + .rf-message-composer__body {
  border-top-left-radius: 0;
  border-top-right-radius: 0;
}

.rf-message-composer textarea {
  width: 100%;
  min-height: 36px;
  max-height: 130px;
  padding: 8px 0 5px;
  resize: none;
  overflow-y: auto;
  color: var(--rf-chat-text);
  font-size: 13px;
  line-height: 1.45;
  background: transparent;
  border: 0;
  outline: none;
}

.rf-message-composer textarea::placeholder {
  color: #a0a7b5;
}

.rf-message-composer__body > button {
  min-width: 76px;
  height: 38px;
  padding: 0 16px;
  color: #ffffff;
  font-size: 11px;
  font-weight: 750;
  background: var(--rf-chat-primary);
  border: 0;
  border-radius: 11px;
  box-shadow:
    0 7px 15px rgba(101, 88, 245, 0.2);
}

.rf-message-composer__body > button:hover:not(:disabled) {
  background: var(--rf-chat-primary-dark);
}

.rf-message-composer__body > button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

/* ------------------------------------------------------------------ */
/* Resource panel                                                     */
/* ------------------------------------------------------------------ */

.rf-resource-panel {
  flex: 0 0 292px;
  min-width: 0;
  overflow-y: auto;
  background: #fafbfe;
  border-left: 1px solid var(--rf-chat-border);
}

.rf-resource-panel > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 19px 17px 14px;
  border-bottom: 1px solid var(--rf-chat-border);
}

.rf-resource-panel h3 {
  margin: 0;
  font-size: 14px;
}

.rf-resource-panel header p {
  margin: 4px 0 0;
  color: var(--rf-chat-muted);
  font-size: 10px;
}

.rf-resource-panel header button {
  padding: 0 5px;
  color: #838b9b;
  font-size: 20px;
  background: transparent;
  border: 0;
}

.rf-resource-add {
  width: calc(100% - 28px);
  height: 37px;
  margin: 14px;
  color: var(--rf-chat-primary);
  font-size: 11px;
  font-weight: 750;
  background: var(--rf-chat-primary-soft);
  border: 1px solid rgba(101, 88, 245, 0.18);
  border-radius: 10px;
}

.rf-resource-form {
  display: grid;
  gap: 8px;
  margin: 0 14px 14px;
  padding: 12px;
  background: #ffffff;
  border: 1px solid var(--rf-chat-border);
  border-radius: 12px;
}

.rf-resource-form input,
.rf-resource-form textarea {
  width: 100%;
  padding: 9px 10px;
  color: var(--rf-chat-text);
  font-size: 11px;
  background: #f8f9fb;
  border: 1px solid var(--rf-chat-border);
  border-radius: 9px;
  outline: none;
}

.rf-resource-form textarea {
  min-height: 66px;
  resize: vertical;
}

.rf-resource-form input:focus,
.rf-resource-form textarea:focus {
  background: #ffffff;
  border-color: rgba(101, 88, 245, 0.5);
}

.rf-resource-form button {
  height: 36px;
  color: #ffffff;
  font-size: 10px;
  font-weight: 750;
  background: var(--rf-chat-primary);
  border: 0;
  border-radius: 9px;
}

.rf-resource-list {
  display: grid;
  gap: 8px;
  padding: 0 14px 18px;
}

.rf-resource-card {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 11px;
  color: inherit;
  text-decoration: none;
  background: #ffffff;
  border: 1px solid var(--rf-chat-border);
  border-radius: 12px;
  transition:
    border-color 150ms ease,
    transform 150ms ease;
}

.rf-resource-card:hover {
  border-color: rgba(101, 88, 245, 0.35);
  transform: translateY(-1px);
}

.rf-resource-card > div {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  color: var(--rf-chat-primary);
  font-size: 10px;
  font-weight: 800;
  background: var(--rf-chat-primary-soft);
  border-radius: 10px;
}

.rf-resource-card span {
  min-width: 0;
}

.rf-resource-card strong,
.rf-resource-card small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-resource-card strong {
  font-size: 11px;
}

.rf-resource-card small {
  margin-top: 3px;
  color: var(--rf-chat-muted);
  font-size: 9px;
}

.rf-resource-empty {
  padding: 28px 10px;
  color: var(--rf-chat-muted);
  font-size: 11px;
  line-height: 1.5;
  text-align: center;
}

/* ------------------------------------------------------------------ */
/* Search results                                                     */
/* ------------------------------------------------------------------ */

.rf-search-results {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 20px 26px;
}

.rf-search-results > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--rf-chat-border);
}

.rf-search-results h3 {
  margin: 0;
  font-size: 15px;
}

.rf-search-results header p {
  margin: 4px 0 0;
  color: var(--rf-chat-muted);
  font-size: 10px;
}

.rf-search-results header button {
  color: var(--rf-chat-primary);
  font-size: 10px;
  font-weight: 750;
  background: transparent;
  border: 0;
}

.rf-search-results > div {
  display: grid;
  gap: 8px;
  padding-top: 14px;
}

.rf-search-results article {
  position: relative;
  padding: 12px 14px;
  background: #f8f9fb;
  border: 1px solid var(--rf-chat-border);
  border-radius: 12px;
}

.rf-search-results article strong {
  font-size: 11px;
}

.rf-search-results article p {
  margin: 6px 0;
  color: #555e70;
  font-size: 12px;
  line-height: 1.5;
}

.rf-search-results article time {
  color: #969dad;
  font-size: 9px;
}

/* ------------------------------------------------------------------ */
/* Group dialog                                                       */
/* ------------------------------------------------------------------ */

.rf-modal-backdrop {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(18, 23, 36, 0.48);
  backdrop-filter: blur(5px);
}

.rf-group-dialog {
  width: min(530px, 100%);
  max-height: min(760px, 92vh);
  overflow-y: auto;
  padding: 0;
  background: #ffffff;
  border: 1px solid var(--rf-chat-border);
  border-radius: 20px;
  box-shadow:
    0 28px 80px rgba(18, 23, 36, 0.22);
}

.rf-group-dialog > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 22px 24px 17px;
  border-bottom: 1px solid var(--rf-chat-border);
}

.rf-group-dialog header p {
  margin: 0 0 5px;
  color: var(--rf-chat-primary);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.rf-group-dialog h2 {
  margin: 0;
  font-size: 18px;
  letter-spacing: -0.02em;
}

.rf-group-dialog header button {
  padding: 0 5px;
  color: #81899a;
  font-size: 23px;
  background: transparent;
  border: 0;
}

.rf-group-dialog > label {
  display: grid;
  gap: 7px;
  padding: 14px 24px 0;
  color: #4a5365;
  font-size: 11px;
  font-weight: 700;
}

.rf-group-dialog input,
.rf-group-dialog textarea {
  width: 100%;
  padding: 10px 12px;
  color: var(--rf-chat-text);
  font-size: 12px;
  font-weight: 500;
  background: #f8f9fb;
  border: 1px solid var(--rf-chat-border);
  border-radius: 10px;
  outline: none;
}

.rf-group-dialog textarea {
  min-height: 75px;
  resize: vertical;
}

.rf-group-dialog input:focus,
.rf-group-dialog textarea:focus {
  background: #ffffff;
  border-color: rgba(101, 88, 245, 0.5);
  box-shadow:
    0 0 0 3px rgba(101, 88, 245, 0.08);
}

.rf-group-dialog fieldset {
  margin: 18px 24px 0;
  padding: 0;
  border: 0;
}

.rf-group-dialog legend {
  margin-bottom: 9px;
  color: #4a5365;
  font-size: 11px;
  font-weight: 700;
}

.rf-group-member-list {
  max-height: 260px;
  overflow-y: auto;
  border: 1px solid var(--rf-chat-border);
  border-radius: 12px;
}

.rf-group-member {
  display: grid;
  grid-template-columns: 18px 36px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  min-height: 58px;
  padding: 8px 11px;
  cursor: pointer;
  border-bottom: 1px solid #eef0f4;
}

.rf-group-member:last-child {
  border-bottom: 0;
}

.rf-group-member:hover {
  background: #fafaff;
}

.rf-group-member input {
  width: 15px;
  height: 15px;
  accent-color: var(--rf-chat-primary);
}

.rf-group-member span {
  min-width: 0;
}

.rf-group-member strong,
.rf-group-member small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-group-member strong {
  font-size: 11px;
}

.rf-group-member small {
  margin-top: 2px;
  color: var(--rf-chat-muted);
  font-size: 9px;
}

.rf-group-dialog > footer {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 20px;
  padding: 15px 24px 20px;
  border-top: 1px solid var(--rf-chat-border);
}

.rf-group-dialog > footer button {
  min-width: 94px;
  height: 38px;
  padding: 0 15px;
  color: #596274;
  font-size: 11px;
  font-weight: 750;
  background: #f4f5f8;
  border: 1px solid var(--rf-chat-border);
  border-radius: 10px;
}

.rf-group-dialog > footer button[type="submit"] {
  color: #ffffff;
  background: var(--rf-chat-primary);
  border-color: var(--rf-chat-primary);
}

.rf-group-dialog > footer button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.rf-dialog-error {
  margin: 14px 24px 0;
  padding: 10px 12px;
  color: #963949;
  font-size: 11px;
  background: #fff2f4;
  border: 1px solid #f2d2d8;
  border-radius: 10px;
}

/* ------------------------------------------------------------------ */
/* Calls                                                              */
/* ------------------------------------------------------------------ */

.rf-call-dialog {
  position: fixed;
  z-index: 1100;
  right: 28px;
  bottom: 28px;
  width: min(300px, calc(100vw - 40px));
  padding: 24px;
  text-align: center;
  background: #ffffff;
  border: 1px solid var(--rf-chat-border);
  border-radius: 22px;
  box-shadow:
    0 24px 65px rgba(18, 23, 36, 0.22);
}

.rf-call-dialog__pulse {
  position: relative;
  display: inline-flex;
}

.rf-call-dialog__pulse::before,
.rf-call-dialog__pulse::after {
  position: absolute;
  content: "";
  inset: -8px;
  border: 1px solid rgba(101, 88, 245, 0.32);
  border-radius: 24px;
  animation: rf-call-pulse 1.8s infinite ease-out;
}

.rf-call-dialog__pulse::after {
  animation-delay: 600ms;
}

@keyframes rf-call-pulse {
  0% {
    opacity: 0.8;
    transform: scale(0.9);
  }

  100% {
    opacity: 0;
    transform: scale(1.45);
  }
}

.rf-call-dialog p {
  margin: 17px 0 5px;
  color: var(--rf-chat-muted);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.rf-call-dialog h3 {
  margin: 0;
  font-size: 18px;
}

.rf-call-dialog__actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
  margin-top: 20px;
}

.rf-call-dialog__actions button {
  height: 41px;
  color: #ffffff;
  font-size: 11px;
  font-weight: 750;
  border: 0;
  border-radius: 11px;
}

.rf-call-decline {
  background: var(--rf-chat-danger);
}

.rf-call-accept {
  background: var(--rf-chat-success);
}

.rf-active-call-bar {
  position: fixed;
  z-index: 1050;
  left: 50%;
  bottom: 24px;
  display: grid;
  grid-template-columns: auto minmax(130px, 1fr) auto;
  align-items: center;
  gap: 13px;
  min-width: 330px;
  max-width: calc(100vw - 40px);
  padding: 10px 11px 10px 14px;
  color: #ffffff;
  background:
    linear-gradient(
      135deg,
      #252d43,
      #171d2e
    );
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 15px;
  box-shadow:
    0 18px 48px rgba(18, 23, 36, 0.26);
  transform: translateX(-50%);
}

.rf-active-call-bar__avatars {
  display: flex;
}

.rf-active-call-bar__avatars
  .rf-chat-avatar {
  margin-left: -8px;
  border: 2px solid #20283b;
}

.rf-active-call-bar__avatars
  .rf-chat-avatar:first-child {
  margin-left: 0;
}

.rf-active-call-bar strong,
.rf-active-call-bar small {
  display: block;
}

.rf-active-call-bar strong {
  font-size: 11px;
}

.rf-active-call-bar small {
  margin-top: 2px;
  color: #abb3c5;
  font-size: 9px;
}

.rf-active-call-bar > button {
  height: 37px;
  padding: 0 15px;
  color: #ffffff;
  font-size: 10px;
  font-weight: 750;
  background: var(--rf-chat-danger);
  border: 0;
  border-radius: 10px;
}

/* ------------------------------------------------------------------ */
/* Loading shell                                                      */
/* ------------------------------------------------------------------ */

.rf-team-chat-shell--loading aside {
  background:
    linear-gradient(
      90deg,
      #f1f2f5,
      #f8f9fb,
      #f1f2f5
    );
  background-size: 220% 100%;
  animation: rf-chat-shimmer 1.4s infinite;
}

.rf-team-chat-shell--loading > section {
  display: flex;
  flex-direction: column;
}

.rf-team-chat-shell--loading
  > section
  > header {
  height: 76px;
  background: #f7f8fa;
  border-bottom: 1px solid var(--rf-chat-border);
}

.rf-team-chat-shell--loading
  > section
  > div {
  flex: 1;
  margin: 24px;
  background:
    linear-gradient(
      90deg,
      #f4f5f7,
      #fafbfc,
      #f4f5f7
    );
  background-size: 220% 100%;
  border-radius: 16px;
  animation: rf-chat-shimmer 1.4s infinite;
}

@keyframes rf-chat-shimmer {
  0% {
    background-position: 100% 0;
  }

  100% {
    background-position: -100% 0;
  }
}

/* ------------------------------------------------------------------ */
/* Responsive                                                         */
/* ------------------------------------------------------------------ */

@media (max-width: 1180px) {
  .rf-chat-header {
    grid-template-columns: minmax(160px, 1fr) auto;
  }

  .rf-chat-search {
    display: none;
  }

  .rf-resource-panel {
    position: absolute;
    z-index: 30;
    top: 76px;
    right: 0;
    bottom: 0;
    width: 300px;
    box-shadow:
      -12px 0 30px rgba(31, 38, 62, 0.09);
  }

  .rf-chat-main {
    position: relative;
  }
}

@media (max-width: 900px) {
  .rf-team-chat-page {
    padding: 12px;
  }

  .rf-team-chat-shell {
    grid-template-columns: 260px minmax(0, 1fr);
    height: calc(100vh - 96px);
    min-height: 620px;
    border-radius: 17px;
  }

  .rf-chat-sidebar__header {
    padding-right: 14px;
