  }

  .rf-sidebar-channel > span {
    font-size: 21px;
  }

  .rf-sidebar-channel > div {
    display: none;
  }

  .rf-sidebar-channel b {
    position: absolute;
    margin-top: -36px;
    margin-left: 37px;
    min-width: 16px;
    height: 16px;
    padding: 0 4px;
    font-size: 8px;
  }

  .rf-sidebar-person {
