  .rf-chat-action-button:nth-child(1)::after {
    content: "R";
  }

  .rf-chat-action-button:nth-last-child(2)::after {
    content: "â˜Ž";
  }

  .rf-chat-action-button:last-child::after {
    content: "â—‰";
  }

  .rf-message-list {
    padding: 16px 11px 10px;
  }

  .rf-message-block {
    max-width: 88%;
  }

  .rf-message-row {
    grid-template-columns: 30px minmax(0, 1fr);
    gap: 7px;
  }

  .rf-message-row
    > .rf-chat-avatar {
    width: 30px;
    height: 30px;
  }

  .rf-message-avatar-spacer {
    width: 30px;
  }

  .rf-message-bubble {
    padding: 9px 11px;
  }

  .rf-message-bubble p {
