  }

  .rf-message-composer {
    padding: 0 8px 9px;
  }

  .rf-message-composer__body {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 6px;
    padding-left: 10px;
  }

  .rf-message-composer__body > button {
    min-width: 58px;
    padding: 0 10px;
  }

  .rf-typing-indicator {
    padding: 0 12px;
  }

  .rf-resource-panel {
    top: 64px;
    width: min(300px, calc(100vw - 88px));
  }

  .rf-group-dialog {
    max-height: 94vh;
    border-radius: 16px;
  }

  .rf-active-call-bar {
    bottom: 12px;
    min-width: auto;
    width: calc(100vw - 24px);
  }
}

@media (max-width: 480px) {
  .rf-team-chat-shell {
    grid-template-columns: 68px minmax(0, 1fr);
  }

  .rf-sidebar-channel {
    width: 44px;
    height: 44px;
  }

  .rf-sidebar-person {
    width: 48px;
  }

  .rf-chat-header__actions {
    gap: 4px;
  }

  .rf-chat-action-button {
    width: 32px;
    min-width: 32px;
    height: 32px;
    min-height: 32px;
  }

  .rf-resource-panel {
    width: calc(100vw - 68px);
  }

  .rf-message-row {
    grid-template-columns: 0 minmax(0, 1fr);
    gap: 0;
  }

  .rf-message-row
    > .rf-chat-avatar,
  .rf-message-avatar-spacer {
    display: none;
  }

  .rf-message-block {
    max-width: 94%;
  }

  .rf-group-dialog > header,
  .rf-group-dialog > label,
  .rf-group-dialog > footer {
    padding-right: 17px;
    padding-left: 17px;
  }

  .rf-group-dialog fieldset {
    margin-right: 17px;
    margin-left: 17px;
  }

  .rf-dialog-error {
    margin-right: 17px;
    margin-left: 17px;
  }
}

/* ------------------------------------------------------------------ */
/* Dark mode support                                                  */
/* ------------------------------------------------------------------ */

@media (prefers-color-scheme: dark) {
  .rf-team-chat-page[data-theme="system"] {
    --rf-chat-bg: #111522;
    --rf-chat-panel: #181d2b;
    --rf-chat-border: #2a3142;
    --rf-chat-text: #edf0f7;
    --rf-chat-muted: #9ba4b7;
    --rf-chat-soft: #222838;
  }
}

[data-theme="dark"] .rf-team-chat-page,
.dark .rf-team-chat-page {
  --rf-chat-bg: #111522;
  --rf-chat-panel: #181d2b;
  --rf-chat-border: #2a3142;
  --rf-chat-text: #edf0f7;
  --rf-chat-muted: #9ba4b7;
  --rf-chat-soft: #222838;

  background:
    radial-gradient(
      circle at top right,
      rgba(101, 88, 245, 0.11),
      transparent 28%
    ),
    var(--rf-chat-bg);
}

[data-theme="dark"]
  .rf-chat-sidebar,
.dark .rf-chat-sidebar {
  background: #151a27;
}

[data-theme="dark"]
  .rf-chat-main,
[data-theme="dark"]
  .rf-message-area,
[data-theme="dark"]
  .rf-message-composer,
.dark .rf-chat-main,
.dark .rf-message-area,
.dark .rf-message-composer {
  background: #181d2b;
}

[data-theme="dark"]
  .rf-chat-header,
[data-theme="dark"]
  .rf-chat-sidebar__profile,
.dark .rf-chat-header,
.dark .rf-chat-sidebar__profile {
  background: rgba(24, 29, 43, 0.92);
}

[data-theme="dark"]
  .rf-sidebar-search input,
[data-theme="dark"]
  .rf-chat-search input,
.dark .rf-sidebar-search input,
.dark .rf-chat-search input {
  color: var(--rf-chat-text);
  background-color: #202637;
}

[data-theme="dark"]
  .rf-sidebar-channel:hover,
[data-theme="dark"]
  .rf-sidebar-person:hover,
.dark .rf-sidebar-channel:hover,
.dark .rf-sidebar-person:hover {
  background: #202637;
}

[data-theme="dark"]
  .rf-message-bubble,
.dark .rf-message-bubble {
  color: #e5e9f2;
  background: #242a3a;
  border-color: #2d3446;
}

[data-theme="dark"]
  .rf-message-composer__body,
.dark .rf-message-composer__body {
  background: #202637;
}

[data-theme="dark"]
  .rf-resource-panel,
.dark .rf-resource-panel {
  background: #151a27;
}

[data-theme="dark"]
  .rf-resource-card,
[data-theme="dark"]
  .rf-resource-form,
.dark .rf-resource-card,
.dark .rf-resource-form {
  background: #1e2433;
}

[data-theme="dark"]
  .rf-group-dialog,
.dark .rf-group-dialog {
  background: #1b2130;
}

[data-theme="dark"]
  .rf-group-dialog input,
[data-theme="dark"]
  .rf-group-dialog textarea,
.dark .rf-group-dialog input,
.dark .rf-group-dialog textarea {
  color: var(--rf-chat-text);
  background: #222838;
}
.rf-role-dashboard {
  --rf-dashboard-bg: #f6f7fb;
  --rf-dashboard-panel: #ffffff;
  --rf-dashboard-border: #e5e8f0;
  --rf-dashboard-text: #182033;
  --rf-dashboard-muted: #747d91;
  --rf-dashboard-primary: #6558f5;
  --rf-dashboard-primary-dark: #5144dc;
  --rf-dashboard-primary-soft: #efedff;
  --rf-dashboard-success: #1f9b65;
  --rf-dashboard-success-soft: #eaf8f1;
  --rf-dashboard-warning: #d48a18;
  --rf-dashboard-warning-soft: #fff6e6;
  --rf-dashboard-danger: #d84c5e;
  --rf-dashboard-danger-soft: #fff0f3;
  --rf-dashboard-info: #2c76d2;
  --rf-dashboard-info-soft: #edf5ff;
  --rf-dashboard-shadow:
    0 18px 50px rgba(27, 35, 58, 0.07);

  width: 100%;
  min-height: calc(100vh - 72px);
  padding: 26px;
  color: var(--rf-dashboard-text);
  background:
    radial-gradient(
      circle at top right,
      rgba(101, 88, 245, 0.07),
      transparent 28%
    ),
    var(--rf-dashboard-bg);
  box-sizing: border-box;
}

.rf-role-dashboard *,
.rf-role-dashboard *::before,
.rf-role-dashboard *::after {
  box-sizing: border-box;
}

.rf-role-dashboard button,
.rf-role-dashboard input,
.rf-role-dashboard textarea,
.rf-role-dashboard select {
  font: inherit;
}

.rf-role-dashboard button,
.rf-role-dashboard a {
  -webkit-tap-highlight-color: transparent;
}

/* ------------------------------------------------------------------ */
/* Header                                                             */
/* ------------------------------------------------------------------ */

.rf-dashboard-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
  padding: 24px 26px;
  background:
    linear-gradient(
      135deg,
      rgba(101, 88, 245, 0.05),
      transparent 42%
    ),
    var(--rf-dashboard-panel);
  border: 1px solid var(--rf-dashboard-border);
  border-radius: 22px;
  box-shadow: var(--rf-dashboard-shadow);
}

.rf-dashboard-header__identity {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 16px;
}

.rf-dashboard-header__identity > div:last-child {
  min-width: 0;
}

.rf-dashboard-eyebrow {
  margin: 0 0 5px;
  color: var(--rf-dashboard-primary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.rf-dashboard-header h1 {
  margin: 0;
  overflow: hidden;
  color: var(--rf-dashboard-text);
  font-size: clamp(24px, 3vw, 33px);
  font-weight: 780;
  letter-spacing: -0.04em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-dashboard-subtitle {
  margin: 7px 0 0;
  color: var(--rf-dashboard-muted);
  font-size: 13px;
}

.rf-dashboard-header__actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.rf-server-status {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 188px;
  padding: 10px 13px;
  background: #f8fafc;
  border: 1px solid var(--rf-dashboard-border);
  border-radius: 13px;
}

.rf-server-status > div {
  min-width: 0;
}

.rf-server-status strong,
.rf-server-status small {
  display: block;
}

.rf-server-status strong {
  color: #40495b;
  font-size: 11px;
}

.rf-server-status small {
  margin-top: 2px;
  color: var(--rf-dashboard-muted);
  font-size: 9px;
}

.rf-status-dot {
  width: 10px;
  height: 10px;
  flex: 0 0 auto;
  background: var(--rf-dashboard-success);
  border-radius: 999px;
  box-shadow:
    0 0 0 5px rgba(31, 155, 101, 0.11);
}

/* ------------------------------------------------------------------ */
/* Buttons and links                                                  */
/* ------------------------------------------------------------------ */

.rf-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 16px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 750;
  text-decoration: none;
  background: var(--rf-dashboard-primary);
  border: 1px solid var(--rf-dashboard-primary);
  border-radius: 11px;
  box-shadow:
    0 8px 18px rgba(101, 88, 245, 0.2);
  cursor: pointer;
  transition:
    transform 150ms ease,
    background 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.rf-button:hover:not(:disabled) {
  background: var(--rf-dashboard-primary-dark);
  border-color: var(--rf-dashboard-primary-dark);
  transform: translateY(-1px);
  box-shadow:
    0 11px 23px rgba(101, 88, 245, 0.24);
}

.rf-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.rf-button--secondary {
  color: #596174;
  background: #ffffff;
  border-color: var(--rf-dashboard-border);
  box-shadow: none;
}

.rf-button--secondary:hover:not(:disabled) {
  color: var(--rf-dashboard-primary);
  background: var(--rf-dashboard-primary-soft);
  border-color: rgba(101, 88, 245, 0.25);
  box-shadow: none;
}

.rf-button--compact {
  min-height: 34px;
  padding: 0 12px;
  font-size: 10px;
  border-radius: 9px;
}

.rf-text-link {
  color: var(--rf-dashboard-primary);
  font-size: 11px;
  font-weight: 750;
  text-decoration: none;
}

.rf-text-link:hover {
  color: var(--rf-dashboard-primary-dark);
  text-decoration: underline;
}

/* ------------------------------------------------------------------ */
/* Alerts                                                             */
/* ------------------------------------------------------------------ */

.rf-inline-alert {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 18px;
  padding: 12px 15px;
  color: #8b3443;
  background: var(--rf-dashboard-danger-soft);
  border: 1px solid #f0d1d7;
  border-radius: 12px;
}

.rf-inline-alert span {
  font-size: 12px;
  line-height: 1.45;
}

.rf-inline-alert button {
  padding: 5px 9px;
  color: #8b3443;
  font-size: 10px;
  font-weight: 750;
  background: transparent;
  border: 0;
  cursor: pointer;
}

/* ------------------------------------------------------------------ */
/* Metrics                                                            */
/* ------------------------------------------------------------------ */

.rf-metric-grid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(190px, 1fr)
    );
  gap: 14px;
  margin-bottom: 18px;
}

.rf-metric-card {
  position: relative;
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  align-items: center;
  min-width: 0;
  gap: 13px;
  min-height: 116px;
  padding: 18px;
  overflow: hidden;
  background: var(--rf-dashboard-panel);
  border: 1px solid var(--rf-dashboard-border);
  border-radius: 17px;
  box-shadow:
    0 9px 28px rgba(28, 35, 57, 0.045);
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.rf-metric-card::after {
  position: absolute;
  content: "";
  right: -28px;
  bottom: -33px;
  width: 94px;
  height: 94px;
  background: rgba(101, 88, 245, 0.04);
  border-radius: 999px;
}

.rf-metric-card:hover {
  border-color: rgba(101, 88, 245, 0.23);
  transform: translateY(-2px);
  box-shadow:
    0 15px 34px rgba(28, 35, 57, 0.075);
}

.rf-metric-card__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  color: var(--rf-dashboard-primary);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.04em;
  background: var(--rf-dashboard-primary-soft);
  border: 1px solid rgba(101, 88, 245, 0.12);
  border-radius: 13px;
}

.rf-metric-card > div:last-child {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.rf-metric-card p,
.rf-metric-card strong,
.rf-metric-card small {
  display: block;
}

.rf-metric-card p {
  margin: 0;
  overflow: hidden;
  color: var(--rf-dashboard-muted);
  font-size: 10px;
  font-weight: 700;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.rf-metric-card strong {
  margin-top: 5px;
  color: var(--rf-dashboard-text);
  font-size: 25px;
  font-weight: 790;
  letter-spacing: -0.04em;
}

.rf-metric-card small {
  margin-top: 4px;
  overflow: hidden;
  color: #8a92a3;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ------------------------------------------------------------------ */
/* Layout                                                             */
/* ------------------------------------------------------------------ */

.rf-dashboard-columns {
  display: grid;
  grid-template-columns:
    minmax(0, 1.65fr)
    minmax(280px, 0.8fr);
  gap: 18px;
  margin-bottom: 18px;
}

.rf-dashboard-columns__primary,
.rf-dashboard-columns__secondary {
  min-width: 0;
}

.rf-panel {
  min-width: 0;
  height: 100%;
  padding: 20px;
  background: var(--rf-dashboard-panel);
  border: 1px solid var(--rf-dashboard-border);
  border-radius: 18px;
  box-shadow:
    0 10px 30px rgba(27, 35, 58, 0.045);
}

.rf-panel + .rf-panel {
  margin-top: 18px;
}

.rf-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 16px;
}

.rf-panel-header > div {
  min-width: 0;
}

.rf-panel-header h2 {
  margin: 0;
  color: var(--rf-dashboard-text);
  font-size: 16px;
  font-weight: 760;
  letter-spacing: -0.02em;
}

.rf-panel-header p {
  max-width: 690px;
  margin: 5px 0 0;
  color: var(--rf-dashboard-muted);
  font-size: 10px;
  line-height: 1.5;
}

/* ------------------------------------------------------------------ */
/* Tables                                                             */
/* ------------------------------------------------------------------ */

.rf-table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid #edf0f5;
  border-radius: 13px;
  scrollbar-width: thin;
  scrollbar-color: #cdd3df transparent;
}

.rf-table {
  width: 100%;
  min-width: 790px;
  border-collapse: collapse;
}

.rf-table th,
.rf-table td {
  padding: 12px 14px;
  text-align: left;
  border-bottom: 1px solid #edf0f5;
}

.rf-table th {
  color: #7d8597;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  background: #fafbfc;
}

.rf-table td {
  color: #454e61;
  font-size: 11px;
}

.rf-table tbody tr:last-child td {
  border-bottom: 0;
}

.rf-table tbody tr {
  transition: background 140ms ease;
}

.rf-table tbody tr:hover {
  background: #fbfbfe;
}

/* ------------------------------------------------------------------ */
/* Member identity and avatar                                         */
/* ------------------------------------------------------------------ */

.rf-member-identity {
  display: flex;
  align-items: center;
  min-width: 175px;
  gap: 10px;
}

.rf-member-identity > div:nth-child(2) {
  min-width: 0;
}

.rf-member-identity strong,
.rf-member-identity small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-member-identity strong {
  color: #2f3748;
  font-size: 11px;
}

.rf-member-identity small {
  margin-top: 2px;
  color: var(--rf-dashboard-muted);
  font-size: 9px;
}

.rf-online-indicator {
  width: 8px;
  height: 8px;
  margin-left: auto;
  flex: 0 0 auto;
  background: var(--rf-dashboard-success);
  border-radius: 999px;
  box-shadow:
    0 0 0 4px rgba(31, 155, 101, 0.1);
}

.rf-avatar {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  overflow: hidden;
  color: var(--rf-dashboard-primary);
  background:
    linear-gradient(
      145deg,
      #e8e5ff,
      #f5f3ff
    );
  border: 1px solid rgba(101, 88, 245, 0.14);
  border-radius: 11px;
}

.rf-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rf-avatar span {
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.02em;
}

.rf-avatar--large {
  width: 58px;
  height: 58px;
  border-radius: 17px;
}

.rf-avatar--large span {
  font-size: 15px;
}

.rf-avatar-stack {
  display: flex;
  align-items: center;
  margin-top: 16px;
}

.rf-avatar-stack > div {
  margin-left: -8px;
}

.rf-avatar-stack > div:first-child {
  margin-left: 0;
}

.rf-avatar-stack .rf-avatar {
  border: 3px solid #ffffff;
}

/* ------------------------------------------------------------------ */
/* Status badges                                                      */
/* ------------------------------------------------------------------ */

.rf-status-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 9px;
  color: #60697a;
  font-size: 9px;
  font-weight: 750;
  white-space: nowrap;
  background: #f1f3f6;
  border: 1px solid #e2e6ec;
  border-radius: 999px;
}

.rf-status-badge--large {
  min-height: 31px;
  padding: 0 13px;
  font-size: 10px;
}

.rf-status-badge--present,
.rf-status-badge--completed,
.rf-status-badge--answered,
.rf-status-badge--connected,
.rf-status-badge--qualified,
.rf-status-badge--available,
.rf-status-badge--online,
.rf-status-badge--successful,
.rf-status-badge--meeting_booked {
  color: #167a4e;
  background: var(--rf-dashboard-success-soft);
  border-color: #ccebdd;
}

.rf-status-badge--late,
.rf-status-badge--pending,
.rf-status-badge--busy,
.rf-status-badge--follow_up,
.rf-status-badge--normal,
.rf-status-badge--in_progress,
.rf-status-badge--assigned {
  color: #9a6413;
  background: var(--rf-dashboard-warning-soft);
  border-color: #f2dfb8;
}

.rf-status-badge--half_day,
.rf-status-badge--away,
.rf-status-badge--interested,
.rf-status-badge--high {
  color: #9b5d13;
  background: #fff2df;
  border-color: #f2d3aa;
}

.rf-status-badge--failed,
.rf-status-badge--declined,
.rf-status-badge--cancelled,
.rf-status-badge--absent,
.rf-status-badge--urgent,
.rf-status-badge--do_not_contact,
.rf-status-badge--suspended {
  color: #a53b4b;
  background: var(--rf-dashboard-danger-soft);
  border-color: #efcfd5;
}

.rf-status-badge--not_checked_in,
.rf-status-badge--offline,
.rf-status-badge--viewer,
.rf-status-badge--unknown {
  color: #687184;
  background: #f1f3f6;
  border-color: #e0e4eb;
}

.rf-status-badge--active,
.rf-status-badge--running,
.rf-status-badge--processing,
.rf-status-badge--caller,
.rf-status-badge--manager,
.rf-status-badge--owner,
.rf-status-badge--admin {
  color: #326db7;
  background: var(--rf-dashboard-info-soft);
  border-color: #d5e6fa;
}

/* ------------------------------------------------------------------ */
/* Attendance                                                         */
/* ------------------------------------------------------------------ */

.rf-attendance-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
  padding: 22px 24px;
  background:
    linear-gradient(
      135deg,
      rgba(101, 88, 245, 0.07),
      rgba(31, 155, 101, 0.03)
    ),
    var(--rf-dashboard-panel);
  border: 1px solid rgba(101, 88, 245, 0.15);
  border-radius: 18px;
  box-shadow:
    0 12px 31px rgba(27, 35, 58, 0.05);
}

.rf-attendance-hero h2 {
  margin: 0;
  font-size: 19px;
  font-weight: 760;
  letter-spacing: -0.02em;
}

.rf-attendance-hero > div > p:last-child {
  margin: 7px 0 0;
  color: var(--rf-dashboard-muted);
  font-size: 11px;
  line-height: 1.5;
}

.rf-summary-list {
  display: grid;
  gap: 4px;
}

.rf-summary-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 39px;
  padding: 0 11px;
  border-bottom: 1px solid #eef0f4;
}

.rf-summary-row:last-child {
  border-bottom: 0;
}

.rf-summary-row span {
  color: var(--rf-dashboard-muted);
  font-size: 10px;
}

.rf-summary-row strong {
  color: var(--rf-dashboard-text);
  font-size: 12px;
}

/* ------------------------------------------------------------------ */
/* Lead cards                                                         */
/* ------------------------------------------------------------------ */

.rf-lead-list {
  display: grid;
  gap: 9px;
}

.rf-lead-item {
  display: grid;
  grid-template-columns:
    42px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding: 12px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 13px;
  transition:
    border-color 150ms ease,
    background 150ms ease,
    transform 150ms ease;
}

.rf-lead-item:hover {
  background: #ffffff;
  border-color: rgba(101, 88, 245, 0.24);
  transform: translateY(-1px);
}

.rf-lead-item__content {
  min-width: 0;
}

.rf-lead-item__content strong,
.rf-lead-item__content span,
.rf-lead-item__content small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-lead-item__content strong {
  color: #333b4d;
  font-size: 11px;
}

.rf-lead-item__content span {
  margin-top: 4px;
  color: #565f72;
  font-size: 10px;
}

.rf-lead-item__content small {
  margin-top: 3px;
  color: var(--rf-dashboard-muted);
  font-size: 9px;
}

.rf-lead-item__actions {
  display: flex;
  align-items: center;
  gap: 9px;
}

.rf-audit-ready,
.rf-audit-pending {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 8px;
  font-size: 8px;
  font-weight: 750;
  white-space: nowrap;
  border-radius: 999px;
}

.rf-audit-ready {
  color: #167a4e;
  background: var(--rf-dashboard-success-soft);
  border: 1px solid #ccebdd;
}

.rf-audit-pending {
  color: #8b641c;
  background: var(--rf-dashboard-warning-soft);
  border: 1px solid #efddb8;
}

/* ------------------------------------------------------------------ */
/* Compact lists                                                      */
/* ------------------------------------------------------------------ */

.rf-compact-list,
.rf-task-list,
.rf-call-list,
.rf-activity-list,
.rf-tool-card-list {
  display: grid;
  gap: 7px;
}

.rf-compact-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 48px;
  padding: 9px 11px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 11px;
}

.rf-compact-row > div {
  min-width: 0;
}

.rf-compact-row strong,
.rf-compact-row small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-compact-row strong {
  color: #3a4355;
  font-size: 10px;
}

.rf-compact-row small {
  margin-top: 3px;
  color: var(--rf-dashboard-muted);
  font-size: 9px;
}

.rf-overdue-label {
  color: #a13a4a;
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
}

/* ------------------------------------------------------------------ */
/* Tasks                                                              */
/* ------------------------------------------------------------------ */

.rf-task-item {
  display: grid;
  grid-template-columns: 27px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 52px;
  padding: 9px 11px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 11px;
}

.rf-task-check {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 25px;
  height: 25px;
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  background: var(--rf-dashboard-success);
  border-radius: 8px;
}

.rf-task-item > div:nth-child(2) {
  min-width: 0;
}

.rf-task-item strong,
.rf-task-item small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-task-item strong {
  font-size: 10px;
}

.rf-task-item small {
  margin-top: 3px;
  color: var(--rf-dashboard-muted);
  font-size: 9px;
}

/* ------------------------------------------------------------------ */
/* Calls                                                              */
/* ------------------------------------------------------------------ */

.rf-call-item {
  display: grid;
  grid-template-columns:
    34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 54px;
  padding: 9px 11px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 11px;
}

.rf-call-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 33px;
  height: 33px;
  color: var(--rf-dashboard-primary);
  font-size: 13px;
  background: var(--rf-dashboard-primary-soft);
  border-radius: 10px;
}

.rf-call-item__content {
  min-width: 0;
}

.rf-call-item__content strong,
.rf-call-item__content small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-call-item__content strong {
  font-size: 10px;
}

.rf-call-item__content small {
  margin-top: 3px;
  color: var(--rf-dashboard-muted);
  font-size: 9px;
}

.rf-call-item__meta {
  display: flex;
  align-items: flex-end;
  flex-direction: column;
  gap: 4px;
}

.rf-call-item__meta small {
  color: var(--rf-dashboard-muted);
  font-size: 8px;
}

/* ------------------------------------------------------------------ */
/* Tools                                                              */
/* ------------------------------------------------------------------ */

.rf-tool-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 51px;
  padding: 10px 12px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 11px;
}

.rf-tool-row > div {
  min-width: 0;
}

.rf-tool-row span,
.rf-tool-row small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-tool-row span {
  color: var(--rf-dashboard-muted);
  font-size: 9px;
  font-weight: 650;
}

.rf-tool-row small {
  margin-top: 3px;
  color: #9199a8;
  font-size: 8px;
}

.rf-tool-row strong {
  max-width: 55%;
  overflow: hidden;
  color: #3c4558;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ------------------------------------------------------------------ */
/* Team directory                                                     */
/* ------------------------------------------------------------------ */

.rf-member-grid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(250px, 1fr)
    );
  gap: 10px;
}

.rf-member-card {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  min-width: 0;
  padding: 12px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 13px;
}

.rf-member-card > div:nth-child(2) {
  min-width: 0;
}

.rf-member-card strong,
.rf-member-card span,
.rf-member-card small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-member-card strong {
  color: #343d50;
  font-size: 11px;
}

.rf-member-card span {
  margin-top: 3px;
  color: #667084;
  font-size: 9px;
}

.rf-member-card small {
  margin-top: 3px;
  color: #959cac;
  font-size: 8px;
}

/* ------------------------------------------------------------------ */
/* Activity                                                           */
/* ------------------------------------------------------------------ */

.rf-activity-item {
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr);
  gap: 9px;
  min-height: 43px;
  padding: 8px 4px;
  border-bottom: 1px solid #eef0f4;
}

.rf-activity-item:last-child {
  border-bottom: 0;
}

.rf-activity-dot {
  width: 8px;
  height: 8px;
  margin-top: 5px;
  background: var(--rf-dashboard-primary);
  border-radius: 999px;
  box-shadow:
    0 0 0 4px rgba(101, 88, 245, 0.09);
}

.rf-activity-item strong,
.rf-activity-item small {
  display: block;
}

.rf-activity-item strong {
  color: #424b5e;
  font-size: 10px;
}

.rf-activity-item small {
  margin-top: 3px;
  color: var(--rf-dashboard-muted);
  font-size: 8px;
}

/* ------------------------------------------------------------------ */
/* Empty states                                                       */
/* ------------------------------------------------------------------ */

.rf-empty-state {
  display: flex;
  min-height: 190px;
  padding: 25px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: #fafbfc;
  border: 1px dashed #dfe3eb;
  border-radius: 13px;
}

.rf-empty-state__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  margin-bottom: 12px;
  color: var(--rf-dashboard-primary);
  font-size: 12px;
  font-weight: 850;
  background: var(--rf-dashboard-primary-soft);
  border-radius: 14px;
}

.rf-empty-state strong {
  color: #3b4457;
  font-size: 12px;
}

.rf-empty-state p {
  max-width: 340px;
  margin: 7px 0 0;
  color: var(--rf-dashboard-muted);
  font-size: 10px;
  line-height: 1.55;
}

/* ------------------------------------------------------------------ */
/* Loading skeleton                                                   */
/* ------------------------------------------------------------------ */

.rf-dashboard-skeleton-header,
.rf-skeleton-card,
.rf-dashboard-skeleton-panel {
  background:
    linear-gradient(
      90deg,
      #eff1f5,
      #f8f9fb,
      #eff1f5
    );
  background-size: 220% 100%;
  animation:
    rf-dashboard-shimmer
    1.4s infinite;
}

.rf-dashboard-skeleton-header {
  height: 128px;
  margin-bottom: 20px;
  border-radius: 22px;
}

.rf-skeleton-card {
  height: 116px;
  border-radius: 17px;
}

.rf-dashboard-skeleton-panel {
  height: 340px;
  margin-bottom: 18px;
  border-radius: 18px;
}

@keyframes rf-dashboard-shimmer {
  0% {
    background-position: 100% 0;
  }

  100% {
    background-position: -100% 0;
  }
}

/* ------------------------------------------------------------------ */
/* Error page                                                         */
/* ------------------------------------------------------------------ */

.rf-dashboard-error {
  display: flex;
  min-height: calc(100vh - 72px);
  padding: 40px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--rf-dashboard-text, #182033);
  text-align: center;
  background: #f6f7fb;
}

.rf-dashboard-error__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin-bottom: 14px;
  color: #a13a4a;
  font-size: 24px;
  font-weight: 800;
  background: #fff0f3;
  border: 1px solid #efcfd5;
  border-radius: 18px;
}

.rf-dashboard-error h1 {
  margin: 0;
  font-size: 21px;
}

.rf-dashboard-error p {
  max-width: 460px;
  margin: 9px 0 18px;
  color: #747d91;
  font-size: 12px;
  line-height: 1.55;
}

/* ------------------------------------------------------------------ */
/* Responsive                                                         */
/* ------------------------------------------------------------------ */

@media (max-width: 1180px) {
  .rf-dashboard-columns {
    grid-template-columns:
      minmax(0, 1.35fr)
      minmax(260px, 0.85fr);
  }

  .rf-dashboard-header {
    align-items: flex-start;
  }

  .rf-dashboard-header__actions {
    align-items: flex-end;
    flex-direction: column;
  }
}

@media (max-width: 960px) {
  .rf-role-dashboard {
    padding: 18px;
  }

  .rf-dashboard-header {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-dashboard-header__actions {
    align-items: center;
    justify-content: space-between;
    flex-direction: row;
  }

  .rf-dashboard-columns {
    grid-template-columns: 1fr;
  }

  .rf-server-status {
    min-width: 0;
  }
}

@media (max-width: 720px) {
  .rf-role-dashboard {
    padding: 12px;
  }

  .rf-dashboard-header {
    margin-bottom: 14px;
    padding: 18px;
    border-radius: 17px;
  }

  .rf-dashboard-header h1 {
    font-size: 23px;
  }

  .rf-dashboard-header__identity {
    align-items: flex-start;
  }

  .rf-dashboard-header__actions {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-server-status {
    width: 100%;
  }

  .rf-button--secondary {
    width: 100%;
  }

  .rf-metric-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
    gap: 9px;
  }

  .rf-metric-card {
    grid-template-columns: 38px minmax(0, 1fr);
    min-height: 102px;
    gap: 10px;
    padding: 13px;
    border-radius: 14px;
  }

  .rf-metric-card__icon {
    width: 38px;
    height: 38px;
    font-size: 9px;
    border-radius: 11px;
  }

  .rf-metric-card strong {
    font-size: 21px;
  }

  .rf-panel {
    padding: 15px;
    border-radius: 15px;
  }

  .rf-attendance-hero {
    align-items: flex-start;
    flex-direction: column;
    padding: 17px;
  }

  .rf-lead-item {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .rf-lead-item__actions {
    grid-column: 1 / -1;
    justify-content: flex-end;
  }

  .rf-member-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .rf-role-dashboard {
    padding: 8px;
  }

  .rf-dashboard-header {
    padding: 15px;
  }

  .rf-dashboard-header__identity {
    gap: 11px;
  }

  .rf-dashboard-header .rf-avatar--large {
    width: 49px;
    height: 49px;
    border-radius: 14px;
  }

  .rf-dashboard-header h1 {
    font-size: 20px;
  }

  .rf-dashboard-subtitle {
    font-size: 11px;
  }

  .rf-metric-grid {
    grid-template-columns: 1fr;
  }

  .rf-metric-card {
    min-height: 94px;
  }

  .rf-panel-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .rf-call-item,
  .rf-task-item {
    grid-template-columns: 32px minmax(0, 1fr);
  }

  .rf-call-item__meta,
  .rf-task-item .rf-status-badge {
    grid-column: 1 / -1;
    align-items: center;
    justify-self: end;
    flex-direction: row;
  }

  .rf-member-card {
    grid-template-columns: 44px minmax(0, 1fr);
  }

  .rf-member-card .rf-status-badge {
    grid-column: 1 / -1;
    justify-self: end;
  }
}

/* ------------------------------------------------------------------ */
/* Dark theme                                                         */
/* ------------------------------------------------------------------ */

[data-theme="dark"] .rf-role-dashboard,
.dark .rf-role-dashboard {
  --rf-dashboard-bg: #111521;
  --rf-dashboard-panel: #191e2b;
  --rf-dashboard-border: #2a3040;
  --rf-dashboard-text: #edf0f7;
  --rf-dashboard-muted: #9da5b7;
  --rf-dashboard-primary-soft: #292442;
  --rf-dashboard-success-soft: #173528;
  --rf-dashboard-warning-soft: #3a2d17;
  --rf-dashboard-danger-soft: #3a1e25;
  --rf-dashboard-info-soft: #1c2d45;

  background:
    radial-gradient(
      circle at top right,
      rgba(101, 88, 245, 0.1),
      transparent 28%
    ),
    var(--rf-dashboard-bg);
}

[data-theme="dark"] .rf-dashboard-header,
[data-theme="dark"] .rf-panel,
[data-theme="dark"] .rf-metric-card,
[data-theme="dark"] .rf-attendance-hero,
.dark .rf-dashboard-header,
.dark .rf-panel,
.dark .rf-metric-card,
.dark .rf-attendance-hero {
  background-color: var(--rf-dashboard-panel);
}

[data-theme="dark"] .rf-server-status,
[data-theme="dark"] .rf-compact-row,
[data-theme="dark"] .rf-task-item,
[data-theme="dark"] .rf-call-item,
[data-theme="dark"] .rf-tool-row,
[data-theme="dark"] .rf-member-card,
[data-theme="dark"] .rf-lead-item,
[data-theme="dark"] .rf-empty-state,
.dark .rf-server-status,
.dark .rf-compact-row,
.dark .rf-task-item,
.dark .rf-call-item,
.dark .rf-tool-row,
.dark .rf-member-card,
.dark .rf-lead-item,
.dark .rf-empty-state {
  background: #202636;
  border-color: #2c3344;
}

[data-theme="dark"] .rf-table th,
.dark .rf-table th {
  background: #202636;
}

[data-theme="dark"] .rf-table td,
[data-theme="dark"] .rf-table th,
.dark .rf-table td,
.dark .rf-table th {
  border-color: #2b3242;
}

[data-theme="dark"] .rf-table tbody tr:hover,
.dark .rf-table tbody tr:hover {
  background: #202636;
}

[data-theme="dark"] .rf-button--secondary,
.dark .rf-button--secondary {
  color: #d3d8e3;
  background: #202636;
}

[data-theme="dark"] .rf-avatar-stack .rf-avatar,
.dark .rf-avatar-stack .rf-avatar {
  border-color: #191e2b;
}
.rf-attendance-page {
  --rf-attendance-bg: #f6f7fb;
  --rf-attendance-panel: #ffffff;
  --rf-attendance-border: #e4e8f0;
  --rf-attendance-text: #182033;
  --rf-attendance-muted: #737c8f;
  --rf-attendance-primary: #6558f5;
  --rf-attendance-primary-dark: #5144dc;
  --rf-attendance-primary-soft: #efedff;
  --rf-attendance-success: #1d9962;
  --rf-attendance-success-soft: #eaf8f1;
  --rf-attendance-warning: #d28917;
  --rf-attendance-warning-soft: #fff6e5;
  --rf-attendance-danger: #d84b5d;
  --rf-attendance-danger-soft: #fff0f3;
  --rf-attendance-info: #3375cb;
  --rf-attendance-info-soft: #edf5ff;
  --rf-attendance-shadow:
    0 18px 48px rgba(28, 35, 57, 0.07);

  width: 100%;
  min-height: calc(100vh - 72px);
  padding: 26px;
  color: var(--rf-attendance-text);
  background:
    radial-gradient(
      circle at top right,
      rgba(101, 88, 245, 0.08),
      transparent 27%
    ),
    var(--rf-attendance-bg);
  box-sizing: border-box;
}

.rf-attendance-page *,
.rf-attendance-page *::before,
.rf-attendance-page *::after {
  box-sizing: border-box;
}

.rf-attendance-page button,
.rf-attendance-page input,
.rf-attendance-page select,
.rf-attendance-page textarea {
  font: inherit;
}

/* ------------------------------------------------------------------ */
/* Header                                                             */
/* ------------------------------------------------------------------ */

.rf-attendance-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 20px;
  padding: 24px 26px;
  background:
    linear-gradient(
      135deg,
      rgba(101, 88, 245, 0.06),
      transparent 42%
    ),
    var(--rf-attendance-panel);
  border: 1px solid var(--rf-attendance-border);
  border-radius: 22px;
  box-shadow: var(--rf-attendance-shadow);
}

.rf-attendance-header > div:first-child {
  min-width: 0;
}

.rf-attendance-eyebrow {
  margin: 0 0 6px;
  color: var(--rf-attendance-primary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.rf-attendance-header h1 {
  margin: 0;
  color: var(--rf-attendance-text);
  font-size: clamp(25px, 3vw, 34px);
  font-weight: 790;
  letter-spacing: -0.04em;
}

.rf-attendance-header > div:first-child > p:last-child {
  max-width: 650px;
  margin: 8px 0 0;
  color: var(--rf-attendance-muted);
  font-size: 12px;
  line-height: 1.55;
}

.rf-attendance-header__actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.rf-attendance-profile {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 190px;
  padding: 9px 12px;
  background: #f8fafc;
  border: 1px solid var(--rf-attendance-border);
  border-radius: 13px;
}

.rf-attendance-profile > span:last-child {
  min-width: 0;
}

.rf-attendance-profile strong,
.rf-attendance-profile small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-attendance-profile strong {
  color: #394255;
  font-size: 11px;
}

.rf-attendance-profile small {
  margin-top: 2px;
  color: var(--rf-attendance-muted);
  font-size: 9px;
}

/* ------------------------------------------------------------------ */
/* Alert                                                              */
/* ------------------------------------------------------------------ */

.rf-attendance-alert {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
  padding: 12px 14px;
  color: #8d3443;
  background: var(--rf-attendance-danger-soft);
  border: 1px solid #efd0d6;
  border-radius: 12px;
}

.rf-attendance-alert span {
  font-size: 11px;
  line-height: 1.45;
}

.rf-attendance-alert button {
  padding: 4px 7px;
  color: #8d3443;
  font-size: 10px;
  font-weight: 750;
  background: transparent;
  border: 0;
  cursor: pointer;
}

/* ------------------------------------------------------------------ */
/* Buttons                                                            */
/* ------------------------------------------------------------------ */

.rf-attendance-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 16px;
  color: #ffffff;
  font-size: 11px;
  font-weight: 760;
  background: var(--rf-attendance-primary);
  border: 1px solid var(--rf-attendance-primary);
  border-radius: 11px;
  box-shadow:
    0 8px 18px rgba(101, 88, 245, 0.21);
  cursor: pointer;
  transition:
    transform 150ms ease,
    background 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.rf-attendance-button:hover:not(:disabled) {
  background: var(--rf-attendance-primary-dark);
  border-color: var(--rf-attendance-primary-dark);
  transform: translateY(-1px);
  box-shadow:
    0 11px 22px rgba(101, 88, 245, 0.25);
}

.rf-attendance-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.rf-attendance-button--secondary {
  color: #586174;
  background: #ffffff;
  border-color: var(--rf-attendance-border);
  box-shadow: none;
}

.rf-attendance-button--secondary:hover:not(:disabled) {
  color: var(--rf-attendance-primary);
  background: var(--rf-attendance-primary-soft);
  border-color: rgba(101, 88, 245, 0.26);
  box-shadow: none;
}

.rf-attendance-button--danger {
  background: var(--rf-attendance-danger);
  border-color: var(--rf-attendance-danger);
  box-shadow:
    0 8px 18px rgba(216, 75, 93, 0.2);
}

.rf-attendance-button--danger:hover:not(:disabled) {
  background: #c43f50;
  border-color: #c43f50;
  box-shadow:
    0 11px 23px rgba(216, 75, 93, 0.24);
}

/* ------------------------------------------------------------------ */
/* Today card                                                         */
/* ------------------------------------------------------------------ */

.rf-today-attendance-card {
  display: grid;
  grid-template-columns:
    minmax(260px, 1.3fr)
    minmax(340px, 1fr)
    auto;
  align-items: center;
  gap: 22px;
  margin-bottom: 18px;
  padding: 22px 24px;
  background:
    linear-gradient(
      135deg,
      rgba(101, 88, 245, 0.07),
      rgba(29, 153, 98, 0.035)
    ),
    var(--rf-attendance-panel);
  border: 1px solid rgba(101, 88, 245, 0.16);
  border-radius: 19px;
  box-shadow:
    0 13px 34px rgba(28, 35, 57, 0.055);
}

.rf-today-attendance-card__main {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 14px;
}

.rf-attendance-state-icon {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  color: var(--rf-attendance-primary);
  font-size: 22px;
  font-weight: 850;
  background: var(--rf-attendance-primary-soft);
  border: 1px solid rgba(101, 88, 245, 0.14);
  border-radius: 17px;
}

.rf-today-attendance-card__main > div:last-child {
  min-width: 0;
}

.rf-today-attendance-card__main h2 {
  margin: 0;
  color: var(--rf-attendance-text);
  font-size: 19px;
  font-weight: 770;
  letter-spacing: -0.025em;
}

.rf-today-attendance-card__main > div:last-child > p:last-child {
  margin: 7px 0 0;
  color: var(--rf-attendance-muted);
  font-size: 11px;
  line-height: 1.5;
}

.rf-today-attendance-card__details {
  display: grid;
  grid-template-columns: repeat(4, minmax(85px, 1fr));
  gap: 8px;
}

.rf-attendance-time-block {
  min-width: 0;
  padding: 11px;
  background: rgba(255, 255, 255, 0.82);
  border: 1px solid var(--rf-attendance-border);
  border-radius: 11px;
}

.rf-attendance-time-block small,
.rf-attendance-time-block strong {
  display: block;
}

.rf-attendance-time-block small {
  color: var(--rf-attendance-muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.rf-attendance-time-block strong {
  margin-top: 5px;
  overflow: hidden;
  color: #394255;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-today-attendance-card__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
}

.rf-workday-complete-label {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 0 12px;
  color: #14784c;
  font-size: 10px;
  font-weight: 780;
  background: var(--rf-attendance-success-soft);
  border: 1px solid #cae9da;
  border-radius: 999px;
}

/* ------------------------------------------------------------------ */
/* Metrics                                                            */
/* ------------------------------------------------------------------ */

.rf-attendance-metric-grid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(170px, 1fr)
    );
  gap: 13px;
  margin-bottom: 18px;
}

.rf-attendance-metric {
  display: grid;
  grid-template-columns: 43px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  min-height: 105px;
  padding: 16px;
  background: var(--rf-attendance-panel);
  border: 1px solid var(--rf-attendance-border);
  border-radius: 16px;
  box-shadow:
    0 9px 25px rgba(28, 35, 57, 0.04);
  transition:
    transform 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.rf-attendance-metric:hover {
  border-color: rgba(101, 88, 245, 0.22);
  transform: translateY(-2px);
  box-shadow:
    0 14px 31px rgba(28, 35, 57, 0.07);
}

.rf-attendance-metric > div {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 43px;
  height: 43px;
  color: var(--rf-attendance-primary);
  font-size: 10px;
  font-weight: 850;
  background: var(--rf-attendance-primary-soft);
  border-radius: 12px;
}

.rf-attendance-metric > span {
  min-width: 0;
}

.rf-attendance-metric small,
.rf-attendance-metric strong,
.rf-attendance-metric em {
  display: block;
}

.rf-attendance-metric small {
  color: var(--rf-attendance-muted);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.rf-attendance-metric strong {
  margin-top: 5px;
  color: var(--rf-attendance-text);
  font-size: 21px;
  font-style: normal;
  font-weight: 790;
  letter-spacing: -0.035em;
}

.rf-attendance-metric em {
  margin-top: 4px;
  overflow: hidden;
  color: #9199a9;
  font-size: 8px;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ------------------------------------------------------------------ */
/* Panels and layout                                                  */
/* ------------------------------------------------------------------ */

.rf-attendance-layout {
  display: grid;
  grid-template-columns:
    minmax(0, 1.65fr)
    minmax(270px, 0.75fr);
  gap: 18px;
  margin-bottom: 18px;
}

.rf-attendance-panel {
  min-width: 0;
  margin-bottom: 18px;
  padding: 20px;
  background: var(--rf-attendance-panel);
  border: 1px solid var(--rf-attendance-border);
  border-radius: 18px;
  box-shadow:
    0 10px 30px rgba(28, 35, 57, 0.045);
}

.rf-attendance-layout .rf-attendance-panel {
  margin-bottom: 0;
}

.rf-attendance-panel-header {
  margin-bottom: 15px;
}

.rf-attendance-panel-header h2 {
  margin: 0;
  color: var(--rf-attendance-text);
  font-size: 16px;
  font-weight: 760;
  letter-spacing: -0.02em;
}

.rf-attendance-panel-header p {
  max-width: 690px;
  margin: 5px 0 0;
  color: var(--rf-attendance-muted);
  font-size: 10px;
  line-height: 1.5;
}

/* ------------------------------------------------------------------ */
/* Filters                                                            */
/* ------------------------------------------------------------------ */

.rf-attendance-filter-row,
.rf-manager-attendance-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 10px;
  margin-bottom: 15px;
  padding: 12px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 12px;
}

.rf-manager-attendance-filters {
  display: grid;
  grid-template-columns:
    minmax(180px, 1.2fr)
    minmax(140px, 0.8fr)
    minmax(140px, 0.7fr)
    minmax(140px, 0.7fr);
}

.rf-attendance-filter-row label,
.rf-manager-attendance-filters label,
.rf-review-field {
  display: grid;
  gap: 6px;
  color: #555e71;
  font-size: 9px;
  font-weight: 750;
}

.rf-attendance-filter-row input,
.rf-manager-attendance-filters input,
.rf-manager-attendance-filters select,
.rf-review-field select,
.rf-review-field textarea {
  width: 100%;
  min-height: 38px;
  padding: 0 10px;
  color: var(--rf-attendance-text);
  font-size: 10px;
  font-weight: 500;
  background: #ffffff;
  border: 1px solid var(--rf-attendance-border);
  border-radius: 9px;
  outline: none;
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.rf-review-field textarea {
  min-height: 92px;
  padding: 10px;
  resize: vertical;
}

.rf-attendance-filter-row input:focus,
.rf-manager-attendance-filters input:focus,
.rf-manager-attendance-filters select:focus,
.rf-review-field select:focus,
.rf-review-field textarea:focus {
  border-color: rgba(101, 88, 245, 0.52);
  box-shadow:
    0 0 0 3px rgba(101, 88, 245, 0.08);
}

/* ------------------------------------------------------------------ */
/* Tables                                                             */
/* ------------------------------------------------------------------ */

.rf-attendance-table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid #edf0f5;
  border-radius: 13px;
  scrollbar-width: thin;
  scrollbar-color: #cad1dd transparent;
}

.rf-attendance-table {
  width: 100%;
  min-width: 720px;
  border-collapse: collapse;
}

.rf-attendance-table--manager {
  min-width: 1020px;
}

.rf-attendance-table th,
.rf-attendance-table td {
  padding: 12px 13px;
  text-align: left;
  border-bottom: 1px solid #edf0f5;
}

.rf-attendance-table th {
  color: #7d8597;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: #fafbfc;
}

.rf-attendance-table td {
  color: #465064;
  font-size: 10px;
}

.rf-attendance-table tbody tr:last-child td {
  border-bottom: 0;
}

.rf-attendance-table tbody tr {
  transition: background 140ms ease;
}

.rf-attendance-table tbody tr:hover {
  background: #fbfbfe;
}

.rf-attendance-row-action {
  min-height: 30px;
  padding: 0 10px;
  color: var(--rf-attendance-primary);
  font-size: 9px;
  font-weight: 750;
  background: var(--rf-attendance-primary-soft);
  border: 1px solid rgba(101, 88, 245, 0.16);
  border-radius: 8px;
  cursor: pointer;
}

.rf-attendance-row-action:hover {
  color: #ffffff;
  background: var(--rf-attendance-primary);
}

/* ------------------------------------------------------------------ */
/* Status badges                                                      */
/* ------------------------------------------------------------------ */

.rf-attendance-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 9px;
  color: #60697a;
  font-size: 8px;
  font-weight: 780;
  white-space: nowrap;
  background: #f1f3f6;
  border: 1px solid #e1e5eb;
  border-radius: 999px;
}

.rf-attendance-status--present {
  color: #16794d;
  background: var(--rf-attendance-success-soft);
  border-color: #cbe9da;
}

.rf-attendance-status--late,
.rf-attendance-status--half_day {
  color: #976212;
  background: var(--rf-attendance-warning-soft);
  border-color: #f0ddb5;
}

.rf-attendance-status--absent {
  color: #a33a4a;
  background: var(--rf-attendance-danger-soft);
  border-color: #efcfd5;
}

.rf-attendance-status--excused {
  color: #316daf;
  background: var(--rf-attendance-info-soft);
  border-color: #d4e5f9;
}

.rf-attendance-status--not_checked_in,
.rf-attendance-status--unknown {
  color: #687184;
  background: #f1f3f6;
  border-color: #e0e4eb;
}

/* ------------------------------------------------------------------ */
/* Verification                                                       */
/* ------------------------------------------------------------------ */

.rf-verification-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.rf-verification-badges span {
  display: inline-flex;
  align-items: center;
  min-height: 21px;
  padding: 0 7px;
  color: #8a91a1;
  font-size: 7px;
  font-weight: 750;
  white-space: nowrap;
  background: #f3f4f7;
  border: 1px solid #e4e7ed;
  border-radius: 999px;
}

.rf-verification-badges span.is-verified {
  color: #16794d;
  background: var(--rf-attendance-success-soft);
  border-color: #cbe9da;
}

.rf-verification-badges--large {
  margin-bottom: 16px;
}

.rf-verification-badges--large span {
  min-height: 28px;
  padding: 0 10px;
  font-size: 9px;
}

/* ------------------------------------------------------------------ */
/* Members and avatars                                                */
/* ------------------------------------------------------------------ */

.rf-attendance-member {
  display: flex;
  align-items: center;
  min-width: 160px;
  gap: 9px;
}

.rf-attendance-member > span:last-child {
  min-width: 0;
}

.rf-attendance-member strong,
.rf-attendance-member small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-attendance-member strong {
  color: #374054;
  font-size: 10px;
}

.rf-attendance-member small {
  margin-top: 2px;
  color: var(--rf-attendance-muted);
  font-size: 8px;
}

.rf-attendance-avatar {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  overflow: hidden;
  color: var(--rf-attendance-primary);
  background:
    linear-gradient(
      145deg,
      #e9e6ff,
      #f6f4ff
    );
  border: 1px solid rgba(101, 88, 245, 0.14);
  border-radius: 11px;
}

.rf-attendance-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rf-attendance-avatar b {
  font-size: 10px;
  font-weight: 850;
}

/* ------------------------------------------------------------------ */
/* Policy                                                             */
/* ------------------------------------------------------------------ */

.rf-attendance-policy-list {
  display: grid;
  gap: 8px;
}

.rf-attendance-policy-item {
  display: grid;
  grid-template-columns: 27px minmax(0, 1fr);
  gap: 10px;
  padding: 11px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 11px;
}

.rf-attendance-policy-item > span {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 25px;
  height: 25px;
  color: #ffffff;
  font-size: 9px;
  font-weight: 800;
  background: var(--rf-attendance-success);
  border-radius: 8px;
}

.rf-attendance-policy-item strong {
  color: #3d4659;
  font-size: 10px;
}

.rf-attendance-policy-item p {
  margin: 4px 0 0;
  color: var(--rf-attendance-muted);
  font-size: 9px;
  line-height: 1.5;
}

/* ------------------------------------------------------------------ */
/* Manager summary                                                    */
/* ------------------------------------------------------------------ */

.rf-manager-attendance-summary {
  display: grid;
  grid-template-columns: minmax(240px, 0.9fr) minmax(0, 1.5fr);
  align-items: center;
  gap: 22px;
  margin-bottom: 18px;
  padding: 21px 23px;
  background:
    linear-gradient(
      135deg,
      rgba(101, 88, 245, 0.06),
      rgba(51, 117, 203, 0.025)
    ),
    var(--rf-attendance-panel);
  border: 1px solid var(--rf-attendance-border);
  border-radius: 18px;
  box-shadow:
    0 10px 29px rgba(28, 35, 57, 0.045);
}

.rf-manager-attendance-summary h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 770;
  letter-spacing: -0.02em;
}

.rf-manager-attendance-summary > div:first-child > p:last-child {
  margin: 6px 0 0;
  color: var(--rf-attendance-muted);
  font-size: 10px;
  line-height: 1.5;
}

.rf-manager-summary-grid {
  display: grid;
  grid-template-columns:
    repeat(
      5,
      minmax(90px, 1fr)
    );
  gap: 8px;
}

.rf-attendance-summary-tile {
  min-width: 0;
  padding: 12px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 11px;
}

.rf-attendance-summary-tile small,
.rf-attendance-summary-tile strong {
  display: block;
}

.rf-attendance-summary-tile small {
  color: var(--rf-attendance-muted);
  font-size: 8px;
  font-weight: 750;
  text-transform: uppercase;
}

.rf-attendance-summary-tile strong {
  margin-top: 5px;
  color: var(--rf-attendance-text);
  font-size: 18px;
  font-weight: 790;
}

.rf-attendance-summary-tile--present {
  background: var(--rf-attendance-success-soft);
  border-color: #cbe9da;
}

.rf-attendance-summary-tile--late,
.rf-attendance-summary-tile--half_day {
  background: var(--rf-attendance-warning-soft);
  border-color: #efddb7;
}

.rf-attendance-summary-tile--absent {
  background: var(--rf-attendance-danger-soft);
  border-color: #efd0d6;
}

.rf-attendance-summary-tile--hours {
  background: var(--rf-attendance-info-soft);
  border-color: #d6e6f9;
}

/* ------------------------------------------------------------------ */
/* Empty state                                                        */
/* ------------------------------------------------------------------ */

.rf-attendance-empty {
  display: flex;
  min-height: 200px;
  padding: 28px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: #fafbfc;
  border: 1px dashed #dfe3eb;
  border-radius: 13px;
}

.rf-attendance-empty > div {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  margin-bottom: 11px;
  color: var(--rf-attendance-primary);
  font-size: 11px;
  font-weight: 850;
  background: var(--rf-attendance-primary-soft);
  border-radius: 14px;
}

.rf-attendance-empty strong {
  color: #3b4457;
  font-size: 12px;
}

.rf-attendance-empty p {
  max-width: 360px;
  margin: 7px 0 0;
  color: var(--rf-attendance-muted);
  font-size: 10px;
  line-height: 1.55;
}

/* ------------------------------------------------------------------ */
/* Modal                                                              */
/* ------------------------------------------------------------------ */

.rf-attendance-modal-backdrop {
  position: fixed;
  z-index: 1200;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 22px;
  background: rgba(18, 23, 36, 0.5);
  backdrop-filter: blur(6px);
}

.rf-photo-capture-dialog,
.rf-attendance-review-dialog {
  width: min(620px, 100%);
  max-height: 94vh;
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid var(--rf-attendance-border);
  border-radius: 21px;
  box-shadow:
    0 30px 90px rgba(18, 23, 36, 0.24);
}

.rf-photo-capture-dialog > header,
.rf-attendance-review-dialog > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 22px 23px 17px;
  border-bottom: 1px solid var(--rf-attendance-border);
}

.rf-photo-capture-dialog h2,
.rf-attendance-review-dialog h2 {
  margin: 0;
  font-size: 19px;
  font-weight: 780;
  letter-spacing: -0.025em;
}

.rf-photo-capture-dialog header span,
.rf-attendance-review-dialog header span {
  display: block;
  margin-top: 6px;
  color: var(--rf-attendance-muted);
  font-size: 10px;
}

.rf-photo-capture-dialog header > button,
.rf-attendance-review-dialog header > button {
  padding: 0 5px;
  color: #7e8798;
  font-size: 23px;
  background: transparent;
  border: 0;
  cursor: pointer;
}

.rf-photo-capture-dialog > footer,
.rf-attendance-review-dialog > footer {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding: 16px 22px 21px;
  border-top: 1px solid var(--rf-attendance-border);
}

.rf-camera-error {
  margin: 14px 20px 0;
  padding: 10px 12px;
  color: #913645;
  font-size: 10px;
  background: var(--rf-attendance-danger-soft);
  border: 1px solid #efd0d6;
  border-radius: 10px;
}

/* ------------------------------------------------------------------ */
/* Camera                                                             */
/* ------------------------------------------------------------------ */

.rf-camera-frame {
  position: relative;
  width: calc(100% - 40px);
  aspect-ratio: 4 / 3;
  margin: 20px;
  overflow: hidden;
  background:
    linear-gradient(
      145deg,
      #22293a,
      #131824
    );
  border-radius: 16px;
}

.rf-camera-frame video,
.rf-camera-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rf-camera-loading {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-size: 11px;
  background: rgba(16, 20, 30, 0.68);
}

.rf-camera-guide {
  position: absolute;
  inset: 14%;
  pointer-events: none;
  border: 2px solid rgba(255, 255, 255, 0.55);
  border-radius: 42% 42% 38% 38% / 34% 34% 48% 48%;
  box-shadow:
    0 0 0 999px rgba(14, 18, 28, 0.18);
}

.rf-capture-context {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 0 20px 18px;
}

.rf-capture-context-row {
  min-width: 0;
  padding: 10px 11px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 10px;
}

.rf-capture-context-row span,
.rf-capture-context-row strong {
  display: block;
}

.rf-capture-context-row span {
  color: var(--rf-attendance-muted);
  font-size: 8px;
  font-weight: 750;
  text-transform: uppercase;
}

.rf-capture-context-row strong {
  margin-top: 4px;
  overflow: hidden;
  color: #40495c;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ------------------------------------------------------------------ */
/* Review dialog                                                      */
/* ------------------------------------------------------------------ */

.rf-attendance-review-dialog {
  width: min(560px, 100%);
}

.rf-review-stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(90px, 1fr));
  gap: 8px;
  padding: 18px 20px 13px;
}

.rf-review-stat {
  padding: 11px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 10px;
}

.rf-review-stat small,
.rf-review-stat strong {
  display: block;
}

.rf-review-stat small {
  color: var(--rf-attendance-muted);
  font-size: 8px;
  font-weight: 750;
  text-transform: uppercase;
}

.rf-review-stat strong {
  margin-top: 5px;
  color: #3d4659;
  font-size: 11px;
}

.rf-attendance-review-dialog
  > .rf-verification-badges,
.rf-attendance-review-dialog
  > .rf-review-field {
  margin-right: 20px;
  margin-left: 20px;
}

.rf-review-field {
  margin-bottom: 14px;
}

/* ------------------------------------------------------------------ */
/* Loading                                                            */
/* ------------------------------------------------------------------ */

.rf-attendance-skeleton-header,
.rf-attendance-skeleton-hero,
.rf-attendance-skeleton-grid > div,
.rf-attendance-skeleton-panel {
  background:
    linear-gradient(
      90deg,
      #eff1f5,
      #f8f9fb,
      #eff1f5
    );
  background-size: 220% 100%;
  animation:
    rf-attendance-shimmer
    1.4s infinite;
}

.rf-attendance-skeleton-header {
  height: 132px;
  margin-bottom: 18px;
  border-radius: 22px;
}

.rf-attendance-skeleton-hero {
  height: 160px;
  margin-bottom: 18px;
  border-radius: 19px;
}

.rf-attendance-skeleton-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 13px;
  margin-bottom: 18px;
}

.rf-attendance-skeleton-grid > div {
  height: 105px;
  border-radius: 16px;
}

.rf-attendance-skeleton-panel {
  height: 360px;
  border-radius: 18px;
}

@keyframes rf-attendance-shimmer {
  0% {
    background-position: 100% 0;
  }

  100% {
    background-position: -100% 0;
  }
}

/* ------------------------------------------------------------------ */
/* Responsive                                                         */
/* ------------------------------------------------------------------ */

@media (max-width: 1180px) {
  .rf-today-attendance-card {
    grid-template-columns:
      minmax(240px, 1fr)
      minmax(320px, 1fr);
  }

  .rf-today-attendance-card__actions {
    grid-column: 1 / -1;
    justify-content: flex-end;
  }

  .rf-manager-summary-grid {
    grid-template-columns:
      repeat(
        3,
        minmax(100px, 1fr)
      );
  }
}

@media (max-width: 960px) {
  .rf-attendance-page {
    padding: 18px;
  }

  .rf-attendance-header {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-attendance-header__actions {
    justify-content: space-between;
  }

  .rf-today-attendance-card {
    grid-template-columns: 1fr;
  }

  .rf-today-attendance-card__details {
    grid-template-columns:
      repeat(
        4,
        minmax(100px, 1fr)
      );
  }

  .rf-today-attendance-card__actions {
    grid-column: auto;
  }

  .rf-attendance-layout {
    grid-template-columns: 1fr;
  }

  .rf-manager-attendance-summary {
    grid-template-columns: 1fr;
  }

  .rf-manager-attendance-filters {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }
}

@media (max-width: 720px) {
  .rf-attendance-page {
    padding: 12px;
  }

  .rf-attendance-header {
    padding: 18px;
    border-radius: 17px;
  }

  .rf-attendance-header h1 {
    font-size: 23px;
  }

  .rf-attendance-header__actions {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-attendance-profile {
    width: 100%;
  }

  .rf-attendance-header__actions
    .rf-attendance-button {
    width: 100%;
  }

  .rf-today-attendance-card {
    padding: 17px;
    border-radius: 16px;
  }

  .rf-today-attendance-card__main {
    align-items: flex-start;
  }

  .rf-today-attendance-card__details {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

  .rf-today-attendance-card__actions {
    justify-content: stretch;
  }

  .rf-today-attendance-card__actions
    .rf-attendance-button {
    width: 100%;
  }

  .rf-attendance-metric-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
    gap: 9px;
  }

  .rf-attendance-panel {
    padding: 15px;
    border-radius: 15px;
  }

  .rf-manager-summary-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

  .rf-capture-context {
    grid-template-columns: 1fr;
  }

  .rf-review-stat-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

  .rf-photo-capture-dialog > footer,
  .rf-attendance-review-dialog > footer {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-photo-capture-dialog > footer
    .rf-attendance-button,
  .rf-attendance-review-dialog > footer
    .rf-attendance-button {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .rf-attendance-page {
    padding: 8px;
  }

  .rf-attendance-header {
    padding: 15px;
  }

  .rf-attendance-header h1 {
    font-size: 20px;
  }

  .rf-today-attendance-card__main {
    flex-direction: column;
  }

  .rf-attendance-state-icon {
    width: 48px;
    height: 48px;
    border-radius: 14px;
  }

  .rf-today-attendance-card__details {
    grid-template-columns: 1fr;
  }

  .rf-attendance-metric-grid {
    grid-template-columns: 1fr;
  }

  .rf-manager-attendance-filters {
    grid-template-columns: 1fr;
  }

  .rf-manager-summary-grid {
    grid-template-columns: 1fr;
  }

  .rf-camera-frame {
    width: calc(100% - 24px);
    margin: 12px;
  }

  .rf-capture-context {
    margin-right: 12px;
    margin-left: 12px;
  }

  .rf-photo-capture-dialog > header,
  .rf-attendance-review-dialog > header {
    padding-right: 16px;
    padding-left: 16px;
  }

  .rf-review-stat-grid {
    grid-template-columns: 1fr;
    padding-right: 14px;
    padding-left: 14px;
  }

  .rf-attendance-review-dialog
    > .rf-verification-badges,
  .rf-attendance-review-dialog
    > .rf-review-field {
    margin-right: 14px;
    margin-left: 14px;
  }
}

/* ------------------------------------------------------------------ */
/* Dark theme                                                         */
/* ------------------------------------------------------------------ */

[data-theme="dark"] .rf-attendance-page,
.dark .rf-attendance-page {
  --rf-attendance-bg: #111521;
  --rf-attendance-panel: #191e2b;
  --rf-attendance-border: #2a3040;
  --rf-attendance-text: #edf0f7;
  --rf-attendance-muted: #9da5b7;
  --rf-attendance-primary-soft: #292442;
  --rf-attendance-success-soft: #173528;
  --rf-attendance-warning-soft: #3a2d17;
  --rf-attendance-danger-soft: #3a1e25;
  --rf-attendance-info-soft: #1c2d45;

  background:
    radial-gradient(
      circle at top right,
      rgba(101, 88, 245, 0.1),
      transparent 28%
    ),
    var(--rf-attendance-bg);
}

[data-theme="dark"] .rf-attendance-header,
[data-theme="dark"] .rf-today-attendance-card,
[data-theme="dark"] .rf-attendance-panel,
[data-theme="dark"] .rf-manager-attendance-summary,
[data-theme="dark"] .rf-attendance-metric,
.dark .rf-attendance-header,
.dark .rf-today-attendance-card,
.dark .rf-attendance-panel,
.dark .rf-manager-attendance-summary,
.dark .rf-attendance-metric {
  background-color: var(--rf-attendance-panel);
}

[data-theme="dark"] .rf-attendance-profile,
[data-theme="dark"] .rf-attendance-time-block,
[data-theme="dark"] .rf-attendance-filter-row,
[data-theme="dark"] .rf-manager-attendance-filters,
[data-theme="dark"] .rf-attendance-policy-item,
[data-theme="dark"] .rf-attendance-summary-tile,
[data-theme="dark"] .rf-attendance-empty,
[data-theme="dark"] .rf-capture-context-row,
[data-theme="dark"] .rf-review-stat,
.dark .rf-attendance-profile,
.dark .rf-attendance-time-block,
.dark .rf-attendance-filter-row,
.dark .rf-manager-attendance-filters,
.dark .rf-attendance-policy-item,
.dark .rf-attendance-summary-tile,
.dark .rf-attendance-empty,
.dark .rf-capture-context-row,
.dark .rf-review-stat {
  background: #202636;
  border-color: #2d3445;
}

[data-theme="dark"] .rf-attendance-table th,
.dark .rf-attendance-table th {
  background: #202636;
}

[data-theme="dark"] .rf-attendance-table td,
[data-theme="dark"] .rf-attendance-table th,
.dark .rf-attendance-table td,
.dark .rf-attendance-table th {
  border-color: #2b3242;
}

[data-theme="dark"] .rf-attendance-table tbody tr:hover,
.dark .rf-attendance-table tbody tr:hover {
  background: #202636;
}

[data-theme="dark"] .rf-attendance-filter-row input,
[data-theme="dark"] .rf-manager-attendance-filters input,
[data-theme="dark"] .rf-manager-attendance-filters select,
[data-theme="dark"] .rf-review-field select,
[data-theme="dark"] .rf-review-field textarea,
.dark .rf-attendance-filter-row input,
.dark .rf-manager-attendance-filters input,
.dark .rf-manager-attendance-filters select,
.dark .rf-review-field select,
.dark .rf-review-field textarea {
  color: var(--rf-attendance-text);
  background: #202636;
}

[data-theme="dark"] .rf-photo-capture-dialog,
[data-theme="dark"] .rf-attendance-review-dialog,
.dark .rf-photo-capture-dialog,
.dark .rf-attendance-review-dialog {
  background: #191e2b;
}

[data-theme="dark"] .rf-attendance-button--secondary,
.dark .rf-attendance-button--secondary {
  color: #d2d7e2;
  background: #202636;
}
.rf-profile-page {
  --rf-profile-bg: #f6f7fb;
  --rf-profile-panel: #ffffff;
  --rf-profile-border: #e4e8f0;
  --rf-profile-text: #182033;
  --rf-profile-muted: #737c8f;
  --rf-profile-primary: #6558f5;
  --rf-profile-primary-dark: #5144dc;
  --rf-profile-primary-soft: #efedff;
  --rf-profile-success: #1d9962;
  --rf-profile-success-soft: #eaf8f1;
  --rf-profile-warning: #d28917;
  --rf-profile-warning-soft: #fff6e5;
  --rf-profile-danger: #d84b5d;
  --rf-profile-danger-soft: #fff0f3;
  --rf-profile-shadow:
    0 18px 48px rgba(28, 35, 57, 0.07);

  width: 100%;
  min-height: calc(100vh - 72px);
  padding: 26px;
  color: var(--rf-profile-text);
  background:
    radial-gradient(
      circle at top right,
      rgba(101, 88, 245, 0.08),
      transparent 27%
    ),
    var(--rf-profile-bg);
  box-sizing: border-box;
}

.rf-profile-page *,
.rf-profile-page *::before,
.rf-profile-page *::after {
  box-sizing: border-box;
}

.rf-profile-page button,
.rf-profile-page input,
.rf-profile-page select,
.rf-profile-page textarea {
  font: inherit;
}

.rf-profile-page button {
  cursor: pointer;
}

/* Header */

.rf-profile-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 20px;
  padding: 24px 26px;
  background:
    linear-gradient(
      135deg,
      rgba(101, 88, 245, 0.06),
      transparent 42%
    ),
    var(--rf-profile-panel);
  border: 1px solid var(--rf-profile-border);
  border-radius: 22px;
  box-shadow: var(--rf-profile-shadow);
}

.rf-profile-header > div:first-child {
  min-width: 0;
}

.rf-profile-eyebrow {
  margin: 0 0 6px;
  color: var(--rf-profile-primary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.rf-profile-header h1 {
  margin: 0;
  color: var(--rf-profile-text);
  font-size: clamp(25px, 3vw, 34px);
  font-weight: 790;
  letter-spacing: -0.04em;
}

.rf-profile-header > div:first-child > p:last-child {
  max-width: 650px;
  margin: 8px 0 0;
  color: var(--rf-profile-muted);
  font-size: 12px;
  line-height: 1.55;
}

.rf-profile-header__identity {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 230px;
  padding: 10px 13px;
  background: #f8fafc;
  border: 1px solid var(--rf-profile-border);
  border-radius: 14px;
}

.rf-profile-header__identity > div {
  min-width: 0;
}

.rf-profile-header__identity strong,
.rf-profile-header__identity span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-profile-header__identity strong {
  color: #394255;
  font-size: 12px;
}

.rf-profile-header__identity > div > span {
  margin-top: 2px;
  color: var(--rf-profile-muted);
  font-size: 9px;
}

/* Alerts */

.rf-profile-alert {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
  padding: 12px 14px;
  border-radius: 12px;
}

.rf-profile-alert span {
  font-size: 11px;
  line-height: 1.45;
}

.rf-profile-alert button {
  padding: 4px 7px;
  font-size: 10px;
  font-weight: 750;
  background: transparent;
  border: 0;
}

.rf-profile-alert--error {
  color: #8d3443;
  background: var(--rf-profile-danger-soft);
  border: 1px solid #efd0d6;
}

.rf-profile-alert--error button {
  color: #8d3443;
}

.rf-profile-alert--success {
  color: #16794d;
  background: var(--rf-profile-success-soft);
  border: 1px solid #cbe9da;
}

.rf-profile-alert--success button {
  color: #16794d;
}

/* Main layout */

.rf-profile-layout {
  display: grid;
  grid-template-columns:
    minmax(250px, 320px)
    minmax(0, 1fr);
  gap: 18px;
}

.rf-profile-sidebar,
.rf-profile-content {
  min-width: 0;
}

.rf-profile-sidebar {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* Identity card */

.rf-profile-identity-card {
  padding: 22px;
  text-align: center;
  background: var(--rf-profile-panel);
  border: 1px solid var(--rf-profile-border);
  border-radius: 18px;
  box-shadow:
    0 10px 30px rgba(28, 35, 57, 0.045);
}

.rf-profile-avatar-wrap {
  position: relative;
  display: inline-flex;
  margin-bottom: 14px;
}

.rf-profile-avatar-wrap > button {
  position: absolute;
  right: -5px;
  bottom: -5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  color: #ffffff;
  font-size: 19px;
  background: var(--rf-profile-primary);
  border: 3px solid #ffffff;
  border-radius: 10px;
  box-shadow:
    0 8px 17px rgba(101, 88, 245, 0.24);
}

.rf-profile-identity-card h2 {
  margin: 0;
  color: var(--rf-profile-text);
  font-size: 18px;
  font-weight: 770;
  letter-spacing: -0.025em;
}

.rf-profile-identity-card > p {
  margin: 5px 0 0;
  color: #5f687a;
  font-size: 10px;
}

.rf-profile-identity-card > span {
  display: block;
  margin-top: 5px;
  overflow: hidden;
  color: var(--rf-profile-muted);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-profile-avatar-actions {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.rf-profile-avatar-actions button {
  min-height: 34px;
  padding: 0 11px;
  color: #596174;
  font-size: 9px;
  font-weight: 750;
  background: #f7f8fa;
  border: 1px solid var(--rf-profile-border);
  border-radius: 9px;
}

.rf-profile-avatar-actions button:first-child {
  color: var(--rf-profile-primary);
  background: var(--rf-profile-primary-soft);
  border-color: rgba(101, 88, 245, 0.2);
}

.rf-profile-avatar-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.rf-profile-identity-card > small {
  display: block;
  margin-top: 11px;
  color: #9aa1b0;
  font-size: 8px;
  line-height: 1.45;
}

/* Avatar */

.rf-profile-avatar {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  overflow: hidden;
  color: var(--rf-profile-primary);
  background:
    linear-gradient(
      145deg,
      #e9e6ff,
      #f6f4ff
    );
  border: 1px solid rgba(101, 88, 245, 0.14);
  border-radius: 12px;
}

.rf-profile-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rf-profile-avatar b {
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.02em;
}

.rf-profile-avatar--large {
  width: 52px;
  height: 52px;
  border-radius: 15px;
}

.rf-profile-avatar--large b {
  font-size: 14px;
}

.rf-profile-avatar--extra-large {
  width: 96px;
  height: 96px;
  border-radius: 26px;
}

.rf-profile-avatar--extra-large b {
  font-size: 24px;
}

/* Availability badge */

.rf-profile-availability-badge {
  display: inline-flex !important;
  align-items: center;
  min-height: 22px;
  margin-top: 6px !important;
  padding: 0 8px;
  font-size: 8px !important;
  font-weight: 750;
  border-radius: 999px;
}

.rf-profile-availability-badge--available {
  color: #16794d !important;
  background: var(--rf-profile-success-soft);
  border: 1px solid #cbe9da;
}

.rf-profile-availability-badge--busy {
  color: #9a6413 !important;
  background: var(--rf-profile-warning-soft);
  border: 1px solid #f0ddb5;
}

.rf-profile-availability-badge--away {
  color: #316daf !important;
  background: #edf5ff;
  border: 1px solid #d4e5f9;
}

.rf-profile-availability-badge--offline {
  color: #687184 !important;
  background: #f1f3f6;
  border: 1px solid #e0e4eb;
}

/* Sidebar navigation */

.rf-profile-navigation {
  display: grid;
  gap: 7px;
  padding: 10px;
  background: var(--rf-profile-panel);
  border: 1px solid var(--rf-profile-border);
  border-radius: 16px;
  box-shadow:
    0 10px 30px rgba(28, 35, 57, 0.045);
}

.rf-profile-navigation button {
  display: block;
  width: 100%;
  padding: 12px;
  text-align: left;
  color: #4b5467;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 11px;
  transition:
    color 150ms ease,
    background 150ms ease,
    border-color 150ms ease;
}

.rf-profile-navigation button:hover {
  background: #f7f8fb;
}

.rf-profile-navigation button.is-active {
  color: var(--rf-profile-primary-dark);
  background: var(--rf-profile-primary-soft);
  border-color: rgba(101, 88, 245, 0.16);
}

.rf-profile-navigation span,
.rf-profile-navigation small {
  display: block;
}

.rf-profile-navigation span {
  font-size: 10px;
  font-weight: 760;
}

.rf-profile-navigation small {
  margin-top: 4px;
  color: var(--rf-profile-muted);
  font-size: 8px;
  line-height: 1.4;
}

/* Panels */

.rf-profile-panel {
  min-width: 0;
  padding: 22px;
  background: var(--rf-profile-panel);
  border: 1px solid var(--rf-profile-border);
  border-radius: 18px;
  box-shadow:
    0 10px 30px rgba(28, 35, 57, 0.045);
}

.rf-profile-panel-header {
  margin-bottom: 18px;
}

.rf-profile-panel-header h2 {
  margin: 0;
  color: var(--rf-profile-text);
  font-size: 17px;
  font-weight: 770;
  letter-spacing: -0.025em;
}

.rf-profile-panel-header p {
  max-width: 700px;
  margin: 5px 0 0;
  color: var(--rf-profile-muted);
  font-size: 10px;
  line-height: 1.5;
}

/* Form */

.rf-profile-form-grid {
  display: grid;
  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );
  gap: 15px;
}

.rf-profile-field {
  display: grid;
  align-content: start;
  gap: 7px;
  min-width: 0;
  color: #545d70;
  font-size: 9px;
  font-weight: 750;
}

.rf-profile-field--wide {
  grid-column: 1 / -1;
}

.rf-profile-field > span b {
  color: var(--rf-profile-danger);
}

.rf-profile-field input,
.rf-profile-field select,
.rf-profile-field textarea {
  width: 100%;
  min-height: 42px;
  padding: 0 12px;
  color: var(--rf-profile-text);
  font-size: 11px;
  font-weight: 500;
  background: #fafbfc;
  border: 1px solid var(--rf-profile-border);
  border-radius: 10px;
  outline: none;
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease,
    background 150ms ease;
}

.rf-profile-field textarea {
  min-height: 110px;
  padding: 11px 12px;
  resize: vertical;
  line-height: 1.5;
}

.rf-profile-field input:focus,
.rf-profile-field select:focus,
.rf-profile-field textarea:focus {
  background: #ffffff;
  border-color: rgba(101, 88, 245, 0.52);
  box-shadow:
    0 0 0 3px rgba(101, 88, 245, 0.08);
}

.rf-profile-field > small {
  justify-self: end;
  color: #989fac;
  font-size: 8px;
  font-weight: 500;
}

.rf-profile-form-footer {
  display: flex;
  justify-content: flex-end;
  margin-top: 20px;
  padding-top: 17px;
  border-top: 1px solid #edf0f5;
}

.rf-profile-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 16px;
  color: #ffffff;
  font-size: 10px;
  font-weight: 760;
  background: var(--rf-profile-primary);
  border: 1px solid var(--rf-profile-primary);
  border-radius: 10px;
  box-shadow:
    0 8px 18px rgba(101, 88, 245, 0.21);
}

.rf-profile-button:hover:not(:disabled) {
  background: var(--rf-profile-primary-dark);
  border-color: var(--rf-profile-primary-dark);
}

.rf-profile-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

/* Availability section */

.rf-availability-options {
  display: grid;
  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );
  gap: 10px;
  margin-bottom: 18px;
}

.rf-availability-option {
  display: grid;
  grid-template-columns: 18px 14px minmax(0, 1fr);
  align-items: flex-start;
  gap: 9px;
  padding: 13px;
  cursor: pointer;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 12px;
  transition:
    border-color 150ms ease,
    background 150ms ease,
    transform 150ms ease;
}

.rf-availability-option:hover {
  transform: translateY(-1px);
}

.rf-availability-option.is-selected {
  background: var(--rf-profile-primary-soft);
  border-color: rgba(101, 88, 245, 0.28);
}

.rf-availability-option input {
  width: 15px;
  height: 15px;
  margin: 2px 0 0;
  accent-color: var(--rf-profile-primary);
}

.rf-availability-option__dot {
  width: 11px;
  height: 11px;
  margin-top: 3px;
  background: #9ca4b3;
  border-radius: 999px;
}

.rf-availability-option--available
  .rf-availability-option__dot {
  background: var(--rf-profile-success);
}

.rf-availability-option--busy
  .rf-availability-option__dot {
  background: var(--rf-profile-warning);
}

.rf-availability-option--away
  .rf-availability-option__dot {
  background: #3375cb;
}

.rf-availability-option--offline
  .rf-availability-option__dot {
  background: #858d9d;
}

.rf-availability-option strong {
  color: #3d4659;
  font-size: 10px;
}

.rf-availability-option p {
  margin: 4px 0 0;
  color: var(--rf-profile-muted);
  font-size: 8px;
  line-height: 1.45;
}

/* Notifications */

.rf-notification-list {
  display: grid;
  gap: 8px;
}

.rf-notification-option {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 42px;
  align-items: center;
  gap: 12px;
  min-height: 64px;
  padding: 11px 13px;
  cursor: pointer;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 12px;
}

.rf-notification-option > div {
  min-width: 0;
}

.rf-notification-option strong {
  color: #3d4659;
  font-size: 10px;
}

.rf-notification-option p {
  margin: 4px 0 0;
  color: var(--rf-profile-muted);
  font-size: 8px;
  line-height: 1.45;
}

.rf-notification-option input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.rf-toggle-switch {
  position: relative;
  display: inline-flex;
  width: 42px;
  height: 24px;
  padding: 3px;
  background: #dfe3ea;
  border-radius: 999px;
  transition: background 150ms ease;
}

.rf-toggle-switch i {
  width: 18px;
  height: 18px;
  background: #ffffff;
  border-radius: 999px;
  box-shadow:
    0 2px 6px rgba(34, 40, 55, 0.18);
  transition: transform 150ms ease;
}

.rf-notification-option
  input:checked
  + .rf-toggle-switch {
  background: var(--rf-profile-primary);
}

.rf-notification-option
  input:checked
  + .rf-toggle-switch
  i {
  transform: translateX(18px);
}

/* Security */

.rf-security-form {
  display: grid;
  gap: 14px;
}

.rf-password-strength {
  display: flex;
  align-items: center;
  gap: 9px;
}

.rf-password-strength > div {
  display: grid;
  flex: 1;
  grid-template-columns:
    repeat(
      5,
      minmax(0, 1fr)
    );
  gap: 4px;
}

.rf-password-strength span {
  height: 4px;
  background: #e3e6ec;
  border-radius: 999px;
}

.rf-password-strength span.is-active {
  background: var(--rf-profile-primary);
}

.rf-password-strength small {
  color: var(--rf-profile-muted);
  font-size: 8px;
  white-space: nowrap;
}

.rf-password-requirements {
  padding: 14px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 12px;
}

.rf-password-requirements > strong {
  color: #3d4659;
  font-size: 10px;
}

.rf-password-requirements ul {
  display: grid;
  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );
  gap: 8px 12px;
  margin: 11px 0 0;
  padding: 0;
  list-style: none;
}

.rf-password-requirements li {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #8b93a3;
  font-size: 8px;
}

.rf-password-requirements li span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
  background: #eef0f4;
  border-radius: 999px;
}

.rf-password-requirements li.is-valid {
  color: #16794d;
}

.rf-password-requirements li.is-valid span {
  color: #ffffff;
  background: var(--rf-profile-success);
}

/* Loading */

.rf-profile-skeleton-header,
.rf-profile-skeleton-layout aside,
.rf-profile-skeleton-layout div {
  background:
    linear-gradient(
      90deg,
      #eff1f5,
      #f8f9fb,
      #eff1f5
    );
  background-size: 220% 100%;
  animation:
    rf-profile-shimmer
    1.4s infinite;
}

.rf-profile-skeleton-header {
  height: 132px;
  margin-bottom: 20px;
  border-radius: 22px;
}

.rf-profile-skeleton-layout {
  display: grid;
  grid-template-columns: 310px minmax(0, 1fr);
  gap: 18px;
}

.rf-profile-skeleton-layout aside,
.rf-profile-skeleton-layout div {
  height: 580px;
  border-radius: 18px;
}

@keyframes rf-profile-shimmer {
  0% {
    background-position: 100% 0;
  }

  100% {
    background-position: -100% 0;
  }
}

/* Responsive */

@media (max-width: 960px) {
  .rf-profile-page {
    padding: 18px;
  }

  .rf-profile-header {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-profile-header__identity {
    width: 100%;
  }

  .rf-profile-layout {
    grid-template-columns: 1fr;
  }

  .rf-profile-sidebar {
    display: grid;
    grid-template-columns: minmax(240px, 0.8fr) minmax(0, 1.2fr);
    align-items: start;
  }
}

@media (max-width: 720px) {
  .rf-profile-page {
    padding: 12px;
  }

  .rf-profile-header {
    padding: 18px;
    border-radius: 17px;
  }

  .rf-profile-header h1 {
    font-size: 23px;
  }

  .rf-profile-sidebar {
    grid-template-columns: 1fr;
  }

  .rf-profile-navigation {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

  .rf-profile-form-grid {
    grid-template-columns: 1fr;
  }

  .rf-profile-field--wide {
    grid-column: auto;
  }

  .rf-availability-options {
    grid-template-columns: 1fr;
  }

  .rf-profile-panel {
    padding: 17px;
    border-radius: 15px;
  }
}

@media (max-width: 480px) {
  .rf-profile-page {
    padding: 8px;
  }

  .rf-profile-header {
    padding: 15px;
  }

  .rf-profile-header h1 {
    font-size: 20px;
  }

  .rf-profile-header__identity {
    min-width: 0;
  }

  .rf-profile-navigation {
    grid-template-columns: 1fr;
  }

  .rf-profile-identity-card {
    padding: 18px;
  }

  .rf-profile-avatar--extra-large {
    width: 82px;
    height: 82px;
    border-radius: 22px;
  }

  .rf-notification-option {
    grid-template-columns: minmax(0, 1fr) 42px;
  }

  .rf-notification-option > input {
    display: none;
  }

  .rf-password-requirements ul {
    grid-template-columns: 1fr;
  }

  .rf-profile-form-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-profile-button {
    width: 100%;
  }

  .rf-profile-skeleton-layout {
    grid-template-columns: 1fr;
  }

  .rf-profile-skeleton-layout aside {
    height: 320px;
  }
}

/* Dark theme */

[data-theme="dark"] .rf-profile-page,
.dark .rf-profile-page {
  --rf-profile-bg: #111521;
  --rf-profile-panel: #191e2b;
  --rf-profile-border: #2a3040;
  --rf-profile-text: #edf0f7;
  --rf-profile-muted: #9da5b7;
  --rf-profile-primary-soft: #292442;
  --rf-profile-success-soft: #173528;
  --rf-profile-warning-soft: #3a2d17;
  --rf-profile-danger-soft: #3a1e25;

  background:
    radial-gradient(
      circle at top right,
      rgba(101, 88, 245, 0.1),
      transparent 28%
    ),
    var(--rf-profile-bg);
}

[data-theme="dark"] .rf-profile-header,
[data-theme="dark"] .rf-profile-panel,
[data-theme="dark"] .rf-profile-identity-card,
[data-theme="dark"] .rf-profile-navigation,
.dark .rf-profile-header,
.dark .rf-profile-panel,
.dark .rf-profile-identity-card,
.dark .rf-profile-navigation {
  background-color: var(--rf-profile-panel);
}

[data-theme="dark"] .rf-profile-header__identity,
[data-theme="dark"] .rf-profile-navigation button:hover,
[data-theme="dark"] .rf-profile-field input,
[data-theme="dark"] .rf-profile-field select,
[data-theme="dark"] .rf-profile-field textarea,
[data-theme="dark"] .rf-availability-option,
[data-theme="dark"] .rf-notification-option,
[data-theme="dark"] .rf-password-requirements,
.dark .rf-profile-header__identity,
.dark .rf-profile-navigation button:hover,
.dark .rf-profile-field input,
.dark .rf-profile-field select,
.dark .rf-profile-field textarea,
.dark .rf-availability-option,
.dark .rf-notification-option,
.dark .rf-password-requirements {
  color: var(--rf-profile-text);
  background: #202636;
  border-color: #2d3445;
}

[data-theme="dark"] .rf-profile-avatar-wrap > button,
.dark .rf-profile-avatar-wrap > button {
  border-color: #191e2b;
}

[data-theme="dark"] .rf-profile-avatar-actions button,
.dark .rf-profile-avatar-actions button {
  color: #d3d8e3;
  background: #202636;
}
.rf-team-management-page {
  --rf-management-bg: #f6f7fb;
  --rf-management-panel: #ffffff;
  --rf-management-border: #e4e8f0;
  --rf-management-text: #182033;
  --rf-management-muted: #737c8f;
  --rf-management-primary: #6558f5;
  --rf-management-primary-dark: #5144dc;
  --rf-management-primary-soft: #efedff;
  --rf-management-success: #1d9962;
  --rf-management-success-soft: #eaf8f1;
  --rf-management-warning: #d28917;
  --rf-management-warning-soft: #fff6e5;
  --rf-management-danger: #d84b5d;
  --rf-management-danger-soft: #fff0f3;
  --rf-management-info: #3375cb;
  --rf-management-info-soft: #edf5ff;
  --rf-management-shadow:
    0 18px 48px rgba(28, 35, 57, 0.07);

  width: 100%;
  min-height: calc(100vh - 72px);
  padding: 26px;
  color: var(--rf-management-text);
  background:
    radial-gradient(
      circle at top right,
      rgba(101, 88, 245, 0.08),
      transparent 27%
    ),
    var(--rf-management-bg);
  box-sizing: border-box;
}

.rf-team-management-page *,
.rf-team-management-page *::before,
.rf-team-management-page *::after {
  box-sizing: border-box;
}

.rf-team-management-page button,
.rf-team-management-page input,
.rf-team-management-page select,
.rf-team-management-page textarea {
  font: inherit;
}

.rf-team-management-page button {
  cursor: pointer;
}

/* Header */

.rf-team-management-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 20px;
  padding: 24px 26px;
  background:
    linear-gradient(
      135deg,
      rgba(101, 88, 245, 0.06),
      transparent 42%
    ),
    var(--rf-management-panel);
  border: 1px solid var(--rf-management-border);
  border-radius: 22px;
  box-shadow: var(--rf-management-shadow);
}

.rf-team-management-header > div:first-child {
  min-width: 0;
}

.rf-management-eyebrow {
  margin: 0 0 6px;
  color: var(--rf-management-primary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.rf-team-management-header h1 {
  margin: 0;
  color: var(--rf-management-text);
  font-size: clamp(25px, 3vw, 34px);
  font-weight: 790;
  letter-spacing: -0.04em;
}

.rf-team-management-header > div:first-child > p:last-child {
  max-width: 700px;
  margin: 8px 0 0;
  color: var(--rf-management-muted);
  font-size: 12px;
  line-height: 1.55;
}

.rf-team-management-header__actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* Buttons */

.rf-management-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 16px;
  color: #ffffff;
  font-size: 10px;
  font-weight: 760;
  background: var(--rf-management-primary);
  border: 1px solid var(--rf-management-primary);
  border-radius: 10px;
  box-shadow:
    0 8px 18px rgba(101, 88, 245, 0.21);
  transition:
    background 150ms ease,
    border-color 150ms ease,
    transform 150ms ease,
    box-shadow 150ms ease;
}

.rf-management-button:hover:not(:disabled) {
  background: var(--rf-management-primary-dark);
  border-color: var(--rf-management-primary-dark);
  transform: translateY(-1px);
  box-shadow:
    0 11px 23px rgba(101, 88, 245, 0.25);
}

.rf-management-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.rf-management-button--secondary {
  color: #596174;
  background: #ffffff;
  border-color: var(--rf-management-border);
  box-shadow: none;
}

.rf-management-button--secondary:hover:not(:disabled) {
  color: var(--rf-management-primary);
  background: var(--rf-management-primary-soft);
  border-color: rgba(101, 88, 245, 0.25);
  box-shadow: none;
}

/* Alerts */

.rf-management-alert {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
  padding: 12px 14px;
  border-radius: 12px;
}

.rf-management-alert span {
  font-size: 11px;
  line-height: 1.45;
}

.rf-management-alert button {
  padding: 4px 7px;
  font-size: 10px;
  font-weight: 750;
  background: transparent;
  border: 0;
}

.rf-management-alert--error {
  color: #8d3443;
  background: var(--rf-management-danger-soft);
  border: 1px solid #efd0d6;
}

.rf-management-alert--error button {
  color: #8d3443;
}

.rf-management-alert--success {
  color: #16794d;
  background: var(--rf-management-success-soft);
  border: 1px solid #cbe9da;
}

.rf-management-alert--success button {
  color: #16794d;
}

/* Metrics */

.rf-management-metric-grid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(180px, 1fr)
    );
  gap: 13px;
  margin-bottom: 18px;
}

.rf-management-metric {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  min-height: 108px;
  padding: 16px;
  background: var(--rf-management-panel);
  border: 1px solid var(--rf-management-border);
  border-radius: 16px;
  box-shadow:
    0 9px 25px rgba(28, 35, 57, 0.04);
  transition:
    transform 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.rf-management-metric:hover {
  border-color: rgba(101, 88, 245, 0.22);
  transform: translateY(-2px);
  box-shadow:
    0 14px 31px rgba(28, 35, 57, 0.07);
}

.rf-management-metric > div {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  color: var(--rf-management-primary);
  font-size: 10px;
  font-weight: 850;
  background: var(--rf-management-primary-soft);
  border-radius: 12px;
}

.rf-management-metric > span {
  min-width: 0;
}

.rf-management-metric small,
.rf-management-metric strong,
.rf-management-metric em {
  display: block;
}

.rf-management-metric small {
  color: var(--rf-management-muted);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.rf-management-metric strong {
  margin-top: 5px;
  color: var(--rf-management-text);
  font-size: 22px;
  font-style: normal;
  font-weight: 790;
  letter-spacing: -0.035em;
}

.rf-management-metric em {
  margin-top: 4px;
  overflow: hidden;
  color: #9199a9;
  font-size: 8px;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Navigation */

.rf-management-navigation {
  display: flex;
  gap: 8px;
  margin-bottom: 18px;
  padding: 8px;
  overflow-x: auto;
  background: var(--rf-management-panel);
  border: 1px solid var(--rf-management-border);
  border-radius: 14px;
  box-shadow:
    0 8px 24px rgba(28, 35, 57, 0.04);
  scrollbar-width: thin;
}

.rf-management-navigation button {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 38px;
  padding: 0 13px;
  color: #667084;
  font-size: 10px;
  font-weight: 720;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 10px;
}

.rf-management-navigation button:hover {
  background: #f7f8fb;
}

.rf-management-navigation button.is-active {
  color: var(--rf-management-primary-dark);
  background: var(--rf-management-primary-soft);
  border-color: rgba(101, 88, 245, 0.16);
}

.rf-management-navigation button b {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  color: #6b7487;
  font-size: 8px;
  background: #eef0f4;
  border-radius: 999px;
}

.rf-management-navigation button.is-active b {
  color: #ffffff;
  background: var(--rf-management-primary);
}

/* Panel */

.rf-management-panel {
  min-width: 0;
  padding: 20px;
  background: var(--rf-management-panel);
  border: 1px solid var(--rf-management-border);
  border-radius: 18px;
  box-shadow:
    0 10px 30px rgba(28, 35, 57, 0.045);
}

.rf-management-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.rf-management-panel-header > div {
  min-width: 0;
}

.rf-management-panel-header h2 {
  margin: 0;
  color: var(--rf-management-text);
  font-size: 16px;
  font-weight: 760;
  letter-spacing: -0.02em;
}

.rf-management-panel-header p {
  max-width: 700px;
  margin: 5px 0 0;
  color: var(--rf-management-muted);
  font-size: 10px;
  line-height: 1.5;
}

/* Filters */

.rf-management-filters {
  display: grid;
  grid-template-columns:
    minmax(220px, 1.6fr)
    minmax(150px, 0.7fr)
    minmax(150px, 0.7fr);
  gap: 10px;
  margin-bottom: 16px;
  padding: 12px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 12px;
}

.rf-management-filters label {
  display: grid;
  gap: 6px;
  color: #555e71;
  font-size: 8px;
  font-weight: 750;
}

.rf-management-filters input,
.rf-management-filters select {
  width: 100%;
  min-height: 38px;
  padding: 0 10px;
  color: var(--rf-management-text);
  font-size: 10px;
  background: #ffffff;
  border: 1px solid var(--rf-management-border);
  border-radius: 9px;
  outline: none;
}

.rf-management-filters input:focus,
.rf-management-filters select:focus {
  border-color: rgba(101, 88, 245, 0.52);
  box-shadow:
    0 0 0 3px rgba(101, 88, 245, 0.08);
}

/* Team cards */

.rf-team-member-grid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(300px, 1fr)
    );
  gap: 12px;
}

.rf-team-member-card {
  min-width: 0;
  padding: 15px;
  background:
    linear-gradient(
      145deg,
      rgba(101, 88, 245, 0.025),
      transparent 55%
    ),
    #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 15px;
  transition:
    transform 150ms ease,
    border-color 150ms ease,
    background 150ms ease,
    box-shadow 150ms ease;
}

.rf-team-member-card:hover {
  background-color: #ffffff;
  border-color: rgba(101, 88, 245, 0.23);
  transform: translateY(-2px);
  box-shadow:
    0 12px 27px rgba(28, 35, 57, 0.06);
}

.rf-team-member-card > header {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) auto;
  align-items: start;
  gap: 11px;
}

.rf-team-member-card > header > div {
  min-width: 0;
}

.rf-team-member-card h3,
.rf-team-member-card p,
.rf-team-member-card header span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-team-member-card h3 {
  margin: 3px 0 0;
  color: #333c4f;
  font-size: 12px;
  font-weight: 760;
}

.rf-team-member-card p {
  margin: 4px 0 0;
  color: #626c7f;
  font-size: 9px;
}

.rf-team-member-card header span {
  margin-top: 4px;
  color: var(--rf-management-muted);
  font-size: 8px;
}

.rf-member-status-row {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid #eceff4;
}

.rf-member-stat-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin-top: 12px;
}

.rf-member-stat {
  min-width: 0;
  padding: 9px;
  text-align: center;
  background: #ffffff;
  border: 1px solid #edf0f5;
  border-radius: 10px;
}

.rf-member-stat small,
.rf-member-stat strong {
  display: block;
}

.rf-member-stat small {
  overflow: hidden;
  color: var(--rf-management-muted);
  font-size: 7px;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.rf-member-stat strong {
  margin-top: 4px;
  color: #3d4659;
  font-size: 14px;
  font-weight: 780;
}

.rf-member-tool-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  margin-top: 12px;
}

.rf-tool-summary {
  min-width: 0;
  padding: 9px 10px;
  background: #f5f7fa;
  border: 1px solid #eceff4;
  border-radius: 10px;
}

.rf-tool-summary small,
.rf-tool-summary strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-tool-summary small {
  color: var(--rf-management-muted);
  font-size: 7px;
  font-weight: 700;
  text-transform: uppercase;
}

.rf-tool-summary strong {
  margin-top: 4px;
  color: #414a5d;
  font-size: 9px;
}

.rf-team-member-card > footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 9px;
  margin-top: 13px;
  padding-top: 12px;
  border-top: 1px solid #eceff4;
}

.rf-team-member-card > footer > button,
.rf-team-member-card > footer > div button {
  min-height: 31px;
  padding: 0 10px;
  color: #657083;
  font-size: 8px;
  font-weight: 740;
  background: #ffffff;
  border: 1px solid var(--rf-management-border);
  border-radius: 8px;
}

.rf-team-member-card > footer > button {
  color: var(--rf-management-primary);
  background: var(--rf-management-primary-soft);
  border-color: rgba(101, 88, 245, 0.18);
}

.rf-team-member-card > footer > div {
  display: flex;
  gap: 5px;
}

/* Avatars */

.rf-management-avatar {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  overflow: hidden;
  color: var(--rf-management-primary);
  background:
    linear-gradient(
      145deg,
      #e9e6ff,
      #f6f4ff
    );
  border: 1px solid rgba(101, 88, 245, 0.14);
  border-radius: 11px;
}

.rf-management-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rf-management-avatar b {
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.02em;
}

.rf-management-avatar--large {
  width: 52px;
  height: 52px;
  border-radius: 15px;
}

.rf-management-avatar--large b {
  font-size: 14px;
}

.rf-management-avatar--extra-large {
  width: 74px;
  height: 74px;
  border-radius: 20px;
}

.rf-management-avatar--extra-large b {
  font-size: 19px;
}

/* Status badges */

.rf-management-status,
.rf-availability-indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 9px;
  color: #60697a;
  font-size: 8px;
  font-weight: 760;
  white-space: nowrap;
  background: #f1f3f6;
  border: 1px solid #e1e5eb;
  border-radius: 999px;
}

.rf-availability-indicator {
  gap: 6px;
}

.rf-availability-indicator i {
  width: 7px;
  height: 7px;
  background: #9aa1b0;
  border-radius: 999px;
}

.rf-management-status--active,
.rf-management-status--available,
.rf-management-status--present,
.rf-management-status--checked_in,
.rf-management-status--completed,
.rf-management-status--answered,
.rf-management-status--qualified,
.rf-management-status--successful,
.rf-management-status--meeting_booked {
  color: #16794d;
  background: var(--rf-management-success-soft);
  border-color: #cbe9da;
}

.rf-management-status--pending,
.rf-management-status--assigned,
.rf-management-status--in_progress,
.rf-management-status--follow_up,
.rf-management-status--late,
.rf-management-status--busy,
.rf-management-status--normal {
  color: #976212;
  background: var(--rf-management-warning-soft);
  border-color: #f0ddb5;
}

.rf-management-status--high,
.rf-management-status--urgent {
  color: #9f5f14;
  background: #fff1df;
  border-color: #f1d2a9;
}

.rf-management-status--suspended,
.rf-management-status--disabled,
.rf-management-status--absent,
.rf-management-status--cancelled,
.rf-management-status--failed,
.rf-management-status--declined,
.rf-management-status--do_not_contact {
  color: #a33a4a;
  background: var(--rf-management-danger-soft);
  border-color: #efcfd5;
}

.rf-management-status--away,
.rf-management-status--manager,
.rf-management-status--caller,
.rf-management-status--admin,
.rf-management-status--owner {
  color: #316daf;
  background: var(--rf-management-info-soft);
  border-color: #d4e5f9;
}

.rf-management-status--viewer,
.rf-management-status--offline,
.rf-management-status--not_checked_in,
.rf-management-status--checked_out,
.rf-management-status--unknown,
.rf-management-status--low {
  color: #687184;
  background: #f1f3f6;
  border-color: #e0e4eb;
}

.rf-availability-indicator--available {
  color: #16794d;
  background: var(--rf-management-success-soft);
  border-color: #cbe9da;
}

.rf-availability-indicator--available i {
  background: var(--rf-management-success);
}

.rf-availability-indicator--busy {
  color: #976212;
  background: var(--rf-management-warning-soft);
  border-color: #f0ddb5;
}

.rf-availability-indicator--busy i {
  background: var(--rf-management-warning);
}

.rf-availability-indicator--away {
  color: #316daf;
  background: var(--rf-management-info-soft);
  border-color: #d4e5f9;
}

.rf-availability-indicator--away i {
  background: var(--rf-management-info);
}

.rf-availability-indicator--offline {
  color: #687184;
}

.rf-availability-indicator--offline i {
  background: #8f97a7;
}

/* Tables */

.rf-management-table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid #edf0f5;
  border-radius: 13px;
  scrollbar-width: thin;
  scrollbar-color: #cad1dd transparent;
}

.rf-management-table {
  width: 100%;
  border-collapse: collapse;
}

.rf-management-table--assignments {
  min-width: 980px;
}

.rf-management-table--performance {
  min-width: 1020px;
}

.rf-management-table th,
.rf-management-table td {
  padding: 12px 13px;
  text-align: left;
  border-bottom: 1px solid #edf0f5;
}

.rf-management-table th {
  color: #7d8597;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: #fafbfc;
}

.rf-management-table td {
  color: #465064;
  font-size: 10px;
}

.rf-management-table tbody tr:last-child td {
  border-bottom: 0;
}

.rf-management-table tbody tr:hover {
  background: #fbfbfe;
}

.rf-table-status-select {
  min-height: 31px;
  padding: 0 8px;
  color: #4d5668;
  font-size: 8px;
  background: #ffffff;
  border: 1px solid var(--rf-management-border);
  border-radius: 8px;
  outline: none;
}

/* Compact member and lead */

.rf-compact-member,
.rf-lead-identity {
  display: flex;
  align-items: center;
  min-width: 160px;
  gap: 9px;
}

.rf-compact-member > span,
.rf-lead-identity > div {
  min-width: 0;
}

.rf-compact-member strong,
.rf-compact-member small,
.rf-lead-identity strong,
.rf-lead-identity small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-compact-member strong,
.rf-lead-identity strong {
  color: #374054;
  font-size: 10px;
}

.rf-compact-member small,
.rf-lead-identity small {
  margin-top: 2px;
  color: var(--rf-management-muted);
  font-size: 8px;
}

.rf-lead-identity > span {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  color: var(--rf-management-primary);
  font-size: 9px;
  font-weight: 850;
  background: var(--rf-management-primary-soft);
  border-radius: 10px;
}

/* Task cards */

.rf-task-management-grid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(270px, 1fr)
    );
  gap: 11px;
}

.rf-managed-task-card {
  min-width: 0;
  padding: 14px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 13px;
}

.rf-managed-task-card > header {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.rf-managed-task-card h3 {
  margin: 13px 0 0;
  color: #353e51;
  font-size: 12px;
  font-weight: 760;
}

.rf-managed-task-card > p {
  min-height: 44px;
  margin: 7px 0 0;
  color: var(--rf-management-muted);
  font-size: 9px;
  line-height: 1.55;
}

.rf-managed-task-card__meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  margin-top: 12px;
}

.rf-managed-task-card__meta > div {
  min-width: 0;
  padding: 9px;
  background: #ffffff;
  border: 1px solid #edf0f5;
  border-radius: 9px;
}

.rf-managed-task-card__meta small,
.rf-managed-task-card__meta strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-managed-task-card__meta small {
  color: var(--rf-management-muted);
  font-size: 7px;
  text-transform: uppercase;
}

.rf-managed-task-card__meta strong {
  margin-top: 4px;
  color: #414a5d;
  font-size: 9px;
}

.rf-managed-task-card > footer {
  margin-top: 12px;
  padding-top: 11px;
  border-top: 1px solid #eceff4;
}

.rf-managed-task-card > footer select {
  width: 100%;
  min-height: 34px;
  padding: 0 9px;
  color: #4f586b;
  font-size: 9px;
  background: #ffffff;
  border: 1px solid var(--rf-management-border);
  border-radius: 8px;
}

/* Performance */

.rf-conversion-value {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 90px;
}

.rf-conversion-value > div {
  flex: 1;
  height: 6px;
  overflow: hidden;
  background: #e8ebf0;
  border-radius: 999px;
}

.rf-conversion-value > div span {
  display: block;
  height: 100%;
  background:
    linear-gradient(
      90deg,
      var(--rf-management-primary),
      #8a7fff
    );
  border-radius: inherit;
}

.rf-conversion-value strong {
  color: #4c5568;
  font-size: 8px;
}

/* Tools */

.rf-tool-overview-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 11px;
  margin-bottom: 16px;
}

.rf-tool-overview-card {
  min-width: 0;
  padding: 16px;
  background:
    linear-gradient(
      145deg,
      rgba(101, 88, 245, 0.05),
      transparent 65%
    ),
    #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 14px;
}

.rf-tool-overview-card header > div {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.rf-tool-overview-card small,
.rf-tool-overview-card strong {
  display: block;
}

.rf-tool-overview-card small {
  color: var(--rf-management-muted);
  font-size: 8px;
  font-weight: 750;
  text-transform: uppercase;
}

.rf-tool-overview-card strong {
  color: var(--rf-management-text);
  font-size: 24px;
  font-weight: 790;
}

.rf-tool-overview-card > p {
  margin: 9px 0 0;
  color: var(--rf-management-muted);
  font-size: 9px;
  line-height: 1.5;
}

.rf-tool-overview-card > div:last-child {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 11px;
}

.rf-tool-overview-card > div:last-child span {
  display: inline-flex;
  min-height: 23px;
  align-items: center;
  padding: 0 8px;
  color: #5f687a;
  font-size: 7px;
  background: #ffffff;
  border: 1px solid #e5e8ee;
  border-radius: 999px;
}

.rf-team-tool-list {
  display: grid;
  gap: 8px;
}

.rf-team-tool-row {
  display: grid;
  grid-template-columns:
    minmax(190px, 1.1fr)
    minmax(150px, 0.8fr)
    minmax(180px, 0.9fr)
    auto;
  align-items: center;
  gap: 10px;
  padding: 11px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 12px;
}

.rf-team-tool-row > button {
  min-height: 33px;
  padding: 0 11px;
  color: var(--rf-management-primary);
  font-size: 8px;
  font-weight: 750;
  background: var(--rf-management-primary-soft);
  border: 1px solid rgba(101, 88, 245, 0.18);
  border-radius: 8px;
}

/* Empty and access denied */

.rf-management-empty,
.rf-management-access-denied {
  display: flex;
  min-height: 220px;
  padding: 28px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: #fafbfc;
  border: 1px dashed #dfe3eb;
  border-radius: 13px;
}

.rf-management-empty > div,
.rf-management-access-denied > div {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  margin-bottom: 12px;
  color: var(--rf-management-primary);
  font-size: 12px;
  font-weight: 850;
  background: var(--rf-management-primary-soft);
  border-radius: 14px;
}

.rf-management-empty strong,
.rf-management-access-denied h1 {
  color: #3b4457;
  font-size: 13px;
}

.rf-management-access-denied h1 {
  margin: 0;
}

.rf-management-empty p,
.rf-management-access-denied p {
  max-width: 420px;
  margin: 7px 0 0;
  color: var(--rf-management-muted);
  font-size: 10px;
  line-height: 1.55;
}

.rf-management-access-denied {
  min-height: calc(100vh - 130px);
  background: var(--rf-management-panel);
  border-style: solid;
}

.rf-management-access-denied a {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  margin-top: 16px;
  padding: 0 14px;
  color: #ffffff;
  font-size: 10px;
  font-weight: 750;
  text-decoration: none;
  background: var(--rf-management-primary);
  border-radius: 10px;
}

/* Dialog */

.rf-management-modal-backdrop,
.rf-management-drawer-backdrop {
  position: fixed;
  z-index: 1200;
  inset: 0;
  display: flex;
  padding: 22px;
  background: rgba(18, 23, 36, 0.5);
  backdrop-filter: blur(6px);
}

.rf-management-modal-backdrop {
  align-items: center;
  justify-content: center;
}

.rf-management-dialog {
  width: min(620px, 100%);
  max-height: 94vh;
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid var(--rf-management-border);
  border-radius: 21px;
  box-shadow:
    0 30px 90px rgba(18, 23, 36, 0.24);
}

.rf-management-dialog--wide {
  width: min(880px, 100%);
}

.rf-management-dialog > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 22px 23px 17px;
  border-bottom: 1px solid var(--rf-management-border);
}

.rf-management-dialog h2 {
  margin: 0;
  font-size: 19px;
  font-weight: 780;
  letter-spacing: -0.025em;
}

.rf-management-dialog header span {
  display: block;
  max-width: 650px;
  margin-top: 6px;
  color: var(--rf-management-muted);
  font-size: 10px;
  line-height: 1.5;
}

.rf-management-dialog > header > button {
  padding: 0 5px;
  color: #7e8798;
  font-size: 23px;
  background: transparent;
  border: 0;
}

.rf-management-dialog-form {
  padding: 18px 22px 0;
}

.rf-dialog-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 13px;
}

.rf-management-field {
  display: grid;
  align-content: start;
  gap: 6px;
  min-width: 0;
  color: #555e71;
  font-size: 9px;
  font-weight: 750;
}

.rf-management-field--wide {
  grid-column: 1 / -1;
}

.rf-management-field > span b {
  color: var(--rf-management-danger);
}

.rf-management-field input,
.rf-management-field select,
.rf-management-field textarea {
  width: 100%;
  min-height: 40px;
  padding: 0 11px;
  color: var(--rf-management-text);
  font-size: 10px;
  font-weight: 500;
  background: #fafbfc;
  border: 1px solid var(--rf-management-border);
  border-radius: 9px;
  outline: none;
}

.rf-management-field textarea {
  min-height: 90px;
  padding: 10px 11px;
  resize: vertical;
  line-height: 1.5;
}

.rf-management-field input:focus,
.rf-management-field select:focus,
.rf-management-field textarea:focus {
  background: #ffffff;
  border-color: rgba(101, 88, 245, 0.52);
  box-shadow:
    0 0 0 3px rgba(101, 88, 245, 0.08);
}

.rf-management-checkbox {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 15px;
  padding: 11px;
  color: #596275;
  font-size: 9px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 10px;
}

.rf-management-checkbox input {
  width: 15px;
  height: 15px;
  accent-color: var(--rf-management-primary);
}

.rf-management-dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  margin: 18px -22px 0;
  padding: 16px 22px 20px;
  border-top: 1px solid var(--rf-management-border);
}

/* Lead selection */

.rf-lead-selection {
  margin-top: 16px;
  overflow: hidden;
  border: 1px solid var(--rf-management-border);
  border-radius: 12px;
}

.rf-lead-selection > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px;
  background: #fafbfc;
  border-bottom: 1px solid #edf0f5;
}

.rf-lead-selection h3 {
  margin: 0;
  color: #3c4558;
  font-size: 11px;
}

.rf-lead-selection header p {
  margin: 3px 0 0;
  color: var(--rf-management-muted);
  font-size: 8px;
}

.rf-lead-selection header input {
  width: min(260px, 50%);
  min-height: 35px;
  padding: 0 10px;
  color: var(--rf-management-text);
  font-size: 9px;
  background: #ffffff;
  border: 1px solid var(--rf-management-border);
  border-radius: 8px;
  outline: none;
}

.rf-lead-selection-list {
  max-height: 320px;
  overflow-y: auto;
}

.rf-lead-selection-item {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) minmax(100px, 0.55fr);
  align-items: center;
  gap: 10px;
  min-height: 54px;
  padding: 9px 12px;
  cursor: pointer;
  border-bottom: 1px solid #edf0f5;
}

.rf-lead-selection-item:last-child {
  border-bottom: 0;
}

.rf-lead-selection-item:hover {
  background: #fbfbfe;
}

.rf-lead-selection-item input {
  width: 15px;
  height: 15px;
  accent-color: var(--rf-management-primary);
}

.rf-lead-selection-item > span,
.rf-lead-selection-item em {
  min-width: 0;
}

.rf-lead-selection-item strong,
.rf-lead-selection-item small,
.rf-lead-selection-item em {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-lead-selection-item strong {
  color: #3d4659;
  font-size: 9px;
}

.rf-lead-selection-item small,
.rf-lead-selection-item em {
  margin-top: 3px;
  color: var(--rf-management-muted);
  font-size: 8px;
  font-style: normal;
}

.rf-lead-selection-empty {
  padding: 28px;
  color: var(--rf-management-muted);
  font-size: 10px;
  text-align: center;
}

/* Tool assignment note */

.rf-tool-assignment-note {
  margin-top: 16px;
  padding: 12px;
  color: #545e71;
  background: var(--rf-management-info-soft);
  border: 1px solid #d4e5f9;
  border-radius: 11px;
}

.rf-tool-assignment-note strong {
  font-size: 9px;
}

.rf-tool-assignment-note p {
  margin: 5px 0 0;
  font-size: 8px;
  line-height: 1.5;
}

/* Drawer */

.rf-management-drawer-backdrop {
  justify-content: flex-end;
  padding: 0;
}

.rf-member-details-drawer {
  width: min(480px, 100%);
  height: 100%;
  overflow-y: auto;
  background: #ffffff;
  box-shadow:
    -20px 0 60px rgba(18, 23, 36, 0.22);
}

.rf-member-details-drawer > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 23px;
  border-bottom: 1px solid var(--rf-management-border);
}

.rf-member-details-drawer > header > div {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 13px;
}

.rf-member-details-drawer header > div > span {
  min-width: 0;
}

.rf-member-details-drawer h2,
.rf-member-details-drawer header p,
.rf-member-details-drawer header small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-member-details-drawer h2 {
  margin: 0;
  color: var(--rf-management-text);
  font-size: 18px;
  font-weight: 780;
}

.rf-member-details-drawer header p {
  margin: 4px 0 0;
  color: #606a7d;
  font-size: 9px;
}

.rf-member-details-drawer header small {
  margin-top: 3px;
  color: var(--rf-management-muted);
  font-size: 8px;
}

.rf-member-details-drawer > header > button {
  padding: 0 5px;
  color: #7e8798;
  font-size: 23px;
  background: transparent;
  border: 0;
}

.rf-drawer-action-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--rf-management-border);
}

.rf-drawer-action-row button {
  min-height: 35px;
  padding: 0 8px;
  color: var(--rf-management-primary);
  font-size: 8px;
  font-weight: 750;
  background: var(--rf-management-primary-soft);
  border: 1px solid rgba(101, 88, 245, 0.18);
  border-radius: 8px;
}

.rf-drawer-section {
  padding: 18px;
  border-bottom: 1px solid var(--rf-management-border);
}

.rf-drawer-section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}

.rf-drawer-section-title h3 {
  margin: 0;
  color: #3b4457;
  font-size: 11px;
  font-weight: 760;
}

.rf-drawer-section-title button {
  padding: 4px 7px;
  color: var(--rf-management-primary);
  font-size: 8px;
  font-weight: 750;
  background: transparent;
  border: 0;
}

.rf-drawer-status-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.rf-drawer-metric-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
}

.rf-drawer-summary-list,
.rf-member-information-list {
  display: grid;
  gap: 7px;
}

.rf-information-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 38px;
  padding: 0 10px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 9px;
}

.rf-information-row span {
  color: var(--rf-management-muted);
  font-size: 8px;
}

.rf-information-row strong {
  max-width: 65%;
  overflow: hidden;
  color: #3f485b;
  font-size: 9px;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-member-edit-form {
  display: grid;
  gap: 11px;
}

.rf-member-details-drawer > footer {
  padding: 18px;
}

.rf-remove-member-button {
  width: 100%;
  min-height: 39px;
  color: #a33a4a;
  font-size: 9px;
  font-weight: 750;
  background: var(--rf-management-danger-soft);
  border: 1px solid #efcfd5;
  border-radius: 10px;
}

/* Loading */

.rf-management-skeleton-header,
.rf-management-skeleton-metrics > div,
.rf-management-skeleton-navigation,
.rf-management-skeleton-panel {
  background:
    linear-gradient(
      90deg,
      #eff1f5,
      #f8f9fb,
      #eff1f5
    );
  background-size: 220% 100%;
  animation:
    rf-management-shimmer
    1.4s infinite;
}

.rf-management-skeleton-header {
  height: 132px;
  margin-bottom: 18px;
  border-radius: 22px;
}

.rf-management-skeleton-metrics {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 13px;
  margin-bottom: 18px;
}

.rf-management-skeleton-metrics > div {
  height: 108px;
  border-radius: 16px;
}

.rf-management-skeleton-navigation {
  height: 56px;
  margin-bottom: 18px;
  border-radius: 14px;
}

.rf-management-skeleton-panel {
  height: 470px;
  border-radius: 18px;
}

@keyframes rf-management-shimmer {
  0% {
    background-position: 100% 0;
  }

  100% {
    background-position: -100% 0;
  }
}

/* Responsive */

@media (max-width: 1100px) {
  .rf-management-skeleton-metrics {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .rf-team-tool-row {
    grid-template-columns:
      minmax(180px, 1fr)
      minmax(140px, 0.8fr)
      minmax(160px, 0.9fr);
  }

  .rf-team-tool-row > button {
    grid-column: 1 / -1;
    justify-self: end;
  }
}

@media (max-width: 960px) {
  .rf-team-management-page {
    padding: 18px;
  }

  .rf-team-management-header {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-team-management-header__actions {
    justify-content: flex-end;
  }

  .rf-management-filters {
    grid-template-columns: 1fr 1fr;
  }

  .rf-management-search {
    grid-column: 1 / -1;
  }

  .rf-tool-overview-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .rf-team-management-page {
    padding: 12px;
  }

  .rf-team-management-header {
    padding: 18px;
    border-radius: 17px;
  }

  .rf-team-management-header h1 {
    font-size: 23px;
  }

  .rf-team-management-header__actions {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-team-management-header__actions .rf-management-button {
    width: 100%;
  }

  .rf-management-metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 9px;
  }

  .rf-management-panel {
    padding: 15px;
    border-radius: 15px;
  }

  .rf-management-panel-header {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-management-panel-header .rf-management-button {
    width: 100%;
  }

  .rf-management-filters {
    grid-template-columns: 1fr;
  }

  .rf-management-search {
    grid-column: auto;
  }

  .rf-team-member-grid {
    grid-template-columns: 1fr;
  }

  .rf-dialog-form-grid {
    grid-template-columns: 1fr;
  }

  .rf-management-field--wide {
    grid-column: auto;
  }

  .rf-management-dialog-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-management-dialog-footer .rf-management-button {
    width: 100%;
  }

  .rf-lead-selection > header {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-lead-selection header input {
    width: 100%;
  }

  .rf-lead-selection-item {
    grid-template-columns: 18px minmax(0, 1fr);
  }

  .rf-lead-selection-item em {
    grid-column: 2;
  }

  .rf-drawer-metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rf-team-tool-row {
    grid-template-columns: 1fr;
  }

  .rf-team-tool-row > button {
    grid-column: auto;
    width: 100%;
  }

  .rf-management-skeleton-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 480px) {
  .rf-team-management-page {
    padding: 8px;
  }

  .rf-team-management-header {
    padding: 15px;
  }

  .rf-team-management-header h1 {
    font-size: 20px;
  }

  .rf-management-metric-grid {
    grid-template-columns: 1fr;
  }

  .rf-team-member-card > header {
    grid-template-columns: 46px minmax(0, 1fr);
  }

  .rf-team-member-card > header .rf-management-status {
    grid-column: 1 / -1;
    justify-self: start;
  }

  .rf-member-stat-grid {
    grid-template-columns: 1fr;
  }

  .rf-member-tool-summary {
    grid-template-columns: 1fr;
  }

  .rf-team-member-card > footer {
    align-items: stretch;
    flex-direction: column;
  }

  .rf-team-member-card > footer > button {
    width: 100%;
  }

  .rf-team-member-card > footer > div {
    width: 100%;
  }

  .rf-team-member-card > footer > div button {
    flex: 1;
  }

  .rf-managed-task-card__meta {
    grid-template-columns: 1fr;
  }

  .rf-management-dialog {
    border-radius: 16px;
  }

  .rf-management-dialog > header {
    padding-right: 16px;
    padding-left: 16px;
  }

  .rf-management-dialog-form {
    padding-right: 15px;
    padding-left: 15px;
  }

  .rf-management-dialog-footer {
    margin-right: -15px;
    margin-left: -15px;
    padding-right: 15px;
    padding-left: 15px;
  }

  .rf-member-details-drawer {
    width: 100%;
  }

  .rf-member-details-drawer > header > div {
    align-items: flex-start;
  }

  .rf-management-avatar--extra-large {
    width: 58px;
    height: 58px;
    border-radius: 16px;
  }

  .rf-drawer-action-row,
  .rf-drawer-metric-grid {
    grid-template-columns: 1fr;
  }

  .rf-management-skeleton-metrics {
    grid-template-columns: 1fr;
  }
}

/* Dark theme */

[data-theme="dark"] .rf-team-management-page,
.dark .rf-team-management-page {
  --rf-management-bg: #111521;
  --rf-management-panel: #191e2b;
  --rf-management-border: #2a3040;
  --rf-management-text: #edf0f7;
  --rf-management-muted: #9da5b7;
  --rf-management-primary-soft: #292442;
  --rf-management-success-soft: #173528;
  --rf-management-warning-soft: #3a2d17;
  --rf-management-danger-soft: #3a1e25;
  --rf-management-info-soft: #1c2d45;

  background:
    radial-gradient(
      circle at top right,
      rgba(101, 88, 245, 0.1),
      transparent 28%
    ),
    var(--rf-management-bg);
}

[data-theme="dark"] .rf-team-management-header,
[data-theme="dark"] .rf-management-panel,
[data-theme="dark"] .rf-management-navigation,
.dark .rf-team-management-header,
.dark .rf-management-panel,
.dark .rf-management-navigation {
  background-color: var(--rf-management-panel);
}

[data-theme="dark"] .rf-management-filters,
[data-theme="dark"] .rf-team-member-card,
[data-theme="dark"] .rf-member-stat,
[data-theme="dark"] .rf-tool-summary,
[data-theme="dark"] .rf-managed-task-card,
[data-theme="dark"] .rf-managed-task-card__meta > div,
[data-theme="dark"] .rf-tool-overview-card,
[data-theme="dark"] .rf-team-tool-row,
[data-theme="dark"] .rf-management-empty,
[data-theme="dark"] .rf-information-row,
[data-theme="dark"] .rf-management-checkbox,
.dark .rf-management-filters,
.dark .rf-team-member-card,
.dark .rf-member-stat,
.dark .rf-tool-summary,
.dark .rf-managed-task-card,
.dark .rf-managed-task-card__meta > div,
.dark .rf-tool-overview-card,
.dark .rf-team-tool-row,
.dark .rf-management-empty,
.dark .rf-information-row,
.dark .rf-management-checkbox {
  background: #202636;
  border-color: #2d3445;
}

[data-theme="dark"] .rf-management-filters input,
[data-theme="dark"] .rf-management-filters select,
[data-theme="dark"] .rf-management-field input,
[data-theme="dark"] .rf-management-field select,
[data-theme="dark"] .rf-management-field textarea,
[data-theme="dark"] .rf-table-status-select,
[data-theme="dark"] .rf-managed-task-card > footer select,
.dark .rf-management-filters input,
.dark .rf-management-filters select,
.dark .rf-management-field input,
.dark .rf-management-field select,
.dark .rf-management-field textarea,
.dark .rf-table-status-select,
.dark .rf-managed-task-card > footer select {
  color: var(--rf-management-text);
  background: #202636;
  border-color: #2d3445;
}

[data-theme="dark"] .rf-management-table th,
.dark .rf-management-table th {
  background: #202636;
}

[data-theme="dark"] .rf-management-table td,
[data-theme="dark"] .rf-management-table th,
.dark .rf-management-table td,
.dark .rf-management-table th {
  border-color: #2b3242;
}

[data-theme="dark"] .rf-management-table tbody tr:hover,
.dark .rf-management-table tbody tr:hover {
  background: #202636;
}

[data-theme="dark"] .rf-management-dialog,
[data-theme="dark"] .rf-member-details-drawer,
.dark .rf-management-dialog,
.dark .rf-member-details-drawer {
  background: #191e2b;
}

[data-theme="dark"] .rf-management-button--secondary,
.dark .rf-management-button--secondary {
  color: #d3d8e3;
  background: #202636;
}
.rf-settings-layout {
  display: grid;
  grid-template-columns: 270px minmax(0, 1fr);
  align-items: start;
  gap: 18px;
}

.rf-settings-navigation-panel {
  position: sticky;
  top: 18px;
  overflow: hidden;
  background: #ffffff;
  border: 1px solid #e4e8f0;
  border-radius: 18px;
  box-shadow: 0 10px 30px rgba(28, 35, 57, 0.045);
}

.rf-settings-profile-summary {
  display: flex;
  padding: 22px 18px 18px;
  flex-direction: column;
  align-items: center;
  text-align: center;
  background:
    linear-gradient(
      145deg,
      rgba(101, 88, 245, 0.08),
      transparent 60%
    );
  border-bottom: 1px solid #e4e8f0;
}

.rf-settings-avatar--extra-large {
  width: 82px;
  height: 82px;
  border-radius: 23px;
}

.rf-settings-avatar--extra-large span {
  font-size: 20px;
}

.rf-settings-profile-summary h2 {
  margin: 13px 0 0;
  color: #182033;
  font-size: 16px;
  font-weight: 780;
}

.rf-settings-profile-summary p {
  margin: 5px 0 0;
  color: #657083;
  font-size: 9px;
}

.rf-settings-profile-summary > span:not(.rf-avatar):not(.rf-dashboard-status) {
  margin: 4px 0 10px;
  color: #8a92a2;
  font-size: 8px;
}

.rf-settings-avatar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}

.rf-settings-danger-link {
  padding: 5px;
  color: #b03f50;
  font-size: 8px;
  font-weight: 750;
  background: transparent;
  border: 0;
}

.rf-settings-navigation {
  display: grid;
  gap: 4px;
  padding: 9px;
}

.rf-settings-navigation button {
  display: grid;
  grid-template-columns: 35px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 58px;
  padding: 8px;
  color: #5f687b;
  text-align: left;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 11px;
}

.rf-settings-navigation button:hover {
  background: #f8f9fb;
}

.rf-settings-navigation button.is-active {
  color: #5144dc;
  background: #efedff;
  border-color: rgba(101, 88, 245, 0.16);
}

.rf-settings-navigation button > span {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 35px;
  height: 35px;
  color: #6558f5;
  font-size: 8px;
  font-weight: 850;
  background: #efedff;
  border-radius: 10px;
}

.rf-settings-navigation button strong,
.rf-settings-navigation button small {
  display: block;
}

.rf-settings-navigation button strong {
  font-size: 9px;
}

.rf-settings-navigation button small {
  margin-top: 3px;
  overflow: hidden;
  color: #8a92a2;
  font-size: 7px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-settings-content {
  min-width: 0;
}

.rf-settings-panel + .rf-settings-panel {
  margin-top: 18px;
}

.rf-settings-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.rf-settings-field {
  display: grid;
  align-content: start;
  gap: 6px;
  min-width: 0;
  color: #555e71;
  font-size: 9px;
  font-weight: 750;
}

.rf-settings-field--wide {
  grid-column: 1 / -1;
}

.rf-settings-field > span b {
  color: #d84b5d;
}

.rf-settings-field input,
.rf-settings-field select,
.rf-settings-field textarea,
.rf-working-hours-row input {
  width: 100%;
  min-height: 41px;
  padding: 0 11px;
  color: #182033;
  font-size: 10px;
  font-weight: 500;
  background: #fafbfc;
  border: 1px solid #e4e8f0;
  border-radius: 9px;
  outline: none;
}

.rf-settings-field textarea {
  min-height: 120px;
  padding: 11px;
  resize: vertical;
  line-height: 1.55;
}

.rf-settings-field input:focus,
.rf-settings-field select:focus,
.rf-settings-field textarea:focus,
.rf-working-hours-row input:focus {
  background: #ffffff;
  border-color: rgba(101, 88, 245, 0.52);
  box-shadow: 0 0 0 3px rgba(101, 88, 245, 0.08);
}

.rf-settings-field input:disabled {
  color: #868e9f;
  background: #f1f3f6;
}

.rf-settings-field > small {
  color: #8a92a2;
  font-size: 7px;
  font-weight: 500;
  line-height: 1.45;
}

.rf-settings-form-footer {
  display: flex;
  justify-content: flex-end;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #edf0f5;
}

.rf-settings-subsection {
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid #edf0f5;
}

.rf-settings-subsection > header h3 {
  margin: 0;
  color: #343d50;
  font-size: 12px;
}

.rf-settings-subsection > header p {
  margin: 5px 0 0;
  color: #737c8f;
  font-size: 8px;
}

.rf-working-hours-list {
  display: grid;
  gap: 8px;
  margin-top: 14px;
}

.rf-working-hours-row {
  display: grid;
  grid-template-columns: minmax(145px, 0.7fr) minmax(220px, 1fr) 90px;
  align-items: center;
  gap: 14px;
  padding: 11px;
  opacity: 0.7;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 11px;
}

.rf-working-hours-row.is-enabled {
  opacity: 1;
  background: #ffffff;
  border-color: rgba(101, 88, 245, 0.18);
}

.rf-working-hours-row > div {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 8px;
}

.rf-working-hours-row input {
  min-height: 35px;
}

.rf-working-hours-row > div span,
.rf-working-hours-row > small {
  color: #7c8597;
  font-size: 8px;
}

.rf-working-hours-row > small {
  text-align: right;
}

.rf-settings-switch {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  cursor: pointer;
}

.rf-settings-switch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.rf-settings-switch > span {
  position: relative;
  display: inline-flex;
  flex: 0 0 auto;
  width: 38px;
  height: 22px;
  background: #dfe3ea;
  border-radius: 999px;
  transition: background 160ms ease;
}

.rf-settings-switch > span::after {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  content: "";
  background: #ffffff;
  border-radius: 999px;
  box-shadow: 0 2px 6px rgba(28, 35, 57, 0.2);
  transition: transform 160ms ease;
}

.rf-settings-switch input:checked + span {
  background: #6558f5;
}

.rf-settings-switch input:checked + span::after {
  transform: translateX(16px);
}

.rf-settings-switch > strong {
  color: #424b5e;
  font-size: 9px;
}

.rf-settings-channel-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 16px;
}

.rf-notification-channel-card {
  display: flex;
  min-height: 100px;
  padding: 13px;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 12px;
}

.rf-notification-channel-card.is-enabled {
  background: #f7f6ff;
  border-color: rgba(101, 88, 245, 0.2);
}

.rf-notification-channel-card strong {
  color: #3d4659;
  font-size: 9px;
}

.rf-notification-channel-card p {
  margin: 5px 0 0;
  color: #737c8f;
  font-size: 7px;
  line-height: 1.5;
}

.rf-settings-toggle-list {
  display: grid;
  overflow: hidden;
  border: 1px solid #edf0f5;
  border-radius: 12px;
}

.rf-settings-toggle-row {
  display: flex;
  min-height: 68px;
  padding: 12px 14px;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  background: #ffffff;
  border-bottom: 1px solid #edf0f5;
}

.rf-settings-toggle-row:last-child {
  border-bottom: 0;
}

.rf-settings-toggle-row > div {
  min-width: 0;
}

.rf-settings-toggle-row strong {
  color: #3d4659;
  font-size: 9px;
}

.rf-settings-toggle-row p {
  margin: 4px 0 0;
  color: #737c8f;
  font-size: 8px;
  line-height: 1.45;
}

.rf-settings-information-box {
  margin-top: 16px;
  padding: 13px;
  color: #4f596c;
  background: #edf5ff;
  border: 1px solid #d4e5f9;
  border-radius: 11px;
}

.rf-settings-information-box strong {
  font-size: 9px;
}

.rf-settings-information-box p {
  margin: 5px 0 0;
  font-size: 8px;
  line-height: 1.55;
}

.rf-settings-information-box a {
  display: inline-flex;
  margin-top: 8px;
  color: #3375cb;
  font-size: 8px;
  font-weight: 750;
}

.rf-settings-security-stack {
  display: grid;
  gap: 18px;
}

.rf-security-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.rf-security-summary {
  padding: 13px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 11px;
}

.rf-security-summary small,
.rf-security-summary strong {
  display: block;
}

.rf-security-summary small {
  color: #737c8f;
  font-size: 7px;
  text-transform: uppercase;
}

.rf-security-summary strong {
  margin-top: 6px;
  color: #3d4659;
  font-size: 10px;
}

.rf-security-summary--success {
  background: #eaf8f1;
  border-color: #cbe9da;
}

.rf-security-summary--warning {
  background: #fff6e5;
  border-color: #f0ddb5;
}

.rf-security-summary--danger {
  background: #fff0f3;
  border-color: #efcfd5;
}

.rf-password-strength {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  margin-top: 14px;
  padding: 12px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 10px;
}

.rf-password-strength > div {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 4px;
}

.rf-password-strength > div span {
  height: 6px;
  background: #dfe3e9;
  border-radius: 999px;
}

.rf-password-strength > div span.is-weak {
  background: #d84b5d;
}

.rf-password-strength > div span.is-medium {
  background: #d28917;
}

.rf-password-strength > div span.is-good {
  background: #3375cb;
}

.rf-password-strength > div span.is-strong {
  background: #1d9962;
}

.rf-password-strength p {
  margin: 0;
}

.rf-password-strength strong,
.rf-password-strength p span {
  display: block;
}

.rf-password-strength strong {
  color: #414a5d;
  font-size: 8px;
}

.rf-password-strength p span {
  margin-top: 3px;
  color: #737c8f;
  font-size: 7px;
}

.rf-session-list {
  display: grid;
  gap: 8px;
}

.rf-session-card {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  padding: 11px;
  background: #fafbfc;
  border: 1px solid #edf0f5;
  border-radius: 11px;
}

.rf-session-card__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  color: #6558f5;
  font-size: 8px;
  font-weight: 850;
  background: #efedff;
  border-radius: 11px;
}

.rf-session-card__content {
  min-width: 0;
}

.rf-session-card__content strong,
.rf-session-card__content span,
.rf-session-card__content small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-session-card__content strong {
  color: #3d4659;
  font-size: 9px;
}

.rf-session-card__content span {
  margin-top: 3px;
  color: #657083;
  font-size: 8px;
}

.rf-session-card__content small {
  margin-top: 3px;
  color: #8a92a2;
  font-size: 7px;
}

.rf-settings-skeleton-navigation {
  height: 620px;
  border-radius: 18px;
  background:
    linear-gradient(
      90deg,
      #eff1f5,
      #f8f9fb,
      #eff1f5
    );
  background-size: 220% 100%;
  animation: rf-dashboard-shimmer 1.4s infinite;
}

@media (max-width: 980px) {
  .rf-settings-layout {
    grid-template-columns: 1fr;
  }

  .rf-settings-navigation-panel {
    position: static;
  }

  .rf-settings-profile-summary {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 12px;
    text-align: left;
  }

  .rf-settings-profile-summary h2,
  .rf-settings-profile-summary p,
  .rf-settings-profile-summary > span:not(.rf-avatar):not(.rf-dashboard-status) {
    grid-column: 2;
  }

  .rf-settings-profile-summary h2 {
    grid-row: 1;
  }

  .rf-settings-profile-summary p {
    grid-row: 1;
    align-self: end;
    margin-bottom: 3px;
    transform: translateY(17px);
  }

  .rf-settings-profile-summary > span:not(.rf-avatar):not(.rf-dashboard-status) {
    grid-row: 1;
    align-self: end;
    transform: translateY(32px);
  }

  .rf-settings-profile-summary .rf-dashboard-status,
  .rf-settings-avatar-actions {
    grid-column: 3;
  }

  .rf-settings-navigation {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .rf-settings-navigation button small {
    white-space: normal;
  }
}

@media (max-width: 720px) {
  .rf-settings-form-grid,
  .rf-settings-channel-grid,
  .rf-security-summary-grid {
    grid-template-columns: 1fr;
  }

  .rf-settings-field--wide {
    grid-column: auto;
  }

  .rf-settings-navigation {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rf-working-hours-row {
    grid-template-columns: 1fr;
  }

  .rf-working-hours-row > small {
    text-align: left;
  }

  .rf-password-strength {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .rf-settings-profile-summary {
    display: flex;
    text-align: center;
  }

  .rf-settings-profile-summary h2,
  .rf-settings-profile-summary p,
  .rf-settings-profile-summary > span:not(.rf-avatar):not(.rf-dashboard-status) {
    grid-column: auto;
    grid-row: auto;
    transform: none;
  }

  .rf-settings-navigation {
    grid-template-columns: 1fr;
  }

  .rf-settings-toggle-row {
    align-items: flex-start;
  }

  .rf-session-card {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .rf-session-card__actions {
    grid-column: 2;
  }
}
.role-assignment-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.role-assignment-actions .btn {
  min-height: 32px;
  padding: 0 11px;
  font-size: 12px;
  text-decoration: none;
}

.role-assignment-actions .btn.secondary {
  color: #5d6576;
  background: #ffffff;
  border: 1px solid #e2e6ee;
}

@media (max-width: 680px) {
  .role-assignment-actions {
    width: 100%;
    justify-content: flex-start;
  }
}
.sb-workspace-role {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  margin-top: 5px;
  padding: 0 8px;
  color: #6558f5;
  font-size: 10px;
  font-style: normal;
  font-weight: 750;
  background: #efedff;
  border: 1px solid #ddd9ff;
  border-radius: 999px;
}

.sb-avatar {
  overflow: hidden;
  text-decoration: none;
}

.sb-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sb-user-copy {
  min-width: 0;
  color: inherit;
  text-decoration: none;
}

.sb-user-copy:hover b {
  color: #6558f5;
}

.topbar-search {
  margin: 0;
}

.topbar-search input {
  min-width: 0;
}

/* ==========================================================
   Team communication
   ========================================================== */

.team-comms-shell {
  display: flex;
  flex-direction: column;
  gap: 20px;
  min-height: calc(100vh - 150px);
  padding: 24px;
}

.team-comms-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  padding: 24px 26px;
  background:
    linear-gradient(
      135deg,
      rgba(94, 82, 246, 0.08),
      rgba(255, 255, 255, 0.96)
    );
  border: 1px solid #e7e8f1;
  border-radius: 22px;
  box-shadow: 0 12px 32px rgba(31, 35, 48, 0.06);
}

.team-comms-header > div:first-child {
  max-width: 760px;
}

.team-comms-header span {
  display: block;
  margin-bottom: 8px;
  color: #6b5cf6;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.team-comms-header h2 {
  margin: 0;
  color: #191b26;
  font-size: clamp(24px, 3vw, 34px);
  line-height: 1.15;
}

.team-comms-header p {
  margin: 10px 0 0;
  color: #6f7485;
  font-size: 14px;
  line-height: 1.7;
}

.team-comms-switch {
  display: inline-flex;
  gap: 6px;
  padding: 5px;
  background: #f3f4f8;
  border: 1px solid #e2e4ec;
  border-radius: 14px;
}

.team-comms-switch button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 14px;
  color: #6d7281;
  font-size: 13px;
  font-weight: 750;
  background: transparent;
  border: 0;
  border-radius: 10px;
  cursor: pointer;
  transition:
    background 160ms ease,
    color 160ms ease,
    box-shadow 160ms ease;
}

.team-comms-switch button.active {
  color: #34304f;
  background: #ffffff;
  box-shadow: 0 5px 14px rgba(31, 35, 48, 0.08);
}

.team-comms-switch button b {
  display: inline-grid;
  place-items: center;
  min-width: 21px;
  height: 21px;
  padding: 0 6px;
  color: #ffffff;
  font-size: 11px;
  background: #6b5cf6;
  border-radius: 999px;
}

.team-comms-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 13px 16px;
  color: #8d2c39;
  background: #fff2f4;
  border: 1px solid #f2c9cf;
  border-radius: 14px;
}

.team-comms-error button {
  color: inherit;
  font-weight: 700;
  background: transparent;
  border: 0;
  cursor: pointer;
}

/* Main chat layout */

.team-chat-layout {
  display: grid;
  grid-template-columns: 320px minmax(0, 1fr);
  min-height: 680px;
  overflow: hidden;
  background: #ffffff;
  border: 1px solid #e6e7ee;
  border-radius: 22px;
  box-shadow: 0 14px 36px rgba(31, 35, 48, 0.06);
}

.team-channel-list {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: #f9fafc;
  border-right: 1px solid #e9eaf0;
}

.team-channel-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 18px 12px;
}

.team-channel-title > div {
  min-width: 0;
}

.team-channel-title b {
  display: block;
  color: #1f2230;
  font-size: 15px;
}

.team-channel-title small {
  display: block;
  margin-top: 3px;
  color: #8a8f9f;
  font-size: 11px;
}

.team-channel-title > button {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  color: #ffffff;
  font-size: 22px;
  background: #6758f5;
  border: 0;
  border-radius: 10px;
  cursor: pointer;
  box-shadow: 0 7px 16px rgba(103, 88, 245, 0.25);
}

.team-comms-search {
  display: block;
  padding: 0 14px 12px;
}

.team-comms-search input {
  width: 100%;
  height: 40px;
  padding: 0 12px;
  color: #282b38;
  background: #ffffff;
  border: 1px solid #e1e3eb;
  border-radius: 11px;
  outline: none;
}

.team-comms-search input:focus {
  border-color: #8d82f6;
  box-shadow: 0 0 0 3px rgba(103, 88, 245, 0.1);
}

.team-channel-scroll,
.team-member-scroll {
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
}

.team-channel-scroll {
  flex: 1 1 auto;
  padding: 0 10px 12px;
}

.team-channel-scroll > button {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  width: 100%;
  margin-bottom: 4px;
  padding: 10px;
  text-align: left;
  background: transparent;
  border: 0;
  border-radius: 13px;
  cursor: pointer;
  transition:
    background 150ms ease,
    transform 150ms ease;
}

.team-channel-scroll > button:hover {
  background: #f0f1f7;
}

.team-channel-scroll > button.active {
  background: #eceaff;
}

.team-channel-scroll > button.active .team-channel-avatar {
  color: #ffffff;
  background: #6758f5;
}

.team-channel-scroll > button > span {
  min-width: 0;
}

.team-channel-scroll > button b {
  display: block;
  overflow: hidden;
  color: #252834;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-channel-scroll > button small {
  display: block;
  margin-top: 3px;
  overflow: hidden;
  color: #8a8f9e;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-channel-scroll > button em {
  display: grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  color: #ffffff;
  font-size: 10px;
  font-style: normal;
  font-weight: 800;
  background: #6758f5;
  border-radius: 999px;
}

.team-direct-title {
  padding: 14px 16px 10px;
  border-top: 1px solid #e7e8ee;
}

.team-direct-title span {
  color: #8b8f9f;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.team-member-scroll {
  max-height: 270px;
  padding: 0 10px 14px;
}

.team-person-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px;
  border-radius: 12px;
}

.team-person-row:hover {
  background: #f0f1f6;
}

.direct-person {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  min-width: 0;
  flex: 1;
  padding: 4px;
  text-align: left;
  background: transparent;
  border: 0;
  cursor: pointer;
}

.direct-person > span {
  min-width: 0;
}

.direct-person b {
  display: block;
  overflow: hidden;
  color: #272a35;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.direct-person small {
  display: block;
  margin-top: 2px;
  color: #969aa7;
  font-size: 10px;
}

.team-person-actions {
  display: flex;
  gap: 4px;
}

.team-person-actions button {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  color: #6a6f80;
  background: #ffffff;
  border: 1px solid #e1e3eb;
  border-radius: 8px;
  cursor: pointer;
}

.team-person-actions button:hover {
  color: #5f50ef;
  border-color: #c7c1fb;
}

/* Avatars and presence */

.team-channel-avatar,
.team-member-avatar {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  width: 38px;
  height: 38px;
  overflow: hidden;
  color: #5d55a6;
  font-size: 12px;
  font-style: normal;
  font-weight: 800;
  background: #e9e7ff;
  border: 1px solid #dcd8ff;
  border-radius: 12px;
}

.team-channel-avatar.large,
.team-member-avatar.large {
  width: 48px;
  height: 48px;
  font-size: 15px;
  border-radius: 15px;
}

.team-member-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.team-presence-dot {
  display: block;
  width: 9px;
  height: 9px;
  background: #adb1bd;
  border: 2px solid #ffffff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px rgba(23, 27, 39, 0.08);
}

.team-presence-dot.online,
.team-presence-dot.available {
  background: #2db87d;
}

.team-presence-dot.busy {
  background: #e65265;
}

.team-presence-dot.away {
  background: #e9a83a;
}

/* Message panel */

.team-message-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: #ffffff;
}

.team-message-panel > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 82px;
  padding: 16px 20px;
  border-bottom: 1px solid #e9eaf0;
}

.team-message-header-main {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.team-message-header-main > div {
  min-width: 0;
}

.team-message-header-main small {
  color: #8b8f9f;
  font-size: 10px;
  font-weight: 750;
  text-transform: uppercase;
}

.team-message-header-main h3 {
  margin: 3px 0 2px;
  overflow: hidden;
  color: #1f2230;
  font-size: 17px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-message-header-main span {
  color: #9296a4;
  font-size: 11px;
}

.team-header-call-actions {
  display: flex;
  gap: 8px;
}

.team-header-call-actions button {
  min-height: 36px;
  padding: 0 12px;
  color: #5146d7;
  font-size: 11px;
  font-weight: 750;
  background: #f0eeff;
  border: 1px solid #dcd8ff;
  border-radius: 10px;
  cursor: pointer;
}

.team-message-stream {
  flex: 1 1 auto;
  min-height: 0;
  padding: 22px;
  overflow-y: auto;
  background:
    linear-gradient(
      180deg,
      #ffffff 0%,
      #fcfcfe 100%
    );
}

.team-message-stream > article {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 10px;
  max-width: 78%;
  /* margin-bottom: 18px; */
}

.team-message-stream > article.mine {
  margin-left: auto;
}

.team-message-stream > article.mine > .team-member-avatar {
  order: 2;
}

.team-message-stream > article.mine > div {
  order: 1;
}

.team-message-stream > article > div {
  min-width: 0;
}

.team-message-stream article p {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 0 0 5px;
}

.team-message-stream article p b {
  color: #323542;
  font-size: 12px;
}

.team-message-stream article p small {
  color: #9a9eaa;
  font-size: 10px;
}

.team-message-stream article > div > div:not(.team-attachment-list):not(.team-shared-lead) {
  width: fit-content;
  max-width: 100%;
  padding: 11px 13px;
  color: #404350;
  font-size: 13px;
  line-height: 1.55;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  background: #f1f2f6;
  border-radius: 6px 15px 15px 15px;
}

.team-message-stream article.mine > div > div:not(.team-attachment-list):not(.team-shared-lead) {
  margin-left: auto;
  color: #ffffff;
  background: #6657f3;
  border-radius: 15px 6px 15px 15px;
}

.team-message-receipt {
  display: block;
  margin-top: 5px;
  color: #a1a5b0;
  font-size: 9px;
  text-align: right;
}

.team-typing {
  display: flex;
  align-items: center;
  gap: 4px;
  margin: 8px 0;
  color: #979ba8;
}

.team-typing > span {
  width: 6px;
  height: 6px;
  background: #9d96ef;
  border-radius: 50%;
  animation: teamTypingPulse 1.2s infinite ease-in-out;
}

.team-typing > span:nth-child(2) {
  animation-delay: 0.15s;
}

.team-typing > span:nth-child(3) {
  animation-delay: 0.3s;
}

.team-typing small {
  margin-left: 5px;
  font-size: 10px;
}

@keyframes teamTypingPulse {
  0%,
  80%,
  100% {
    opacity: 0.35;
    transform: translateY(0);
  }

  40% {
    opacity: 1;
    transform: translateY(-3px);
  }
}

.team-message-loading {
  display: flex;
  justify-content: center;
  gap: 7px;
  padding: 40px 0;
}

.team-message-loading span {
  width: 9px;
  height: 9px;
  background: #8b80ef;
  border-radius: 50%;
  animation: teamTypingPulse 1.2s infinite ease-in-out;
}

.team-message-loading span:nth-child(2) {
  animation-delay: 0.15s;
}

.team-message-loading span:nth-child(3) {
  animation-delay: 0.3s;
}

.team-empty {
  display: grid;
  place-items: center;
  min-height: 230px;
  padding: 36px;
  text-align: center;
}

.team-empty b {
  color: #343744;
  font-size: 16px;
}

.team-empty p {
  max-width: 440px;
  margin: 8px 0 0;
  color: #8a8f9f;
  font-size: 12px;
  line-height: 1.7;
}

/* Composer */

.team-message-panel > footer {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: flex-end;
  gap: 10px;
  padding: 14px;
  background: #fbfbfd;
  border-top: 1px solid #e8e9ef;
}

.team-message-tools {
  display: flex;
  gap: 7px;
}

.team-message-tools > button,
.team-lead-share-menu > button {
  display: grid;
  place-items: center;
  min-width: 38px;
  height: 38px;
  padding: 0 8px;
  color: #6258a6;
  font-size: 10px;
  font-weight: 800;
  background: #ffffff;
  border: 1px solid #dedfe7;
  border-radius: 10px;
  cursor: pointer;
}

.team-message-panel > footer textarea {
  width: 100%;
  min-height: 42px;
  max-height: 140px;
  padding: 11px 13px;
  resize: vertical;
  color: #343744;
  font: inherit;
  font-size: 13px;
  background: #ffffff;
  border: 1px solid #dddfe7;
  border-radius: 12px;
  outline: none;
}

.team-message-panel > footer textarea:focus {
  border-color: #9388f7;
  box-shadow: 0 0 0 3px rgba(103, 88, 245, 0.09);
}

.team-message-panel > footer > button {
  min-height: 42px;
  padding: 0 16px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  background: #6657f3;
  border: 0;
  border-radius: 11px;
  cursor: pointer;
  box-shadow: 0 8px 18px rgba(102, 87, 243, 0.22);
}

.team-message-panel > footer > button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
}

/* Lead sharing */

.team-lead-share-menu {
  position: relative;
}

.team-lead-share-menu > div {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 0;
  z-index: 30;
  width: 260px;
  max-height: 280px;
  padding: 6px;
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid #dedfe7;
  border-radius: 13px;
  box-shadow: 0 16px 40px rgba(25, 28, 40, 0.14);
}

.team-lead-share-menu > div button {
  width: 100%;
  padding: 10px;
  overflow: hidden;
  color: #373a47;
  font-size: 11px;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  background: transparent;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
}

.team-lead-share-menu > div button:hover {
  background: #f2f1ff;
}

.team-shared-lead {
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-width: 360px;
  padding: 13px;
  background: #ffffff;
  border: 1px solid #dddff0;
  border-left: 4px solid #6657f3;
  border-radius: 12px;
  box-shadow: 0 6px 16px rgba(31, 35, 48, 0.06);
}

.team-shared-lead > span {
  color: #766beb;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.team-shared-lead strong {
  color: #262936;
  font-size: 13px;
}

.team-shared-lead small {
  color: #858a99;
  font-size: 10px;
}

.team-shared-lead a {
  width: fit-content;
  margin-top: 5px;
  color: #5e51eb;
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
}

/* Attachments */

.team-attachment-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 7px;
}

.team-image-attachment {
  display: block;
  width: 180px;
  max-width: 100%;
  overflow: hidden;
  border-radius: 12px;
  border: 1px solid #dedfe7;
}

.team-image-attachment img {
  display: block;
  width: 100%;
  max-height: 180px;
  object-fit: cover;
}

.team-file-attachment {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 210px;
  padding: 10px;
  color: inherit;
  text-decoration: none;
  background: #ffffff;
  border: 1px solid #e0e1e8;
  border-radius: 11px;
}

.team-file-attachment > span {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  color: #6657f3;
  font-size: 9px;
  font-weight: 850;
  background: #efedff;
  border-radius: 9px;
}

.team-file-attachment strong {
  display: block;
  max-width: 160px;
  overflow: hidden;
  color: #343744;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-file-attachment small {
  display: block;
  margin-top: 2px;
  color: #979ba8;
  font-size: 9px;
}

/* ==========================================================
   Work assignments
   ========================================================== */

.team-task-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  gap: 20px;
}

.task-board,
.task-editor {
  background: #ffffff;
  border: 1px solid #e5e7ee;
  border-radius: 20px;
  box-shadow: 0 12px 32px rgba(31, 35, 48, 0.05);
}

.task-board {
  padding: 20px;
}

.task-board-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 18px;
}

.task-board-head h3 {
  margin: 0;
  color: #20232f;
  font-size: 18px;
}

.task-board-head p {
  max-width: 620px;
  margin: 7px 0 0;
  color: #878c9b;
  font-size: 12px;
  line-height: 1.65;
}

.work-task {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 12px;
  padding: 16px;
  overflow: hidden;
  background: #fbfbfd;
  border: 1px solid #e5e7ed;
  border-radius: 15px;
}

.work-task::before {
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  content: "";
  background: #9aa0ad;
}

.work-task.high::before {
  background: #e69a36;
}

.work-task.urgent::before {
  background: #e34e61;
}

.work-task.low::before {
  background: #47a8d8;
}

.task-priority {
  padding: 5px 8px;
  color: #777c8b;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: #eceef3;
  border-radius: 999px;
}

.task-main {
  min-width: 0;
}

.task-main h4 {
  margin: 0;
  color: #2a2d39;
  font-size: 14px;
}

.task-main p {
  margin: 7px 0 10px;
  color: #747987;
  font-size: 12px;
  line-height: 1.6;
}

.task-main > small {
  color: #9b9faa;
  font-size: 9px;
}

.task-lead {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 9px;
  padding: 8px 10px;
  background: #f0efff;
  border-radius: 9px;
}

.task-lead b {
  color: #494278;
  font-size: 11px;
}

.task-lead span {
  overflow: hidden;
  color: #7e789b;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.task-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.task-actions .status {
  padding: 5px 8px;
  color: #717684;
  font-size: 9px;
  font-weight: 800;
  background: #eceef3;
  border-radius: 999px;
}

.task-actions .status.in_progress {
  color: #5e51e7;
  background: #efedff;
}

.task-actions .status.completed {
  color: #247758;
  background: #e4f7ef;
}

.task-actions .status.blocked,
.task-actions .status.cancelled {
  color: #9b3440;
  background: #ffecef;
}

.task-actions button,
.task-actions select {
  min-height: 33px;
  padding: 0 10px;
  color: #5549df;
  font-size: 10px;
  font-weight: 750;
  background: #ffffff;
  border: 1px solid #d8d5f8;
  border-radius: 9px;
  cursor: pointer;
}

.task-editor {
  align-self: start;
  padding: 20px;
}

.task-editor > span {
  display: block;
  margin-bottom: 5px;
  color: #6b5cf6;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.task-editor h3 {
  margin: 0 0 18px;
  color: #252834;
  font-size: 18px;
}

.task-editor label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-bottom: 13px;
  color: #676c7b;
  font-size: 11px;
  font-weight: 750;
}

.task-editor input,
.task-editor select,
.task-editor textarea {
  width: 100%;
  min-height: 42px;
  padding: 10px 11px;
  color: #343744;
  font: inherit;
  font-size: 12px;
  background: #ffffff;
  border: 1px solid #dfe1e8;
  border-radius: 10px;
  outline: none;
}

.task-editor textarea {
  min-height: 100px;
  resize: vertical;
}

.task-editor input:focus,
.task-editor select:focus,
.task-editor textarea:focus {
  border-color: #9186f4;
  box-shadow: 0 0 0 3px rgba(103, 88, 245, 0.09);
}

.task-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.create-task-button {
  width: 100%;
  min-height: 44px;
  margin-top: 4px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  background: #6657f3;
  border: 0;
  border-radius: 11px;
  cursor: pointer;
  box-shadow: 0 8px 18px rgba(102, 87, 243, 0.22);
}

.create-task-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
}

/* ==========================================================
   Dialogs
   ========================================================== */

.team-dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 500;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(20, 22, 31, 0.58);
  backdrop-filter: blur(5px);
}

.team-dialog {
  width: min(560px, 100%);
  max-height: 88vh;
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.7);
  border-radius: 20px;
  box-shadow: 0 28px 80px rgba(11, 13, 20, 0.28);
}

.team-dialog > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 20px;
  border-bottom: 1px solid #e8e9ef;
}

.team-dialog > header span {
  color: #6b5cf6;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.team-dialog > header h3 {
  margin: 4px 0 0;
  color: #242734;
  font-size: 20px;
}

.team-dialog > header button {
  width: 34px;
  height: 34px;
  color: #787d8c;
  font-size: 22px;
  background: #f3f4f7;
  border: 0;
  border-radius: 10px;
  cursor: pointer;
}

.team-dialog > label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin: 16px 20px 0;
  color: #686d7d;
  font-size: 11px;
  font-weight: 750;
}

.team-dialog input,
.team-dialog textarea {
  width: 100%;
  min-height: 42px;
  padding: 10px 11px;
  color: #343744;
  font: inherit;
  font-size: 12px;
  border: 1px solid #dfe1e8;
  border-radius: 10px;
  outline: none;
}

.team-dialog textarea {
  min-height: 85px;
  resize: vertical;
}

.team-group-member-list {
  max-height: 260px;
  margin: 18px 20px 0;
  padding: 6px;
  overflow-y: auto;
  background: #f8f9fb;
  border: 1px solid #e4e6ed;
  border-radius: 13px;
}

.team-group-member {
  display: grid;
  grid-template-columns: auto 38px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 8px;
  border-radius: 10px;
}

.team-group-member:hover {
  background: #ffffff;
}

.team-group-member input {
  width: 16px;
  height: 16px;
  min-height: 0;
}

.team-group-member b {
  display: block;
  color: #333642;
  font-size: 12px;
}

.team-group-member small {
  display: block;
  margin-top: 2px;
  color: #9296a4;
  font-size: 9px;
}

.team-dialog > footer {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding: 18px 20px 20px;
}

.team-dialog > footer button {
  min-height: 40px;
  padding: 0 15px;
  color: #666b79;
  font-size: 11px;
  font-weight: 750;
  background: #f1f2f6;
  border: 0;
  border-radius: 10px;
  cursor: pointer;
}

.team-dialog > footer button.primary {
  color: #ffffff;
  background: #6657f3;
}

/* ==========================================================
   Internal calling
   ========================================================== */

.team-incoming-call {
  width: min(380px, 100%);
  padding: 30px;
  text-align: center;
  background: #ffffff;
  border-radius: 22px;
  box-shadow: 0 30px 90px rgba(10, 12, 20, 0.3);
}

.team-incoming-call .team-member-avatar {
  margin: 0 auto 16px;
}

.team-incoming-call > span {
  color: #777c8b;
  font-size: 11px;
  font-weight: 750;
}

.team-incoming-call h3 {
  margin: 7px 0 22px;
  color: #242734;
  font-size: 22px;
}

.team-incoming-call > div {
  display: flex;
  justify-content: center;
  gap: 12px;
}

.team-incoming-call button {
  min-width: 112px;
  min-height: 44px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  border: 0;
  border-radius: 12px;
  cursor: pointer;
}

.team-incoming-call button.reject {
  background: #e45566;
}

.team-incoming-call button.accept {
  background: #2bb67a;
}

.team-call-overlay {
  position: fixed;
  inset: 0;
  z-index: 600;
  display: flex;
  flex-direction: column;
  background: #11131a;
}

.team-call-stage {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.team-call-remote-video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: #151821;
}

.team-call-local-video {
  position: absolute;
  right: 22px;
  bottom: 22px;
  z-index: 4;
  width: min(240px, 28vw);
  aspect-ratio: 16 / 10;
  object-fit: cover;
  background: #252936;
  border: 2px solid rgba(255, 255, 255, 0.7);
  border-radius: 16px;
  box-shadow: 0 16px 38px rgba(0, 0, 0, 0.34);
}

.team-call-fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 10px;
  color: #ffffff;
  pointer-events: none;
}

.team-call-fallback h3 {
  margin: 0;
  font-size: 24px;
}

.team-call-fallback span {
  color: rgba(255, 255, 255, 0.7);
  font-size: 12px;
}

.team-call-overlay > footer {
  display: flex;
  justify-content: center;
  gap: 12px;
  padding: 18px;
  background: #171a23;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.team-call-overlay > footer button {
  min-width: 110px;
  min-height: 44px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  background: #2a2e3a;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  cursor: pointer;
}

.team-call-overlay > footer button.active {
  background: #5d50e4;
}

.team-call-overlay > footer button.end {
  background: #df4e60;
}

/* ==========================================================
   Responsive
   ========================================================== */

@media (max-width: 1100px) {
  .team-task-layout {
    grid-template-columns: 1fr;
  }

  .task-editor {
    order: -1;
  }
}

@media (max-width: 900px) {
  .team-comms-shell {
    padding: 16px;
  }

  .team-comms-header {
    align-items: stretch;
    flex-direction: column;
  }

  .team-comms-switch {
    width: 100%;
  }

  .team-comms-switch button {
    justify-content: center;
    flex: 1;
  }

  .team-chat-layout {
    grid-template-columns: 270px minmax(0, 1fr);
  }

  .team-header-call-actions {
    display: none;
  }
}

@media (max-width: 720px) {
  .team-comms-shell {
    padding: 10px;
  }

  .team-comms-header {
    padding: 18px;
    border-radius: 16px;
  }

  .team-chat-layout {
    display: flex;
    flex-direction: column;
    min-height: auto;
    border-radius: 16px;
  }

  .team-channel-list {
    max-height: 380px;
    border-right: 0;
    border-bottom: 1px solid #e9eaf0;
  }

  .team-member-scroll {
    max-height: 190px;
  }

  .team-message-panel {
    min-height: 620px;
  }

  .team-message-stream > article {
    max-width: 94%;
  }

  .team-message-panel > footer {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .team-message-panel > footer > button {
    grid-column: 1 / -1;
    width: 100%;
  }

  .work-task {
    grid-template-columns: 1fr;
  }

  .task-actions {
    align-items: stretch;
  }

  .task-actions button,
  .task-actions select {
    width: 100%;
  }

  .task-form-row {
    grid-template-columns: 1fr;
  }

  .team-call-local-video {
    right: 12px;
    bottom: 12px;
    width: 42vw;
  }

  .team-call-overlay > footer {
    flex-wrap: wrap;
  }

  .team-call-overlay > footer button {
    min-width: 95px;
  }
}

/* ==========================================================
   Team Communication â€” Slack-style refinement
   Place this AFTER the existing team communication CSS
   ========================================================== */

.team-comms-shell {
  gap: 16px;
  padding: 20px;
  background:
    radial-gradient(
      circle at top right,
      rgba(111, 76, 255, 0.07),
      transparent 32%
    ),
    #f7f7fb;
}

.team-comms-header {
  align-items: center;
  padding: 22px 26px;
  background: #ffffff;
  border: 1px solid #e6e7ef;
  border-radius: 18px;
  box-shadow:
    0 1px 2px rgba(20, 22, 35, 0.03),
    0 12px 32px rgba(20, 22, 35, 0.05);
}

.team-comms-header h2 {
  font-size: 27px;
  letter-spacing: -0.035em;
}

.team-comms-header p {
  max-width: 780px;
  margin-top: 7px;
  color: #74798a;
  line-height: 1.55;
}

.team-comms-switch {
  flex-shrink: 0;
  padding: 4px;
  background: #f2f3f7;
  border-color: #e1e3ea;
  border-radius: 12px;
}

.team-comms-switch button {
  min-height: 42px;
  padding-inline: 17px;
  border-radius: 9px;
}

.team-comms-switch button.active {
  color: #312d49;
  background: #ffffff;
  box-shadow:
    0 1px 3px rgba(18, 20, 30, 0.08),
    0 5px 14px rgba(18, 20, 30, 0.05);
}

/* Main application frame */

.team-chat-layout {
  grid-template-columns: 310px minmax(0, 1fr);
  height: calc(100vh - 270px);
  min-height: 660px;
  overflow: hidden;
  background: #ffffff;
  border: 1px solid #e2e4eb;
  border-radius: 18px;
  box-shadow:
    0 1px 2px rgba(20, 22, 35, 0.03),
    0 16px 42px rgba(20, 22, 35, 0.06);
}

/* Slack-like conversation sidebar */

.team-channel-list {
  background: #f8f8fb;
  border-right: 1px solid #e4e5eb;
}

.team-channel-title {
  padding: 20px 17px 12px;
}

.team-channel-title b {
  font-size: 16px;
  letter-spacing: -0.015em;
}

.team-channel-title > button {
  width: 36px;
  height: 36px;
  font-size: 21px;
  background:
    linear-gradient(
      135deg,
      #7564f7,
      #a43ed4
    );
  border-radius: 10px;
  box-shadow: 0 8px 18px rgba(111, 82, 239, 0.23);
}

.team-comms-search {
  padding-inline: 14px;
}

.team-comms-search input {
  height: 42px;
  padding-inline: 13px;
  font-size: 13px;
  background: #ffffff;
  border-color: #dcdee7;
  border-radius: 10px;
}

.team-channel-scroll {
  padding: 0 9px 14px;
}

.team-channel-scroll > button {
  grid-template-columns: 38px minmax(0, 1fr) auto;
  min-height: 57px;
  margin-bottom: 3px;
  padding: 8px 10px;
  border-radius: 10px;
}

.team-channel-scroll > button:hover {
  background: #eeeeF5;
}

.team-channel-scroll > button.active {
  background: #e8e5ff;
}

.team-channel-scroll > button.active b {
  color: #30285e;
}

.team-channel-scroll > button b {
  font-size: 13px;
  font-weight: 750;
}

.team-channel-scroll > button small {
  color: #8a8e9b;
  font-size: 11px;
}

.team-channel-avatar {
  width: 36px;
  height: 36px;
  color: #6557dc;
  background: #e9e6ff;
  border: 0;
  border-radius: 10px;
}

.team-direct-title {
  margin: 0 14px;
  padding: 15px 2px 9px;
}

.team-member-scroll {
  padding: 0 9px 15px;
}

.team-person-row {
  min-height: 52px;
  padding: 5px 7px;
}

.direct-person {
  grid-template-columns: 36px minmax(0, 1fr) auto;
}

.direct-person b {
  max-width: 130px;
  font-size: 12px;
}

.direct-person small {
  font-size: 10px;
}

.team-person-actions {
  opacity: 0;
  transition: opacity 140ms ease;
}

.team-person-row:hover .team-person-actions {
  opacity: 1;
}

.team-person-actions button {
  width: 30px;
  height: 30px;
  background: #ffffff;
  border-color: #dfe1e8;
}

/* Conversation header */

.team-message-panel {
  min-width: 0;
  background: #ffffff;
}

.team-message-panel > header {
  min-height: 78px;
  padding: 14px 20px;
  background: rgba(255, 255, 255, 0.96);
  border-bottom: 1px solid #e6e7ed;
}

.team-message-header-main {
  min-width: 0;
}

.team-message-header-main h3 {
  margin: 2px 0;
  font-size: 17px;
  letter-spacing: -0.02em;
}

.team-message-header-main small {
  color: #777b8c;
  font-size: 10px;
  letter-spacing: 0.055em;
}

.team-message-header-main span {
  color: #9599a5;
}

.team-header-call-actions button {
  min-height: 38px;
  padding-inline: 13px;
  color: #5144d8;
  background: #f2f0ff;
  border-color: #ddd8ff;
}

/* Message stream */

.team-message-stream {
  padding: 18px 24px 26px;
  background: #ffffff;
  scroll-behavior: smooth;
}

/*
 * Critical fix:
 * sent messages must reverse both content order AND grid columns.
 */
.team-message-stream > article {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  align-items: flex-start;
  gap: 10px;
  width: 100%;
  max-width: 760px;
  margin: 0 0 4px;
  padding: 7px 8px;
  border-radius: 9px;
}

.team-message-stream > article:hover {
  background: #f8f8fa;
}

.team-message-stream > article.mine {
  grid-template-columns: minmax(0, 1fr) 38px;
  margin-left: auto;
}

.team-message-stream > article.mine > .team-member-avatar {
  grid-column: 2;
  order: initial;
}

.team-message-stream > article.mine > div {
  grid-column: 1;
  order: initial;
  justify-self: end;
  width: min(100%, 680px);
}

.team-message-stream > article:not(.mine) > div {
  width: min(100%, 680px);
}

.team-message-stream > article > div {
  min-width: 0;
}

.team-message-stream article p {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 5px 8px;
  margin: 0 0 5px;
}

.team-message-stream article.mine p {
  justify-content: flex-end;
}

.team-message-stream article p b {
  color: #292c36;
  font-size: 12px;
  line-height: 1.3;
}

.team-message-stream article p small {
  color: #999da8;
  font-size: 10px;
  white-space: nowrap;
}

/*
 * Message bubble.
 * This overrides the broad selector from the previous CSS.
 */
.team-message-stream
  article
  > div
  > div:not(.team-attachment-list):not(.team-shared-lead) {
  display: block;
  width: fit-content;
  min-width: 40px;
  max-width: min(600px, 100%);
  padding: 9px 12px;
  color: #383b47;
  font-size: 13px;
  line-height: 1.52;
  white-space: pre-wrap;
  overflow-wrap: break-word;
  word-break: normal;
  background: #f0f1f4;
  border: 1px solid #e8e9ed;
  border-radius: 5px 13px 13px 13px;
}

.team-message-stream
  article.mine
  > div
  > div:not(.team-attachment-list):not(.team-shared-lead) {
  margin-left: auto;
  color: #ffffff;
  background:
    linear-gradient(
      135deg,
      #6957ed,
      #7759de
    );
  border-color: transparent;
  border-radius: 13px 5px 13px 13px;
  box-shadow: 0 5px 12px rgba(101, 82, 226, 0.15);
}

.team-message-receipt {
  margin-top: 4px;
  color: #a1a4ae;
  text-align: right;
}

.team-member-avatar {
  width: 36px;
  height: 36px;
  color: #634fd2;
  background:
    linear-gradient(
      135deg,
      #e5ddff,
      #f0def7
    );
  border: 0;
  border-radius: 10px;
}

/* Empty and loading states */

.team-empty {
  min-height: 100%;
  color: #777b89;
}

.team-message-loading {
  min-height: 180px;
  align-items: center;
}

/* Slack-like composer */

.team-message-panel > footer {
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 14px;
  background: #fafafd;
  border-top: 1px solid #e5e6ec;
}

.team-message-tools {
  align-items: center;
}

.team-message-tools > button,
.team-lead-share-menu > button {
  min-width: 39px;
  height: 39px;
  background:
    linear-gradient(
      135deg,
      #6f4de8,
      #c13abf
    );
  color: #ffffff;
  border: 0;
  border-radius: 11px;
  box-shadow: 0 5px 12px rgba(111, 69, 220, 0.18);
}

.team-message-panel > footer textarea {
  min-height: 48px;
  max-height: 150px;
  padding: 13px 14px;
  resize: none;
  line-height: 1.45;
  background: #ffffff;
  border: 1px solid #d9dbe3;
  border-radius: 12px;
}

.team-message-panel > footer textarea:focus {
  border-color: #8a77ed;
  box-shadow: 0 0 0 3px rgba(105, 87, 237, 0.1);
}

.team-message-panel > footer > button {
  min-height: 43px;
  padding-inline: 17px;
  background:
    linear-gradient(
      135deg,
      #7464ec,
      #9a63e4
    );
  border-radius: 10px;
}

/* Shared lead card */

.team-shared-lead {
  width: min(380px, 100%);
  padding: 13px 14px;
  background: #ffffff;
  border: 1px solid #dedfe7;
  border-left: 4px solid #6d5af1;
  border-radius: 10px;
  box-shadow: 0 5px 16px rgba(24, 27, 39, 0.05);
}

/* Improved scrollbar */

.team-channel-scroll,
.team-member-scroll,
.team-message-stream {
  scrollbar-color: #c8cad3 transparent;
  scrollbar-width: thin;
}

.team-channel-scroll::-webkit-scrollbar,
.team-member-scroll::-webkit-scrollbar,
.team-message-stream::-webkit-scrollbar {
  width: 7px;
}

.team-channel-scroll::-webkit-scrollbar-thumb,
.team-member-scroll::-webkit-scrollbar-thumb,
.team-message-stream::-webkit-scrollbar-thumb {
  background: #c8cad3;
  border: 2px solid transparent;
  background-clip: padding-box;
  border-radius: 999px;
}

/* Responsive */

@media (max-width: 1050px) {
  .team-chat-layout {
    grid-template-columns: 280px minmax(0, 1fr);
  }

  .team-message-stream > article {
    max-width: 92%;
  }
}

@media (max-width: 760px) {
  .team-comms-shell {
    padding: 10px;
  }

  .team-comms-header {
    align-items: stretch;
    flex-direction: column;
  }

  .team-chat-layout {
    display: flex;
    flex-direction: column;
    height: auto;
    min-height: 0;
  }

  .team-channel-list {
    max-height: 390px;
    border-right: 0;
    border-bottom: 1px solid #e4e5eb;
  }

  .team-message-panel {
    min-height: 620px;
  }

  .team-message-stream > article,
  .team-message-stream > article.mine {
    max-width: 100%;
  }

  .team-message-panel > footer {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .team-message-panel > footer > button {
    grid-column: 1 / -1;
    width: 100%;
  }
}
/* ==========================================================
   ReachFly Team Communication
   Complete final chat, task, dialog and calling styles
   Keep this section at the END of styles.css
   ========================================================== */

.team-comms-shell,
.team-comms-shell * {
  box-sizing: border-box;
}

.team-comms-shell {
  --team-primary: #6c55e8;
  --team-primary-dark: #5641cf;
  --team-primary-soft: #ede9ff;
  --team-gradient: linear-gradient(
    135deg,
    #7555ed,
    #b43ec7
  );
  --team-background: #f6f7fb;
  --team-sidebar: #f8f8fb;
  --team-surface: #ffffff;
  --team-border: #e3e5ed;
  --team-border-strong: #d7d9e3;
  --team-text: #202331;
  --team-muted: #818696;
  --team-danger: #dc5063;
  --team-success: #2dac78;

  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
  min-width: 0;
  min-height: calc(100vh - 140px);
  padding: 18px;
  background:
    radial-gradient(
      circle at top right,
      rgba(115, 82, 237, 0.07),
      transparent 32%
    ),
    var(--team-background);
}

/* ==========================================================
   Top header
   ========================================================== */

.team-comms-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 22px 26px;
  background: var(--team-surface);
  border: 1px solid var(--team-border);
  border-radius: 18px;
  box-shadow:
    0 1px 2px rgba(25, 28, 40, 0.03),
    0 13px 34px rgba(25, 28, 40, 0.05);
}

.team-comms-header > div:first-child {
  min-width: 0;
  max-width: 820px;
}

.team-comms-header > div:first-child > span {
  display: block;
  margin-bottom: 7px;
  color: var(--team-primary);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.team-comms-header h2 {
  margin: 0;
  color: var(--team-text);
  font-size: clamp(24px, 3vw, 31px);
  line-height: 1.15;
  letter-spacing: -0.035em;
}

.team-comms-header p {
  max-width: 760px;
  margin: 8px 0 0;
  color: var(--team-muted);
  font-size: 13px;
  line-height: 1.65;
}

.team-comms-switch {
  display: inline-flex;
  flex: 0 0 auto;
  gap: 5px;
  padding: 4px;
  background: #f1f2f6;
  border: 1px solid #e1e3ea;
  border-radius: 13px;
}

.team-comms-switch button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 41px;
  padding: 0 16px;
  color: #707584;
  font-size: 12px;
  font-weight: 800;
  background: transparent;
  border: 0;
  border-radius: 9px;
  cursor: pointer;
  transition:
    color 150ms ease,
    background 150ms ease,
    box-shadow 150ms ease;
}

.team-comms-switch button.active {
  color: #312b50;
  background: #ffffff;
  box-shadow:
    0 1px 3px rgba(21, 24, 35, 0.08),
    0 5px 14px rgba(21, 24, 35, 0.05);
}

.team-comms-switch button b {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  color: #ffffff;
  font-size: 10px;
  background: var(--team-primary);
  border-radius: 999px;
}

/* ==========================================================
   Errors
   ========================================================== */

.team-comms-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 15px;
  color: #91333f;
  background: #fff1f3;
  border: 1px solid #f1c8ce;
  border-radius: 12px;
}

.team-comms-error button {
  color: inherit;
  font-size: 11px;
  font-weight: 800;
  background: transparent;
  border: 0;
  cursor: pointer;
}

/* ==========================================================
   Main chat frame
   ========================================================== */

.team-chat-layout {
  display: grid;
  grid-template-columns: 310px minmax(0, 1fr);
  width: 100%;
  min-width: 0;
  height: min(780px, calc(100vh - 215px));
  min-height: 650px;
  overflow: hidden;
  background: var(--team-surface);
  border: 1px solid var(--team-border);
  border-radius: 19px;
  box-shadow:
    0 1px 2px rgba(24, 27, 39, 0.03),
    0 18px 48px rgba(24, 27, 39, 0.07);
}

/* ==========================================================
   Sidebar
   ========================================================== */

.team-channel-list {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--team-sidebar);
  border-right: 1px solid var(--team-border);
}

.team-channel-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 20px 17px 12px;
}

.team-channel-title > div {
  min-width: 0;
}

.team-channel-title b {
  display: block;
  color: var(--team-text);
  font-size: 17px;
  letter-spacing: -0.02em;
}

.team-channel-title small {
  display: block;
  margin-top: 3px;
  color: #9296a4;
  font-size: 11px;
}

.team-channel-title > button {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  color: #ffffff;
  font-size: 22px;
  line-height: 1;
  background: var(--team-gradient);
  border: 0;
  border-radius: 11px;
  cursor: pointer;
  box-shadow: 0 8px 18px rgba(110, 75, 225, 0.24);
}

.team-channel-title > button:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 22px rgba(110, 75, 225, 0.28);
}

.team-comms-search {
  display: block;
  padding: 0 14px 13px;
}

.team-comms-search input {
  width: 100%;
  height: 43px;
  padding: 0 13px;
  color: #30333f;
  font: inherit;
  font-size: 13px;
  background: #ffffff;
  border: 1px solid #dadee7;
  border-radius: 11px;
  outline: none;
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.team-comms-search input::placeholder {
  color: #969aa7;
}

.team-comms-search input:focus {
  border-color: #8b78ed;
  box-shadow: 0 0 0 3px rgba(108, 85, 232, 0.1);
}

.team-channel-scroll,
.team-member-scroll,
.team-message-stream {
  scrollbar-width: thin;
  scrollbar-color: #c8cad3 transparent;
}

.team-channel-scroll {
  flex: 1 1 auto;
  min-height: 130px;
  padding: 0 9px 13px;
  overflow-x: hidden;
  overflow-y: auto;
}

.team-channel-scroll > button {
  position: relative;
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-width: 0;
  min-height: 58px;
  margin-bottom: 4px;
  padding: 8px 10px;
  text-align: left;
  background: transparent;
  border: 0;
  border-radius: 11px;
  cursor: pointer;
  transition: background 150ms ease;
}

.team-channel-scroll > button:hover {
  background: #efeff5;
}

.team-channel-scroll > button.active {
  background: #e9e5ff;
}

.team-channel-scroll > button.active::before {
  position: absolute;
  top: 50%;
  left: 0;
  width: 3px;
  height: 29px;
  content: "";
  background: var(--team-primary);
  border-radius: 0 5px 5px 0;
  transform: translateY(-50%);
}

.team-channel-scroll > button > span {
  min-width: 0;
}

.team-channel-scroll > button b,
.team-channel-scroll > button small {
  display: block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-channel-scroll > button b {
  color: #292c38;
  font-size: 13px;
  font-weight: 800;
}

.team-channel-scroll > button small {
  margin-top: 3px;
  color: #8c909e;
  font-size: 11px;
}

.team-channel-scroll > button em {
  display: grid;
  place-items: center;
  min-width: 21px;
  height: 21px;
  padding: 0 6px;
  color: #ffffff;
  font-size: 10px;
  font-style: normal;
  font-weight: 800;
  background: var(--team-primary);
  border-radius: 999px;
}

.team-direct-title {
  margin: 0 14px;
  padding: 15px 2px 9px;
  border-top: 1px solid #e4e5eb;
}

.team-direct-title span {
  color: #878b9a;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.team-member-scroll {
  flex: 0 1 285px;
  min-height: 100px;
  padding: 0 9px 14px;
  overflow-x: hidden;
  overflow-y: auto;
}

.team-person-row {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-width: 0;
  min-height: 54px;
  padding: 5px 7px;
  border-radius: 10px;
}

.team-person-row:hover {
  background: #efeff4;
}

.direct-person {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  min-width: 0;
  flex: 1;
  padding: 3px;
  text-align: left;
  background: transparent;
  border: 0;
  cursor: pointer;
}

.direct-person > span {
  min-width: 0;
}

.direct-person b,
.direct-person small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.direct-person b {
  color: #30333f;
  font-size: 12px;
  font-weight: 800;
}

.direct-person small {
  margin-top: 2px;
  color: #9195a3;
  font-size: 10px;
}

.team-person-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 4px;
  opacity: 0;
  transition: opacity 140ms ease;
}

.team-person-row:hover .team-person-actions {
  opacity: 1;
}

.team-person-actions button {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  padding: 0;
  color: #666b7a;
  background: #ffffff;
  border: 1px solid #dfe1e8;
  border-radius: 8px;
  cursor: pointer;
}

.team-person-actions button:hover {
  color: var(--team-primary-dark);
  background: var(--team-primary-soft);
  border-color: #ccc5fa;
}

/* ==========================================================
   Avatars and presence
   ========================================================== */

.team-channel-avatar,
.team-member-avatar {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  width: 38px;
  height: 38px;
  overflow: hidden;
  color: #5f4fd1;
  font-size: 12px;
  font-style: normal;
  font-weight: 850;
  background:
    linear-gradient(
      135deg,
      #e7e1ff,
      #f0dff8
    );
  border: 0;
  border-radius: 11px;
}

.team-channel-avatar {
  color: #ffffff;
  background: #6754e6;
}

.team-channel-avatar.large,
.team-member-avatar.large {
  width: 50px;
  height: 50px;
  font-size: 15px;
  border-radius: 14px;
}

.team-member-avatar img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.team-presence-dot {
  display: block;
  width: 10px;
  height: 10px;
  flex: 0 0 auto;
  background: #acb0bb;
  border: 2px solid #ffffff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px rgba(20, 23, 33, 0.08);
}

.team-presence-dot.online,
.team-presence-dot.available {
  background: #2eaf78;
}

.team-presence-dot.busy {
  background: #df5364;
}

.team-presence-dot.away {
  background: #e6a53b;
}

/* ==========================================================
   Main message panel
   ========================================================== */

.team-message-panel {
  display: flex;
  flex-direction: column;
  width: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: #ffffff;
}

.team-message-panel > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  flex: 0 0 auto;
  min-width: 0;
  min-height: 80px;
  padding: 14px 20px;
  background: rgba(255, 255, 255, 0.98);
  border-bottom: 1px solid var(--team-border);
}

.team-message-header-main {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.team-message-header-main > div {
  min-width: 0;
}

.team-message-header-main small {
  display: block;
  color: #7d8190;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.team-message-header-main h3 {
  max-width: 100%;
  margin: 3px 0 2px;
  overflow: hidden;
  color: var(--team-text);
  font-size: 18px;
  letter-spacing: -0.025em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-message-header-main span,
.team-channel-subtitle {
  display: block;
  max-width: 100%;
  overflow: hidden;
  color: #898e9d;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-header-call-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 8px;
}

.team-header-call-actions button {
  min-height: 38px;
  padding: 0 13px;
  color: #5143d4;
  font-size: 11px;
  font-weight: 800;
  background: #f1efff;
  border: 1px solid #dcd7ff;
  border-radius: 10px;
  cursor: pointer;
}

.team-header-call-actions button:hover {
  background: #e8e4ff;
}

/* ==========================================================
   Message stream
   ========================================================== */

.team-message-stream {
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  min-height: 0;
  padding: 18px 22px 26px;
  overflow-x: hidden;
  overflow-y: auto;
  background: #ffffff;
}

/*
 * Supports both the original MessageItem markup and the newer
 * team-message-item grouped-message markup.
 */

.team-message-item,
.team-message-stream > article {
  position: relative;
  display: grid !important;
  grid-template-columns: 40px minmax(0, 1fr) !important;
  align-items: flex-start !important;
  gap: 10px !important;
  width: 100% !important;
  max-width: none !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 7px 8px !important;
  background: transparent;
  border-radius: 9px;
}

.team-message-item:hover,
.team-message-stream > article:hover {
  background: #f7f7fa;
}

.team-message-item.mine,
.team-message-stream > article.mine {
  grid-template-columns: minmax(0, 1fr) 40px !important;
  margin-left: 0 !important;
}

.team-message-item > .team-message-avatar-slot {
  grid-column: 1;
  grid-row: 1;
}

.team-message-item > .team-message-content {
  grid-column: 2;
  grid-row: 1;
}

.team-message-item.mine > .team-message-avatar-slot {
  grid-column: 2 !important;
  grid-row: 1 !important;
}

.team-message-item.mine > .team-message-content {
  grid-column: 1 !important;
  grid-row: 1 !important;
  justify-self: end;
  width: min(100%, 720px);
}

.team-message-stream > article.mine > .team-member-avatar {
  grid-column: 2 !important;
  grid-row: 1 !important;
  order: initial !important;
}

.team-message-stream > article.mine > div {
  grid-column: 1 !important;
  grid-row: 1 !important;
  order: initial !important;
  justify-self: end;
  width: min(100%, 720px) !important;
  min-width: 0 !important;
}

.team-message-stream > article:not(.mine) > div {
  width: min(100%, 720px) !important;
  min-width: 0 !important;
}

.team-message-avatar-slot {
  display: flex;
  justify-content: center;
  width: 40px;
  min-width: 40px;
}

.team-message-content {
  width: 100%;
  min-width: 0;
}

.team-message-meta,
.team-message-stream article > div > p {
  display: flex !important;
  align-items: baseline !important;
  justify-content: flex-start !important;
  flex-wrap: wrap;
  gap: 5px 7px !important;
  width: 100%;
  min-width: 0;
  margin: 0 0 4px !important;
  text-align: left !important;
}

.team-message-item.mine .team-message-meta,
.team-message-stream article.mine > div > p {
  justify-content: flex-end !important;
  text-align: right !important;
}

.team-message-meta strong,
.team-message-stream article > div > p b {
  color: var(--team-text);
  font-size: 12px;
  font-weight: 850;
}

.team-message-meta span,
.team-message-meta time,
.team-message-stream article > div > p small {
  color: #9296a4;
  font-size: 10px;
  font-weight: 500;
  white-space: nowrap;
}

.team-message-body-row {
  display: flex;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 8px;
  width: 100%;
  min-width: 0;
}

.team-message-item.mine .team-message-body-row {
  justify-content: flex-end;
}

.team-message-payload {
  width: fit-content;
  min-width: 0;
  max-width: min(620px, 100%);
}

/*
 * Actual message bubble.
 * The old broad selectors are deliberately overridden here.
 */

.team-message-text,
.team-message-stream
  article
  > div
  > div:not(.team-attachment-list):not(.team-shared-lead):not(.team-message-body-row):not(.team-message-payload):not(.team-message-hover-actions) {
  display: block !important;
  width: fit-content !important;
  min-width: 44px !important;
  max-width: 100% !important;
  margin: 0 !important;
  padding: 9px 12px !important;
  color: #383b47 !important;
  font-size: 13px !important;
  line-height: 1.5 !important;
  white-space: pre-wrap !important;
  overflow-wrap: anywhere !important;
  word-break: normal !important;
  background: #f0f1f4 !important;
  border: 1px solid #e5e7eb !important;
  border-radius: 5px 14px 14px 14px !important;
  box-shadow: none !important;
}

.team-message-item.mine .team-message-text,
.team-message-stream
  article.mine
  > div
  > div:not(.team-attachment-list):not(.team-shared-lead):not(.team-message-body-row):not(.team-message-payload):not(.team-message-hover-actions) {
  margin-left: auto !important;
  color: #ffffff !important;
  background:
    linear-gradient(
      135deg,
      #6957e9,
      #7357dc
    ) !important;
  border-color: transparent !important;
  border-radius: 14px 5px 14px 14px !important;
  box-shadow: 0 5px 14px rgba(102, 82, 220, 0.16) !important;
}

/* Consecutive message grouping */

.team-message-item.compact {
  padding-top: 2px !important;
  padding-bottom: 2px !important;
}

.team-message-item.compact .team-message-meta {
  display: none !important;
}

.team-compact-time {
  display: none;
  padding-top: 7px;
  color: #9da1ad;
  font-size: 9px;
}

.team-message-item.compact:hover .team-compact-time {
  display: block;
}

/* Message actions â€” hidden until hover */

.team-message-hover-actions {
  position: absolute;
  top: -8px;
  right: 8px;
  z-index: 5;
  display: flex;
  gap: 4px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(3px);
  transition:
    opacity 140ms ease,
    transform 140ms ease;
}

.team-message-item.mine .team-message-hover-actions {
  right: 48px;
}

.team-message-item:hover .team-message-hover-actions {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.team-message-hover-actions button {
  min-height: 28px;
  padding: 0 9px;
  color: #666b79;
  font-size: 10px;
  font-weight: 750;
  background: #ffffff;
  border: 1px solid #dfe1e7;
  border-radius: 7px;
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(24, 27, 39, 0.1);
}

.team-message-hover-actions button:hover {
  color: var(--team-primary-dark);
  background: var(--team-primary-soft);
  border-color: #cbc4fa;
}

/* Never render native-looking Copy button inside the bubble */

.team-message-payload > button,
.team-message-text + button {
  display: none !important;
}

.team-message-receipt {
  display: block;
  width: 100%;
  margin-top: 4px;
  color: #9ca0ad;
  font-size: 9px;
  text-align: right;
}

/* Typing indicator */

.team-typing {
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 30px;
  margin: 4px 0 4px 50px;
  color: #9094a1;
}

.team-typing > span {
  width: 6px;
  height: 6px;
  background: #8d80ed;
  border-radius: 50%;
  animation: teamTypingPulse 1.15s infinite ease-in-out;
}

.team-typing > span:nth-child(2) {
  animation-delay: 0.15s;
}

.team-typing > span:nth-child(3) {
  animation-delay: 0.3s;
}

.team-typing small {
  margin-left: 5px;
  font-size: 10px;
}

@keyframes teamTypingPulse {
  0%,
  80%,
  100% {
    opacity: 0.35;
    transform: translateY(0);
  }

  40% {
    opacity: 1;
    transform: translateY(-3px);
  }
}

/* Loading */

.team-message-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 180px;
}

.team-message-loading span {
  width: 8px;
  height: 8px;
  background: #8375e9;
  border-radius: 50%;
  animation: teamTypingPulse 1.15s infinite ease-in-out;
}

.team-message-loading span:nth-child(2) {
  animation-delay: 0.15s;
}

.team-message-loading span:nth-child(3) {
  animation-delay: 0.3s;
}

/* Empty state */

.team-empty {
  display: grid;
  place-content: center;
  justify-items: center;
  min-height: 100%;
  padding: 36px;
  text-align: center;
}

.team-empty b {
  color: #343744;
  font-size: 16px;
}

.team-empty p {
  max-width: 430px;
  margin: 8px 0 0;
  color: #8b8f9d;
  font-size: 12px;
  line-height: 1.65;
}

/* ==========================================================
   Shared leads and attachments
   ========================================================== */

.team-shared-lead {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: min(390px, 100%);
  max-width: 100%;
  padding: 13px 14px;
  background: #ffffff;
  border: 1px solid #dedfe8;
  border-left: 4px solid var(--team-primary);
  border-radius: 11px;
  box-shadow: 0 5px 16px rgba(24, 27, 39, 0.05);
}

.team-shared-lead > span {
  color: var(--team-primary);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.team-shared-lead strong {
  color: #2b2e3a;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.team-shared-lead small {
  color: #858a98;
  font-size: 10px;
  overflow-wrap: anywhere;
}

.team-shared-lead a {
  width: fit-content;
  margin-top: 5px;
  color: var(--team-primary-dark);
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
}

.team-attachment-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  max-width: 100%;
  margin-top: 7px;
}

.team-image-attachment {
  display: block;
  width: min(300px, 100%);
  overflow: hidden;
  background: #f2f3f6;
  border: 1px solid #dedfe7;
  border-radius: 12px;
}

.team-image-attachment img {
  display: block;
  width: 100%;
  max-height: 280px;
  object-fit: cover;
}

.team-file-attachment {
  display: flex;
  align-items: center;
  gap: 10px;
  width: min(340px, 100%);
  min-width: 0;
  padding: 10px;
  color: inherit;
  text-decoration: none;
  background: #ffffff;
  border: 1px solid #dfe1e8;
  border-radius: 11px;
}

.team-file-attachment > span {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  color: var(--team-primary-dark);
  font-size: 9px;
  font-weight: 850;
  background: var(--team-primary-soft);
  border-radius: 9px;
}

.team-file-attachment > div {
  min-width: 0;
}

.team-file-attachment strong {
  display: block;
  max-width: 230px;
  overflow: hidden;
  color: #343744;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-file-attachment small {
  display: block;
  margin-top: 2px;
  color: #969aa7;
  font-size: 9px;
}

/* ==========================================================
   Composer
   ========================================================== */

.team-message-panel > footer {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: flex-end;
  gap: 10px;
  flex: 0 0 auto;
  width: 100%;
  min-width: 0;
  padding: 13px 14px;
  background: #fafafd;
  border-top: 1px solid var(--team-border);
}

.team-message-tools {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: 0 0 auto;
}

.team-message-tools > button,
.team-lead-share-menu > button {
  display: grid;
  place-items: center;
  min-width: 41px;
  height: 41px;
  padding: 0 9px;
  color: #ffffff;
  font-size: 10px;
  font-weight: 850;
  background: var(--team-gradient);
  border: 0;
  border-radius: 11px;
  cursor: pointer;
  box-shadow: 0 6px 14px rgba(110, 75, 225, 0.19);
}

.team-message-tools > button:disabled,
.team-lead-share-menu > button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
}

.team-message-panel > footer textarea {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  max-height: 150px;
  padding: 12px 14px;
  resize: none;
  color: #30333f;
  font: inherit;
  font-size: 13px;
  line-height: 1.45;
  background: #ffffff;
  border: 1px solid #d7dae4;
  border-radius: 12px;
  outline: none;
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease;
}

.team-message-panel > footer textarea::placeholder {
  color: #9296a4;
}

.team-message-panel > footer textarea:focus {
  border-color: #8975ed;
  box-shadow: 0 0 0 3px rgba(108, 85, 232, 0.1);
}

.team-message-panel > footer > button {
  min-height: 43px;
  padding: 0 17px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 850;
  white-space: nowrap;
  background:
    linear-gradient(
      135deg,
      #7766ec,
      #a267e3
    );
  border: 0;
  border-radius: 11px;
  cursor: pointer;
  box-shadow: 0 8px 18px rgba(108, 85, 232, 0.2);
}

.team-message-panel > footer > button:disabled {
  opacity: 0.48;
  cursor: not-allowed;
  box-shadow: none;
}

/* Lead share menu */

.team-lead-share-menu {
  position: relative;
}

.team-lead-share-menu > div {
  position: absolute;
  bottom: calc(100% + 9px);
  left: 0;
  z-index: 50;
  width: 270px;
  max-height: 290px;
  padding: 6px;
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid #dedfe7;
  border-radius: 13px;
  box-shadow: 0 18px 42px rgba(23, 26, 38, 0.16);
}

.team-lead-share-menu > div button {
  width: 100%;
  padding: 10px;
  overflow: hidden;
  color: #373a46;
  font-size: 11px;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  background: transparent;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
}

.team-lead-share-menu > div button:hover {
  color: var(--team-primary-dark);
  background: var(--team-primary-soft);
}

/* ==========================================================
   Tasks
   ========================================================== */

.team-task-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  gap: 20px;
  width: 100%;
  min-width: 0;
}

.task-board,
.task-editor {
  min-width: 0;
  background: #ffffff;
  border: 1px solid var(--team-border);
  border-radius: 18px;
  box-shadow: 0 12px 32px rgba(25, 28, 40, 0.05);
}

.task-board {
  padding: 20px;
}

.task-board-head {
  margin-bottom: 18px;
}

.task-board-head h3 {
  margin: 0;
  color: var(--team-text);
  font-size: 18px;
}

.task-board-head p {
  max-width: 620px;
  margin: 7px 0 0;
  color: var(--team-muted);
  font-size: 12px;
  line-height: 1.65;
}

.work-task {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: flex-start;
  gap: 15px;
  min-width: 0;
  margin-bottom: 11px;
  padding: 15px;
  overflow: hidden;
  background: #fbfbfd;
  border: 1px solid #e4e6ed;
  border-radius: 14px;
}

.work-task::before {
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  content: "";
  background: #989eaa;
}

.work-task.high::before {
  background: #e39b3c;
}

.work-task.urgent::before {
  background: var(--team-danger);
}

.work-task.low::before {
  background: #47a7d7;
}

.task-priority {
  padding: 5px 8px;
  color: #777c89;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: #eceef3;
  border-radius: 999px;
}

.task-main {
  min-width: 0;
}

.task-main h4 {
  margin: 0;
  color: #2a2d39;
  font-size: 14px;
  overflow-wrap: anywhere;
}

.task-main p {
  margin: 7px 0 10px;
  color: #747987;
  font-size: 12px;
  line-height: 1.6;
  overflow-wrap: anywhere;
}

.task-main > small {
  color: #999da9;
  font-size: 9px;
}

.task-lead {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  margin-bottom: 9px;
  padding: 8px 10px;
  background: #f0efff;
  border-radius: 9px;
}

.task-lead b {
  color: #494278;
  font-size: 11px;
}

.task-lead span {
  min-width: 0;
  overflow: hidden;
  color: #7e789b;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.task-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.task-actions .status {
  padding: 5px 8px;
  color: #717684;
  font-size: 9px;
  font-weight: 800;
  background: #eceef3;
  border-radius: 999px;
}

.task-actions .status.in_progress {
  color: #5e51e7;
  background: #efedff;
}

.task-actions .status.completed {
  color: #247758;
  background: #e4f7ef;
}

.task-actions .status.blocked,
.task-actions .status.cancelled {
  color: #9b3440;
  background: #ffecef;
}

.task-actions button,
.task-actions select {
  min-height: 33px;
  padding: 0 10px;
  color: #5549df;
  font-size: 10px;
  font-weight: 750;
  background: #ffffff;
  border: 1px solid #d8d5f8;
  border-radius: 9px;
  cursor: pointer;
}

.task-editor {
  align-self: start;
  padding: 20px;
}

.task-editor > span {
  display: block;
  margin-bottom: 5px;
  color: var(--team-primary);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.task-editor h3 {
  margin: 0 0 18px;
  color: #252834;
  font-size: 18px;
}

.task-editor label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-bottom: 13px;
  color: #676c7b;
  font-size: 11px;
  font-weight: 750;
}

.task-editor input,
.task-editor select,
.task-editor textarea {
  width: 100%;
  min-height: 42px;
  padding: 10px 11px;
  color: #343744;
  font: inherit;
  font-size: 12px;
  background: #ffffff;
  border: 1px solid #dfe1e8;
  border-radius: 10px;
  outline: none;
}

.task-editor textarea {
  min-height: 100px;
  resize: vertical;
}

.task-editor input:focus,
.task-editor select:focus,
.task-editor textarea:focus {
  border-color: #9186f4;
  box-shadow: 0 0 0 3px rgba(103, 88, 245, 0.09);
}

.task-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.create-task-button {
  width: 100%;
  min-height: 44px;
  margin-top: 4px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  background: var(--team-primary);
  border: 0;
  border-radius: 11px;
  cursor: pointer;
  box-shadow: 0 8px 18px rgba(102, 87, 243, 0.22);
}

/* ==========================================================
   Dialogs
   ========================================================== */

.team-dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 900;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(19, 21, 30, 0.6);
  backdrop-filter: blur(5px);
}

.team-dialog {
  width: min(560px, 100%);
  max-height: 88vh;
  overflow: hidden;
  background: #ffffff;
  border-radius: 20px;
  box-shadow: 0 30px 85px rgba(11, 13, 20, 0.3);
}

.team-dialog > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 20px;
  border-bottom: 1px solid var(--team-border);
}

.team-dialog > header span {
  color: var(--team-primary);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.team-dialog > header h3 {
  margin: 4px 0 0;
  color: #242734;
  font-size: 20px;
}

.team-dialog > header button {
  width: 34px;
  height: 34px;
  color: #787d8c;
  font-size: 22px;
  background: #f3f4f7;
  border: 0;
  border-radius: 10px;
  cursor: pointer;
}

.team-dialog > label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin: 16px 20px 0;
  color: #686d7d;
  font-size: 11px;
  font-weight: 750;
}

.team-dialog input,
.team-dialog textarea {
  width: 100%;
  min-height: 42px;
  padding: 10px 11px;
  color: #343744;
  font: inherit;
  font-size: 12px;
  border: 1px solid #dfe1e8;
  border-radius: 10px;
  outline: none;
}

.team-dialog textarea {
  min-height: 85px;
  resize: vertical;
}

.team-group-member-list {
  max-height: 270px;
  margin: 18px 20px 0;
  padding: 6px;
  overflow-x: hidden;
  overflow-y: auto;
  background: #f8f9fb;
  border: 1px solid #e4e6ed;
  border-radius: 13px;
}

.team-group-member {
  display: grid;
  grid-template-columns: auto 38px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 8px;
  border-radius: 10px;
}

.team-group-member:hover {
  background: #ffffff;
}

.team-group-member input {
  width: 16px;
  height: 16px;
  min-height: 0;
}

.team-group-member > span {
  min-width: 0;
}

.team-group-member b,
.team-group-member small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-group-member b {
  color: #333642;
  font-size: 12px;
}

.team-group-member small {
  margin-top: 2px;
  color: #9296a4;
  font-size: 9px;
}

.team-dialog > footer {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding: 18px 20px 20px;
}

.team-dialog > footer button {
  min-height: 40px;
  padding: 0 15px;
  color: #666b79;
  font-size: 11px;
  font-weight: 750;
  background: #f1f2f6;
  border: 0;
  border-radius: 10px;
  cursor: pointer;
}

.team-dialog > footer button.primary {
  color: #ffffff;
  background: var(--team-primary);
}

/* ==========================================================
   Internal calls
   ========================================================== */

.team-incoming-call {
  width: min(380px, 100%);
  padding: 30px;
  text-align: center;
  background: #ffffff;
  border-radius: 22px;
  box-shadow: 0 30px 90px rgba(10, 12, 20, 0.3);
}

.team-incoming-call .team-member-avatar {
  margin: 0 auto 16px;
}

.team-incoming-call > span {
  color: #777c8b;
  font-size: 11px;
  font-weight: 750;
}

.team-incoming-call h3 {
  margin: 7px 0 22px;
  color: #242734;
  font-size: 22px;
}

.team-incoming-call > div {
  display: flex;
  justify-content: center;
  gap: 12px;
}

.team-incoming-call button {
  min-width: 112px;
  min-height: 44px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  border: 0;
  border-radius: 12px;
  cursor: pointer;
}

.team-incoming-call button.reject {
  background: var(--team-danger);
}

.team-incoming-call button.accept {
  background: var(--team-success);
}

.team-call-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  background: #11131a;
}

.team-call-stage {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  background:
    radial-gradient(
      circle at center,
      #2b2f40,
      #11131a 70%
    );
}

.team-call-remote-video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.team-call-local-video {
  position: absolute;
  right: 22px;
  bottom: 22px;
  z-index: 4;
  width: min(240px, 28vw);
  aspect-ratio: 16 / 10;
  object-fit: cover;
  background: #252936;
  border: 2px solid rgba(255, 255, 255, 0.7);
  border-radius: 16px;
  box-shadow: 0 16px 38px rgba(0, 0, 0, 0.34);
}

.team-call-fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 10px;
  color: #ffffff;
  pointer-events: none;
}

.team-call-fallback h3 {
  margin: 0;
  font-size: 24px;
}

.team-call-fallback span {
  color: rgba(255, 255, 255, 0.7);
  font-size: 12px;
}

.team-call-overlay > footer {
  display: flex;
  justify-content: center;
  gap: 12px;
  padding: 18px;
  background: rgba(23, 26, 35, 0.96);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(10px);
}

.team-call-overlay > footer button {
  min-width: 110px;
  min-height: 44px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  background: #2a2e3a;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  cursor: pointer;
}

.team-call-overlay > footer button.active {
  background: var(--team-primary);
}

.team-call-overlay > footer button.end {
  background: var(--team-danger);
}

/* ==========================================================
   Scrollbars
   ========================================================== */

.team-channel-scroll::-webkit-scrollbar,
.team-member-scroll::-webkit-scrollbar,
.team-message-stream::-webkit-scrollbar {
  width: 8px;
}

.team-channel-scroll::-webkit-scrollbar-thumb,
.team-member-scroll::-webkit-scrollbar-thumb,
.team-message-stream::-webkit-scrollbar-thumb {
  background: #c8cad3;
  border: 2px solid transparent;
  background-clip: padding-box;
  border-radius: 999px;
}

/* ==========================================================
   Tablet
   ========================================================== */

@media (max-width: 1100px) {
  .team-chat-layout {
    grid-template-columns: 275px minmax(0, 1fr);
  }

  .team-task-layout {
    grid-template-columns: 1fr;
  }

  .task-editor {
    order: -1;
  }
}

/* ==========================================================
   Mobile
   ========================================================== */

@media (max-width: 760px) {
  .team-comms-shell {
    min-height: auto;
    padding: 8px;
  }

  .team-comms-header {
    align-items: stretch;
    flex-direction: column;
    padding: 18px;
    border-radius: 15px;
  }

  .team-comms-switch {
    width: 100%;
  }

  .team-comms-switch button {
    flex: 1;
  }

  .team-chat-layout {
    display: flex;
    flex-direction: column;
    height: auto;
    min-height: 0;
    border-radius: 14px;
  }

  .team-channel-list {
    flex: 0 0 auto;
    max-height: 390px;
    border-right: 0;
    border-bottom: 1px solid var(--team-border);
  }

  .team-channel-scroll {
    max-height: 190px;
  }

  .team-member-scroll {
    max-height: 150px;
  }

  .team-message-panel {
    min-height: 580px;
  }

  .team-message-panel > header {
    min-height: 70px;
    padding: 12px;
  }

  .team-message-header-main h3 {
    font-size: 15px;
  }

  .team-header-call-actions {
    display: flex;
  }

  .team-header-call-actions button {
    width: 36px;
    min-width: 36px;
    padding: 0;
    overflow: hidden;
    font-size: 0;
  }

  .team-header-call-actions button:first-child::after {
    content: "â˜Ž";
    font-size: 15px;
  }

  .team-header-call-actions button:last-child::after {
    content: "â—‰";
    font-size: 15px;
  }

  .team-message-stream {
    padding: 13px 7px 20px;
  }

  .team-message-item,
  .team-message-stream > article {
    grid-template-columns: 34px minmax(0, 1fr) !important;
    gap: 7px !important;
    padding: 5px 3px !important;
  }

  .team-message-item.mine,
  .team-message-stream > article.mine {
    grid-template-columns: minmax(0, 1fr) 34px !important;
  }

  .team-message-avatar-slot {
    width: 34px;
    min-width: 34px;
  }

  .team-member-avatar {
    width: 32px;
    height: 32px;
    border-radius: 9px;
  }

  .team-message-payload {
    max-width: 100%;
  }

  .team-message-hover-actions {
    display: none;
  }

  .team-message-panel > footer {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .team-message-panel > footer > button {
    grid-column: 1 / -1;
    width: 100%;
  }

  .work-task {
    grid-template-columns: 1fr;
  }

  .task-actions {
    align-items: stretch;
  }

  .task-actions button,
  .task-actions select {
    width: 100%;
  }

  .task-form-row {
    grid-template-columns: 1fr;
  }

  .team-call-local-video {
    right: 12px;
    bottom: 12px;
    width: 42vw;
  }

  .team-call-overlay > footer {
    flex-wrap: wrap;
  }

  .team-call-overlay > footer button {
    min-width: 95px;
  }
}
