@media (max-width: 720px) {
  .live-assignment-form {
    grid-template-columns: 1fr;
  }
}
.rf-manager-lead-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 18px;
}

.rf-manager-lead-card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
  padding: 18px;
  border: 1px solid #e3e8f1;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 10px 30px rgba(29, 41, 57, 0.06);
  cursor: pointer;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.rf-manager-lead-card:hover {
  transform: translateY(-2px);
  border-color: #c9d4ff;
  box-shadow: 0 16px 38px rgba(29, 41, 57, 0.1);
}

.rf-manager-lead-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.rf-manager-lead-card__identity {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.rf-manager-lead-card__identity h3 {
  margin: 3px 0 4px;
  color: #182230;
  font-size: 15px;
  line-height: 1.35;
}

.rf-manager-lead-card__identity p,
.rf-manager-lead-card__eyebrow {
  margin: 0;
  color: #667085;
  font-size: 11px;
}

.rf-manager-lead-card__eyebrow {
  display: block;
  color: #7f56d9;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.rf-manager-lead-card__badges {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 7px;
}

.rf-manager-status,
.rf-manager-priority {
  display: inline-flex;
  align-items: center;
  min-height: 25px;
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  white-space: nowrap;
}

.rf-manager-status {
  color: #344054;
  background: #f2f4f7;
}

.rf-manager-status--in_progress,
.rf-manager-status--follow_up {
  color: #b54708;
  background: #fffaeb;
}

.rf-manager-status--qualified,
.rf-manager-status--meeting_booked,
.rf-manager-status--completed {
  color: #027a48;
  background: #ecfdf3;
}

.rf-manager-status--do_not_contact {
  color: #b42318;
  background: #fef3f2;
}

.rf-manager-priority {
  color: #475467;
  background: #f9fafb;
  border: 1px solid #eaecf0;
}

.rf-manager-priority--high,
.rf-manager-priority--urgent {
  color: #b42318;
  background: #fef3f2;
}

.rf-manager-lead-card__contact-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.rf-manager-lead-card__contact {
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid #eaecf0;
  border-radius: 12px;
  background: #f9fafb;
}

.rf-manager-lead-card__contact small {
  display: block;
  margin-bottom: 4px;
  color: #98a2b3;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.rf-manager-lead-card__contact span {
  display: block;
  overflow: hidden;
  color: #344054;
  font-size: 11px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-manager-lead-card__meta {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid #eaecf0;
  border-radius: 13px;
}

.rf-manager-lead-card__meta > div {
  padding: 11px;
  text-align: center;
  border-right: 1px solid #eaecf0;
}

.rf-manager-lead-card__meta > div:last-child {
  border-right: 0;
}

.rf-manager-lead-card__meta small {
  display: block;
  margin-bottom: 4px;
  color: #98a2b3;
  font-size: 9px;
}

.rf-manager-lead-card__meta strong {
  color: #182230;
  font-size: 12px;
}

.rf-manager-lead-card__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: auto;
}

.rf-manager-lead-card__status-select {
  min-width: 145px;
  min-height: 34px;
  padding: 0 10px;
  border: 1px solid #d0d5dd;
  border-radius: 9px;
  background: #ffffff;
  color: #344054;
  font-size: 10px;
  font-weight: 600;
}

@media (max-width: 1100px) {
  .rf-manager-lead-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .rf-manager-lead-card__header {
    flex-direction: column;
  }

  .rf-manager-lead-card__badges {
    justify-content: flex-start;
  }

  .rf-manager-lead-card__contact-grid,
  .rf-manager-lead-card__meta {
    grid-template-columns: 1fr;
  }

  .rf-manager-lead-card__meta > div {
    border-right: 0;
    border-bottom: 1px solid #eaecf0;
  }

  .rf-manager-lead-card__meta > div:last-child {
    border-bottom: 0;
  }

  .rf-manager-lead-card__actions > * {
    flex: 1 1 100%;
  }
}
/* Caller attendance, Builder-style leads, and call workspace */

.attendance-page {
  max-width: 1320px;
  margin: auto;
}

.attendance-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.attendance-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(320px, .8fr);
  gap: 20px;
}

.attendance-camera-frame {
  position: relative;
  overflow: hidden;
  aspect-ratio: 4 / 3;
  border-radius: 24px;
  background: linear-gradient(135deg, #160c2b, #2b1263);
}

.attendance-camera-frame video,
.attendance-camera-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transform: scaleX(-1);
}

.attendance-camera-actions,
.caller-call-actions,
.caller-call-audit-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
}

.attendance-status {
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  padding: 0 10px;
  border-radius: 999px;
  background: #f2f4f7;
  color: #475467;
  font-size: 11px;
  font-weight: 900;
}

.attendance-status.active {
  background: #ecfdf3;
  color: #027a48;
}

.attendance-status.complete {
  background: #f4f3ff;
  color: #6938ef;
}

.attendance-history {
  display: grid;
  gap: 10px;
}

.attendance-history-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  padding: 13px 14px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: #fbf9ff;
}

.attendance-history-row b,
.attendance-history-row small {
  display: block;
}

.attendance-history-row small {
  margin-top: 4px;
  color: var(--muted);
}

.caller-lead-status-select {
  min-height: 38px;
  max-width: 150px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0 10px;
  background: #fff;
  color: var(--ink);
  font-size: 11px;
  font-weight: 800;
}

.caller-call-backdrop {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(13, 7, 29, .72);
  backdrop-filter: blur(10px);
}

.caller-call-workspace {
  width: min(1180px, 100%);
  max-height: calc(100vh - 48px);
  overflow: auto;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 30px;
  background: #f8f6ff;
  box-shadow: 0 36px 110px rgba(10, 3, 28, .42);
}

.caller-call-header {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 28px;
  color: #fff;
  background: radial-gradient(circle at 12% 0%, rgba(255,78,205,.3), transparent 24rem), linear-gradient(135deg, #160c2b, #2b1263);
}

.caller-call-header h2 {
  margin: 10px 0 5px;
  font-size: 30px;
}

.caller-call-header p {
  margin: 0;
  color: rgba(255,255,255,.7);
}

.caller-call-grid {
  display: grid;
  grid-template-columns: minmax(0, .9fr) minmax(380px, 1.1fr);
  gap: 20px;
  padding: 22px;
}

.caller-call-main,
.caller-call-audit {
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 24px;
  background: #fff;
  box-shadow: var(--shadow);
}

.caller-call-contact-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #fbf9ff;
}

.caller-call-contact-card h3 {
  margin: 0 0 5px;
}

.caller-call-contact-card p {
  margin: 0;
  color: var(--muted);
}

@media (max-width: 980px) {
  .attendance-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .attendance-layout,
  .caller-call-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 620px) {
  .attendance-metrics {
    grid-template-columns: 1fr;
  }

  .caller-call-backdrop {
    padding: 0;
  }

  .caller-call-workspace {
    min-height: 100vh;
    max-height: 100vh;
    border-radius: 0;
  }

  .caller-call-header {
    flex-direction: column;
  }

  .lead-action-row {
    flex-direction: column;
  }

  .caller-lead-status-select,
  .lead-action-row > * {
    width: 100%;
    max-width: none;
  }
}
