  font-size: 15px;
  line-height: 1.65;
}

.rf-agent-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.rf-agent-live-pill {
