.rf-agent-page {
  --agent-ink: #18203a;
  --agent-muted: #667085;
  --agent-line: #e7e9f2;
  --agent-soft: #f7f7fc;
  --agent-purple: #6d4aff;
  --agent-purple-dark: #5635e8;
  --agent-green: #087f5b;
  --agent-red: #c33245;
  --agent-amber: #b56b00;
  width: 100%;
  padding: 28px;
  color: var(--agent-ink);
}

.rf-agent-page *,
.rf-agent-page *::before,
.rf-agent-page *::after {
