/* ReachFly guided Voice Agent onboarding */
.rf-voice-wizard {
  max-width: 980px;
  margin: 0 auto 28px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 28px;
  background:
    radial-gradient(circle at top right, rgba(99, 102, 241, 0.13), transparent 32%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.98));
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.10);
  overflow: hidden;
}

.rf-voice-wizard-top {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 34px 38px 24px;
}

.rf-voice-wizard-top h2 {
  margin: 7px 0 8px;
  font-size: clamp(1.6rem, 3vw, 2.35rem);
  line-height: 1.12;
  letter-spacing: -0.035em;
}

.rf-voice-wizard-top p {
  max-width: 650px;
  margin: 0;
  color: #64748b;
  line-height: 1.65;
}

.rf-voice-wizard-kicker {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 11px;
  border-radius: 999px;
  background: rgba(79, 70, 229, 0.09);
  color: #4338ca;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.rf-voice-wizard-step-count {
  flex: 0 0 auto;
  height: 38px;
  padding: 0 14px;
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  background: #0f172a;
  color: white;
  font-weight: 800;
}

.rf-voice-progress {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  padding: 0 38px 28px;
}

.rf-voice-progress-item {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 7px;
  color: #94a3b8;
}

.rf-voice-progress-item::before {
  content: "";
  position: absolute;
  top: 16px;
  left: calc(-50% + 22px);
  width: calc(100% - 12px);
  height: 2px;
  background: #e2e8f0;
}

.rf-voice-progress-item:first-child::before {
  display: none;
}

.rf-voice-progress-item span {
  position: relative;
  z-index: 1;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 2px solid #e2e8f0;
  background: white;
  font-size: 0.8rem;
  font-weight: 900;
}

.rf-voice-progress-item small {
  font-size: 0.72rem;
  font-weight: 800;
}

.rf-voice-progress-item.done,
.rf-voice-progress-item.current {
  color: #4338ca;
}

.rf-voice-progress-item.done span {
  border-color: #22c55e;
  background: #22c55e;
  color: white;
}

.rf-voice-progress-item.done::before,
.rf-voice-progress-item.current::before {
  background: linear-gradient(90deg, #22c55e, #6366f1);
}

.rf-voice-progress-item.current span {
  border-color: #6366f1;
  box-shadow: 0 0 0 5px rgba(99, 102, 241, 0.10);
}

.rf-voice-wizard-body {
  border-top: 1px solid #e2e8f0;
  padding: 30px 38px 38px;
}

.rf-voice-wizard-note {
  display: grid;
  gap: 5px;
  padding: 15px 17px;
  margin-bottom: 22px;
  border: 1px solid rgba(99, 102, 241, 0.16);
  border-radius: 16px;
  background: rgba(238, 242, 255, 0.72);
}

.rf-voice-wizard-note b {
  color: #312e81;
}

.rf-voice-wizard-note span {
  color: #64748b;
  line-height: 1.5;
}

.rf-voice-essential-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.rf-voice-essential-grid.two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.rf-voice-wizard-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 22px;
}

.rf-voice-wizard-actions.end {
  justify-content: flex-end;
}

.rf-voice-wizard-actions.split {
  justify-content: space-between;
}

.rf-voice-primary-action {
  min-width: 190px;
}

.rf-voice-number-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 24px;
}

.rf-voice-number-card,
.rf-voice-credit-card {
  display: grid;
  gap: 16px;
  padding: 20px;
  border: 1px solid #e2e8f0;
  border-radius: 19px;
  background: white;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.05);
}

.rf-voice-number-card:hover,
.rf-voice-credit-card:hover {
  border-color: rgba(99, 102, 241, 0.42);
  transform: translateY(-1px);
}

.rf-voice-number-card h3,
.rf-voice-credit-card h3 {
  margin: 7px 0 3px;
  font-size: 1.18rem;
}

.rf-voice-number-card p,
.rf-voice-credit-card p {
  margin: 0;
  color: #64748b;
}

.rf-voice-number-badge {
  width: fit-content;
  padding: 5px 9px;
  border-radius: 999px;
  background: #ecfdf5;
  color: #047857;
  font-size: 0.7rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.rf-voice-number-price {
  display: grid;
  gap: 3px;
}

.rf-voice-number-price b {
  font-size: 1.35rem;
}

.rf-voice-number-price small,
.rf-voice-number-price span {
  color: #64748b;
}

.rf-voice-credit-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.rf-voice-credit-card.recommended {
  border-color: rgba(99, 102, 241, 0.42);
  background: linear-gradient(180deg, #fff, #f5f7ff);
}

.rf-voice-credit-card > b {
  font-size: 1.45rem;
}

.rf-voice-credit-card small {
  color: #64748b;
}

.rf-voice-active-number,
.rf-voice-summary-strip,
.rf-voice-review-card {
  display: grid;
  gap: 12px;
  margin-bottom: 20px;
}

.rf-voice-active-number {
  padding: 16px 18px;
  border-radius: 16px;
  background: #ecfdf5;
  color: #065f46;
}

.rf-voice-summary-strip,
.rf-voice-review-card {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.rf-voice-review-card {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.rf-voice-summary-strip > div,
.rf-voice-review-card > div {
  display: grid;
  gap: 4px;
  padding: 15px 16px;
  border-radius: 15px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}

.rf-voice-summary-strip small,
.rf-voice-review-card small {
  color: #64748b;
}

.rf-voice-policy-check {
  display: flex;
  gap: 13px;
  align-items: flex-start;
  padding: 18px;
  margin-bottom: 12px;
  border: 1px solid rgba(99, 102, 241, 0.28);
  border-radius: 17px;
  background: rgba(238, 242, 255, 0.54);
  cursor: pointer;
}

.rf-voice-policy-check.secondary {
  border-color: #e2e8f0;
  background: #f8fafc;
}

.rf-voice-policy-check input {
  margin-top: 3px;
  width: 18px;
  height: 18px;
}

.rf-voice-policy-check span {
  display: grid;
  gap: 5px;
}

.rf-voice-policy-check small {
  color: #64748b;
  line-height: 1.5;
}

.rf-voice-inline-warning {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 14px 16px;
  margin-top: 18px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #fff7ed;
  color: #9a3412;
}

.rf-voice-legal-note {
  display: block;
  margin-top: 20px;
  color: #94a3b8;
  line-height: 1.5;
}

.rf-voice-success-panel {
  display: flex;
  gap: 14px;
  align-items: center;
  padding: 24px;
  border-radius: 18px;
  background: #ecfdf5;
  color: #065f46;
}

.rf-voice-success-panel > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #22c55e;
  color: white;
  font-weight: 900;
}

.rf-voice-success-panel p {
  margin: 4px 0 0;
  color: #047857;
}

@media (max-width: 820px) {
  .rf-voice-wizard-top,
  .rf-voice-wizard-body {
    padding-left: 20px;
    padding-right: 20px;
  }

  .rf-voice-progress {
    padding-left: 20px;
    padding-right: 20px;
    overflow-x: auto;
  }

  .rf-voice-essential-grid,
  .rf-voice-essential-grid.two,
  .rf-voice-number-grid,
  .rf-voice-credit-grid,
  .rf-voice-summary-strip,
  .rf-voice-review-card {
    grid-template-columns: 1fr;
  }

  .rf-voice-wizard-top {
    align-items: flex-start;
  }

  .rf-voice-progress {
    min-width: 520px;
  }
}

/* ============================================================================
   ReachFly.Ai â€” 2026 FUTURE PROFESSIONAL VISUAL SYSTEM
   Final cascade layer. Keep this block at the END of styles.css.
   Purpose: unify marketing + dashboard + auth + billing + voice + admin UI.
   ============================================================================ */

:root {
  --bg: #f5f7fb;
  --ink: #0d1020;
  --muted: #667085;
  --dim: #98a2b3;
  --line: rgba(15, 23, 42, 0.09);
  --line-strong: rgba(79, 70, 229, 0.18);
  --card: rgba(255, 255, 255, 0.88);
  --purple: #6d5dfc;
  --purple-2: #8b5cf6;
  --pink: #d946ef;
  --orange: #ff8a5b;
  --blue: #4f7cff;
  --green: #16b67a;
  --cyan: #22c7e8;
  --red: #ef476f;
  --navy: #0b0d19;
  --navy-2: #11152a;
  --grad: linear-gradient(135deg, #635bff 0%, #8b5cf6 42%, #d946ef 72%, #ff8a5b 100%);
  --grad-blue: linear-gradient(135deg, #4f7cff 0%, #6d5dfc 48%, #bd4df2 100%);
  --grad-cool: linear-gradient(135deg, #4f7cff 0%, #6d5dfc 52%, #22c7e8 100%);
  --surface: rgba(255, 255, 255, 0.82);
  --surface-strong: #ffffff;
  --surface-soft: #f8f9fd;
  --shadow-xs: 0 1px 2px rgba(15, 23, 42, 0.035), 0 3px 10px rgba(15, 23, 42, 0.025);
  --shadow-sm: 0 8px 30px rgba(25, 31, 58, 0.07);
  --shadow: 0 18px 50px rgba(25, 31, 58, 0.085);
  --shadow-lg: 0 36px 100px rgba(25, 31, 58, 0.14);
  --ring: 0 0 0 4px rgba(99, 91, 255, 0.11);
  --radius-sm: 12px;
  --radius: 18px;
  --radius-lg: 26px;
  --radius-xl: 34px;
}

html {
  background: #f5f7fb;
}

body {
  min-height: 100vh;
  background:
    radial-gradient(circle at 8% -6%, rgba(99, 91, 255, 0.11), transparent 30rem),
    radial-gradient(circle at 96% 1%, rgba(217, 70, 239, 0.08), transparent 28rem),
    radial-gradient(circle at 70% 90%, rgba(79, 124, 255, 0.055), transparent 34rem),
    linear-gradient(180deg, #fbfcff 0%, #f6f7fb 44%, #f2f4f9 100%);
  color: var(--ink);
  font-family: "Plus Jakarta Sans", Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-feature-settings: "ss01" 1, "ss02" 1, "cv05" 1;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input,
select,
textarea {
  font-family: inherit;
}

h1,
h2,
h3,
h4,
h5,
h6,
.brand b,
.sb-name,
.metric-num,
.step-count {
  font-family: "Sora", "Plus Jakarta Sans", Inter, sans-serif;
  text-wrap: balance;
}

::selection {
  color: #fff;
  background: #655cf6;
}

/* --------------------------------------------------------------------------
   Global interactions
   -------------------------------------------------------------------------- */

button,
a,
input,
select,
textarea,
.card,
.cardish,
.metric-card,
.campaign-card {
  transition:
    color 160ms ease,
    background-color 160ms ease,
    border-color 160ms ease,
    box-shadow 180ms ease,
    transform 180ms ease;
}

:focus-visible {
  outline: 2px solid rgba(99, 91, 255, 0.75);
  outline-offset: 3px;
}

/* --------------------------------------------------------------------------
   Core buttons
   -------------------------------------------------------------------------- */

.btn {
  min-height: 44px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 13px;
  padding: 0 17px;
  background: rgba(255, 255, 255, 0.9);
  color: #1b2140;
  font-size: 13px;
  font-weight: 750;
  letter-spacing: -0.012em;
  box-shadow: var(--shadow-xs);
  backdrop-filter: blur(12px);
}

.btn:hover:not(:disabled) {
  transform: translateY(-2px);
  color: #4f46e5;
  border-color: rgba(99, 91, 255, 0.22);
  box-shadow: 0 12px 28px rgba(30, 37, 70, 0.09);
}

.btn.primary,
.btn.btn-primary {
  position: relative;
  overflow: hidden;
  color: #fff;
  border-color: rgba(255, 255, 255, 0.12);
  background: var(--grad);
