  border-color: rgba(99,91,255,.18);
  background: #f7f6ff;
}

/* --------------------------------------------------------------------------
   Auth pages
   -------------------------------------------------------------------------- */

.rf-auth-page {
  background:
    radial-gradient(circle at 5% 0%, rgba(99,91,255,.14), transparent 32rem),
    radial-gradient(circle at 95% 4%, rgba(217,70,239,.10), transparent 30rem),
    linear-gradient(180deg, #fbfcff 0%, #f5f7fb 100%);
}

.rf-auth-shell {
  gap: 28px;
}

.rf-auth-hero {
  border-radius: 30px;
  background:
    radial-gradient(circle at 15% 0%, rgba(139,92,246,.30), transparent 24rem),
    radial-gradient(circle at 92% 15%, rgba(79,124,255,.22), transparent 24rem),
    linear-gradient(145deg, #141729 0%, #0a0d18 68%, #100b1d 100%);
  box-shadow: 0 30px 80px rgba(9,11,21,.18);
}

.rf-auth-form {
  border-radius: 26px;
}

.rf-auth-card-head h2 {
  color: #14192f;
  font-family: "Sora", sans-serif;
  letter-spacing: -.04em;
}

.rf-auth-input {
  border-radius: 12px;
  border-color: rgba(15,23,42,.09);
  background: #f8f9fc;
}

.rf-auth-input:focus-within {
  border-color: rgba(99,91,255,.35);
  background: #fff;
  box-shadow: var(--ring);
}

.rf-auth-submit {
  border-radius: 13px;
  background: var(--grad);
  box-shadow: 0 14px 30px rgba(99,91,255,.24);
}

/* ============================================================================
   MARKETING PAGE â€” futuristic, premium, high-conversion visual layer
   Scope: .cu-page only
   ============================================================================ */

.cu-page {
  --cu-bg: #f6f7fb;
  --cu-bg-warm: #fbfcff;
  --cu-ink: #0c1020;
  --cu-ink-soft: #232a44;
  --cu-muted: #6f768c;
  --cu-muted-2: #949bae;
  --cu-card: rgba(255,255,255,.88);
  --cu-line: rgba(15,23,42,.085);
  --cu-line-strong: rgba(99,91,255,.18);
  --cu-purple: #635bff;
  --cu-purple-dark: #4f46e5;
  --cu-purple-soft: #efefff;
  --cu-pink: #d946ef;
  --cu-orange: #ff8a5b;
  --cu-green: #16b67a;
  --cu-navy: #090b14;
  --cu-navy-2: #111426;
  --cu-grad: linear-gradient(135deg, #635bff 0%, #8b5cf6 44%, #d946ef 76%, #ff8a5b 100%);
  --cu-grad-warm: linear-gradient(135deg, #635bff 0%, #b14fed 62%, #ff8a5b 100%);
  --cu-shadow-sm: 0 10px 30px rgba(23,31,58,.065);
  --cu-shadow-md: 0 24px 68px rgba(23,31,58,.10);
  --cu-shadow-lg: 0 44px 120px rgba(16,21,40,.16);

  background:
    radial-gradient(circle at 8% -8%, rgba(99,91,255,.12), transparent 32rem),
    radial-gradient(circle at 96% 2%, rgba(217,70,239,.08), transparent 31rem),
    linear-gradient(180deg, #fcfdff 0%, #f8f9fd 48%, #f4f6fb 100%);
  color: var(--cu-ink);
  font-family: "Plus Jakarta Sans", Inter, sans-serif;
}

.cu-page::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  opacity: .30;
  background-image:
    linear-gradient(rgba(99,91,255,.028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(99,91,255,.028) 1px, transparent 1px);
  background-size: 54px 54px;
  mask-image: radial-gradient(circle at 50% 15%, #000, transparent 68%);
}

.cu-nav {
  height: 76px;
  padding: 0 clamp(22px, 4.4vw, 70px);
  border-bottom: 1px solid rgba(15,23,42,.065);
  background: rgba(252,253,255,.78);
  box-shadow: 0 8px 30px rgba(23,31,58,.035);
  backdrop-filter: blur(24px) saturate(155%);
}

.cu-brand {
  color: #10152b;
  font-family: "Sora", sans-serif;
  font-size: 19px;
  font-weight: 680;
  letter-spacing: -.045em;
}

.cu-brand-mark {
  width: 40px;
  height: 40px;
  border-radius: 13px;
}

.cu-nav-links {
  gap: 30px;
}

.cu-nav-links a {
  padding: 27px 0 24px;
  color: #626a80;
  font-size: 12px;
  font-weight: 650;
}

.cu-nav-links a::after {
  bottom: 17px;
  height: 2px;
  background: linear-gradient(90deg, #635bff, #d946ef);
}

.cu-btn {
  min-height: 43px;
  border-radius: 12px;
  font-size: 12.5px;
  font-weight: 740;
}

.cu-btn-primary {
  position: relative;
  overflow: hidden;
  background: var(--cu-grad);
  box-shadow:
    0 12px 28px rgba(99,91,255,.24),
    inset 0 1px 0 rgba(255,255,255,.26);
}

.cu-btn-primary::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 25%, rgba(255,255,255,.23) 48%, transparent 70%);
  transform: translateX(-125%);
  transition: transform 440ms ease;
}

.cu-btn-primary:hover::before {
  transform: translateX(125%);
}

.cu-btn-ghost {
  color: #313751;
  background: rgba(255,255,255,.74);
  border-color: rgba(15,23,42,.10);
  box-shadow: 0 4px 14px rgba(23,31,58,.035);
}

.cu-btn-xl {
  min-height: 52px;
  padding: 0 22px;
  border-radius: 14px;
}

/* Hero */

.cu-hero {
  min-height: 760px;
  padding: clamp(76px, 8vw, 118px) clamp(22px, 4.4vw, 70px) 72px;
}

.cu-hero-bg {
  background-image:
    linear-gradient(rgba(99,91,255,.042) 1px, transparent 1px),
    linear-gradient(90deg, rgba(99,91,255,.042) 1px, transparent 1px);
  background-size: 58px 58px;
  mask-image: linear-gradient(to bottom, rgba(0,0,0,.82), transparent 82%);
}

.cu-hero::before {
  background:
    radial-gradient(ellipse at 52% 34%, rgba(255,255,255,.06), transparent 55%),
    linear-gradient(90deg, rgba(255,255,255,.93), rgba(255,255,255,.32) 48%, rgba(255,255,255,.72)),
    linear-gradient(180deg, transparent 65%, #fafbfe 100%);
}

.cu-hero-glow {
  filter: blur(115px);
}

.cu-hero-glow-one {
  width: 560px;
  height: 560px;
  left: -280px;
  top: 10px;
  background: rgba(99,91,255,.22);
}

.cu-hero-glow-two {
  width: 600px;
  height: 600px;
  right: -310px;
  top: 50px;
  background: rgba(217,70,239,.14);
}

.cu-hero-inner {
  width: min(1340px, 100%);
  grid-template-columns: minmax(0, .93fr) minmax(500px, 1.07fr);
  gap: clamp(48px, 6vw, 92px);
}

.cu-pill,
.cu-eyebrow {
  min-height: 30px;
  padding: 0 12px;
  border: 1px solid rgba(99,91,255,.17);
  color: #5549df;
  background: rgba(243,242,255,.88);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.88),
    0 6px 18px rgba(99,91,255,.045);
  font-size: 10px;
  font-weight: 760;
}

.cu-hero h1 {
  max-width: 760px;
  margin: 24px 0 25px;
  font-family: "Sora", sans-serif;
  font-size: clamp(58px, 5.9vw, 88px);
  font-weight: 690;
  line-height: .98;
  letter-spacing: -.067em;
  color: #0b0f1f;
  background: linear-gradient(118deg, #0a0e1d 0%, #141a36 48%, #5148df 73%, #b43bd7 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.cu-hero-copy > p {
  max-width: 650px;
  color: #646d83;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.75;
}

.cu-hero-actions {
  gap: 10px;
}

.cu-proof-row {
  gap: 10px 18px;
}

.cu-proof-row span {
  color: #737b91;
  font-size: 11px;
  font-weight: 620;
}

/* Product preview â€” the main futuristic visual */

.cu-preview {
  overflow: visible;
  border-radius: 26px;
  border: 1px solid rgba(99,91,255,.16);
  background: rgba(255,255,255,.78);
  box-shadow:
    0 48px 130px rgba(24,31,58,.18),
    0 18px 48px rgba(99,91,255,.10),
    inset 0 1px 0 rgba(255,255,255,.98);
  transform: perspective(1700px) rotateY(-2.6deg) rotateX(1.2deg) translateY(-2px);
  backdrop-filter: blur(18px) saturate(135%);
}

.cu-preview::before {
  inset: -1px;
  border-radius: 27px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.96),
    0 0 0 1px rgba(255,255,255,.32);
}

.cu-preview::after {
  z-index: -2;
  inset: auto 6% -46px;
  height: 84px;
  background: linear-gradient(90deg, rgba(79,124,255,.22), rgba(99,91,255,.27), rgba(217,70,239,.20));
  filter: blur(42px);
}

.cu-preview-top {
  height: 48px;
  border-bottom-color: rgba(15,23,42,.07);
  border-radius: 25px 25px 0 0;
  background: linear-gradient(180deg, rgba(252,253,255,.98), rgba(247,248,252,.95));
}

.cu-preview-body {
  grid-template-columns: 162px 1fr;
  min-height: 490px;
}

.cu-preview-side {
  border-radius: 0 0 0 25px;
  background:
    radial-gradient(circle at 0 0, rgba(139,92,246,.28), transparent 18rem),
    radial-gradient(circle at 100% 72%, rgba(79,124,255,.12), transparent 18rem),
    linear-gradient(180deg, #15182b 0%, #090b14 100%);
}

.cu-preview-nav-item {
  border-radius: 9px;
}

.cu-preview-nav-item.active {
  background: linear-gradient(90deg, rgba(99,91,255,.30), rgba(255,255,255,.055));
  box-shadow: inset 2px 0 0 #8f83ff;
}

.cu-preview-main {
  border-radius: 0 0 25px 0;
  background:
    radial-gradient(circle at 90% 0, rgba(99,91,255,.045), transparent 18rem),
    linear-gradient(180deg, #fbfcff, #f6f7fb);
}

.cu-preview-header,
.cu-preview-metrics div,
.cu-preview-panel,
.cu-preview-table {
  border-color: rgba(15,23,42,.075);
  background: rgba(255,255,255,.90);
  box-shadow: 0 7px 20px rgba(23,31,58,.045);
}

.cu-preview-header {
  border-radius: 14px;
}

.cu-preview-header h3,
.cu-preview-metrics b,
.cu-audit-score strong {
  font-family: "Sora", sans-serif;
}

.cu-preview-header button {
  border-radius: 9px;
  background: var(--cu-grad);
  box-shadow: 0 8px 20px rgba(99,91,255,.20);
}

.cu-preview-metrics div {
  border-radius: 11px;
}

.cu-preview-metrics b {
  color: #14192f;
}

.cu-progress-line span {
  background: linear-gradient(90deg, #4f7cff, #635bff, #b64ae8);
}

.cu-audit-score strong {
  color: #635bff;
}

.cu-preview-table b {
  color: #5548df;
  background: #efefff;
}

/* Capability strip */

.cu-chip-strip {
  width: min(1320px, calc(100% - 32px));
  margin-top: 70px;
  padding: 14px 0;
  border-color: rgba(15,23,42,.075);
}

.cu-product-chip {
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid rgba(15,23,42,.065);
  border-radius: 10px;
  color: #626b82;
  background: rgba(255,255,255,.72);
  box-shadow: 0 4px 14px rgba(23,31,58,.025);
}

/* Sections */

.cu-section {
  width: min(1280px, calc(100% - 44px));
  padding: clamp(86px, 8vw, 118px) 0;
}

.cu-section-head {
  max-width: 860px;
  margin-bottom: 46px;
}

.cu-section-head h2,
.cu-replace-copy h2,
.cu-solutions-copy h2,
.cu-roi-copy h2,
.cu-final h2 {
  color: #10152b;
  font-family: "Sora", sans-serif;
  font-size: clamp(40px, 4.6vw, 62px);
  font-weight: 670;
  line-height: 1.02;
  letter-spacing: -.058em;
}

.cu-section-head p,
.cu-replace-copy p,
.cu-solutions-copy p,
.cu-roi-copy p,
.cu-final p {
  color: #70788d;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.72;
}

.cu-workspace-grid {
  gap: 16px;
}

.cu-work-card {
  min-height: 236px;
  padding: 25px;
  border-radius: 20px;
  border-color: rgba(15,23,42,.08);
  background:
    radial-gradient(circle at 100% 0, rgba(99,91,255,.055), transparent 16rem),
    linear-gradient(180deg, rgba(255,255,255,.96), rgba(249,250,253,.94));
  box-shadow: 0 14px 42px rgba(23,31,58,.06);
}

.cu-work-card:nth-child(3n+2) {
  background:
    radial-gradient(circle at 100% 0, rgba(79,124,255,.065), transparent 16rem),
    linear-gradient(180deg, rgba(255,255,255,.96), rgba(249,250,253,.94));
}

.cu-work-card:nth-child(3n) {
  background:
    radial-gradient(circle at 100% 0, rgba(217,70,239,.055), transparent 16rem),
    linear-gradient(180deg, rgba(255,255,255,.96), rgba(249,250,253,.94));
}

.cu-work-card:hover {
  transform: translateY(-5px);
  border-color: rgba(99,91,255,.18);
  box-shadow: 0 26px 60px rgba(23,31,58,.10);
}

.cu-work-card > span {
  border-radius: 12px;
  color: #5b4ee5;
  background: linear-gradient(180deg, #f3f2ff, #ecebff);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.92);
}

.cu-work-card h3 {
  color: #1a2039;
  font-family: "Sora", sans-serif;
  font-size: 19px;
  font-weight: 640;
}

.cu-work-card p {
  color: #747c91;
}

/* Dark specialist section */

.cu-agents {
  padding: clamp(94px, 8.5vw, 132px) clamp(22px, 4.4vw, 70px);
  background:
    radial-gradient(circle at 10% 4%, rgba(99,91,255,.28), transparent 34rem),
    radial-gradient(circle at 92% 76%, rgba(217,70,239,.13), transparent 30rem),
    radial-gradient(circle at 52% 110%, rgba(79,124,255,.12), transparent 38rem),
    linear-gradient(145deg, #111426 0%, #080a12 62%, #0b0814 100%);
}

.cu-agents::before {
  opacity: .7;
  background-size: 56px 56px;
}

.cu-agent-grid {
  gap: 14px;
}

.cu-agent-card {
  min-height: 270px;
  border-radius: 18px;
  border-color: rgba(255,255,255,.10);
  background:
    linear-gradient(180deg, rgba(255,255,255,.075), rgba(255,255,255,.035));
  box-shadow:
    0 20px 56px rgba(0,0,0,.16),
    inset 0 1px 0 rgba(255,255,255,.06);
}

.cu-agent-card:hover {
  transform: translateY(-5px);
  border-color: rgba(145,129,255,.25);
  background: linear-gradient(180deg, rgba(255,255,255,.09), rgba(255,255,255,.045));
}

.cu-agent-top span {
  border-color: rgba(145,129,255,.18);
  color: #c6beff;
  background: rgba(99,91,255,.13);
}

.cu-agent-card h3 {
  color: #fff;
  font-family: "Sora", sans-serif;
  font-weight: 620;
}

.cu-agent-card p {
  color: rgba(235,238,250,.64);
}

/* Pricing */

.cu-pricing {
  background:
    radial-gradient(circle at 50% 0, rgba(99,91,255,.075), transparent 30rem),
    linear-gradient(180deg, #f6f7fb, #fbfcff);
}

.cu-price-grid {
  gap: 16px;
}

.cu-price-grid article {
  min-height: 500px;
  padding: 29px;
  border-radius: 20px;
  border-color: rgba(15,23,42,.085);
  background: linear-gradient(180deg, #fff, #fafbfe);
  box-shadow: 0 18px 50px rgba(23,31,58,.07);
}

.cu-price-grid article:hover {
  transform: translateY(-4px);
  border-color: rgba(99,91,255,.17);
  box-shadow: 0 26px 66px rgba(23,31,58,.10);
}

.cu-price-grid article.featured {
  transform: translateY(-8px);
  background:
    radial-gradient(circle at 74% 0, rgba(139,92,246,.34), transparent 20rem),
    radial-gradient(circle at 10% 100%, rgba(79,124,255,.13), transparent 18rem),
    linear-gradient(155deg, #171a31 0%, #080a12 100%);
  border-color: rgba(255,255,255,.11);
  box-shadow: 0 32px 84px rgba(12,15,28,.20);
}

.cu-price-grid h3,
.cu-price-grid strong {
  font-family: "Sora", sans-serif;
}

.cu-price-grid h3 {
  color: #171c34;
  font-weight: 640;
}

.cu-price-grid strong {
  color: #13182e;
  font-weight: 650;
}

.cu-price-grid li {
  color: #687087;
}

/* Final CTA â€” turn the plain white card into a memorable product moment */

.cu-final {
  width: min(1280px, calc(100% - 44px));
  margin-top: clamp(46px, 6vw, 76px);
  padding: clamp(72px, 8vw, 110px) clamp(28px, 7vw, 100px);
  border-radius: 30px;
  border: 1px solid rgba(255,255,255,.09);
  color: #fff;
  background:
    radial-gradient(circle at 12% 8%, rgba(99,91,255,.34), transparent 30rem),
    radial-gradient(circle at 90% 90%, rgba(217,70,239,.18), transparent 28rem),
    radial-gradient(circle at 50% 120%, rgba(79,124,255,.15), transparent 28rem),
    linear-gradient(145deg, #15182b 0%, #090b14 70%, #0c0814 100%);
  box-shadow:
    0 38px 100px rgba(12,15,28,.20),
    inset 0 1px 0 rgba(255,255,255,.06);
}

.cu-final::before {
  opacity: .72;
  background-size: 56px 56px;
}

.cu-final::after {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -48%);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(99,91,255,.18), transparent 68%);
  filter: blur(18px);
  pointer-events: none;
}

.cu-final > div {
  position: relative;
  z-index: 2;
}

.cu-final .cu-eyebrow {
  color: #d0caff;
  background: rgba(99,91,255,.12);
  border-color: rgba(167,154,255,.20);
}

.cu-final h2 {
  max-width: 940px;
  color: #fff;
  font-size: clamp(44px, 5.2vw, 70px);
  text-shadow: 0 12px 40px rgba(0,0,0,.18);
}

.cu-final p {
  max-width: 760px;
  color: rgba(239,242,255,.66);
}

.cu-final .cu-btn-primary {
  min-width: 164px;
  box-shadow: 0 16px 36px rgba(99,91,255,.28);
}

.cu-footer {
  width: min(1280px, calc(100% - 44px));
  padding: 36px 0 46px;
  color: #777f93;
}

.cu-footer p,
.cu-footer > div span {
  color: #7f879a;
}

/* --------------------------------------------------------------------------
   Blog surface
   -------------------------------------------------------------------------- */

.rf-blog-shell {
  color: #171d35;
  font-family: "Plus Jakarta Sans", Inter, sans-serif;
}

.rf-blog-hero h1,
.rf-blog-article h1,
.rf-blog-article h2,
.rf-blog-card h2 {
  font-family: "Sora", sans-serif;
}

.rf-blog-card {
  border-color: rgba(15,23,42,.08);
  border-radius: 18px;
  background: linear-gradient(180deg, #fff, #fafbfe);
  box-shadow: var(--shadow-sm);
}

.rf-blog-card:hover {
  transform: translateY(-4px);
  border-color: rgba(99,91,255,.16);
  box-shadow: 0 22px 54px rgba(25,31,58,.10);
}

.rf-blog-cta {
  border-radius: 22px;
  background:
    radial-gradient(circle at 90% 0, rgba(139,92,246,.30), transparent 20rem),
    linear-gradient(135deg, #171a31, #090b14);
}

/* --------------------------------------------------------------------------
   System scrollbars
   -------------------------------------------------------------------------- */

* {
  scrollbar-width: thin;
  scrollbar-color: rgba(99,91,255,.28) rgba(15,23,42,.04);
}

*::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

*::-webkit-scrollbar-track {
  background: rgba(15,23,42,.035);
}

*::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(99,91,255,.50), rgba(139,92,246,.38));
  background-clip: padding-box;
}

/* --------------------------------------------------------------------------
   Motion
   -------------------------------------------------------------------------- */

@keyframes rf-soft-float {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(0, -7px, 0); }
}

@keyframes rf-aurora-shift {
  0%, 100% { filter: hue-rotate(0deg); opacity: .72; }
  50% { filter: hue-rotate(10deg); opacity: .9; }
}

@media (min-width: 1181px) and (prefers-reduced-motion: no-preference) {
  .cu-hero-glow-one,
  .cu-hero-glow-two {
    animation: rf-aurora-shift 9s ease-in-out infinite;
  }

  .cu-preview {
    animation: rf-soft-float 7s ease-in-out infinite;
  }
}

/* --------------------------------------------------------------------------
   Responsive refinements
   -------------------------------------------------------------------------- */

@media (max-width: 1180px) {
  .cu-hero {
    min-height: auto;
  }

  .cu-hero-inner {
    grid-template-columns: 1fr;
    gap: 52px;
  }

  .cu-hero-copy {
    max-width: 900px;
    margin: 0 auto;
    text-align: center;
  }

  .cu-hero h1,
  .cu-hero-copy > p {
    margin-left: auto;
    margin-right: auto;
  }

  .cu-hero-actions,
  .cu-proof-row {
    justify-content: center;
    margin-left: auto;
    margin-right: auto;
  }

  .cu-pill,
  .cu-eyebrow {
    margin-left: auto;
    margin-right: auto;
  }

  .cu-preview {
    width: min(850px, 100%);
    margin: 0 auto;
    transform: none;
  }
}

@media (max-width: 980px) {
  .app-main {
    margin-left: 0;
    padding: 72px 18px 34px;
  }

  .topbar {
    top: 10px;
  }

