/* ---------------- Marquee fix ---------------- */

/*
   The marquee is now OUTSIDE .cu-hero in JSX.
   These rules keep it in the normal document flow and guarantee
   that the dashboard preview cannot cover it.
*/
.cu-chip-strip-after-hero {
  position: relative !important;
  inset: auto !important;
  z-index: 8 !important;
  width: 100%;
  min-height: 58px;
  margin: 0 !important;
  padding: 10px 0 !important;
  overflow: hidden !important;
  border-top: 1px solid rgba(111, 66, 245, 0.07);
  border-bottom: 1px solid rgba(111, 66, 245, 0.08);
  background:
    linear-gradient(90deg, #fbfaff, #fff 18%, #fff 82%, #fbf8ff);
}

.cu-chip-strip-after-hero::before,
.cu-chip-strip-after-hero::after {
  content: "";
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: 90px;
  pointer-events: none;
}

.cu-chip-strip-after-hero::before {
  left: 0;
  background: linear-gradient(90deg, #fbfaff, transparent);
}

.cu-chip-strip-after-hero::after {
  right: 0;
  background: linear-gradient(-90deg, #fbfaff, transparent);
}

.cu-chip-strip-after-hero .cu-chip-track {
  position: relative !important;
  z-index: 2 !important;
}

