    grid-template-columns: 1fr;
  }

  .cu-platform-flow {
    grid-template-columns: 1fr;
  }

  .cu-platform-flow article {
    grid-template-columns: 48px 1fr;
    justify-items: start;
    text-align: left;
  }

  .cu-platform-flow article > div {
