  }

  .cu-problem-card {
    min-height: 230px;
  }

  .cu-card-number {
    margin-bottom: 32px;
  }

  .cu-process-card,
  .cu-outcome-card {
    min-height: 220px;
  }

  .cu-footer-v2-main {
    gap: 42px;
    padding-top: 46px;
  }

  .cu-footer-v2-links {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cu-footer-v2-bottom {
    flex-direction: column;
  }
}

@media (max-width: 540px) {
  .cu-story-section,
  .cu-process-section,
  .cu-operators-section {
    width: min(100% - 30px, 1240px);
    padding: 68px 0;
  }

  .cu-hero-v2 h1 {
