  .rf-auth-brand,
  .auth-brand {
    font-size:
      17px !important;
  }


  .rf-auth-brand span,
  .auth-brand span {
    width:
      40px !important;

    height:
      40px !important;

    border-radius:
      13px !important;
  }


  .rf-auth-eyebrow,
  .auth-eyebrow {
    min-height:
      29px;

    padding:
      0
      10px !important;

    font-size:
      8px !important;
  }


  .rf-auth-copy h1,
  .auth-left h1 {
    margin:
      16px
      0
      12px !important;

    font-size:
      clamp(34px, 11vw, 44px) !important;

    line-height:
      1 !important;
  }


  .rf-auth-copy p,
  .auth-left p {
    font-size:
