/* =========================================================
   ReachFly Voice UI V5
   Sidebar sub-navigation + ElevenLabs voice library
   + owned number management
   ========================================================= */

/* ---------- Voice Agent sidebar tree ---------- */

.sb-nav-tree {
  display: grid;
  gap: 4px;
}

.sb-nav-tree.open > .sb-item {
  margin-bottom: 2px;
}

.sb-tree-chevron {
  margin-left: auto;
  color: rgba(229, 220, 255, 0.5);
  font-size: 18px;
  line-height: 1;
  transform: rotate(0deg);
  transition: transform 160ms ease, color 160ms ease;
}

.sb-nav-tree.open .sb-tree-chevron {
  transform: rotate(90deg);
  color: #fff;
}

.sb-subnav {
  position: relative;
  display: grid;
  gap: 3px;
  margin: 0 0 7px 22px;
  padding: 4px 0 3px 15px;
}

.sb-subnav::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 4px;
  width: 1px;
  background:
    linear-gradient(
      180deg,
      rgba(135, 96, 255, 0.5),
      rgba(237, 77, 172, 0.12)
    );
}

.sb-subitem {
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 10px;
  border-radius: 10px;
  color: rgba(223, 218, 235, 0.62);
  text-decoration: none;
  font-size: 10.5px;
  font-weight: 700;
  transition:
    color 150ms ease,
    background 150ms ease,
    transform 150ms ease;
}

.sb-subitem:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.055);
  transform: translateX(2px);
}

.sb-subitem.active {
  color: #fff;
  background:
    linear-gradient(
      90deg,
      rgba(111, 66, 245, 0.27),
      rgba(234, 77, 171, 0.10)
    );
}

.sb-subitem-dot {
  width: 6px;
  height: 6px;
  flex: 0 0 6px;
  border-radius: 50%;
  border: 1px solid rgba(187, 164, 255, 0.55);
  background: transparent;
}

.sb-subitem.active .sb-subitem-dot {
  border-color: transparent;
  background: #a78bfa;
  box-shadow: 0 0 0 4px rgba(139, 92, 246, 0.12);
}

