/* =========================================================
   ReachFly Voice UI V5
   Sidebar sub-navigation + ElevenLabs voice library
   + owned number management
   ========================================================= */

/* ---------- Voice Agent sidebar tree ---------- */

.sb-nav-tree {
  display: grid;
  gap: 4px;
}

.sb-nav-tree.open > .sb-item {
  margin-bottom: 2px;
}

.sb-tree-chevron {
  margin-left: auto;
  color: rgba(229, 220, 255, 0.5);
  font-size: 18px;
  line-height: 1;
  transform: rotate(0deg);
  transition: transform 160ms ease, color 160ms ease;
}

.sb-nav-tree.open .sb-tree-chevron {
  transform: rotate(90deg);
  color: #fff;
}

.sb-subnav {
  position: relative;
  display: grid;
  gap: 3px;
  margin: 0 0 7px 22px;
  padding: 4px 0 3px 15px;
}

.sb-subnav::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 4px;
  width: 1px;
  background:
    linear-gradient(
      180deg,
      rgba(135, 96, 255, 0.5),
      rgba(237, 77, 172, 0.12)
    );
}

.sb-subitem {
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 10px;
  border-radius: 10px;
  color: rgba(223, 218, 235, 0.62);
  text-decoration: none;
  font-size: 10.5px;
  font-weight: 700;
  transition:
    color 150ms ease,
    background 150ms ease,
    transform 150ms ease;
}

.sb-subitem:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.055);
  transform: translateX(2px);
}

.sb-subitem.active {
  color: #fff;
  background:
    linear-gradient(
      90deg,
      rgba(111, 66, 245, 0.27),
      rgba(234, 77, 171, 0.10)
    );
}

.sb-subitem-dot {
  width: 6px;
  height: 6px;
  flex: 0 0 6px;
  border-radius: 50%;
  border: 1px solid rgba(187, 164, 255, 0.55);
  background: transparent;
}

.sb-subitem.active .sb-subitem-dot {
  border-color: transparent;
  background: #a78bfa;
  box-shadow: 0 0 0 4px rgba(139, 92, 246, 0.12);
}

/* ---------- Identity step ---------- */

.rf-voice-identity-stack {
  display: grid;
  gap: 20px;
}

.rf-voice-picker-field {
  min-width: 0;
}

/* ---------- Selected voice ---------- */

.rf-voice-library {
  display: grid;
  gap: 15px;
  margin-top: 7px;
}

.rf-selected-voice-summary {
  min-height: 92px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 15px 16px;
  border: 1px solid rgba(111, 66, 245, 0.20);
  border-radius: 17px;
  background:
    radial-gradient(
      circle at 100% 0,
      rgba(234, 77, 171, 0.08),
      transparent 13rem
    ),
    linear-gradient(135deg, #fbf9ff, #fff);
}

.rf-selected-voice-summary > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.rf-selected-voice-summary > div > span {
  color: #7655e3;
  font-size: 9px;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: 0.09em;
}

.rf-selected-voice-summary strong {
  overflow: hidden;
  color: #1e1926;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-selected-voice-summary small {
  overflow: hidden;
  color: #797280;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-voice-preview-main {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid rgba(111, 66, 245, 0.16);
  border-radius: 12px;
  color: #623ce3;
  background: #f2eeff;
  font-size: 10px;
  font-weight: 850;
  cursor: pointer;
}

.rf-voice-preview-main:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* ---------- Voice avatar / image ---------- */

.rf-voice-avatar {
  position: relative;
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 16px;
  color: #fff;
  background:
    radial-gradient(
      circle at 25% 20%,
      rgba(255, 255, 255, 0.33),
      transparent 28%
    ),
    linear-gradient(
      145deg,
      #6f42f5,
      #a447df 55%,
      #ee4ca9
    );
  box-shadow: 0 10px 24px rgba(111, 66, 245, 0.18);
}

.rf-voice-avatar.large {
  width: 60px;
  height: 60px;
  flex-basis: 60px;
  border-radius: 18px;
}

.rf-voice-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rf-voice-avatar > b {
  font-size: 14px;
  font-weight: 900;
  letter-spacing: -0.04em;
}

.rf-voice-avatar > i {
  position: absolute;
  left: 7px;
  right: 7px;
  bottom: 7px;
  height: 8px;
  display: flex;
  justify-content: center;
  align-items: end;
  gap: 2px;
}

.rf-voice-avatar > i span {
  width: 2px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.73);
}

.rf-voice-avatar > i span:nth-child(1) { height: 4px; }
.rf-voice-avatar > i span:nth-child(2) { height: 8px; }
.rf-voice-avatar > i span:nth-child(3) { height: 6px; }
.rf-voice-avatar > i span:nth-child(4) { height: 3px; }

/* ---------- Voice filters ---------- */

.rf-voice-library-toolbar {
  display: grid;
  grid-template-columns:
    minmax(220px, 1.35fr)
    repeat(4, minmax(120px, 0.7fr));
  gap: 9px;
  padding: 12px;
  border: 1px solid #e5e5ed;
  border-radius: 15px;
  background: #fafafd;
}

.rf-voice-library-toolbar label {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.rf-voice-library-toolbar label > span {
  color: #716a78;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.rf-voice-library-toolbar input,
.rf-voice-library-toolbar select {
  width: 100%;
  height: 38px;
  min-width: 0;
  padding: 0 10px;
  border: 1px solid #dedee7;
  border-radius: 10px;
  outline: none;
  color: #2f2936;
  background: #fff;
  font-size: 10px;
  font-weight: 650;
}

.rf-voice-library-toolbar input:focus,
.rf-voice-library-toolbar select:focus {
  border-color: rgba(111, 66, 245, 0.52);
  box-shadow: 0 0 0 3px rgba(111, 66, 245, 0.07);
}

.rf-voice-library-meta {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  color: #8d8693;
  font-size: 9px;
  font-weight: 700;
}

.rf-voice-library-meta button {
  padding: 0;
  border: 0;
  color: #6d49dc;
  background: transparent;
  font-size: 9px;
  font-weight: 850;
  cursor: pointer;
}

/* ---------- Voice cards ---------- */

.rf-voice-card-grid {
  max-height: 455px;
  overflow: auto;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
  padding: 2px 3px 4px 2px;
  scrollbar-width: thin;
}

.rf-voice-card {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 9px;
  min-width: 0;
  padding: 10px;
  border: 1px solid #e3e3eb;
  border-radius: 15px;
  background: #fff;
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease,
    transform 150ms ease;
}

.rf-voice-card:hover {
  transform: translateY(-1px);
  border-color: rgba(111, 66, 245, 0.26);
  box-shadow: 0 12px 26px rgba(38, 27, 68, 0.06);
}

.rf-voice-card.selected {
  border-color: #7858eb;
  background:
    linear-gradient(135deg, #fff, #f8f5ff);
  box-shadow:
    0 0 0 3px rgba(111, 66, 245, 0.06),
    0 12px 28px rgba(74, 45, 151, 0.07);
}

.rf-voice-card-select {
  min-width: 0;
  display: flex;
  gap: 11px;
  align-items: flex-start;
  padding: 0;
  border: 0;
  text-align: left;
  color: inherit;
  background: transparent;
  cursor: pointer;
}

.rf-voice-card-copy {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.rf-voice-card-copy > div:first-child {
  min-width: 0;
  display: flex;
  gap: 7px;
  align-items: center;
}

.rf-voice-card-copy strong {
  min-width: 0;
  overflow: hidden;
  color: #211c28;
  font-size: 11.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-voice-card-copy em {
  flex: 0 0 auto;
  padding: 3px 6px;
  border-radius: 999px;
  color: #6740df;
  background: #eee9ff;
  font-size: 7px;
  font-style: normal;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.rf-voice-card-copy p {
  min-height: 29px;
  margin: 0;
  overflow: hidden;
  color: #827b88;
  font-size: 9px;
  line-height: 1.45;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.rf-voice-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.rf-voice-tags span {
  padding: 3px 6px;
  border-radius: 999px;
  color: #696271;
  background: #f4f3f7;
  font-size: 7.5px;
  font-weight: 750;
}

.rf-voice-card-preview {
  width: 58px;
  align-self: stretch;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 5px;
  padding: 6px;
  border: 1px solid rgba(111, 66, 245, 0.10);
  border-radius: 11px;
  color: #6842de;
  background: #f6f2ff;
  font-size: 8px;
  font-weight: 850;
  cursor: pointer;
}

.rf-voice-card-preview > span {
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #fff;
  background: linear-gradient(135deg, #6f42f5, #e74bab);
  font-size: 9px;
  box-shadow: 0 7px 15px rgba(111, 66, 245, 0.17);
}

.rf-voice-card-preview:disabled {
  opacity: 0.32;
  cursor: not-allowed;
}

.rf-voice-library-empty {
  min-height: 150px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 7px;
  padding: 24px;
  border: 1px dashed #dcd9e5;
  border-radius: 15px;
  color: #77707e;
  text-align: center;
  background: #faf9fc;
}

.rf-voice-library-empty p {
  margin: 0;
  font-size: 10px;
}

/* ---------- Owned numbers ---------- */

.rf-owned-numbers-section {
  display: grid;
  gap: 15px;
  margin-bottom: 20px;
  padding: 18px;
  border: 1px solid #e2e2eb;
  border-radius: 20px;
  background:
    radial-gradient(
      circle at 100% 0,
      rgba(111, 66, 245, 0.06),
      transparent 15rem
    ),
    #fbfbfd;
}

.rf-owned-numbers-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.rf-owned-numbers-head > div {
  display: grid;
  gap: 4px;
}

.rf-owned-numbers-head span {
  color: #6c46df;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.rf-owned-numbers-head h4 {
  margin: 0;
  color: #221c29;
  font-size: 16px;
  letter-spacing: -0.03em;
}

.rf-owned-numbers-head p {
  max-width: 620px;
  margin: 0;
  color: #827b89;
  font-size: 10px;
  line-height: 1.5;
}

.rf-owned-numbers-head > b {
  min-width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  color: #6540df;
  background: #eee9ff;
  font-size: 12px;
}

.rf-owned-number-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.rf-owned-number-card {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid #dedee7;
  border-radius: 15px;
  background: #fff;
}

.rf-owned-number-card.selected {
  border-color: #7958ea;
  box-shadow: 0 0 0 3px rgba(111, 66, 245, 0.06);
}

.rf-owned-number-top {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 9px;
  align-items: center;
}

.rf-owned-number-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  color: #6540df;
  background: #f0ecff;
}

.rf-owned-number-top > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.rf-owned-number-top strong {
  color: #211c27;
  font-size: 12px;
}

.rf-owned-number-top small {
  overflow: hidden;
  color: #89828f;
  font-size: 8.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-owned-number-top em {
  padding: 4px 7px;
  border-radius: 999px;
  color: #8b6b20;
  background: #fff6d8;
  font-size: 7px;
  font-style: normal;
  font-weight: 900;
  text-transform: uppercase;
}

.rf-owned-number-top em.active {
  color: #087044;
  background: #e5f9ef;
}

.rf-owned-number-capabilities {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.rf-owned-number-capabilities span {
  padding: 4px 7px;
  border-radius: 999px;
  color: #857e8b;
  background: #f4f3f6;
  font-size: 7.5px;
  font-weight: 750;
}

.rf-owned-number-capabilities span.ready {
  color: #6540df;
  background: #eeeaff;
}

.rf-owned-numbers-empty {
  min-height: 100px;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 16px;
  border: 1px dashed #d9d6e3;
  border-radius: 15px;
  background: #fff;
}

.rf-owned-numbers-empty > span {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  flex: 0 0 40px;
  border-radius: 12px;
  color: #7050dd;
  background: #f1edff;
}

.rf-owned-numbers-empty b {
  color: #302a38;
  font-size: 11px;
}

.rf-owned-numbers-empty p {
  margin: 4px 0 0;
  color: #837c89;
  font-size: 9.5px;
  line-height: 1.5;
}

@media (max-width: 1180px) {
  .rf-voice-library-toolbar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rf-voice-search {
    grid-column: 1 / -1;
  }
}

@media (max-width: 820px) {
  .rf-selected-voice-summary {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .rf-voice-preview-main {
    grid-column: 1 / -1;
  }

  .rf-voice-card-grid,
  .rf-owned-number-grid {
    grid-template-columns: 1fr;
  }

  .rf-voice-library-toolbar {
    grid-template-columns: 1fr;
  }

  .rf-voice-search {
    grid-column: auto;
  }
}
