  border-radius: 22px;
  background:
    radial-gradient(
      circle at 100% 0,
      rgba(111, 66, 245, 0.1),
      transparent 20rem
    ),
    radial-gradient(
      circle at 0 100%,
      rgba(231, 75, 169, 0.045),
      transparent 18rem
    ),
    linear-gradient(
      180deg,
      #ffffff 0%,
      #fcfbff 100%
    );
  box-shadow:
    0 18px 45px rgba(43, 29, 77, 0.055),
    0 2px 7px rgba(43, 29, 77, 0.025);
}

.rf-lead-flow-header::before {
  content: "";
  position: absolute;
  top: 0;
  left: 28px;
