  gap: 2px;
  margin: 2px 0 7px 31px;
  padding: 3px 0 3px 10px;
  border-left: 1px solid rgba(255, 255, 255, 0.105);
}

.sb-subsubitem {
  position: relative;
  min-width: 0;
  min-height: 31px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 9px;
  border: 1px solid transparent;
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.47);
  background: transparent;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 750;
  text-decoration: none;
  transition:
    color 0.16s ease,
    background 0.16s ease,
    border-color 0.16s ease,
    transform 0.16s ease;
}

.sb-subsubitem:hover {
  color: rgba(255, 255, 255, 0.92);
  background: rgba(255, 255, 255, 0.055);
  transform: translateX(1px);
}

.sb-subsubitem:focus-visible {
  outline: 2px solid rgba(180, 144, 255, 0.52);
  outline-offset: 1px;
}

.sb-subsubitem-line {
  width: 5px;
  height: 5px;
  flex: 0 0 5px;
