.sb-subsubitem[href*="view=my-numbers"],
.sb-subsubitem[href*="view=buy-numbers"],
.sb-subsubitem[href*="view=connect-number"] {
  font-weight: 800;
}

/* Sidebar can become taller after adding the nested Voice Agent tree. */
.sb-scroll {
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.18) transparent;
}

.sb-scroll::-webkit-scrollbar {
