    ),
    radial-gradient(
      circle at 93% 100%,
      rgba(232, 65, 174, 0.07),
      transparent 150px
    ),
    linear-gradient(
      135deg,
      #fbf9ff,
      #ffffff
    ) !important;
}

.rf-agent-page .rf-selected-voice-summary::after {
  content: "";

  position: absolute;

  width: 150px;
  height: 150px;

  right: -90px;
  top: -90px;

  border-radius: 50%;

  pointer-events: none;

  background:
    radial-gradient(
      circle,
      rgba(113, 72, 239, 0.08),
      transparent 70%
    );
}


