/* ==========================================================================
   6. CRITICAL FIX â€” REMOVE THE BAD GLOBAL WIZARD HEIGHT
   ========================================================================== */

.rf-agent-page .rf-voice-setup-shell {
  width: 100% !important;
  max-width: none !important;

  /*
    IMPORTANT:
    Previous CSS constrained the ENTIRE wizard to viewport height.
    That caused the compressed / cropped stage.
  */
  max-height: none !important;
  height: auto !important;

  display: block !important;

  overflow: visible !important;

  margin: 0 !important;

  border:
    1px solid rgba(105, 80, 190, 0.13) !important;

  border-radius: 27px !important;

  background:
    radial-gradient(
      circle at 93% 2%,
      rgba(114, 82, 245, 0.12),
      transparent 27rem
    ),
    radial-gradient(
      circle at 7% 10%,
      rgba(231, 72, 181, 0.055),
      transparent 24rem
    ),
    linear-gradient(
      180deg,
      #fbfaff 0%,
      #f8f6fd 100%
    ) !important;

  box-shadow:
    0 26px 75px rgba(44, 29, 83, 0.09),
    0 2px 8px rgba(39, 28, 70, 0.025) !important;
}

.rf-agent-page .rf-voice-setup-shell::before {
  opacity: 0.11 !important;
}


