/* ============================================================================
   ReachFly Voice Agent v5.5 â€” Artist portraits + full Agent & Voice details
   This file is imported AFTER styles.css by TelnyxAIAgentPage.v55.jsx.
   ============================================================================ */

.rf-agent-page {
  --rf55-ink: #17152b;
  --rf55-muted: #7d788a;
  --rf55-line: rgba(79, 65, 126, 0.11);
  --rf55-purple: #6e51ed;
  --rf55-violet: #8151ee;
  --rf55-pink: #dd47b5;
  --rf55-soft: #faf9fd;
}

/* --------------------------------------------------------------------------
   Do not crop the setup stage or hide lower sections.
   -------------------------------------------------------------------------- */
.rf-agent-page .rf-voice-setup-shell,
.rf-agent-page .rf-voice-setup-stage,
.rf-agent-page .rf-voice-setup-pane {
  height: auto !important;
  max-height: none !important;
}

.rf-agent-page .rf-voice-setup-shell,
.rf-agent-page .rf-voice-setup-stage {
  overflow: visible !important;
}

.rf-agent-page .rf-voice-setup-pane {
  overflow: visible !important;
  padding: 16px 18px 15px !important;
}

/* --------------------------------------------------------------------------
   Agent step desktop/laptop layout.
   Start at 900px because the app sidebar reduces the usable content width.
   -------------------------------------------------------------------------- */
@media (min-width: 900px) {
  .rf-agent-page
  .rf-voice-setup-pane:has(> .rf-voice-identity-stack) {
    display: grid !important;
    grid-template-columns: minmax(0, 1.28fr) minmax(310px, .72fr) !important;
    grid-template-areas:
      "voice language"
      "voice summary" !important;
    grid-template-rows: auto auto !important;
    gap: 14px 16px !important;
    align-items: stretch !important;
  }

  .rf-agent-page
  .rf-voice-setup-pane:has(> .rf-voice-identity-stack)
  > .rf-voice-identity-stack {
    grid-area: voice !important;
    align-self: stretch !important;
    min-height: 0 !important;
    display: grid !important;
    grid-template-rows: auto minmax(0, 1fr) !important;
  }

  .rf-agent-page
  .rf-voice-setup-pane:has(> .rf-voice-identity-stack)
  > .rf-voice-language-panel {
    grid-area: language !important;
    display: grid !important;
    align-self: start !important;
    margin: 0 !important;
  }

  .rf-agent-page
  .rf-voice-setup-pane:has(> .rf-voice-identity-stack)
  > .rf-voice-summary-strip {
    grid-area: summary !important;
    align-self: start !important;
    margin: 0 !important;
  }
}

/* --------------------------------------------------------------------------
   Left voice studio card.
   -------------------------------------------------------------------------- */
.rf-agent-page .rf-voice-identity-stack {
  min-width: 0 !important;
  gap: 11px !important;
  padding: 13px !important;
  border: 1px solid var(--rf55-line) !important;
  border-radius: 18px !important;
  background:
    radial-gradient(circle at 0 0, rgba(111, 80, 237, .07), transparent 18rem),
    linear-gradient(180deg, #fff, #fdfcff) !important;
  box-shadow: 0 10px 30px rgba(42, 28, 77, .045) !important;
}

.rf-agent-page .rf-voice-picker-field,
.rf-agent-page .rf-voice-library {
  min-height: 0 !important;
}

.rf-agent-page .rf-voice-picker-field {
  display: grid !important;
  grid-template-rows: auto minmax(0, 1fr) !important;
  gap: 7px !important;
}

.rf-agent-page .rf-voice-library {
  display: flex !important;
  flex-direction: column !important;
  gap: 9px !important;
}

/* --------------------------------------------------------------------------
   Generated DiceBear portraits.
   -------------------------------------------------------------------------- */
.rf-agent-page .rf-voice-avatar {
  position: relative !important;
  width: 58px !important;
  height: 58px !important;
  flex: 0 0 58px !important;
  overflow: hidden !important;
  border: 2px solid rgba(255,255,255,.96) !important;
  border-radius: 17px !important;
  outline: 1px solid rgba(107, 78, 222, .2) !important;
  background: linear-gradient(145deg, #ede9fe, #fce7f3) !important;
  box-shadow:
    0 10px 25px rgba(73, 45, 139, .16),
    0 0 0 4px rgba(111, 78, 226, .045) !important;
  isolation: isolate !important;
}

.rf-agent-page .rf-voice-avatar.large {
  width: 72px !important;
  height: 72px !important;
  flex-basis: 72px !important;
  border-radius: 20px !important;
}

.rf-agent-page .rf-voice-avatar img {
  position: relative !important;
  z-index: 1 !important;
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: center !important;
  transform: scale(1.015) !important;
  transition: transform .2s ease !important;
}

.rf-agent-page .rf-voice-avatar::before {
  content: "" !important;
  position: absolute !important;
  z-index: 2 !important;
  inset: 0 !important;
  pointer-events: none !important;
  background: linear-gradient(145deg, rgba(255,255,255,.3), transparent 38%, rgba(83,52,190,.08)) !important;
}

.rf-agent-page .rf-voice-avatar::after {
  content: "" !important;
  position: absolute !important;
  z-index: 3 !important;
  right: -9px !important;
  bottom: -9px !important;
  width: 34px !important;
  height: 22px !important;
  border-radius: 50% !important;
  pointer-events: none !important;
  background: rgba(221, 71, 181, .42) !important;
  filter: blur(10px) !important;
}

.rf-agent-page .rf-voice-card:hover .rf-voice-avatar img {
  transform: scale(1.075) !important;
}

/* --------------------------------------------------------------------------
   Selected voice feature card.
   -------------------------------------------------------------------------- */
.rf-agent-page .rf-selected-voice-summary {
  min-height: 92px !important;
  grid-template-columns: auto minmax(0, 1fr) auto !important;
  gap: 12px !important;
  align-items: center !important;
  padding: 10px 12px !important;
  border: 1px solid rgba(108, 78, 226, .22) !important;
  border-radius: 17px !important;
  background:
    radial-gradient(circle at 0 50%, rgba(112,80,239,.14), transparent 145px),
    radial-gradient(circle at 100% 100%, rgba(228,68,179,.08), transparent 170px),
    linear-gradient(135deg, #faf8ff, #fff) !important;
  box-shadow: 0 10px 27px rgba(70,45,132,.065) !important;
}

.rf-agent-page .rf-selected-voice-summary > div {
  min-width: 0 !important;
}

.rf-agent-page .rf-selected-voice-summary strong {
  display: block !important;
  overflow: hidden !important;
  color: #241e34 !important;
  font-size: 11px !important;
  font-weight: 900 !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

.rf-agent-page .rf-selected-voice-summary small {
  display: block !important;
  margin-top: 3px !important;
  overflow: hidden !important;
  color: #8c8596 !important;
  font-size: 7.5px !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

/* --------------------------------------------------------------------------
   Keep ALL voice details / filters visible.
   This intentionally reverses the earlier CSS that hid Age and Niche.
   -------------------------------------------------------------------------- */
.rf-agent-page .rf-voice-library-toolbar {
  display: grid !important;
  grid-template-columns:
    minmax(180px, 1.45fr)
    repeat(4, minmax(86px, .65fr)) !important;
  gap: 7px !important;
  padding: 8px !important;
  border: 1px solid rgba(82,68,124,.085) !important;
  border-radius: 12px !important;
  background: #f8f7fb !important;
}

.rf-agent-page .rf-voice-library-toolbar > label {
  display: grid !important;
  min-width: 0 !important;
  gap: 3px !important;
}

.rf-agent-page .rf-voice-library-toolbar label > span {
  display: block !important;
  color: #8c8596 !important;
  font-size: 6px !important;
  font-weight: 850 !important;
  letter-spacing: .055em !important;
  text-transform: uppercase !important;
}

.rf-agent-page .rf-voice-library-toolbar input,
.rf-agent-page .rf-voice-library-toolbar select {
  width: 100% !important;
  height: 35px !important;
  min-width: 0 !important;
  padding: 0 9px !important;
  border: 1px solid rgba(79,65,116,.12) !important;
  border-radius: 9px !important;
  background: #fff !important;
  color: #50495d !important;
  font-size: 8px !important;
}

/* --------------------------------------------------------------------------
   Voice collection: the only intentional vertical scroller on this step.
   -------------------------------------------------------------------------- */
.rf-agent-page .rf-voice-card-grid {
  flex: 1 1 auto !important;
  min-height: 300px !important;
  max-height: 430px !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: 8px !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  padding: 2px 6px 2px 2px !important;
  scrollbar-width: thin !important;
  scrollbar-color: rgba(110,78,224,.42) rgba(81,65,122,.04) !important;
  overscroll-behavior: contain !important;
}

.rf-agent-page .rf-voice-card-grid::-webkit-scrollbar {
  width: 5px !important;
}

.rf-agent-page .rf-voice-card-grid::-webkit-scrollbar-track {
  background: rgba(74,61,107,.04) !important;
  border-radius: 999px !important;
}

.rf-agent-page .rf-voice-card-grid::-webkit-scrollbar-thumb {
  background: linear-gradient(#8060ef, #d04fbe) !important;
  border-radius: 999px !important;
}

.rf-agent-page .rf-voice-card {
  min-width: 0 !important;
  min-height: 88px !important;
  padding: 7px !important;
  border: 1px solid rgba(76,63,111,.105) !important;
  border-radius: 14px !important;
  background: linear-gradient(145deg, #fff, #fbfafe) !important;
  box-shadow: 0 6px 18px rgba(44,30,77,.035) !important;
}

.rf-agent-page .rf-voice-card.selected {
  border-color: rgba(108,77,226,.38) !important;
  background: linear-gradient(145deg, #faf7ff, #fff) !important;
  box-shadow: 0 10px 25px rgba(91,58,182,.11) !important;
}

.rf-agent-page .rf-voice-card-select {
  min-width: 0 !important;
  gap: 9px !important;
}

.rf-agent-page .rf-voice-card-copy {
  min-width: 0 !important;
}

.rf-agent-page .rf-voice-card-copy strong {
  display: block !important;
  overflow: hidden !important;
  color: #2b2636 !important;
  font-size: 8.5px !important;
  font-weight: 900 !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

.rf-agent-page .rf-voice-card-copy p {
  display: -webkit-box !important;
  min-height: 0 !important;
  margin: 3px 0 5px !important;
  overflow: hidden !important;
  color: #918a99 !important;
  font-size: 6.5px !important;
  line-height: 1.28 !important;
  -webkit-line-clamp: 2 !important;
  -webkit-box-orient: vertical !important;
}

.rf-agent-page .rf-voice-tags {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 3px !important;
}

.rf-agent-page .rf-voice-tags span {
  display: inline-flex !important;
  max-width: 88px !important;
  overflow: hidden !important;
  padding: 2px 5px !important;
  border-radius: 999px !important;
  background: #f3f1f7 !important;
  color: #756e7e !important;
  font-size: 5.5px !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

.rf-agent-page .rf-voice-card-preview {
  width: 46px !important;
  border: 1px solid rgba(107,77,220,.11) !important;
  border-radius: 10px !important;
  background: linear-gradient(180deg, #faf8ff, #f3efff) !important;
  color: #6846db !important;
  font-size: 5.5px !important;
}

.rf-agent-page .rf-voice-card-preview > span {
  width: 25px !important;
  height: 25px !important;
  color: #fff !important;
  background: linear-gradient(135deg, #7254ec, #dc46b3) !important;
  box-shadow: 0 5px 12px rgba(110,74,220,.24) !important;
}

/* --------------------------------------------------------------------------
   Right-side language details must always be visible.
   -------------------------------------------------------------------------- */
.rf-agent-page .rf-voice-language-panel {
  display: grid !important;
  visibility: visible !important;
  opacity: 1 !important;
  min-width: 0 !important;
  gap: 10px !important;
  padding: 13px !important;
  border: 1px solid rgba(86,70,134,.105) !important;
  border-radius: 18px !important;
  background:
    radial-gradient(circle at 100% 0, rgba(83,123,255,.065), transparent 15rem),
    linear-gradient(180deg, #fff, #fbfafe) !important;
  box-shadow: 0 9px 28px rgba(41,29,74,.04) !important;
}

.rf-agent-page .rf-voice-language-panel .rf-voice-essential-grid.two {
  display: grid !important;
  grid-template-columns: 1fr !important;
  gap: 8px !important;
}

.rf-agent-page .rf-v6-language-chips {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 5px !important;
  overflow: visible !important;
}

.rf-agent-page .rf-v6-language-chips label {
  min-width: 0 !important;
  min-height: 28px !important;
  overflow: hidden !important;
  border-radius: 8px !important;
}

.rf-agent-page .rf-v6-language-overrides {
  display: grid !important;
  max-height: none !important;
  overflow: visible !important;
  gap: 6px !important;
}

.rf-agent-page .rf-v6-language-row {
  display: grid !important;
  grid-template-columns: 1fr !important;
  gap: 6px !important;
  padding: 8px !important;
  border: 1px solid rgba(77,65,111,.085) !important;
  border-radius: 10px !important;
  background: #faf9fc !important;
}

/* --------------------------------------------------------------------------
   Summary strip stays under language panel on desktop.
   -------------------------------------------------------------------------- */
@media (min-width: 900px) {
  .rf-agent-page
  .rf-voice-setup-pane:has(> .rf-voice-identity-stack)
  > .rf-voice-summary-strip {
    display: grid !important;
    grid-template-columns: 1fr !important;
    gap: 6px !important;
    padding: 8px !important;
    border: 1px solid rgba(82,67,124,.085) !important;
    border-radius: 14px !important;
    background: #faf9fc !important;
  }

  .rf-agent-page
  .rf-voice-setup-pane:has(> .rf-voice-identity-stack)
  > .rf-voice-summary-strip > div {
    min-height: 37px !important;
    display: grid !important;
    grid-template-columns: 94px minmax(0, 1fr) !important;
    align-items: center !important;
    gap: 8px !important;
    padding: 6px 8px !important;
    border: 0 !important;
    border-radius: 9px !important;
    background: #fff !important;
  }
}

/* --------------------------------------------------------------------------
   Navigation belongs AFTER the content; don't let it cover details.
   -------------------------------------------------------------------------- */
.rf-agent-page .rf-voice-setup-nav {
  position: relative !important;
  bottom: auto !important;
  z-index: 10 !important;
  margin: 0 14px 14px !important;
}

/* --------------------------------------------------------------------------
   Intermediate widths: preserve details, stack only when genuinely needed.
   -------------------------------------------------------------------------- */
@media (min-width: 900px) and (max-width: 1180px) {
  .rf-agent-page .rf-voice-library-toolbar {
    grid-template-columns: minmax(170px, 1.4fr) repeat(2, minmax(90px, .7fr)) !important;
  }

  .rf-agent-page .rf-voice-library-toolbar > label:nth-child(4),
  .rf-agent-page .rf-voice-library-toolbar > label:nth-child(5) {
    display: grid !important;
  }

  .rf-agent-page .rf-voice-library-toolbar > label:nth-child(4) {
    grid-column: 1 / 2 !important;
  }

  .rf-agent-page .rf-voice-library-toolbar > label:nth-child(5) {
    grid-column: 2 / 4 !important;
  }

  .rf-agent-page .rf-voice-card-grid {
    min-height: 330px !important;
    max-height: 450px !important;
  }
}

@media (max-width: 899px) {
  .rf-agent-page .rf-voice-setup-pane:has(> .rf-voice-identity-stack) {
    display: grid !important;
    grid-template-columns: 1fr !important;
    gap: 12px !important;
  }

  .rf-agent-page .rf-voice-card-grid {
    min-height: 0 !important;
    max-height: 350px !important;
    grid-template-columns: 1fr !important;
  }

  .rf-agent-page .rf-voice-library-toolbar {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .rf-agent-page .rf-voice-search {
    grid-column: 1 / -1 !important;
  }

  .rf-agent-page .rf-voice-setup-nav {
    position: sticky !important;
    bottom: 7px !important;
  }
}

@media (max-width: 520px) {
  .rf-agent-page .rf-selected-voice-summary {
    grid-template-columns: auto minmax(0, 1fr) !important;
  }

  .rf-agent-page .rf-selected-voice-summary .rf-voice-preview-main {
    grid-column: 1 / -1 !important;
    width: 100% !important;
  }

  .rf-agent-page .rf-voice-library-toolbar {
    grid-template-columns: 1fr !important;
  }

  .rf-agent-page .rf-voice-search,
  .rf-agent-page .rf-voice-library-toolbar > label {
    grid-column: auto !important;
  }

  .rf-agent-page .rf-v6-language-chips {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
}

.rf-agent-page .rf-voice-avatar-fallback {
  position: relative !important;
  z-index: 4 !important;
  display: grid !important;
  width: 100% !important;
  height: 100% !important;
  place-items: center !important;
  color: #fff !important;
  background: linear-gradient(145deg, #6549df, #9650e8 55%, #df47b4) !important;
  font-size: 12px !important;
  font-weight: 950 !important;
  letter-spacing: -.03em !important;
}


/* ==========================================================================
   REACHFLY.AI STITCH V7 DESIGN SYSTEM â€” MIGRATION LAYER
   Appended 2026-08-18. Preserve legacy selectors above while screens migrate.
   ========================================================================== */

/*
 * ReachFly.AI â€” Next UI foundation
 * --------------------------------
 * Canonical implementation layer for the Stitch "ReachFly.AI Core" system.
 *
 * IMPORTANT:
 * - This file is intentionally scoped under .rf-app-v7 / .rf7-* so it can be
 *   introduced without breaking the large legacy styles.css file.
 * - Import it AFTER ../styles.css from the new AppShell.
 * - Page migrations should use rf7-* primitives so the entire product keeps
 *   one visual language while old screens continue to work during rollout.
 */

:root {
  --rf7-surface: #f8f9fa;
  --rf7-surface-bright: #ffffff;
  --rf7-surface-low: #f3f4f5;
  --rf7-surface-container: #edeeef;
  --rf7-surface-high: #e7e8e9;
  --rf7-surface-highest: #e1e3e4;
  --rf7-text: #191c1d;
  --rf7-text-soft: #464554;
  --rf7-text-muted: #767586;
  --rf7-outline: #dfe0e5;
  --rf7-outline-strong: #c7c4d7;

  --rf7-primary: #4648d4;
  --rf7-primary-hover: #3e40c2;
  --rf7-primary-soft: #e9e9ff;
  --rf7-primary-soft-strong: #dfe0ff;
  --rf7-violet: #6b38d4;
  --rf7-violet-soft: #f5f3ff;

  --rf7-navy: #2e3132;
  --rf7-navy-deep: #242728;
  --rf7-navy-text: #f0f1f2;
  --rf7-navy-muted: #c7cbd0;

  --rf7-success: #0f8a55;
  --rf7-success-bg: #e9f8f0;
  --rf7-warning: #9a6700;
  --rf7-warning-bg: #fff6df;
  --rf7-danger: #ba1a1a;
  --rf7-danger-bg: #fff0ee;
  --rf7-info: #275fba;
  --rf7-info-bg: #edf4ff;

  --rf7-sidebar-width: 260px;
  --rf7-topbar-height: 64px;
  --rf7-page-max: 1440px;
  --rf7-page-pad: 32px;

  --rf7-radius-xs: 6px;
  --rf7-radius-sm: 8px;
  --rf7-radius-md: 12px;
  --rf7-radius-lg: 16px;
  --rf7-radius-xl: 20px;

  --rf7-shadow-1: 0 1px 2px rgba(20, 24, 31, 0.05);
  --rf7-shadow-2: 0 8px 24px rgba(20, 24, 31, 0.08);
  --rf7-shadow-3: 0 18px 48px rgba(20, 24, 31, 0.13);

  --rf7-ease: cubic-bezier(.2, .7, .2, 1);
}

/* -------------------------------------------------------------------------- */
/* App shell                                                                   */
/* -------------------------------------------------------------------------- */

.rf-app-v7 {
  min-height: 100vh;
  background: var(--rf7-surface);
  color: var(--rf7-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  isolation: isolate;
}

.rf-app-v7,
.rf-app-v7 *,
.rf-app-v7 *::before,
.rf-app-v7 *::after {
  box-sizing: border-box;
}

.rf-app-v7 button,
.rf-app-v7 input,
.rf-app-v7 select,
.rf-app-v7 textarea {
  font: inherit;
}

.rf-app-v7 button,
.rf-app-v7 a {
  -webkit-tap-highlight-color: transparent;
}

.rf7-shell {
  min-height: 100vh;
  background: var(--rf7-surface);
}

.rf7-sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  z-index: 70;
  width: var(--rf7-sidebar-width);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  color: var(--rf7-navy-text);
  background: var(--rf7-navy);
  border-right: 1px solid rgba(255,255,255,.06);
  transition: transform 220ms var(--rf7-ease), width 220ms var(--rf7-ease);
}

.rf7-sidebar-head {
  min-height: 76px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 20px;
}

.rf7-brand {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  color: #fff;
  text-decoration: none;
}

.rf7-brand-mark {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 1px 0 rgba(255,255,255,.18) inset;
}

.rf7-brand-mark img,
.rf7-brand-mark svg {
  width: 23px;
  height: 23px;
  object-fit: contain;
}

.rf7-brand-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.rf7-brand-copy strong {
  overflow: hidden;
  color: #fff;
  font-family: Geist, Inter, ui-sans-serif, sans-serif;
  font-size: 15px;
  font-weight: 600;
  line-height: 20px;
  letter-spacing: -.02em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf7-brand-copy small {
  overflow: hidden;
  color: rgba(240,241,242,.58);
  font-size: 10px;
  line-height: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf7-sidebar-toggle,
.rf7-icon-btn {
  appearance: none;
  width: 36px;
  height: 36px;
  display: inline-grid;
  place-items: center;
  flex: 0 0 36px;
  padding: 0;
  color: inherit;
  background: transparent;
  border: 0;
  border-radius: 9px;
  cursor: pointer;
  transition: background 160ms var(--rf7-ease), color 160ms var(--rf7-ease),
    transform 160ms var(--rf7-ease);
}

.rf7-sidebar-toggle:hover,
.rf7-icon-btn:hover {
  background: rgba(255,255,255,.08);
}

.rf7-sidebar-toggle:active,
.rf7-icon-btn:active {
  transform: scale(.96);
}

.rf7-workspace-switcher {
  margin: 0 14px 10px;
  padding: 10px 10px 10px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
  color: #fff;
  background: rgba(255,255,255,.055);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 10px;
  cursor: pointer;
  transition: background 160ms var(--rf7-ease), border-color 160ms var(--rf7-ease);
}

.rf7-workspace-switcher:hover {
  background: rgba(255,255,255,.08);
  border-color: rgba(255,255,255,.12);
}

.rf7-workspace-icon {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  flex: 0 0 28px;
  color: #fff;
  background: linear-gradient(145deg, var(--rf7-primary), var(--rf7-violet));
  border-radius: 8px;
}

.rf7-workspace-copy {
  min-width: 0;
  flex: 1;
  display: grid;
  gap: 1px;
}

.rf7-workspace-copy strong,
.rf7-workspace-copy span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf7-workspace-copy strong {
  font-size: 12px;
  line-height: 16px;
  font-weight: 600;
}

.rf7-workspace-copy span {
  color: rgba(240,241,242,.58);
  font-size: 10px;
  line-height: 14px;
}

.rf7-nav-scroll {
  min-height: 0;
  flex: 1;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 8px 14px 22px;
  scrollbar-width: none;
}

.rf7-nav-scroll::-webkit-scrollbar {
  display: none;
}

.rf7-nav-group + .rf7-nav-group {
  margin-top: 22px;
}

.rf7-nav-label {
  display: block;
  padding: 0 8px;
  margin: 0 0 7px;
  color: rgba(240,241,242,.52);
  font-size: 10px;
  font-weight: 700;
  line-height: 14px;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.rf7-nav-list {
  display: grid;
  gap: 3px;
}

.rf7-nav-link {
  position: relative;
  min-height: 40px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 10px;
  color: rgba(240,241,242,.77);
  text-decoration: none;
  border-radius: 8px;
  outline: none;
  transition: color 160ms var(--rf7-ease), background 160ms var(--rf7-ease),
    transform 160ms var(--rf7-ease);
}

.rf7-nav-link::before {
  content: "";
  position: absolute;
  left: -14px;
  top: 8px;
  bottom: 8px;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: transparent;
}

.rf7-nav-link:hover {
  color: #fff;
  background: rgba(255,255,255,.055);
}

.rf7-nav-link.active {
  color: #fff;
  background: var(--rf7-primary);
  box-shadow: 0 5px 14px rgba(70,72,212,.23);
}

.rf7-nav-link.active::before {
  background: #bfc0ff;
}

.rf7-nav-link svg {
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  stroke-width: 1.8;
}

.rf7-nav-link-text {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  font-size: 13px;
  font-weight: 450;
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf7-nav-badge {
  min-width: 19px;
  height: 19px;
  padding: 0 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  background: rgba(255,255,255,.14);
  border-radius: 999px;
  font-size: 10px;
  font-style: normal;
  font-weight: 700;
}

.rf7-nav-link.active .rf7-nav-badge {
  color: var(--rf7-primary);
  background: #fff;
}

.rf7-sidebar-foot {
  padding: 13px 14px 16px;
  border-top: 1px solid rgba(255,255,255,.07);
}

.rf7-sidebar-help {
  margin-bottom: 8px;
}

.rf7-profile-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 8px;
  border-radius: 9px;
  transition: background 160ms var(--rf7-ease);
}

.rf7-profile-row:hover {
  background: rgba(255,255,255,.055);
}

.rf7-profile-avatar {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  display: grid;
  place-items: center;
  overflow: hidden;
  color: #fff;
  background: linear-gradient(145deg, #6e70e4, #8c58e3);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 700;
}

.rf7-profile-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rf7-profile-copy {
  min-width: 0;
  flex: 1;
  display: grid;
  gap: 1px;
}

.rf7-profile-copy strong,
.rf7-profile-copy span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf7-profile-copy strong {
  color: #fff;
  font-size: 11px;
  line-height: 15px;
  font-weight: 600;
}

.rf7-profile-copy span {
  color: rgba(240,241,242,.55);
  font-size: 9px;
  line-height: 13px;
  text-transform: capitalize;
}

.rf7-shell-main {
  min-height: 100vh;
  padding-left: var(--rf7-sidebar-width);
  background: var(--rf7-surface);
  transition: padding-left 220ms var(--rf7-ease);
}

.rf7-topbar {
  position: fixed;
  z-index: 60;
  top: 0;
  right: 0;
  left: var(--rf7-sidebar-width);
  height: var(--rf7-topbar-height);
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 0 28px;
  background: rgba(248,249,250,.88);
  border-bottom: 1px solid rgba(25,28,29,.06);
  backdrop-filter: blur(14px);
  transition: left 220ms var(--rf7-ease);
}

.rf7-topbar-start,
.rf7-topbar-end {
  display: flex;
  align-items: center;
  min-width: 0;
}

.rf7-topbar-start {
  flex: 1;
  gap: 20px;
}

.rf7-topbar-end {
  justify-content: flex-end;
  gap: 9px;
}

.rf7-mobile-menu-btn {
  display: none;
  color: var(--rf7-text-soft);
  background: #fff;
  border: 1px solid var(--rf7-outline);
}

.rf7-breadcrumbs {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--rf7-text-soft);
  font-size: 11px;
  line-height: 16px;
  white-space: nowrap;
}

.rf7-breadcrumbs strong {
  color: var(--rf7-text);
  font-weight: 600;
}

.rf7-breadcrumbs svg {
  width: 13px;
  height: 13px;
  color: var(--rf7-text-muted);
}

.rf7-global-search {
  width: min(360px, 33vw);
  min-width: 220px;
  height: 40px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 10px 0 12px;
  color: var(--rf7-text-soft);
  background: var(--rf7-surface-low);
  border: 1px solid transparent;
  border-radius: 9px;
  transition: background 160ms var(--rf7-ease), border-color 160ms var(--rf7-ease),
    box-shadow 160ms var(--rf7-ease);
}

.rf7-global-search:focus-within {
  background: #fff;
  border-color: rgba(70,72,212,.38);
  box-shadow: 0 0 0 3px rgba(70,72,212,.10);
}

.rf7-global-search svg {
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
}

.rf7-global-search input {
  min-width: 0;
  flex: 1;
  padding: 0;
  color: var(--rf7-text);
  background: transparent;
  border: 0;
  outline: 0;
  font-size: 12px;
}

.rf7-global-search input::placeholder {
  color: #9695a2;
}

.rf7-key-hint {
  padding: 2px 5px;
  color: var(--rf7-text-muted);
  background: rgba(255,255,255,.75);
  border: 1px solid var(--rf7-outline-strong);
  border-radius: 5px;
  font-size: 9px;
  font-weight: 600;
  line-height: 13px;
}

.rf7-create-btn,
.rf7-button {
  appearance: none;
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 15px;
  color: var(--rf7-text);
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: 8px;
  box-shadow: var(--rf7-shadow-1);
  cursor: pointer;
  text-decoration: none;
  font-size: 12px;
  font-weight: 600;
  line-height: 18px;
  transition: transform 150ms var(--rf7-ease), background 150ms var(--rf7-ease),
    border-color 150ms var(--rf7-ease), box-shadow 150ms var(--rf7-ease), color 150ms var(--rf7-ease);
}

.rf7-create-btn,
.rf7-button.primary {
  color: #fff;
  background: var(--rf7-primary);
  border-color: var(--rf7-primary);
  box-shadow: 0 5px 14px rgba(70,72,212,.18);
}

.rf7-create-btn:hover,
.rf7-button.primary:hover {
  background: var(--rf7-primary-hover);
  border-color: var(--rf7-primary-hover);
  box-shadow: 0 8px 18px rgba(70,72,212,.22);
  transform: translateY(-1px);
}

.rf7-button:hover {
  background: var(--rf7-surface-low);
  border-color: #d5d6dc;
}

.rf7-button.ghost {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
}

.rf7-button.danger {
  color: var(--rf7-danger);
  background: var(--rf7-danger-bg);
  border-color: #f1c8c4;
}

.rf7-button.small {
  min-height: 34px;
  padding-inline: 11px;
  font-size: 11px;
}

.rf7-button:disabled,
.rf7-create-btn:disabled {
  opacity: .55;
  cursor: not-allowed;
  transform: none;
}

.rf7-topbar-icon {
  position: relative;
  color: var(--rf7-text-soft);
  background: transparent;
  border: 0;
}

.rf7-topbar-icon:hover {
  color: var(--rf7-primary);
  background: var(--rf7-primary-soft);
}

.rf7-notification-dot {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 7px;
  height: 7px;
  background: #e43e46;
  border: 2px solid var(--rf7-surface);
  border-radius: 50%;
}

.rf7-page-stage {
  min-height: 100vh;
  padding-top: var(--rf7-topbar-height);
}

.rf7-page-content {
  width: 100%;
  max-width: var(--rf7-page-max);
  margin: 0 auto;
  padding: var(--rf7-page-pad);
}

/* -------------------------------------------------------------------------- */
/* Page primitives                                                             */
/* -------------------------------------------------------------------------- */

.rf7-page {
  width: 100%;
}

.rf7-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
}

.rf7-page-title-wrap {
  min-width: 0;
}

.rf7-eyebrow {
  display: block;
  margin-bottom: 5px;
  color: var(--rf7-primary);
  font-size: 10px;
  font-weight: 700;
  line-height: 14px;
  letter-spacing: .09em;
  text-transform: uppercase;
}

.rf7-page-title,
.rf7-section-title {
  margin: 0;
  color: var(--rf7-text);
  font-family: Geist, Inter, ui-sans-serif, sans-serif;
  letter-spacing: -.02em;
}

.rf7-page-title {
  font-size: 30px;
  font-weight: 620;
  line-height: 38px;
}

.rf7-section-title {
  font-size: 18px;
  font-weight: 620;
  line-height: 26px;
}

.rf7-page-subtitle,
.rf7-section-copy {
  margin: 5px 0 0;
  color: var(--rf7-text-soft);
  font-size: 13px;
  line-height: 20px;
}

.rf7-page-actions,
.rf7-section-actions,
.rf7-inline-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.rf7-card {
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: var(--rf7-radius-lg);
  box-shadow: var(--rf7-shadow-1);
}

.rf7-card.pad {
  padding: 22px;
}

.rf7-card.ai {
  background: linear-gradient(180deg, #faf8ff 0%, #f7f5ff 100%);
  border-color: #dfd6fa;
  box-shadow: inset 3px 0 0 var(--rf7-violet), var(--rf7-shadow-1);
}

.rf7-section-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 18px;
}

.rf7-grid {
  display: grid;
  gap: 20px;
}

.rf7-grid.cols-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.rf7-grid.cols-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.rf7-grid.cols-4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.rf7-stack {
  display: grid;
  gap: 16px;
}

.rf7-divider {
  height: 1px;
  background: var(--rf7-outline);
}

.rf7-muted {
  color: var(--rf7-text-muted);
}

.rf7-ai-surface {
  background: var(--rf7-violet-soft);
  border: 1px solid #e2daf9;
  border-left: 3px solid var(--rf7-violet);
  border-radius: 12px;
}

/* -------------------------------------------------------------------------- */
/* Metrics                                                                     */
/* -------------------------------------------------------------------------- */

.rf7-stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.rf7-stat-card {
  position: relative;
  min-width: 0;
  min-height: 150px;
  padding: 20px;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: 15px;
  box-shadow: var(--rf7-shadow-1);
}

.rf7-stat-card.featured {
  color: #fff;
  background: linear-gradient(145deg, #5455dd, #4a47d3);
  border-color: transparent;
  box-shadow: 0 10px 25px rgba(70,72,212,.21);
}

.rf7-stat-label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--rf7-text-soft);
  font-size: 11px;
  font-weight: 600;
  line-height: 16px;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.rf7-stat-card.featured .rf7-stat-label {
  color: rgba(255,255,255,.84);
}

.rf7-stat-icon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  color: var(--rf7-primary);
  background: var(--rf7-primary-soft);
  border-radius: 50%;
}

.rf7-stat-card.featured .rf7-stat-icon {
  color: #fff;
  background: rgba(255,255,255,.14);
}

.rf7-stat-value {
  display: block;
  margin-top: 18px;
  color: var(--rf7-text);
  font-family: Geist, Inter, ui-sans-serif, sans-serif;
  font-size: 28px;
  font-weight: 620;
  line-height: 34px;
  letter-spacing: -.03em;
}

.rf7-stat-card.featured .rf7-stat-value {
  color: #fff;
}

.rf7-stat-foot {
  margin-top: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--rf7-text-muted);
  font-size: 10px;
}

.rf7-stat-card.featured .rf7-stat-foot {
  color: rgba(255,255,255,.78);
}

.rf7-trend {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 7px;
  color: var(--rf7-primary);
  background: var(--rf7-primary-soft);
  border-radius: 5px;
  font-size: 10px;
  font-weight: 700;
}

.rf7-stat-card.featured .rf7-trend {
  color: var(--rf7-primary);
  background: rgba(255,255,255,.92);
}

/* -------------------------------------------------------------------------- */
/* Toolbars, tabs, fields                                                      */
/* -------------------------------------------------------------------------- */

.rf7-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 10px;
  margin-bottom: 16px;
  background: var(--rf7-surface-low);
  border: 1px solid rgba(25,28,29,.035);
  border-radius: 12px;
}

.rf7-toolbar-group {
  min-width: 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.rf7-tabs {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px;
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: 9px;
  box-shadow: var(--rf7-shadow-1);
}

.rf7-tab {
  appearance: none;
  min-height: 30px;
  padding: 0 12px;
  color: var(--rf7-text-soft);
  background: transparent;
  border: 0;
  border-radius: 6px;
  cursor: pointer;
  font-size: 11px;
  font-weight: 550;
  transition: background 150ms var(--rf7-ease), color 150ms var(--rf7-ease);
}

.rf7-tab:hover {
  color: var(--rf7-primary);
  background: var(--rf7-surface-low);
}

.rf7-tab.active {
  color: var(--rf7-primary);
  background: var(--rf7-primary-soft-strong);
}

.rf7-search-field,
.rf7-field-control {
  height: 40px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--rf7-text);
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: 8px;
  outline: none;
  transition: border-color 150ms var(--rf7-ease), box-shadow 150ms var(--rf7-ease),
    background 150ms var(--rf7-ease);
}

.rf7-search-field {
  min-width: 230px;
  padding: 0 11px;
}

.rf7-search-field:focus-within,
.rf7-field-control:focus,
.rf7-field-control:focus-within {
  border-color: rgba(70,72,212,.52);
  box-shadow: 0 0 0 3px rgba(70,72,212,.11);
}

.rf7-search-field input {
  min-width: 0;
  flex: 1;
  padding: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: inherit;
  font-size: 12px;
}

.rf7-field {
  display: grid;
  gap: 6px;
}

.rf7-field > span,
.rf7-field > label {
  color: var(--rf7-text-soft);
  font-size: 11px;
  font-weight: 600;
  line-height: 16px;
}

input.rf7-field-control,
select.rf7-field-control,
textarea.rf7-field-control {
  width: 100%;
  padding: 0 11px;
  font-size: 12px;
}

textarea.rf7-field-control {
  min-height: 104px;
  height: auto;
  padding-block: 10px;
  resize: vertical;
}

.rf7-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

/* -------------------------------------------------------------------------- */
/* Tables                                                                      */
/* -------------------------------------------------------------------------- */

.rf7-table-card {
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: 14px;
  box-shadow: var(--rf7-shadow-1);
}

.rf7-table-scroll {
  overflow-x: auto;
}

.rf7-table {
  width: 100%;
  min-width: 820px;
  border-collapse: collapse;
  table-layout: auto;
}

.rf7-table th,
.rf7-table td {
  padding: 12px 14px;
  text-align: left;
  vertical-align: middle;
  border-bottom: 1px solid #eff0f2;
}

.rf7-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  color: var(--rf7-text-soft);
  background: #f4f4f5;
  font-size: 10px;
  font-weight: 650;
  line-height: 15px;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.rf7-table td {
  color: #2e3037;
  font-size: 12px;
  line-height: 18px;
}

.rf7-table tbody tr {
  transition: background 140ms var(--rf7-ease);
}

.rf7-table tbody tr:hover {
  background: #fafafa;
}

.rf7-table tbody tr:last-child td {
  border-bottom: 0;
}

.rf7-cell-main {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.rf7-cell-avatar {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  display: grid;
  place-items: center;
  overflow: hidden;
  color: var(--rf7-primary);
  background: var(--rf7-primary-soft);
  border-radius: 50%;
  font-size: 10px;
  font-weight: 700;
}

.rf7-cell-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rf7-cell-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.rf7-cell-copy strong,
.rf7-cell-copy span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf7-cell-copy strong {
  color: var(--rf7-text);
  font-size: 12px;
  font-weight: 600;
}

.rf7-cell-copy span {
  color: var(--rf7-text-muted);
  font-size: 10px;
}

.rf7-table-footer {
  min-height: 54px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 14px;
  border-top: 1px solid var(--rf7-outline);
  color: var(--rf7-text-soft);
  font-size: 10px;
}

/* -------------------------------------------------------------------------- */
/* Badges/status                                                               */
/* -------------------------------------------------------------------------- */

.rf7-badge {
  min-height: 22px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  color: var(--rf7-text-soft);
  background: var(--rf7-surface-high);
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 650;
  line-height: 14px;
  white-space: nowrap;
}

.rf7-badge.primary {
  color: var(--rf7-primary);
  background: var(--rf7-primary-soft);
}

.rf7-badge.success {
  color: var(--rf7-success);
  background: var(--rf7-success-bg);
}

.rf7-badge.warning {
  color: var(--rf7-warning);
  background: var(--rf7-warning-bg);
}

.rf7-badge.danger {
  color: var(--rf7-danger);
  background: var(--rf7-danger-bg);
}

.rf7-badge.info {
  color: var(--rf7-info);
  background: var(--rf7-info-bg);
}

.rf7-status-dot {
  width: 6px;
  height: 6px;
  flex: 0 0 6px;
  border-radius: 50%;
  background: currentColor;
}

/* -------------------------------------------------------------------------- */
/* Feedback / empty / loading                                                  */
/* -------------------------------------------------------------------------- */

.rf7-alert {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 14px;
  margin-bottom: 16px;
  color: var(--rf7-text-soft);
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: 10px;
  font-size: 11px;
  line-height: 17px;
}

.rf7-alert.success {
  color: #176a48;
  background: var(--rf7-success-bg);
  border-color: #cbeada;
}

.rf7-alert.warning {
  color: #765000;
  background: var(--rf7-warning-bg);
  border-color: #f0ddb0;
}

.rf7-alert.error {
  color: #8f2924;
  background: var(--rf7-danger-bg);
  border-color: #f1cac6;
}

.rf7-empty {
  min-height: 220px;
  display: grid;
  place-items: center;
  padding: 34px;
  text-align: center;
}

.rf7-empty-inner {
  max-width: 440px;
  display: grid;
  justify-items: center;
  gap: 9px;
}

.rf7-empty-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  margin-bottom: 4px;
  color: var(--rf7-primary);
  background: var(--rf7-primary-soft);
  border-radius: 14px;
}

.rf7-empty h3,
.rf7-empty p {
  margin: 0;
}

.rf7-empty h3 {
  font-family: Geist, Inter, sans-serif;
  font-size: 16px;
  line-height: 23px;
}

.rf7-empty p {
  color: var(--rf7-text-soft);
  font-size: 11px;
  line-height: 18px;
}

.rf7-skeleton {
  position: relative;
  overflow: hidden;
  background: #eceef0;
  border-radius: 7px;
}

.rf7-skeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.7), transparent);
  animation: rf7-shimmer 1.4s infinite;
}

@keyframes rf7-shimmer {
  to { transform: translateX(100%); }
}

/* -------------------------------------------------------------------------- */
/* Drawer / modal                                                              */
/* -------------------------------------------------------------------------- */

.rf7-overlay {
  position: fixed;
  inset: 0;
  z-index: 110;
  background: rgba(20,22,27,.38);
  backdrop-filter: blur(2px);
  animation: rf7-fade-in 140ms ease-out;
}

.rf7-drawer {
  position: fixed;
  z-index: 120;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(560px, 94vw);
  overflow-y: auto;
  background: #fff;
  border-left: 1px solid var(--rf7-outline);
  box-shadow: -18px 0 48px rgba(20,24,31,.14);
  animation: rf7-drawer-in 220ms var(--rf7-ease);
}

.rf7-modal-wrap {
  position: fixed;
  inset: 0;
  z-index: 125;
  display: grid;
  place-items: center;
  padding: 20px;
}

.rf7-modal {
  width: min(640px, 96vw);
  max-height: min(820px, calc(100vh - 40px));
  overflow-y: auto;
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: 16px;
  box-shadow: var(--rf7-shadow-3);
  animation: rf7-modal-in 180ms var(--rf7-ease);
}

@keyframes rf7-fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes rf7-drawer-in { from { transform: translateX(24px); opacity: .3; } to { transform: translateX(0); opacity: 1; } }
@keyframes rf7-modal-in { from { transform: translateY(8px) scale(.985); opacity: 0; } to { transform: translateY(0) scale(1); opacity: 1; } }

/* -------------------------------------------------------------------------- */
/* Command palette + quick create                                              */
/* -------------------------------------------------------------------------- */

.rf7-popover {
  position: absolute;
  z-index: 100;
  min-width: 240px;
  padding: 7px;
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: 11px;
  box-shadow: var(--rf7-shadow-2);
}

.rf7-quick-create {
  top: 51px;
  right: 54px;
  width: 265px;
}

.rf7-menu-item {
  width: 100%;
  min-height: 39px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 9px;
  color: var(--rf7-text-soft);
  background: transparent;
  border: 0;
  border-radius: 7px;
  cursor: pointer;
  text-align: left;
  text-decoration: none;
  font-size: 11px;
  font-weight: 550;
}

.rf7-menu-item:hover {
  color: var(--rf7-primary);
  background: var(--rf7-primary-soft);
}

.rf7-menu-item svg {
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
}

.rf7-command-backdrop {
  position: fixed;
  inset: 0;
  z-index: 140;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 12vh 20px 20px;
  background: rgba(20,22,27,.32);
  backdrop-filter: blur(3px);
}

.rf7-command {
  width: min(660px, 96vw);
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--rf7-outline);
  border-radius: 15px;
  box-shadow: var(--rf7-shadow-3);
  animation: rf7-modal-in 180ms var(--rf7-ease);
}

.rf7-command-input {
  height: 56px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 16px;
  border-bottom: 1px solid var(--rf7-outline);
}

.rf7-command-input input {
  min-width: 0;
  flex: 1;
  padding: 0;
  color: var(--rf7-text);
  background: transparent;
  border: 0;
  outline: 0;
  font-size: 14px;
}

.rf7-command-results {
  max-height: 420px;
  overflow-y: auto;
  padding: 8px;
}

.rf7-command-empty {
  padding: 28px;
  color: var(--rf7-text-muted);
  text-align: center;
  font-size: 11px;
}

/* -------------------------------------------------------------------------- */
/* Mobile                                                                      */
/* -------------------------------------------------------------------------- */

.rf7-sidebar-overlay {
  display: none;
}

.rf7-mobile-bottom-nav {
  display: none;
}

@media (max-width: 1180px) {
  :root {
    --rf7-page-pad: 24px;
  }

  .rf7-global-search {
    width: 280px;
  }

  .rf7-stat-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rf7-grid.cols-4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  :root {
    --rf7-page-pad: 18px;
  }

  .rf7-sidebar {
    transform: translateX(-101%);
    box-shadow: 20px 0 50px rgba(20,24,31,.18);
  }

  .rf7-sidebar.open {
    transform: translateX(0);
  }

  .rf7-sidebar-overlay {
    position: fixed;
    inset: 0;
    z-index: 65;
    display: block;
    background: rgba(20,22,27,.35);
    border: 0;
    backdrop-filter: blur(2px);
  }

  .rf7-shell-main {
    padding-left: 0;
  }

  .rf7-topbar {
    left: 0;
    padding-inline: 16px;
  }

  .rf7-mobile-menu-btn {
    display: inline-grid;
  }

  .rf7-breadcrumbs {
    display: none;
  }

  .rf7-global-search {
    width: min(420px, 48vw);
    min-width: 0;
  }

  .rf7-page-header {
    align-items: flex-start;
  }

  .rf7-grid.cols-3,
  .rf7-grid.cols-2 {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  :root {
    --rf7-topbar-height: 58px;
    --rf7-page-pad: 16px;
  }

  .rf7-topbar {
    height: var(--rf7-topbar-height);
    gap: 8px;
    padding-inline: 12px;
  }

  .rf7-global-search {
    flex: 1;
    width: auto;
    height: 36px;
  }

  .rf7-global-search input::placeholder {
    color: transparent;
  }

  .rf7-key-hint,
  .rf7-create-btn .rf7-create-label,
  .rf7-topbar .rf7-notifications-label {
    display: none;
  }

  .rf7-create-btn {
    width: 36px;
    min-width: 36px;
    min-height: 36px;
    padding: 0;
  }

  .rf7-page-stage {
    padding-bottom: 68px;
  }

  .rf7-page-title {
    font-size: 24px;
    line-height: 31px;
  }

  .rf7-page-header {
    flex-direction: column;
    gap: 14px;
    margin-bottom: 18px;
  }

  .rf7-page-actions {
    width: 100%;
  }

  .rf7-page-actions .rf7-button {
    flex: 1;
  }

  .rf7-stat-grid,
  .rf7-grid.cols-4 {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .rf7-stat-card {
    min-height: 126px;
    padding: 15px;
  }

  .rf7-stat-value {
    font-size: 23px;
    line-height: 29px;
  }

  .rf7-toolbar {
    align-items: stretch;
  }

  .rf7-toolbar-group,
  .rf7-search-field {
    width: 100%;
  }

  .rf7-form-grid {
    grid-template-columns: 1fr;
  }

  .rf7-table-card.mobile-list .rf7-table-scroll {
    overflow: visible;
  }

  .rf7-drawer {
    width: 100vw;
    border-left: 0;
  }

  .rf7-quick-create {
    position: fixed;
    top: 62px;
    right: 10px;
    left: 10px;
    width: auto;
  }

  .rf7-mobile-bottom-nav {
    position: fixed;
    z-index: 62;
    right: 0;
    bottom: 0;
    left: 0;
    height: 62px;
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    padding: 5px 7px max(5px, env(safe-area-inset-bottom));
    background: rgba(255,255,255,.96);
    border-top: 1px solid var(--rf7-outline);
    box-shadow: 0 -8px 24px rgba(20,24,31,.05);
    backdrop-filter: blur(14px);
  }

  .rf7-mobile-bottom-link {
    min-width: 0;
    display: grid;
    place-items: center;
    align-content: center;
    gap: 2px;
    color: var(--rf7-text-muted);
    text-decoration: none;
    border-radius: 8px;
    font-size: 9px;
    font-weight: 600;
  }

  .rf7-mobile-bottom-link svg {
    width: 19px;
    height: 19px;
  }

  .rf7-mobile-bottom-link.active {
    color: var(--rf7-primary);
    background: var(--rf7-primary-soft);
  }
}

@media (max-width: 420px) {
  .rf7-stat-grid,
  .rf7-grid.cols-4 {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .rf-app-v7 *,
  .rf-app-v7 *::before,
  .rf-app-v7 *::after {
    scroll-behavior: auto !important;
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
  }
}
