/* ============================== AUTH SHARED V9 â€” animated auth environment and shared shell ============================== */
.rf-auth-page{
        --rfa-bg:#f8f9fa;
        --rfa-card:#fff;
        --rfa-text:#191c1d;
        --rfa-text2:#464554;
        --rfa-muted:#767586;
        --rfa-line:#e2e4e7;
        --rfa-primary:#4648d4;
        --rfa-primary-dark:#3537bb;
        --rfa-primary-soft:#e8e9ff;
        --rfa-violet:#6b38d4;
        --rfa-success:#087a51;
        --rfa-danger:#ba1a1a;
        --rfa-danger-soft:#ffedeb;
        --rfa-dark:#2e3132;
        --rfa-ease:cubic-bezier(.2,.8,.2,1);
        min-height:100vh;
        display:grid;
        place-items:center;
        padding:24px;
        color:var(--rfa-text);
        background:
          radial-gradient(circle at 14% 15%,rgba(70,72,212,.08),transparent 28%),
          radial-gradient(circle at 86% 82%,rgba(107,56,212,.06),transparent 28%),
          linear-gradient(180deg,#fafbfc 0%,#f5f6f7 100%);
        font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
        overflow-x:hidden;
        animation:rfaPageIn 260ms var(--rfa-ease);
      }

      .rf-auth-page *,
      .rf-auth-page *::before,
      .rf-auth-page *::after{
        box-sizing:border-box;
      }

      .rf-auth-page a{
        color:inherit;
      }

      @keyframes rfaPageIn{
        from{opacity:0}
        to{opacity:1}
      }

      @keyframes rfaHeroIn{
        from{
          opacity:0;
          transform:translate3d(-10px,0,0);
        }
        to{
          opacity:1;
          transform:none;
        }
      }

      @keyframes rfaPanelIn{
        from{
          opacity:0;
          transform:translate3d(0,9px,0);
        }
        to{
          opacity:1;
          transform:none;
        }
      }

      @keyframes rfaGlow{
        0%,100%{
          transform:translate3d(0,0,0);
          opacity:.75;
        }
        50%{
          transform:translate3d(-10px,-8px,0);
          opacity:1;
        }
      }

      .rf-auth-shell{
        position:relative;
        width:min(1180px,100%);
        min-height:min(760px,calc(100vh - 48px));
        display:grid;
        grid-template-columns:minmax(0,1.08fr) minmax(440px,.92fr);
        overflow:hidden;
        background:#fff;
        border:1px solid rgba(221,224,227,.96);
        border-radius:22px;
        box-shadow:
          0 28px 80px rgba(25,28,29,.10),
          0 4px 14px rgba(25,28,29,.04);
      }

      .rf-auth-hero{
        position:relative;
        z-index:1;
        min-width:0;
        min-height:100%;
        display:flex;
        flex-direction:column;
        overflow:hidden;
        padding:34px 38px 27px;
        color:#fff;
        background:
          radial-gradient(circle at 15% 19%,rgba(107,111,255,.29),transparent 32%),
          radial-gradient(circle at 84% 73%,rgba(117,59,216,.25),transparent 34%),
          linear-gradient(145deg,#292c2e 0%,#303336 52%,#292c2f 100%);
        animation:rfaHeroIn 340ms var(--rfa-ease) both;
      }

      .rf-auth-hero::before{
        content:"";
        position:absolute;
        inset:0;
        z-index:-2;
        pointer-events:none;
        opacity:.34;
        background-image:
          linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),
          linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);
        background-size:28px 28px;
        mask-image:linear-gradient(to bottom,#000,transparent 85%);
      }

      .rf-auth-hero::after{
        content:"";
        position:absolute;
        z-index:-1;
        width:470px;
        height:470px;
        left:-195px;
        bottom:-250px;
        pointer-events:none;
        border:1px solid rgba(138,141,255,.17);
        border-radius:50%;
        box-shadow:
          0 0 0 42px rgba(104,106,220,.028),
          0 0 0 88px rgba(104,106,220,.018);
        animation:rfaGlow 9s ease-in-out infinite;
      }

      .rf-auth-hero-top{
        position:relative;
        z-index:3;
        display:flex;
        align-items:center;
        justify-content:space-between;
        gap:18px;
      }

      .rf-auth-brand{
        display:inline-flex;
        align-items:center;
        gap:10px;
        width:max-content;
        color:#fff!important;
        text-decoration:none;
      }

      .rf-auth-brand > span{
