        place-items:center;
        color:#777984;
        background:#eceeef;
        border-radius:50%;
        font-size:6px;
      }

      .rf-auth-card .rf-auth-stepbar > span.active{
        color:var(--rfa-primary);
      }

      .rf-auth-card .rf-auth-stepbar > span.active b{
        color:#fff;
        background:var(--rfa-primary);
      }

      .rf-auth-card .rf-auth-stepbar > i{
