        color:var(--rfl-muted)!important;
        background:#f5f6f7!important;
        border:1px dashed #d7d9dd!important;
        border-radius:8px!important;
        text-align:center!important;
        font-size:7px!important;
      }

      .rfl-google-loading{
        position:absolute;
        z-index:7;
        inset:0;
        display:flex;
        align-items:center;
        justify-content:center;
        gap:7px;
        color:#4b4d59;
        background:rgba(255,255,255,.93);
        border:1px solid var(--rfl-line);
        border-radius:8px;
        font-size:7px;
        font-weight:650;
      }

      .rfl-google-loading i,
      .rfl-button-spinner{
        width:12px;
        height:12px;
        display:block;
        border:2px solid currentColor;
        border-right-color:transparent;
        border-radius:50%;
        animation:rfl-spin .7s linear infinite;
      }

      .rf-auth-divider{
        position:relative!important;
        display:flex!important;
        align-items:center!important;
        justify-content:center!important;
        min-height:43px!important;
        margin:1px 0!important;
      }

      .rf-auth-divider::before{
        content:"";
        position:absolute;
        left:0;
        right:0;
        top:50%;
        height:1px;
        background:var(--rfl-line);
      }

      .rf-auth-divider span{
        position:relative!important;
        z-index:1!important;
        padding:0 9px!important;
        color:#8a8995!important;
        background:#fff!important;
        font-size:6px!important;
        font-weight:650!important;
        letter-spacing:.05em!important;
        text-transform:uppercase!important;
      }

      .rf-auth-email-form{
        display:grid!important;
        gap:13px!important;
      }

      .rf-auth-input.rfl-field{
        display:grid!important;
        gap:6px!important;
        margin:0!important;
      }

      .rfl-field-label{
        color:var(--rfl-text)!important;
        font-size:7px!important;
        font-weight:700!important;
      }

      .rf-auth-input.rfl-field > div{
        min-height:45px!important;
        display:flex!important;
        align-items:center!important;
        gap:8px!important;
        padding:0 10px!important;
        color:#8c8d95!important;
        background:#fff!important;
        border:1px solid var(--rfl-line)!important;
        border-radius:8px!important;
        box-shadow:0 1px 2px rgba(25,28,29,.015)!important;
        transition:
          border-color .14s var(--rfl-ease),
          box-shadow .14s var(--rfl-ease),
          background .14s var(--rfl-ease)!important;
      }

      .rf-auth-input.rfl-field > div:focus-within{
        background:#fefeff!important;
        border-color:rgba(70,72,212,.55)!important;
        box-shadow:0 0 0 3px rgba(70,72,212,.07)!important;
      }

      .rf-auth-input.rfl-field > div > svg{
        flex:0 0 auto!important;
      }

      .rf-auth-input.rfl-field input{
        min-width:0!important;
        width:100%!important;
        height:43px!important;
        padding:0!important;
        color:var(--rfl-text)!important;
        background:transparent!important;
        border:0!important;
        outline:0!important;
        box-shadow:none!important;
        font-size:9px!important;
      }

      .rf-auth-input.rfl-field input::placeholder{
        color:#a4a4ad!important;
      }

      .rfl-password-toggle{
        min-width:38px;
        height:27px;
        padding:0 7px;
        color:var(--rfl-primary);
        background:var(--rfl-primary-soft);
        border:0;
        border-radius:6px;
        cursor:pointer;
        font-size:6px;
        font-weight:750;
      }

      .rfl-password-toggle:disabled{
        opacity:.45;
        cursor:not-allowed;
      }

      .rf-auth-login-options{
        min-height:26px!important;
        display:flex!important;
        align-items:center!important;
        justify-content:space-between!important;
        gap:10px!important;
        margin:0!important;
      }

      .rfl-remember{
        display:flex!important;
        align-items:center!important;
        gap:6px!important;
        color:var(--rfl-text2)!important;
        cursor:pointer!important;
      }

      .rfl-remember > input{
        position:absolute!important;
        opacity:0!important;
        pointer-events:none!important;
      }

      .rfl-remember > span{
        width:16px;
        height:16px;
        display:grid;
        place-items:center;
        color:transparent;
        background:#fff;
        border:1px solid #cfd2d6;
        border-radius:5px;
        transition:.14s var(--rfl-ease);
      }

      .rfl-remember > input:checked + span{
        color:#fff;
        background:var(--rfl-primary);
        border-color:var(--rfl-primary);
      }

      .rfl-remember b{
        font-size:7px;
        font-weight:600;
      }

      .rf-auth-login-options > a{
        color:var(--rfl-primary)!important;
        font-size:7px!important;
        font-weight:700!important;
        text-decoration:none!important;
      }

      .rf-auth-login-options > a:hover{
        text-decoration:underline!important;
      }

      .rf-auth-submit{
        min-height:45px!important;
        display:flex!important;
        align-items:center!important;
        justify-content:center!important;
        gap:7px!important;
        width:100%!important;
        margin-top:1px!important;
        padding:9px 13px!important;
        color:#fff!important;
        background:linear-gradient(135deg,#4a4cd8,#4143cb)!important;
        border:1px solid #4143c6!important;
        border-radius:8px!important;
        box-shadow:
          0 8px 18px rgba(70,72,212,.18),
          inset 0 1px rgba(255,255,255,.10)!important;
        cursor:pointer!important;
        font-size:8px!important;
        font-weight:750!important;
        transition:
          transform .14s var(--rfl-ease),
          background .14s var(--rfl-ease),
          box-shadow .14s var(--rfl-ease)!important;
      }

      .rf-auth-submit:hover:not(:disabled){
        transform:translateY(-1px)!important;
        background:linear-gradient(135deg,#4143cb,#3739bb)!important;
        box-shadow:0 11px 24px rgba(70,72,212,.22)!important;
      }

      .rf-auth-submit:disabled{
        opacity:.58!important;
        cursor:not-allowed!important;
      }

      .rfl-trust-row{
        display:flex;
        align-items:center;
        justify-content:center;
        gap:9px;
        margin-top:17px;
        color:#8b8b94;
      }

      .rfl-trust-row span{
        display:flex;
        align-items:center;
        gap:4px;
        font-size:5.8px;
      }

      .rfl-trust-row i{
        width:3px;
        height:3px;
        background:#c6c7cb;
        border-radius:50%;
      }

      .rf-auth-footer{
        width:100%!important;
        max-width:430px!important;
        margin:18px auto 0!important;
        color:var(--rfl-muted)!important;
        text-align:center!important;
        font-size:7px!important;
      }

      .rf-auth-footer a{
        color:var(--rfl-primary)!important;
        font-weight:750!important;
        text-decoration:none!important;
      }

      .rf-auth-footer a:hover{
        text-decoration:underline!important;
      }

      @media(max-width:980px){
        .rf-auth-page{
          overflow:auto!important;
          padding:18px!important;
        }

        .rf-auth-shell{
          width:min(640px,100%)!important;
          min-height:0!important;
          grid-template-columns:1fr!important;
        }

        .rf-auth-hero{
          min-height:240px!important;
          padding:26px 28px!important;
        }

        .rf-auth-copy{
          max-width:500px!important;
          margin:28px 0 0!important;
        }

        .rf-auth-copy h1{
          font-size:34px!important;
        }

        .rf-auth-copy p{
          max-width:500px!important;
        }

        .rfl-hero-enhancement{
          display:none;
        }

        .rf-auth-panel{
          padding:35px 30px!important;
        }
      }

      @media(max-width:620px){
        .rf-auth-page{
          display:block!important;
          min-height:100svh!important;
          padding:0!important;
          background:#fff!important;
        }

        .rf-auth-shell{
          width:100%!important;
          min-height:100svh!important;
          display:block!important;
          border:0!important;
          border-radius:0!important;
          box-shadow:none!important;
        }

        .rf-auth-hero{
          min-height:0!important;
          display:block!important;
          padding:18px 18px 16px!important;
          background:#2e3132!important;
        }

        .rf-auth-hero::before,
        .rf-auth-hero::after{
          display:none!important;
        }

        .rf-auth-brand{
          gap:7px!important;
        }

        .rf-auth-brand b{
          font-size:14px!important;
        }

        .rf-auth-copy{
          display:none!important;
        }

        .rf-auth-panel{
          min-height:calc(100svh - 78px)!important;
          justify-content:flex-start!important;
          padding:26px 18px 34px!important;
        }

        .rfl-mobile-brand-copy{
          display:block;
          margin-bottom:22px;
        }

        .rfl-mobile-brand-copy > span{
          display:inline-flex;
          align-items:center;
          gap:5px;
          color:var(--rfl-primary);
          font-size:6px;
          font-weight:800;
          letter-spacing:.08em;
          text-transform:uppercase;
        }

        .rfl-mobile-brand-copy h1{
          margin:7px 0 0;
          font:600 28px/34px Geist,Inter,sans-serif;
          letter-spacing:-.03em;
        }

        .rfl-mobile-brand-copy p{
          margin:4px 0 0;
          color:var(--rfl-text2);
          font-size:9px;
        }

        .rf-auth-card-head h2{
          font-size:21px!important;
          line-height:27px!important;
        }

        .rf-auth-card-head p{
          font-size:8px!important;
          line-height:13px!important;
        }
      }

      @media(max-width:390px){
        .rf-auth-login-options{
          align-items:flex-start!important;
          flex-direction:column!important;
        }

        .rfl-trust-row{
          flex-wrap:wrap;
        }
      }



      /* V9 premium login polish */
      .rf-auth-form-v7 .rf-auth-input>div{transition:border-color .18s ease,box-shadow .18s ease,transform .18s ease;background:rgba(255,255,255,.92)}
      .rf-auth-form-v7 .rf-auth-input>div:focus-within{transform:translateY(-1px);box-shadow:0 0 0 4px rgba(70,72,212,.08),0 11px 24px rgba(25,28,38,.06)}
      .rf-auth-form-v7 .rf-auth-submit{position:relative;overflow:hidden;box-shadow:0 14px 34px rgba(70,72,212,.24)}
      .rf-auth-form-v7 .rf-auth-submit::after{content:"";position:absolute;inset:-2px auto -2px -40%;width:34%;transform:skewX(-20deg);background:linear-gradient(90deg,transparent,rgba(255,255,255,.3),transparent);transition:left .55s ease}
      .rf-auth-form-v7 .rf-auth-submit:hover::after{left:112%}
      .rfl-product-window{transform-style:preserve-3d;box-shadow:0 32px 70px rgba(0,0,0,.3),0 0 0 1px rgba(255,255,255,.06)}
      .rfl-value-stack article{transition:transform .22s cubic-bezier(.2,.8,.2,1),background .22s ease}.rfl-value-stack article:hover{transform:translateX(6px);background:rgba(255,255,255,.08)}

            @media(prefers-reduced-motion:reduce){
        .rf-auth-page,
        .rf-auth-card,
        .rfl-auth-alert,
        .rfl-product-window,
        .rfl-google-loading i,
        .rfl-button-spinner{
          animation:none!important;
        }

        .rf-auth-page *,
        .rf-auth-page *::before,
        .rf-auth-page *::after{
          transition-duration:.01ms!important;
          scroll-behavior:auto!important;
        }
      }

/* ============================== SIGNUP V9 â€” signup wizard, progress, workspace cards, security step ============================== */
.rf-signup-v7{
        --rfsu-text:#191c1d;
        --rfsu-text2:#464554;
        --rfsu-muted:#767586;
        --rfsu-line:#e2e4e7;
        --rfsu-soft:#f3f4f5;
        --rfsu-primary:#4648d4;
        --rfsu-primary-dark:#3537bb;
        --rfsu-primary-soft:#e8e9ff;
        --rfsu-violet:#6b38d4;
        --rfsu-success:#087a51;
        --rfsu-success-soft:#dff8eb;
        --rfsu-danger:#ba1a1a;
        --rfsu-danger-soft:#ffedeb;
        --rfsu-ease:cubic-bezier(.2,.8,.2,1);
        width:100%;
      }

      .rf-signup-v7 *,
      .rf-signup-v7 *::before,
      .rf-signup-v7 *::after{
        box-sizing:border-box;
      }

      @keyframes rfsuStepIn{
        from{
          opacity:0;
          transform:translate3d(0,7px,0);
        }
        to{
          opacity:1;
          transform:none;
        }
      }

      @keyframes rfsuSpin{
        to{
          transform:rotate(360deg);
        }
      }

      .rfsu-mobile-intro{
        display:none;
      }

      .rfsu-progress{
        display:flex;
        align-items:center;
        margin:0 0 20px;
      }

      .rfsu-progress-segment{
        min-width:0;
        display:flex;
        align-items:center;
        flex:1 1 0;
      }

      .rfsu-progress-segment:last-child{
        flex:0 0 auto;
      }

      .rfsu-progress-segment > button{
        display:flex;
        align-items:center;
        gap:6px;
        padding:0;
        color:#9899a2;
        background:transparent;
        border:0;
        cursor:pointer;
        font:inherit;
      }

      .rfsu-progress-segment > button:disabled{
        cursor:default;
      }

      .rfsu-progress-segment > button > span{
        width:23px;
        height:23px;
        display:grid;
        place-items:center;
        flex:0 0 23px;
        color:#777985;
        background:#eceeef;
        border-radius:50%;
        font-size:6px;
        font-weight:800;
        transition:.16s var(--rfsu-ease);
      }

      .rfsu-progress-segment > button > b{
        font-size:6px;
        font-weight:700;
        white-space:nowrap;
      }

      .rfsu-progress-segment > button.active{
        color:var(--rfsu-primary);
      }

      .rfsu-progress-segment > button.active > span{
        color:#fff;
        background:var(--rfsu-primary);
        box-shadow:0 4px 10px rgba(70,72,212,.14);
      }

      .rfsu-progress-segment > button.complete{
        color:#5557c9;
      }

      .rfsu-progress-segment > button.complete > span{
        color:var(--rfsu-primary);
        background:var(--rfsu-primary-soft);
      }

      .rfsu-progress-segment > i{
        height:1px;
        flex:1 1 auto;
        margin:0 8px;
        background:#e2e4e7;
      }

      .rfsu-progress-segment > i.complete{
        background:#bfc0fa;
      }

      .rfsu-step-panel{
        animation:rfsuStepIn 220ms var(--rfsu-ease);
      }

      .rfsu-card-head{
        margin-bottom:15px!important;
      }

      .rfsu-card-eyebrow{
        display:block;
        margin-bottom:4px;
        color:var(--rfsu-primary);
        font-size:6px;
        font-weight:800;
        letter-spacing:.10em;
        text-transform:uppercase;
      }

      .rfsu-card-head h2{
        font-size:25px!important;
        line-height:31px!important;
      }

      .rfsu-card-head p{
        max-width:420px;
      }

      .rfsu-alert{
        display:grid;
        grid-template-columns:25px minmax(0,1fr) 22px;
        align-items:start;
        gap:7px;
        padding:9px 10px;
        margin:0 0 13px;
        color:#7f1b1b;
        background:var(--rfsu-danger-soft);
        border:1px solid #ffd0cc;
        border-radius:8px;
        animation:rfsuStepIn 170ms var(--rfsu-ease);
      }

      .rfsu-alert > span{
        width:25px;
        height:25px;
        display:grid;
        place-items:center;
        color:var(--rfsu-danger);
        background:#fff;
        border-radius:7px;
      }

      .rfsu-alert > div{
        min-width:0;
      }

      .rfsu-alert strong{
        display:block;
        font-size:7px;
      }

      .rfsu-alert p{
        margin:1px 0 0;
        font-size:7px;
        line-height:11px;
      }

      .rfsu-alert > button{
        width:22px;
        height:22px;
        display:grid;
        place-items:center;
        padding:0;
        color:#9f5858;
        background:transparent;
        border:0;
        border-radius:5px;
        cursor:pointer;
      }

      .rfsu-workspace-grid{
        display:grid;
        grid-template-columns:1fr 1fr;
        gap:9px;
      }

      .rfsu-workspace-card{
        position:relative;
        min-height:230px;
        display:grid;
        grid-template-rows:auto auto 1fr;
        align-content:start;
        gap:11px;
        padding:15px;
        color:inherit;
        background:#fff;
        border:1px solid var(--rfsu-line);
        border-radius:11px;
        text-align:left;
        cursor:pointer;
        transition:
          transform 150ms var(--rfsu-ease),
          border-color 150ms var(--rfsu-ease),
          box-shadow 150ms var(--rfsu-ease),
          background 150ms var(--rfsu-ease);
      }

      .rfsu-workspace-card:hover{
        transform:translateY(-2px);
        border-color:#cfd0fb;
        box-shadow:0 8px 20px rgba(25,28,29,.045);
      }

      .rfsu-workspace-card.active{
        background:
          linear-gradient(180deg,#fcfcff,#f8f8ff);
        border-color:var(--rfsu-primary);
        box-shadow:
          0 0 0 1px var(--rfsu-primary),
          0 8px 20px rgba(70,72,212,.06);
      }

      .rfsu-workspace-card > header{
        display:flex;
        align-items:center;
        justify-content:space-between;
      }

      .rfsu-workspace-card > header > span{
        width:43px;
        height:43px;
        display:grid;
        place-items:center;
        color:var(--rfsu-primary);
        background:var(--rfsu-primary-soft);
        border-radius:10px;
      }

      .rfsu-workspace-card.active > header > span{
        color:#fff;
        background:var(--rfsu-primary);
      }

      .rfsu-workspace-card > header > i{
        width:24px;
        height:24px;
        display:grid;
        place-items:center;
        color:#fff;
        background:var(--rfsu-primary);
        border-radius:50%;
        box-shadow:0 3px 8px rgba(70,72,212,.14);
      }

      .rfsu-workspace-card > div strong{
        display:block;
        color:var(--rfsu-text);
        font:600 11px/15px Geist,Inter,sans-serif;
      }

      .rfsu-workspace-card > div p{
        margin:4px 0 0;
        color:var(--rfsu-text2);
        font-size:7px;
        line-height:12px;
      }

      .rfsu-workspace-card ul{
        display:grid;
