      .rfsu-workspace-card li{
        display:flex;
        align-items:center;
        gap:5px;
        color:#686a74;
        font-size:6.5px;
      }

      .rfsu-workspace-card li svg{
        color:var(--rfsu-primary);
        flex:0 0 auto;
      }

      .rfsu-info-note,
      .rfsu-security-note{
        display:flex;
        align-items:flex-start;
        gap:8px;
        padding:10px;
        margin-top:11px;
