      }

      .rfsu-field > div{
        min-height:44px;
        display:flex;
        align-items:center;
        gap:8px;
        padding:0 10px;
        color:#8a8b94;
        background:#fff;
        border:1px solid var(--rfsu-line);
        border-radius:8px;
        transition:
          border-color 140ms var(--rfsu-ease),
          box-shadow 140ms var(--rfsu-ease);
      }

      .rfsu-field > div:focus-within{
        border-color:rgba(70,72,212,.55);
        box-shadow:0 0 0 3px rgba(70,72,212,.07);
      }

      .rfsu-field > div > svg{
        flex:0 0 auto;
      }

      .rfsu-field input{
        min-width:0;
        width:100%;
        height:42px;
        padding:0;
        color:var(--rfsu-text);
        background:transparent;
        border:0;
        outline:0;
        font-size:9px;
      }

      .rfsu-field input::placeholder{
        color:#a3a4ac;
      }

      .rfsu-field input:disabled{
        cursor:not-allowed;
      }

      .rfsu-privacy-note{
        display:flex;
        align-items:flex-start;
        gap:7px;
        padding:9px 10px;
        margin-top:11px;
        color:var(--rfsu-primary);
        background:#f7f7fc;
        border-radius:8px;
      }

      .rfsu-privacy-note > svg{
        flex:0 0 auto;
        margin-top:1px;
      }

      .rfsu-privacy-note p{
        margin:0;
        color:var(--rfsu-text2);
        font-size:6.5px;
        line-height:11px;
      }

      .rfsu-form-actions{
        margin-top:13px!important;
      }

      .rfsu-form-actions .rf-auth-back-btn{
        min-width:90px;
      }

      .rfsu-form-actions .rf-auth-submit{
        min-width:170px!important;
      }

      .rfsu-account-form{
        display:grid;
      }

      .rfsu-account-summary{
        min-height:67px;
        display:grid;
        grid-template-columns:37px minmax(0,1fr);
        align-items:center;
        gap:9px;
        padding:10px;
        margin-bottom:13px;
        background:#f7f7f9;
        border:1px solid #eceef0;
        border-radius:9px;
      }

      .rfsu-account-summary > span{
        width:37px;
        height:37px;
        display:grid;
        place-items:center;
        color:var(--rfsu-primary);
        background:#fff;
        border-radius:9px;
        box-shadow:0 1px 3px rgba(25,28,29,.04);
      }

      .rfsu-account-summary > div{
        min-width:0;
      }

      .rfsu-account-summary small{
        display:block;
        color:var(--rfsu-muted);
        font-size:5.5px;
        text-transform:uppercase;
      }

      .rfsu-account-summary strong{
        display:block;
        overflow:hidden;
        color:var(--rfsu-text);
        text-overflow:ellipsis;
        white-space:nowrap;
        font-size:8px;
      }

      .rfsu-account-summary p{
        margin:1px 0 0;
        overflow:hidden;
        color:var(--rfsu-muted);
        text-overflow:ellipsis;
        white-space:nowrap;
        font-size:6px;
      }

      .rfsu-account-fields{
        display:grid;
        gap:11px;
      }

      .rfsu-password-toggle{
        min-width:38px;
        height:27px;
        padding:0 7px;
        color:var(--rfsu-primary);
        background:var(--rfsu-primary-soft);
        border:0;
        border-radius:6px;
        cursor:pointer;
        font-size:6px;
        font-weight:750;
      }

      .rfsu-password-toggle:disabled{
        opacity:.45;
      }

      .rfsu-password-strength{
        display:flex;
        align-items:center;
        justify-content:space-between;
        gap:9px;
        margin-top:-3px;
      }

      .rfsu-password-strength > div{
        display:grid;
        grid-template-columns:repeat(4,1fr);
        gap:4px;
        flex:1;
      }

      .rfsu-password-strength i{
        height:4px;
        display:block;
        background:#e6e7e9;
        border-radius:999px;
      }

      .rfsu-password-strength i.active{
        background:var(--rfsu-primary);
      }

      .rfsu-password-strength > span{
        min-width:85px;
        color:var(--rfsu-muted);
        text-align:right;
        font-size:6px;
      }

      .rfsu-security-note{
        color:var(--rfsu-primary);
        background:var(--rfsu-primary-soft);
        border-color:#dedfff;
      }

      .rfsu-security-note > span{
        color:var(--rfsu-primary);
      }

      .rfsu-security-note strong{
        color:#3739ac;
      }

      .rfsu-submit-caption{
        max-width:370px;
        margin:9px auto 0;
        color:var(--rfsu-muted);
        text-align:center;
        font-size:5.8px;
        line-height:9px;
      }

      .rfsu-spinner{
        width:12px;
        height:12px;
        display:block;
        border:2px solid currentColor;
        border-right-color:transparent;
        border-radius:50%;
        animation:rfsuSpin 700ms linear infinite;
      }

      .rf-signup-v7 .rf-auth-submit:focus-visible,
      .rfsu-workspace-card:focus-visible,
      .rfsu-password-toggle:focus-visible,
      .rfsu-selected-workspace > button:focus-visible,
      .rfsu-progress button:focus-visible{
        outline:3px solid rgba(70,72,212,.16);
        outline-offset:3px;
      }

      @media(max-width:620px){
        .rfsu-mobile-intro{
          display:block;
          margin-bottom:20px;
        }

        .rfsu-mobile-intro > span{
          display:inline-flex;
          align-items:center;
          gap:5px;
          color:var(--rfsu-primary);
          font-size:6px;
          font-weight:800;
          letter-spacing:.08em;
          text-transform:uppercase;
        }

        .rfsu-mobile-intro h1{
          margin:7px 0 0;
          font:600 27px/33px Geist,Inter,sans-serif;
          letter-spacing:-.03em;
        }

        .rfsu-mobile-intro p{
          margin:4px 0 0;
          color:var(--rfsu-text2);
          font-size:8px;
          line-height:13px;
        }

        .rfsu-progress{
          margin-bottom:17px;
        }

        .rfsu-progress-segment > button > b{
          display:none;
        }

        .rfsu-progress-segment > i{
          margin:0 6px;
        }

        .rfsu-card-head h2{
          font-size:21px!important;
          line-height:27px!important;
        }

        .rfsu-workspace-grid{
          grid-template-columns:1fr;
        }

        .rfsu-workspace-card{
          min-height:180px;
        }

        .rfsu-details-grid{
          grid-template-columns:1fr;
        }

        .rfsu-field.wide{
          grid-column:auto;
        }
      }

      @media(max-width:430px){
        .rfsu-single-action .rf-auth-submit{
          width:100%!important;
        }

        .rfsu-form-actions{
          display:grid!important;
          grid-template-columns:1fr!important;
        }

        .rfsu-form-actions .rf-auth-back-btn,
        .rfsu-form-actions .rf-auth-submit{
          width:100%!important;
        }
      }



      /* V9 premium signup polish */
      .rf-signup-v7 .rfsu-step-panel{will-change:transform,opacity,filter}
      .rf-signup-v7 .rfsu-workspace-card{transition:transform .25s cubic-bezier(.2,.8,.2,1),box-shadow .25s ease,border-color .25s ease}
      .rf-signup-v7 .rfsu-workspace-card:hover{transform:translateY(-5px);box-shadow:0 20px 46px rgba(27,31,41,.11)}
      .rf-signup-v7 .rf-auth-submit{position:relative;overflow:hidden;box-shadow:0 13px 32px rgba(70,72,212,.24)}
      .rf-signup-v7 .rf-auth-submit::after{content:"";position:absolute;inset:-2px auto -2px -38%;width:32%;transform:skewX(-20deg);background:linear-gradient(90deg,transparent,rgba(255,255,255,.28),transparent);transition:left .55s ease}
      .rf-signup-v7 .rf-auth-submit:hover::after{left:112%}

            @media(prefers-reduced-motion:reduce){
        .rfsu-step-panel,
        .rfsu-alert,
        .rfsu-spinner{
          animation:none!important;
        }

        .rf-signup-v7 *,
        .rf-signup-v7 *::before,
        .rf-signup-v7 *::after{
          transition-duration:.01ms!important;
          scroll-behavior:auto!important;
        }
      }
