  --rf15-line:rgba(171,181,255,.16);
  --rf15-line-strong:rgba(171,181,255,.30);
  --rf15-text:#f8f9ff;
  --rf15-body:#c0c7dc;
  --rf15-muted:#9099b4;
  --rf15-dim:#6f7892;
  --rf15-primary:#7868ff;
  --rf15-primary-2:#9b5cff;
  --rf15-cyan:#59d7ff;
  --rf15-success:#4ee1a6;
  --rf15-danger:#ff7585;
  min-height:100svh;
  width:100%;
  display:grid;
  place-items:center;
  padding:clamp(18px,3vw,34px);
